        return {"error": "This combination of values is not possible."}
    elif u_int == -3:
        return {"message": "We have a case where the upvotes and downvotes are equal. Unfortunately, that is all we can say."}
    else:
        return {"upvotes": u_int, "downvotes": d_int}

