# all class and function definitions in the code file, if any
def coordinate_list(length, coordinates):
    X = []
    for i in range(length):
        x = coordinates[2 * i]
        y = coordinates[2 * i + 1]
        X.append([x, y])
    return X

def nrook_successor3(board, N, X):
    board_suc = []
    if len(board) == 0:
        c = 0
    else:
        c = board[len(board) - 1][1] + 1
    for r in range(N - 1, -1, -1):
        if (r in [each[0] for each in board]) or ([r + 1, c + 1] in X):
            continue
        else:
            board_suc += [board[0:N] + [[r, c]]]
    return board_suc

def nrook_is_goal(board, N):
    if len(board) != N:
        return False
    else:
        for p in range(1, N):
            for i in range(0, p):
                if (board[p][0] == board[i][0]) or (board[p][1] == board[i][1]):
                    return False
    return True

def nrook_solve(initial_board, N, X):
    fringe = [initial_board]
    while len(fringe) > 0:
        for s in nrook_successor3(fringe.pop(), N, X):
            if nrook_is_goal(s, N):
                return s
            fringe.append(s)
    return False

# main function
