    # Convert JSON serializable inputs to original input variables
    X = coordinate_list(len(unavailable_points) // 2, unavailable_points)

    # Initial board is empty
    initial_board = []

    # Solve the N-Rooks problem
    solution = nrook_solve(initial_board, N, X)

