# import necessary packages
import json

# all class and function definitions in the code file, if any
class Node:
    def __init__(self, data):
        self.__data = data
        self.__left = None
        self.__right = None

    @property
    def left(self):
        return self.__left

    @left.setter
    def left(self, node):
        self.__left = node

    @property
    def right(self):
        return self.__right

    @right.setter
    def right(self, node):
        self.__right = node

class ReturnData:
    def __init__(self, isbalanced, height):
        self.__isbalanced = isbalanced
        self.__height = height

    @property
    def isbalanced(self):
        return self.__isbalanced

    @isbalanced.setter
    def isbalanced(self, isbalanced):
        self.__isbalanced = isbalanced

    @property
    def height(self):
        return self.__height

    @height.setter
    def height(self, height):
        self.__height = height

def is_balanced_tree(head):
    def process(head):
        if not head:
            return ReturnData(True, 0)

        left_result = process(head.left)
        right_result = process(head.right)

