# import necessary packages
import random

# all class and function definitions in the code file, if any
class TicTacToe:

    def __init__(self):
        """Initialize with empty board"""
        self.board = [" ", " ", " ", 
                      " ", " ", " ", 
                      " ", " ", " "]

    def availableMoves(self):
        """Return empty spaces on the board"""
        moves = []
        for i in range(0, len(self.board)):
            if self.board[i] == " ":
                moves.append(i)
        return moves

    def makeMove(self, position, player):
        """Make a move on the board"""
        self.board[position] = player

    def checkWin(self):
        """Return the player that wins the game"""
        combos = ([0, 1, 2], [3, 4, 5], [6, 7, 8],
                  [0, 3, 6], [1, 4, 7], [2, 5, 8],
                  [0, 4, 8], [2, 4, 6])

        for player in ("X", "O"):
            positions = self.getMoves(player)
            for combo in combos:
                win = True
                for pos in combo:
                    if pos not in positions:
                        win = False
                if win:
                    return player

    def gameOver(self):
        """Return True if X wins, O wins, or draw, else return False"""
        if self.checkWin() != None:
            return True
        for i in self.board:
            if i == " ":
                return False
        return True

    def getMoves(self, player):
        """Get all moves made by a given player"""
        moves = []
        for i in range(0, len(self.board)):
            if self.board[i] == player:
                moves.append(i)
        return moves

    def minimax(self, node, depth, player):
        """
        Recursively analyze every possible game state and choose
        the best move location.
        node - the board
        depth - how far down the tree to look
        player - what player to analyze best move for (currently setup up ONLY for "O")
        """
        if depth == 0 or node.gameOver():
            if node.checkWin() == "X":
                return 0
            elif node.checkWin() == "O":
                return 100
            else:
                return 50

        if player == "O":
            bestValue = 0
            for move in node.availableMoves():
                node.makeMove(move, player)
                moveValue = self.minimax(node, depth-1, 'X')
                node.makeMove(move, " ")
                bestValue = max(bestValue, moveValue)
            return bestValue

        if player == "X":
            bestValue = 100
            for move in node.availableMoves():
                node.makeMove(move, player)
                moveValue = self.minimax(node, depth-1, 'O')
                node.makeMove(move, " ")
                bestValue = min(bestValue, moveValue)
            return bestValue

def get_best_move(board, depth):
    starting_value = 40
    board_choices = []
    player = 'O'

    for move in board.availableMoves():
        board.makeMove(move, player)
        move_value = board.minimax(board, depth-1, 'X')
        board.makeMove(move, " ")

        if move_value > starting_value:
            board_choices = [move]
            break
        elif move_value == starting_value:
            board_choices.append(move)

    if len(board_choices) > 0:
        return random.choice(board_choices)
    else:
        return random.choice(board.availableMoves())

# main function
def main_solution(board_state, player_move):
    """
    Main function to determine the next move in a Tic-Tac-Toe game.

    Parameters:
    board_state (list of str): A list representing the current state of the Tic-Tac-Toe board.
    player_move (int): The position (1-9) where the player wants to place their mark.

    Returns:
    dict: A dictionary with the key 'next_move' containing the position (1-9) where the computer should place its mark.
