        letter = note[:-1]
        octave = note[-1]
        offsetNoteIndex = _class.noteNames.index(letter) - aToCTuningOffset

        octaveComponent = 2 ** int(octave)
        noteComponent = semitoneRatio ** offsetNoteIndex
        frequency = round((275 * octaveComponent * noteComponent / 10.0), precision)

        return frequency

