    lines = (board + [[board[i][j] for i in range(3)] for j in range(3)] +
             [[board[i][i] for i in range(3)], [board[i][2-i] for i in range(3)]])
    for line in lines:
        if line.count(X) == 3:
            return X
        if line.count(O) == 3:
            return O
    return None

