# import necessary packages
from math import sqrt

# Function to get all divisors of a number
def getAllDivisor(n):
    divisor = [1]
    for i in range(2, int(sqrt(n)) + 1):
        if n % i == 0:
            divisor.extend([i, n // i])
    return list(set(divisor))

# main function
def main_solution(limit):
    # Convert the input to the required format
    limit = int(limit)

    # List to store all the abundant numbers
    abundantNumbers = []

    # Generating all the abundant numbers
    for i in range(12, limit):
        if sum(getAllDivisor(i)) > i:
            abundantNumbers.append(i)

    # Let us assume all the numbers are not sum_of_abundant_numbers
    nonAbundantSum = [x for x in range(limit)]

    # Generating sum of two abundant numbers
    for i in range(len(abundantNumbers)):
        for j in range(i, len(abundantNumbers)):
            if abundantNumbers[i] + abundantNumbers[j] < limit:
                # Neglecting the value which can be written as sum of two abundant numbers
                nonAbundantSum[abundantNumbers[i] + abundantNumbers[j]] = 0
            else:
                break

    # Return the sum of all positive integers which cannot be written as the sum of two abundant numbers
    return sum(nonAbundantSum)

