# import necessary packages
import random

# all class and function definitions in the code file, if any
class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class BinaryTree:
    def __init__(self, root_value):
        self.root = Node(root_value)

    def build_tree(self, values):
        def insert_node(root, value):
            if root is None:
                return Node(value)
            if value < root.value:
                root.left = insert_node(root.left, value)
            else:
                root.right = insert_node(root.right, value)
            return root

        for value in values:
            self.root = insert_node(self.root, value)

    def find_lca(self, root, node1, node2):
        if root is None:
            return None
        if node1 < root.value and node2 < root.value:
            return self.find_lca(root.left, node1, node2)
        elif node1 > root.value and node2 > root.value:
            return self.find_lca(root.right, node1, node2)
        else:
            return root.value

# main function
def main_solution(root_value, values, node1, node2):
    # Build the binary tree
    tree = BinaryTree(root_value)
    tree.build_tree(values)

    # Find the Lowest Common Ancestor (LCA)
    lca_value = tree.find_lca(tree.root, node1, node2)

    # Return the LCA value
    return lca_value

