    for k in range(n-1):
        pivot = A[k,k]

        for i in range(k+1, n):
            l = A[i, k]/pivot

            for j in range(k+1):
                A[i, j] = 0

            for j in range(k+1, n):
                A[i, j] -= l * A[k, j]
            b[i] -= l * b[k]

def backward_substitution(U, b):
    n = b.size
    x = np.zeros(n)
    for i in reversed(range(n)):
        x[i] = b[i]/U[i, i]
        for j in range(i):
            b[j] -= U[j,i]*x[i]
    return x

