# import necessary packages
import collections
import itertools

# main function
def main_solution(MN):
    # Convert the input list of edges to a network dictionary
    network = {}
    for a, b in MN:
        if a in network:
            network[a].add(b)
        else:
            network[a] = {b}
        if b in network:
            network[b].add(a)
        else:
            network[b] = {a}

    # Function to find loops in the network
    def __loop_iterator(node, chain):
        if node not in chain:
            chain[node] = None
            next_nodes = network[node]
            while next_nodes:
                n = next_nodes.pop()
                network[n].remove(node)
                yield from __loop_iterator(n, chain)
            chain.popitem()
        else:
            yield tuple(itertools.chain(itertools.takewhile(lambda x: x is not node, reversed(chain)), (node,)))

    # Find all loops in the network
    loops = []
    for node in network:
        chain = collections.OrderedDict()
        loops.extend(list(__loop_iterator(node, chain)))

    # Convert loops to a list of sorted lists
    result = [sorted(loop) for loop in loops]

