import math

def isSquare(n):
    root = math.sqrt(n)
    return root == int(root)

def factor(n):
    if n % 2 == 0:
        return (2, int(n / 2))
    a = int(math.ceil(math.sqrt(n)))
    b2 = a * a - n
    while not isSquare(b2):
        a += 1
