# Constants
NUM_COLS = 3
NUM_ROWS = 3
BOARD_LENGTH = NUM_COLS * NUM_ROWS
NUM_STATES = 3 ** BOARD_LENGTH

# Function to convert board to hash value
def boardToHash(board):
    hash_value = 0
    for i in range(BOARD_LENGTH):
        hash_value += board[i] * 3 ** i
    return hash_value

# Function to convert hash value to board
def hashToBoard(hash_value):
    board = [0] * BOARD_LENGTH
    for i in range(BOARD_LENGTH):
        rem = hash_value % 3
        board[i] = rem
        hash_value = (hash_value - rem) // 3
    return board

# Function to check if a player has won or if the game has ended
def checkWin(board, piece):
    # Checking rows
    for r in range(NUM_ROWS):
        if all([board[t] == piece for t in range(NUM_COLS * r, NUM_COLS * (r + 1))]):
            return (1, 1)
    # Checking cols
    for c in range(NUM_COLS):
        if all([board[t] == piece for t in range(c, BOARD_LENGTH, NUM_COLS)]):
            return (1, 1)
    # Checking diagonals
    if all([board[t] == piece for t in range(0, BOARD_LENGTH, NUM_ROWS + 1)]):
        return (1, 1)
    if all([board[t] == piece for t in range(NUM_COLS - 1, BOARD_LENGTH - 1, NUM_ROWS - 1)]):
        return (1, 1)

    # Count how many pieces are on the board:
    tot_pieces = sum([1 for i in range(BOARD_LENGTH) if board[i] != 0])
    return (0, tot_pieces == BOARD_LENGTH)

# Main function
def main_solution(board_hash, piece):
    """
    Determines if the player with the given piece has won or if the game has ended.

    Args:
        board_hash (int): The hash value representing the current state of the board.
        piece (int): The piece type (1 or 2) of the player to check for a win.

    Returns:
        dict: A dictionary with keys 'win' (bool) and 'finished' (bool) indicating the game status.
    """
    board = hashToBoard(board_hash)
    win, finished = checkWin(board, piece)
    return {'win': win, 'finished': finished}

