# import necessary packages
import random

# all class and function definitions in the code file, if any
class Solution:
    def exist(self, board, word):
        m = len(board)
        n = len(board[0])
        board_state = [False] * (m * n)

        for row in range(m):
            for col in range(n):
                if self._exist(board, word, board_state, [row, col], m, n):
                    return True

        return False

    def _exist(self, board, word, board_state, start, m, n):
        l = len(word)
        if l == 0:
            return True
        elif word[0] != board[start[0]][start[1]] or board_state[start[0] * n + start[1]]:
            return False
        else:
            board_state[start[0] * n + start[1]] = True
            neighbors = []
            if start[0] > 0:
                neighbors.append([start[0] - 1, start[1]])
            if start[0] < m - 1:
                neighbors.append([start[0] + 1, start[1]])
            if start[1] > 0:
                neighbors.append([start[0], start[1] - 1])
            if start[1] < n - 1:
                neighbors.append([start[0], start[1] + 1])

            for neighbor in neighbors:
                if self._exist(board, word[1:], board_state, neighbor, m, n):
                    return True
            board_state[start[0] * n + start[1]] = False
            if l > 1:       
                return False
            else:
                return True

# main function
def main_solution(board, word):
    # Convert the board from a list of strings to a list of lists
    board = [list(row) for row in board]

    # Create an instance of the Solution class
    solution = Solution()

    # Call the exist method and return the result
    result = solution.exist(board, word)

    # Return the result as a JSON serializable output
    return result

