    k = 2
    while True:
        if (pow(a, k) % n) == 1:
            break
        else:
            k += 1
    return k

def is_congruent(a, p, r):
    x, poly, n = ([1], [a, 1], p)
    while n != 0:
        if n & 1:
            x = polyMult(x, poly, r, p)
        n >>= 1
        poly = polyMult(poly, poly, r, p)

    check = [0] * r
    check[0] = a 
    check[p % r] = 1

    return x == check

def polyMult(a, b, r, p):
    res = [0] * r
    for i, u in enumerate(a):
        for j, v in enumerate(b):
            idx = (i + j) % r
            res[idx] = (res[idx] + u * v) % p
    return res

