    value = [1, 4, 5, 9, 10, 40, 50, 90, 100, 400, 500, 900, 1000]
    letter = ['I', 'IV', 'V', 'IX', 'X', 'XL', 'L', 'XC', 'C', 'CD', 'D', 'CM', 'M']
    value = list(reversed(value))
    letter = list(reversed(letter))
    roman = ''
    while arab > 0:
        for i in range(len(value)):
            if arab >= value[i]:
                roman += letter[i]
                arab -= value[i]
                break
    return roman

