# import necessary packages
import numpy as np

# all class and function definitions in the code file, if any
alph = ['a','b','c','d','e','f', 'g', 'h','i','j','k', \
        'l','m','n','o','p','q','r','s','t', \
        'u','v','w','x','y','z']

def shift_cipher(text, key):
    str_index = [alph.index(char) for char in text]
    encrypted_text = ''.join(alph[(i + key) % 26].upper() for i in str_index)
    return encrypted_text

def affine_cipher(text, key1, key2):
    str_index = [alph.index(char) for char in text]
    encrypted_text = ''.join(alph[(i * key1 + key2) % 26].upper() for i in str_index)
    return encrypted_text

def substitution_cipher(text):
    str_index = [alph.index(char) for char in text]
    encrypted_text = ''.join(alph[25 - i].upper() for i in str_index)
    return encrypted_text

def vigenere_cipher(text, key):
    str_index = [alph.index(char) for char in text]
    key_index = [alph.index(char) for char in key]
    encrypted_text = ''.join(alph[(str_index[i] + key_index[i % len(key)]) % 26].upper() for i in range(len(text)))
    return encrypted_text

def beaufort_cipher(text, key):
    str_index = [alph.index(char) for char in text]
    key_index = [alph.index(char) for char in key]
    encrypted_text = ''.join(alph[(str_index[i] - key_index[i % len(key)] - 1) % 26].upper() for i in range(len(text)))
    return encrypted_text

def hill_cipher(text, key_matrix):
    str_index = [alph.index(char) for char in text]
    key_matrix = np.array(key_matrix)
    shift = np.dot(str_index, key_matrix)
    encrypted_text = ''.join(alph[(str_index[i] + shift[i]) % 26].upper() for i in range(len(text)))
    return encrypted_text

def permutation_cipher(text, key):
    str_index = [alph.index(char) for char in text]
    key_len = len(key)
    encrypted_text = ''.join(alph[str_index[key[i % key_len] - 1 + i // key_len * key_len]].upper() for i in range(len(text)))
    return encrypted_text

def vigenere_autokey_cipher(text, key):
    str_index = [alph.index(char) for char in text]
    encrypted_text = ''.join(alph[(str_index[i] + (str_index[i - 1] if i > 0 else key)) % 26].upper() for i in range(len(text)))
    return encrypted_text

