# all class and function definitions in the code file, if any
class Empty(Exception):
    """Error attempting to access an element from an empty container"""
    pass

class Full(Empty):
    pass

class ArrayStack:
    """LIFO stack implementation using a python list as underlying storage"""
    def __init__(self, maxlen=None):
        if maxlen:
            self._data = [None] * maxlen
        else:
            self._data = []
        self._maxlen = 10

    def __len__(self):
        return len(self._data)

    def is_empty(self):
        return len(self._data) == 0

    def push(self, e):
        if len(self._data) >= self._maxlen:
            raise Full('Stack is full')
        self._data.append(e)

    def top(self):
        if self.is_empty():
            raise Empty('Stack is empty')
        return self._data[-1]

    def pop(self):
        if self.is_empty():
            raise Empty('Stack is empty')
        return self._data.pop()

# main function
def main_solution(html_content):
    """
    Checks if all HTML tags in the given content are properly matched.

    Parameters:
    html_content (str): A string containing HTML content.

    Returns:
    bool: True if all HTML tags are properly matched, False otherwise.
    """
    def is_matched_html(raw):
        """Return True if all HTML tags are properly matched; False otherwise"""
        stack = ArrayStack()
        fst = raw.find('<')
        while fst != -1:
            sec = raw.find('>', fst + 1)
            if sec == -1:
                return False
            tag_idx = raw.find(' ', fst + 1)
            tag = raw[fst + 1:tag_idx]
