    Returns:
    int: The smallest positive number that is evenly divisible by all numbers from 1 to n.
    """
    def prime_factors(num):
        """Helper function to find the prime factors of a number."""
        factors = {}
        for i in range(2, num + 1):
            while num % i == 0:
                if i in factors:
                    factors[i] += 1
                else:
                    factors[i] = 1
                num //= i
        return factors

