# import necessary packages
import random

# all class and function definitions in the code file, if any
class my_stack:
    def __init__(self):
        self.array = list()
        self.top = 0

    def push(self, new_value):
        if not self.is_empty():
            self.top += 1
        self.array.append(new_value)

    def pop(self):
        if self.is_empty():
            return None
        temp = self.array.pop()
        if self.top >= 1:
            self.top -= 1
        return temp

    def is_empty(self):
        return len(self.array) == 0

    def peek(self):
        if self.is_empty():
            return None
        return self.array[self.top]

# main function
def main_solution(expression):
    # Convert the input expression to a string if it's not already
    expression = str(expression)

    # Function to check if a 'haakjes uitdrukking' is correct
    def check_string(s):
        stack = my_stack()
        for char in s:
            if char in '<[(':
                stack.push(char)
            elif char == '>':
                if stack.peek() == '<':
                    stack.pop()
            elif char == ']':
                if stack.peek() == '[':
                    stack.pop()
            elif char == ')':
                if stack.peek() == '(':
                    stack.pop()
        return "correcte string" if stack.is_empty() else "incorrecte string"

    # Return the result of the check_string function
    return check_string(expression)

