class Node:
    def __init__(self, data, left=None, right=None):
        self.data = data
        self.left = left
        self.right = right
    def __repr__(self):
        return str(self.data)

class Info:
    def __init__(self, s, e):
        self.s = s
        self.e = e
    def __repr__(self):
        return f'开始{self.s} 结尾{self.e}'

def process(x):
    if not x:
        return Info(None, None)
    left = process(x.left)
    right = process(x.right)
    if left.e:
        left.e.right = x
    x.left = left.e
    x.right = right.s
    if right.s:
        right.s.left = x
    return Info(left.s if left.s else x, right.e if right.e else x)

# main function
def main_solution(tree_structure):
    # Convert the JSON serializable input to the original input variables
    def build_tree(structure):
        if not structure:
            return None
        root = Node(structure['data'])
        root.left = build_tree(structure['left'])
        root.right = build_tree(structure['right'])
        return root

    root = build_tree(tree_structure)
    result = process(root)

    # Convert the result to JSON serializable output
    return {
