    # Convert dice outcomes to a list of tuples
    dice_outcomes = [tuple(sorted(outcome)) for outcome in dice_outcomes]

    # Return the results as JSON serializable outputs
    return {
        "permutations": permutations,
        "dice_outcomes": dice_outcomes
    }

