                self.table[i][ja-1] = 1
                self.move_right_i(i, ja)
                return
        self.table[i][j] = 0

    def move_left(self, i, j):
        if j == 0 or self.table[i][j-1] == 1:
            return False
        for ja in reversed(range(0, j-2)):
            if self.table[i][ja] == 1:
                sa = copy.deepcopy(self)
                sa.table[i][j] = 0
                sa.table[i][ja+1] = 1
                sa.moves.append(['L', (i, j)])
                sa.move_left_i(i, ja)
                return sa
