                self.table[i][ja+1] = 1
                self.move_right_i(i, ja)
                return
        self.table[i][j] = 0

    def winner(self):
        balls = sum(sum(row) for row in self.table)
        return balls == 1

    def next_states(self):
        states = []
        for i in range(len(self.table)):
            for j in range(len(self.table[i])):
                if self.table[i][j] == 1:
                    s = self.move_left(i, j)
                    if s:
