        line (str): The input line to process.

    Returns:
        str: The processed line with highlighted and replaced tokens.
    """
    line_tokens = tokenize_line(line)
    if not line_tokens:
        return line

    replacements = {
        _matched_portion(token): f"REPLACED_{_matched_portion(token)}"
        for token in line_tokens if isinstance(token, re.Match)
    }

