digits = ['1', '2', '3', '4', '5', '6', '7', '8', '9']

def isValid(board, r, c, num):
    for i in range(9):
        # column
        if board[i][c] == num:
            return False
        # row
        if board[r][i] == num:
            return False
        # grid
        if board[r//3*3+i//3][c//3*3+i%3] == num:
            return False
    return True

def backtrack(board, r, c):
    # reach the end of a row, row + 1
    if c == 9:
        return backtrack(board, r+1, 0)
    # base case, we find the solution
    if r == 9:
        return True
    # there is already a digit at (r, c)
    if board[r][c] != '.':
        return backtrack(board, r, c+1)

    for num in digits:
        # if the num cannot be here, continue
        if not isValid(board, r, c, num):
            continue
        board[r][c] = num
        if backtrack(board, r, c+1):
            return True
        board[r][c] = '.'
    return False

# main function
def main_solution(board):
    # Convert the input board to a list of lists if it's not already
    if isinstance(board, str):
        board = [list(row) for row in board.split(';')]

    # Solve the Sudoku puzzle
    backtrack(board, 0, 0)

    # Convert the solved board to a string format for JSON serialization
    solved_board = ';'.join([''.join(row) for row in board])

    return solved_board

