            return True
        if zeros == 0:
            for i in range(1, len(numbers)):
                if numbers[i] - numbers[i-1] != 1:
                    return False
            return True
        else:
            gap = 0
            for i in range(1, len(numbers)):
                if numbers[i] == numbers[i-1]:
                    return False
                gap += numbers[i] - numbers[i-1] - 1
            if gap > zeros:
                return False
            else:
                return True

