In a fantasy adventure game, a player starts with a set of keys and encounters a series of locked chests. Each chest requires a specific key to open and contains a set of keys inside. The player needs to determine the order in which to open the chests to collect all keys and open all chests. Given the initial set of keys and the details of each chest, what is the sequence of chest openings that ensures all chests are opened, or determine if it is impossible to open all chests?

The input and output requirements are as follows:

Input:
  `keys` (list of int): A list of integers representing the keys available at the start.
  `chests` (list of list of int): A list of lists where each inner list represents a chest. The first element of the inner list is the key needed to open the chest, the second element is ignored, and the remaining elements are the keys inside the chest.

Output:
  `return` (str): A string representing the order in which the chests should be opened. If it is impossible to open all chests, the string "IMPOSSIBLE" is returned.

Given the following input:

{'keys': [3], 'chests': [[2, 0, 4, 3], [1, 0, 2, 1, 5]]}

Can you predict the output without writing any code? Please reason and put your final answer in the following json format: {"output": <your output>}, where <your output> should strictly match the the output requirement as specified.

Tip: Here is a reference code snippet for this question. You can refer to this code to guide your reasoning but not copy spans of code directly.

# import necessary packages
import random

# all class and function definitions in the code file, if any
class Chest():
    def __init__(self, row, pos):
        self.pos = pos
        self.needs = row[0]
        self.loot = row[2:]
        self.isfree = self.needs in self.loot

    def __str__(self):
        return str(self.pos) + ": {" + str(self.needs) + "}" + str(self.loot)

class ChestGame():
    def __init__(self, keys, chests):
        self.keys = keys
        self.chest = [Chest(chest, i+1) for i, chest in enumerate(chests)]
        self.order = []

    def solve(self):
        if len(self.chest) == 0:
            return True

        missing = [chest.needs for chest in self.chest]
        while len(self.chest) > 0:
            for i in range(len(self.chest)):
                chest = self.chest[i]
                n = self.keys.count(chest.needs)

                if n == 0:
                    continue
                else:
                    p = self.keys.index(chest.needs)

                if chest.isfree or n > 1 or missing.count(chest.needs) <= 1:
                    itsFree = True
                else:
                    savepoint = [list(missing), list(self.keys), list(self.chest), list(self.order)]
                    itsFree = False
                self.order.append(chest)
                del self.keys[p]
                del self.chest[i]
                del missing[i]
                self.keys.extend(chest.loot)

                if itsFree or self.solve():
                    break
                else:
                    missing, self.keys, self.chest, self.order = savepoint
                    savepoint = None
            else:
                return False
        return True

    def solution(self):
        if len(self.chest) > 0:
            return "IMPOSSIBLE"
        else:
            return ' '.join(str(chest.pos) for chest in self.order)

# main function
def main_solution(keys, chests):
    game = ChestGame(keys, chests)
    game.solve()
    return game.solution()

