def suffle(cards, x):
    N = len(cards)
    new_cards = [0] * N
    if x < N // 2:
        j = 0
        for i in range(N):
            if i < N // 2 - x or i >= N // 2 + x:
                new_cards[i] = cards[i]
            else:
                if j % 2:
                    new_cards[i] = cards[N // 2 - x + j // 2]
                    j += 1
                else:
                    new_cards[i] = cards[N // 2 + j // 2]
                    j += 1
