        j = 0
        x = N - x - 1
        for i in range(N):
            if i < N // 2 - x:
                new_cards[i] = cards[N // 2 + i]
            elif i >= N // 2 + x:
                new_cards[i] = cards[i - N // 2]
            else:
                if j % 2:
                    new_cards[i] = cards[N // 2 + j // 2 + N // 2 - x]
