    if cnt > 5 or cnt > Min:
        return Min
    if cards == cards_s or cards == cards_r:
        Min = min(Min, cnt)
    else:
        for i in range(1, len(cards)):
            cards_c = suffle(cards, i)
            Min = back(cards_c, cnt + 1, Min, cards_s, cards_r)
    return Min

