        if src not in self.nodes:
            raise ValueError('Node {0}not in graph'.format(src))
        elif dest not in self.nodes:
            raise ValueError('Node {0} note in graph'.format(dest))
        for e in self.edges[src]:
            if e[0] == dest:
                return e

