        edges_list = []
        for e in self.edges[node]:
            edges_list.append(e[0])
        return edges_list

    def __str__(self):
        res = ''
        for k in self.edges:
            for d in self.edges[k]:
                res = '{0}{1}->{2} ({3:.1f}, {4:.1f})\n'.format(res, k, d[0], d[1][0], d[1][1])
        return res[:-1]


def printPath(path):
    result = ''
    for i in range(len(path)):
        if i == len(path) - 1:
            result = result + str(path[i])
        else:
            result = result + str(path[i]) + '->'
    return result

