def main_solution(nodes, edges):
    # Convert JSON serializable inputs to original input variables
    node_objects = [Node(name) for name in nodes]
    edge_objects = [WeightedEdge(Node(src), Node(dest), weight1, weight2) for src, dest, weight1, weight2 in edges]

    # Create the graph
