def subSquare(x, y, grId):
    for i in range(3 * (x // 3), 3 * (x // 3) + 3):
        for j in range(3 * (y // 3), 3 * (y // 3) + 3):
            if len(grId[i][j]) > 1:
                grId[i][j] = grId[i][j] - grId[x][y]

