class Literal:
    def __init__(self, name, sign=True):
        self.name = name
        self.sign = sign

    def __neg__(self):
        return Literal(self.name, bool(1 - self.sign))

    def get_sign(self):
        return self.sign

    def get_name(self):
        return self.name

def DPLLSatisfiable(KB):
    model = {literal.get_name(): "free" for clause in KB for literal in clause}
    degrees = {literal.get_name(): sum(literal in clause for clause in KB) for clause in KB for literal in clause}
    return DPLL(KB, model, degrees)

def TruthValue(model, literal):
    return (model[literal.get_name()] == 'true' and literal.get_sign() == True) or (model[literal.get_name()] == 'false' and literal.get_sign() == False)

def findUnitClause(KB, model):
    for clause in KB:
        number = 0
        unitLiteral = None
        flag = False
        for literal in clause:
            if TruthValue(model, literal):
                flag = True
                break
            elif model[literal.get_name()] == 'free':
                number += 1
                unitLiteral = literal
        if number == 1 and flag == False:
            return unitLiteral
    return -1

def findPureSymbol(KB, model):
    signs = {}
    for clause in KB:
        flag = False
        for literal in clause:
            if TruthValue(model, literal):
                flag = True
                break
        if flag:
