# import necessary packages
from xml.etree import ElementTree as elle
import random

# all class and function definitions in the code file, if any
class Condition(object):
    def __init__(self):
        self.flag = False
        self.type = ''
        self.parent = None
        self.leaf = False
        self.place = 0

    def test(self, p):
        return False

    def toString(self):
        return ""

    def toXml(self):
        return ""

    def morph(self, state):
        state.parent = self.parent
        state.place = self.place
        if self.place == 1:
            self.parent.c1 = state
        elif self.place == 2:
            self.parent.c2 = state

class Ender(Condition):
    def __init__(self):
        Condition.__init__(self)
        self.leaf = True

class Floater(Ender):
    def __init__(self, limit=0.0):
        Ender.__init__(self)
        self.limit = limit

class Inter(Ender):
    def __init__(self, limit=0):
        Ender.__init__(self)
        self.limit = limit

class Klaus(Condition):
    def __init__(self):
        Condition.__init__(self)
        self.leaf = False

class Unik(Klaus):
    def __init__(self, c1):
        Klaus.__init__(self)
        self.c1 = c1

    def setNull(self):
        if self.c1 is None:
            self.c1 = NullCon()
        self.c1.place = 1
        self.c1.parent = self

class Bik(Klaus):
    def __init__(self, c1, c2):
        Klaus.__init__(self)
        self.c1 = c1
        self.c2 = c2

    def setNull(self):
        if self.c1 is None:
            self.c1 = NullCon()
        if self.c2 is None:
            self.c2 = NullCon()
        self.c2.place = 2
        self.c2.parent = self
        self.c1.place = 1
        self.c1.parent = self

class NullCon(Ender):
    def __init__(self):
        Ender.__init__(self)
        self.type = "Null"

    def test(self, p):
        return True

    def toString(self):
        return 'Null'

    def toXml(self):
        return elle.Element('null')

class TimeLimit(Floater):
    def __init__(self, limit=0.0):
        Floater.__init__(self, limit)
        self.type = 'Time Limit'

    def test(self, p):
        if p['time'] > self.limit:
            self.flag = True
            return True
        else:
            return False

    def toString(self):
        return "TimeLimit=%f" % (self.limit)

    def toXml(self):
        lim = elle.Element('time')
        lim.set('limit', str(self.limit))
        return lim

class TrialsLimit(Inter):
    def __init__(self, limit=0):
        Inter.__init__(self, limit)
        self.type = 'Max Trials'

    def test(self, p):
        if p['trials'] > self.limit:
            self.flag = True
            return True
        else:
            return False

    def toString(self):
        return "MaxTrials=%d" % (self.limit)

    def toXml(self):
        lim = elle.Element('trials')
        lim.set('limit', str(self.limit))
        return lim

class RewardsLimit(Inter):
    def __init__(self, limit=0):
        Inter.__init__(self, limit)
        self.type = 'Max Rewards'

    def test(self, p):
        if p['rewards'] >= self.limit:
            self.flag = True
            return True
        else:
            return False

    def toString(self):
        return "MaxRewards=%d" % (self.limit)

    def toXml(self):
        lim = elle.Element('rewards')
        lim.set('limit', str(self.limit))
        return lim

class ConRwLimit(Inter):
    def __init__(self, limit=0):
        Inter.__init__(self, limit)
        self.type = 'Max Consecutive Rewards'

    def test(self, p):
        if p['cc'] >= self.limit:
            self.flag = True
            return True
        else:
            return False

    def toString(self):
        return "ConsecRewards=%d" % (self.limit)

    def toXml(self):
        lim = elle.Element('cc')
        lim.set('limit', str(self.limit))
        return lim

class BiasRandom(Floater):
    def __init__(self, limit=0.5):
        Floater.__init__(self, limit)
        self.type = 'Random Switch'

    def test(self, p):
        r = random.random()
        if r < self.limit:
            self.flag = True
        else:
            self.flag = False
        return self.flag

    def toString(self):
        return "BiasRandom=%f" % (self.limit)

    def toXml(self):
        ran = elle.Element('random')
        ran.set('limit', str(self.limit))
        return ran

class Noty(Unik):
    def __init__(self, c1=None):
        Unik.__init__(self, c1)
        self.type = "Not"

    def test(self, p):
        if self.c1:
            self.flag = not (self.c1.test(p))
        return self.flag

    def toString(self):
        return "NOT( %s )" % (self.c1.toString())

    def toXml(self):
        noty = elle.Element('not')
        noty.append(self.c1.toXml())
        return noty

class Ory(Bik):
    def __init__(self, c1=None, c2=None):
        Bik.__init__(self, c1, c2)
        self.type = "Or"

    def test(self, p):
        if self.c1 or self.c2:
            self.flag = (self.c1.test(p) or self.c2.test(p))
        return self.flag

    def toString(self):
        return "( %s OR %s )" % (self.c1.toString(), self.c2.toString())

