    def toXml(self):
        dou = elle.Element('xor')
        dou.extend([self.c1.toXml(), self.c2.toXml()])
        return dou

def parseXml(node):
    nodeName = node.tag
    obj = None
    if nodeName == 'null':
        obj = NullCon()
    elif nodeName == 'time':
        lim = float(node.get('limit'))
        obj = TimeLimit(lim)
    elif nodeName == 'trials':
        lim = int(node.get('limit'))
        obj = TrialsLimit(lim)
    elif nodeName == 'rewards':
        lim = int(node.get('limit'))
        obj = RewardsLimit(lim)
    elif nodeName == 'cc':
        lim = int(node.get('limit'))
        obj = ConRwLimit(lim)
    elif nodeName == 'random':
        ran = float(node.get('limit'))
        obj = BiasRandom(ran)
    elif nodeName == 'not':
        c1txt = list(node)[0]
        c1 = parseXml(c1txt)
        obj = Noty(c1)
    elif nodeName in ['or', 'and', 'xor']:
        clist = list(node)
        c1 = parseXml(clist[0])
        c2 = parseXml(clist[1])
        if nodeName == 'or':
            obj = Ory(c1, c2)
        elif nodeName == 'and':
            obj = Andy(c1, c2)
        else:
            obj = Xory(c1, c2)
        obj.setNull()
    else:
        obj = NullCon()
    return obj

