        blocks = {}
        for loc in self:
            blockname = loc['block1']
            bit = loc['bit1']
            blocks[blockname] = max(blocks.get(blockname, 0), bit+1)
            if 'block2' in loc: 
                blockname = loc['block2']
                bit = loc['bit2']
                blocks[blockname] = max(blocks.get(blockname, 0), bit+1)
        return blocks

def rest(block, bit):
