                    if self.boxes[i][j].get_val() == self.boxes[i][j + 1].get_val():
                        self.boxes[i][j].double()
                        self.boxes[i][j + 1] = None
                        self.score += self.boxes[i][j].get_val()

        for i in range(len(self.boxes)):
