    # Generate pentagonal numbers up to the given limit
    pentalist = pentagonalGen(max_num)
    pentaset = set(pentalist)
    lowestD = float('inf')

    # Find the pair of pentagonal numbers with the smallest difference D
    for i in range(max_num):
        x = pentalist[i]
        for j in range(i + 1, max_num):
            y = pentalist[j]
            if y - x > lowestD:
                break
            if (y - x) in pentaset and (x + y) in pentaset:
                if y - x < lowestD:
                    lowestD = y - x

    # Return the smallest difference D
    return lowestD

