                return Token('LPAREN', '(')

            elif self.current_char == ')':
                self.advance()
                return Token('RPAREN', ')')

            else:
                self.error()

        return Token('EOF', None)

class Compound:
    def __init__(self):
        self.children = []

    def append(self, node):
        self.children.append(node)

class Assign:
    def __init__(self, left, op, right):
        self.left = left
        self.token = self.op = op
        self.right = right

