    def __init__(self, token):
        self.token = token
        self.value = token.value

class Num:
    def __init__(self, token):
        self.token = token
        self.value = token.value

class BinOp:
    def __init__(self, left, op, right):
        self.left = left
        self.op = op
        self.right = right

class UnaryOp:
    def __init__(self, op, expr):
        self.token = self.op = op
        self.expr = expr

class Parser:
    def __init__(self, lexer):
        self.lexer = lexer
        self.current_token = self.lexer.get_next_token()

    def error(self):
        raise Exception('Invalid syntax')

    def eat(self, type):
        if self.current_token.type == type:
            self.current_token = self.lexer.get_next_token()
        else:
            self.error()

    def factor(self):
        node = self.current_token
        if self.current_token.type == 'INTEGER':
            self.eat('INTEGER')
            return Num(node)

        if self.current_token.type == 'PLUS':
            self.eat('PLUS')
            node = UnaryOp(node, self.factor())
            return node

        elif self.current_token.type == 'MINUS':
            self.eat('MINUS')
            node = UnaryOp(node, self.factor())
            return node

        elif self.current_token.type == 'LPAREN':
            self.eat('LPAREN')
            node = self.expr()
            self.eat('RPAREN')
            return node

        elif self.current_token.type == 'ID':
            node = self.variable()
            return node

        else:
            self.error()

    def term(self):
        node = self.factor()

        while self.current_token.type in ('MUL', 'DIV'):
            if self.current_token.type == 'MUL':
                self.eat('MUL')
                node = BinOp(node, Token('MUL', '*'), self.factor())

            elif self.current_token.type == 'DIV':
                self.eat('DIV')
                node = BinOp(node, Token('DIV', '/'), self.factor())

        return node

    def expr(self):
        node = self.term()

        while self.current_token.type in ('PLUS', 'MINUS'):
            if self.current_token.type == 'PLUS':
                self.eat('PLUS')
                node = BinOp(node, Token('PLUS', '+'), self.factor())
            elif self.current_token.type == 'MINUS':
                self.eat('MINUS')
                node = BinOp(node, Token('MINUS', '-'), self.factor())

        return node

    def program(self):
        node = self.compound_statement()
        self.eat('DOT')
        return node

    def compound_statement(self):
        self.eat('BEGIN')
        nodes = self.statement_list()
        self.eat('END')

        root = Compound()
        for node in nodes:
            root.append(node)

        return root

    def statement_list(self):
        node = self.statement()

        results = [node]

        while self.current_token.type == 'SEMI':
            self.eat('SEMI')
            results.append(self.statement())

        return results

    def statement(self):
        if self.current_token.type == 'BEGIN':
            node = self.compound_statement()
        elif self.current_token.type == 'ID':
            node = self.assignment_statement()
        else:
            node = self.empty()

        return node

    def assignment_statement(self):
        left = self.variable()
        token = self.current_token
        self.eat('ASSIGN')
        right = self.expr()
        node = Assign(left, token, right)
        return node

    def variable(self):
        node = Var(self.current_token)
        self.eat('ID')
        return node

    def empty(self):
        return NoOp()

    def parse(self):
        return self.program()

class NodeVisitor:
    def visit(self, node):
        method_name = 'visit_' + type(node).__name__
        visitor = getattr(self, method_name, self.generic_visit)
        return visitor(node)

    def generic_visit(self, node):
        raise Exception('No visit_{} method'.format(type(node).__name__))

class Interpreter(NodeVisitor):
    def __init__(self, parser):
        self.parser = parser
        self.GLOBAL_SCOPE = {}

    def visit_Num(self, node):
        return node.value

    def visit_BinOp(self, node):
        if node.op.type == 'PLUS':
            return self.visit(node.left) + self.visit(node.right)
        elif node.op.type == 'MINUS':
            return self.visit(node.left) - self.visit(node.right)
        elif node.op.type == 'MUL':
            return self.visit(node.left) * self.visit(node.right)
        elif node.op.type == 'DIV':
            return self.visit(node.left) / self.visit(node.right)

    def visit_UnaryOp(self, node):
        op = node.op.type
        if op == 'PLUS':
            return +self.visit(node.expr)
        elif op == 'MINUS':
            return -self.visit(node.expr)

    def visit_Compound(self, node):
        for child in node.children:
            self.visit(child)

    def visit_NoOp(self, node):
        pass

    def visit_Assign(self, node):
        var_name = node.left.value
        self.GLOBAL_SCOPE[var_name] = self.visit(node.right)

    def visit_Var(self, node):
        var_name = node.value
        val = self.GLOBAL_SCOPE.get(var_name)
        if val is None:
            raise NameError(repr(var_name))
        else:
            return val

    def interpret(self):
        tree = self.parser.parse()
        return self.visit(tree)

# main function
def main_solution(program_text):
    lexer = Lexer(program_text)
    parser = Parser(lexer)
    interpreter = Interpreter(parser)
    interpreter.interpret()
    return interpreter.GLOBAL_SCOPE

