# all class and function definitions in the code file, if any
class Vector(object):
    def __init__(self, coordinates):
        try:
            if not coordinates:
                raise ValueError
            self.coordinates = tuple(coordinates)
            self.dimension = len(coordinates)

        except ValueError:
            raise ValueError('The coordinates must be nonempty')

        except TypeError:
            raise TypeError('The coordinates must be an iterable')

    def __str__(self):
        return 'Vector: {}'.format(self.coordinates)

    def __eq__(self, v):
        return self.coordinates == v.coordinates

    def plus(self, v):
        new_coordinates = [x+y for x,y in zip(self.coordinates, v.coordinates)]
        return Vector(new_coordinates)

    def minus(self, v):
        new_coordinates = [x-y for x,y in zip(self.coordinates, v.coordinates)]
        return Vector(new_coordinates)

    def times_scalar(self, c):
        new_coordinates = [c*x for x in self.coordinates]
        return Vector(new_coordinates)

    def magnitude(self):
        new_coordinates = [x*x for x in self.coordinates]
        sum = 0
        for y in new_coordinates:
            sum += y
        return math.sqrt(sum)

    def normalize(self):
        try:
            magnitude = self.magnitude()
            return self.times_scalar(1./magnitude)
        except ZeroDivisionError:
            raise Exception("Unable to normalize a 0 vector")

    def vTimesV(self, v):
        new_coordinates = [x*y for x,y in zip(self.coordinates, v.coordinates)]
        numerator = 0
        for y in new_coordinates:
            numerator += y
        return numerator

    def dotProd(self, v):
        numerator = self.vTimesV(v)
        divisor = self.magnitude() * v.magnitude()
        if divisor == 0:
            return 0
        val = numerator / divisor
        return math.acos(val)

    def dotProdDegrees(self, v):
        numerator = self.vTimesV(v)
        divisor = self.magnitude() * v.magnitude()
        if divisor == 0:
            return 0
        val = (numerator / divisor)
        res = math.acos(val) * 180 / math.pi
        return res

    @staticmethod
    def isOrthogonal(v1, v2):
        ninetyDProd = v1.dotProdDegrees(v2) == 90.0
        zeroVectorV1 = v1.vTimesV(v1) == 0
        zeroVectorV2 = v2.vTimesV(v2) == 0
        return ninetyDProd or zeroVectorV2 or zeroVectorV1

    def isParallel(self, v):
        dProdDegrees = self.dotProdDegrees(v)
        return dProdDegrees == 0 or dProdDegrees == 180

