# import necessary packages
import itertools
import random

# all class and function definitions in the code file, if any
class Node(object):
    def __init__(self, name, children=None):
        self.name = name
        self.children = set(children) if children else set()

    def __eq__(self, other):
        if isinstance(self, type(other)):
            return self.name == other.name
        return NotImplemented

    def __ne__(self, other):
        result = self.__eq__(other)
        if result is NotImplemented:
            return result
        return not result

    def __hash__(self):
        return hash(self.name)

    def __repr__(self):
        return "Node(%r)" % (self.name,)

class LadderNode(Node):
    def __init__(self, name, words, cache=None):
        super(LadderNode, self).__init__(name)
        self._words = words
        self._cache = cache

    @property
    def children(self):
        children = self._get_children()
        try:
            first_child = next(children)
            return itertools.chain([first_child], children)
        except StopIteration:
            return []

    def _get_children(self):
        if self._cache is not None:
            return self._cached_child_search()
        else:
            return self._linear_child_search()

    def _cached_child_search(self):
        for word in self._cache.find_adjacent_words(self.name):
            yield LadderNode(word, None, self._cache)

    def _linear_child_search(self):
        child_words = [word for word in self._words if word != self.name]
        for word in child_words:
            if distance(word, self.name) == 1:
                yield LadderNode(word, child_words)

    @children.setter
    def children(self, words):
        self._words = words

def distance(word_one, word_two):
    return sum([1 for (x, y) in zip(word_one, word_two) if x != y])

def create_branch(names, node_class=Node):
    parents, children = itertools.tee(node_class(n) for n in names)
    path = [next(children)]
    for parent, child in zip(parents, children):
        parent.children.add(child)
        path.append(child)
    return path

# main function
def main_solution(names):
    # Convert input to a list of Node objects
    nodes = create_branch(names, node_class=Node)

    # Extract the names of the nodes in the path
    result = [node.name for node in nodes]

    # Return the result as a list of strings
    return result

