class Token(object):
    def __init__(self, token_type, token_value):
        self.token_type = token_type
        self.token_value = token_value

class Lexer(object):
    def __init__(self, text):
        self.text = text
        self.index = 0
        self.current_char = self.text[self.index]

    def error(self):
        raise Exception('Invalid character')

    def advance(self):
        self.index += 1
        if self.index == len(self.text):
            self.current_char = None
        else:
            self.current_char = self.text[self.index]

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def generate_number(self):
        result = []
        while self.current_char is not None and self.current_char.isdigit():
            result.append(self.current_char)
            self.advance()
        return int(''.join(result))

    def get_next_token(self):
        while self.current_char is not None:
            if self.current_char.isspace():
                self.skip_whitespace()
                continue
            if self.current_char.isdigit():
                number = self.generate_number()
                return Token('INTEGER', number)
            if self.current_char == '+':
                self.advance()
                return Token('PLUS', '+')
            if self.current_char == '-':
                self.advance()
                return Token('MINUS', '-')
            if self.current_char == '*':
                self.advance()
                return Token('MUL', '*')
            if self.current_char == '/':
                self.advance()
                return Token('DIV', '/')
            if self.current_char == '(':
                self.advance()
                return Token('LPAREN', '(')
            if self.current_char == ')':
                self.advance()
                return Token('RPAREN', ')')
            self.error()
        return Token('EOF', None)

class AbstractSyntaxTree(object):
    pass

class BinaryOperator(AbstractSyntaxTree):
    def __init__(self, left, op, right):
        self.left = left
        self.token = self.op = op
        self.right = right

class UnaryOperator(AbstractSyntaxTree):
    def __init__(self, op, expr):
        self.token = self.op = op
        self.expr = expr

class Number(AbstractSyntaxTree):
    def __init__(self, token):
        self.token = token
        self.value = token.token_value

class Parser(object):
    def __init__(self, lexer):
        self.lexer = lexer
        self.current_token = self.lexer.get_next_token()

    def error(self):
        raise Exception('Invalid syntax')

    def walk(self, token_type):
        token = self.current_token
        if token.token_type == token_type:
            self.current_token = self.lexer.get_next_token()
        else:
            self.error()       

    def factor(self):
        token = self.current_token
        if token.token_type == 'PLUS':
            self.walk('PLUS')
            node = UnaryOperator(token, self.factor())
            return node
        elif token.token_type == 'MINUS':
            self.walk('MINUS')
            node = UnaryOperator(token, self.factor())
            return node
        elif token.token_type == 'INTEGER':
