# import necessary packages
import random

# all class and function definitions in the code file, if any
class DictWithLists:
    def __init__(self):
        self._keys = []
        self._values = []

    def _getIndex(self, k):
        i = 0
        while i < len(self._keys) and self._keys[i] != k:
            i += 1
        return i

    def __len__(self):
        return len(self._keys)

    def __contains__(self, k):
        return k in self._keys

    def __getitem__(self, k):
        ind = self._getIndex(k)
        if ind == len(self):
            raise KeyError(repr(k))
        return self._values[ind]

    def __setitem__(self, k, v):
        ind = self._getIndex(k)
        if ind < len(self):
            self._values[ind] = v
        else:
            self._keys.append(k)
            self._values.append(v)

    def clear(self):
        self._keys = []
        self._values = []

    def pop(self, k):
        ind = self._getIndex(k)
        if ind == len(self):
            raise KeyError(repr(k))
        self._keys.pop(ind)
        return self._values.pop(ind)

    def popitem(self):
        if len(self) == 0:
            raise KeyError('popitem(): dictionary is empty')
        return (self._keys.pop(), self._values.pop())

    def keys(self):
        return list(self._keys)

