def is_correct_length(x, y):
    if (len(str(x)) + len(str(y)) + len(str(x * y))) < 10:
        return True
    return False

def is_pandigital(x, y):
    if (len(str(x)) + len(str(y)) + len(str(x * y))) != 9:
        return False
    counter = {key: 0 for key in "123456789"}
    digits = str(x * y) + str(x) + str(y)
    for d in digits:
