# import necessary packages
import random

# all class and function definitions in the code file, if any
# they will be used in the main_solution function, you may need to modify them to meet the requirements of the main_solution function (optional)

# the indexes of the winning combinations
winning_slots = (
    [0, 1, 2], [3, 4, 5], [6, 7, 8],
    [0, 3, 6], [1, 4, 7], [2, 5, 8],
    [0, 4, 8], [2, 4, 6])

def _other(Player):
    if Player == 'X':
        return 'O'
    return 'X'

class Board(object):
    def __init__(self, grid=None):
        if not grid:
            grid = [None for _ in range(9)]
        self.grid = grid

    states_explored = 0

    def _complete(self):
        if None not in self.grid:
            return True
        if self._winner():
            return True
        else:
            return False

    def _openSlots(self):
        return [i for i, j in enumerate(self.grid) if j is None]

    def _getPositions(self, Player):
        return [i for i, j in enumerate(self.grid) if j == Player]

    def _winner(self):
        for player in ('X', 'O'):
            positions = self._getPositions(player)
            for combo in winning_slots:
                win = True
                for pos in combo:
                    if pos not in positions:
                        win = False
                if win:
                    return player
        return None

    def _takeTurn(self, position, Player):
        self.grid[position] = Player

    def _miniMax(self, state, Player, alpha, beta):
        self.states_explored += 1
        if state._complete():
            if state._winner() == 'X':
                return -1
            elif state._winner() == 'O':
                return 1
            else:
                return 0
        if Player == 'O': #maximizing player
            _value = -2
            for slot in state._openSlots():
                state._takeTurn(slot, Player)
                _value = max(_value, self._miniMax(state, _other(Player), alpha, beta))
                state._takeTurn(slot, None)
                alpha = max(alpha, _value)
                if beta <= alpha:
                    break
            return _value
        if Player == 'X': #minimizing player
            _value = 2
            for slot in state._openSlots():
                state._takeTurn(slot, Player)
                _value = min(_value, self._miniMax(state, _other(Player), alpha, beta))
                state._takeTurn(slot, None)
                beta = min(beta, _value)
                if beta <= alpha:
                    break
            return _value

def TakeTurnX(state, Player):
    state.states_explored = 0
    a = 1
    moves = []
    for slot in state._openSlots():
        state._takeTurn(slot, Player)
        _value = state._miniMax(state, _other(Player), -2, 2)
        state._takeTurn(slot, None)
        if _value < a:
            a = _value
            moves = [slot]
        elif _value == a:
            moves.append(slot)
    return random.choice(moves)

def TakeTurnO(state, Player):
    state.states_explored = 0
    a = -1
    moves = []
    if len(state._openSlots()) == 9: #if empty board, just take the middle
        return 4
    for slot in state._openSlots():
        state._takeTurn(slot, Player)
        _value = state._miniMax(state, _other(Player), -2, 2)
        state._takeTurn(slot, None)
        if _value > a:
            a = _value
            moves = [slot]
        elif _value == a:
            moves.append(slot)
    return random.choice(moves)

# main function
def main_solution(grid, player):
    # Convert JSON serializable input to original input variables
    board = Board(grid)

    # Determine the best move for the given player
    if player == 'X':
        move = TakeTurnX(board, player)
    else:
        move = TakeTurnO(board, player)

    # Return the best move as a JSON serializable output
    return move

