class Link:
    empty = ()

    def __init__(self, first, rest=empty):
        assert rest is Link.empty or isinstance(rest, Link)
        self.first = first
        self.rest = rest

class Tree:
    def __init__(self, root, branches=[]):
        for c in branches:
            assert isinstance(c, Tree)
        self.root = root
        self.branches = branches

    def is_leaf(self):
        return not self.branches

def deep_len(lnk):
    ans = 0
    if lnk.rest == lnk.empty:
        if isinstance(lnk.first, int):
            ans += 1
        elif isinstance(lnk.first, Link):
            ans += deep_len(lnk.first)
    else:
        if isinstance(lnk.first, int):
            ans += 1
        elif isinstance(lnk.first, Link):
            ans += deep_len(lnk.first)
        ans += deep_len(lnk.rest)
    return ans

def tree_map(fn, t):
    if t.is_leaf():
        t.root = fn(t.root)
        return t
    else:
        t.root = fn(t.root)
        for i in range(len(t.branches)):
            t.branches[i] = tree_map(fn, t.branches[i])
        return t

