class Pos:
    def __init__(self, x: int, y: int):
        self.x = x
        self.y = y

class GameOfLife:
    def __init__(self, cellsPos: List[Pos], steps: int):
        minPos = Pos(float('inf'), float('inf'))
        maxPos = Pos(float('-inf'), float('-inf'))
        for pos in cellsPos:
            if pos.x < minPos.x:
                minPos.x = pos.x
            if pos.x > maxPos.x:
                maxPos.x = pos.x
            if pos.y < minPos.y:
