    Parameters:
    numbers (list of int): A list containing exactly four integers between 1 and 13.

    Returns:
    bool: True if there exists an arithmetic expression using the given numbers that evaluates to 24, False otherwise.
    """
    def parse(s, L):
        b = 0
        while b != len(s):
            while b != len(s) and not s[b].isdigit():
                b += 1
            e = b
            while e != len(s) and s[e].isdigit():
                e += 1
            if b == e:
