            try:
                i = int(s[b:e])
                idx = L.index(i)
                L.pop(idx)
            except Exception:
                return False
            b = e
        if len(L) != 0:
            return False
        try:
            val = eval(s)
        except Exception:
            return False
        if val != 24:
            return False
        if '//' in s:
            return False
        if '#' in s:
            return False
        for c in s:
            if c.isalpha():
                return False
        return True

    # Generate all possible permutations of the numbers
    from itertools import permutations
    for perm in permutations(numbers):
        # Try all possible arithmetic expressions
        for op1 in ['+', '-', '*', '/']:
            for op2 in ['+', '-', '*', '/']:
                for op3 in ['+', '-', '*', '/']:
