                evaluation, _ = temp.minimaxWithAlphaBeta(temp, depth-1, 'Human', alpha, beta)
                if maxEval < evaluation:
                    maxMove = move
                    maxEval = evaluation
                alpha = max(alpha, maxEval)
                if beta <= alpha:
