class Node:
    def __init__(self, k):
        self.key = k
        self.parent = None
        self.left = None
        self.right = None

    def __str__(self):
        return "Node(%s)" % self.key

class BST(object):
    def __init__(self):
        self.root = None

    def INSERT(self, z):
        new = Node(z)
        y = None
        x = self.root
        while x != None:
            y = x
            if new.key <= x.key:
                x = x.left
            else:
                x = x.right
        new.parent = y
        if y == None:
            self.root = new
        elif new.key < y.key:
            y.left = new
        else:
            y.right = new
        return new

    def MINIMUM(self, x=None):
        if not x:
            x = self.root
        while x.left:
            x = x.left
        return x

    def MAXIMUM(self, x=None):
        if not x:
            x = self.root
        while x.right:
            x = x.right
        return x

    def SUCCESSOR(self, x):
        if x.right:
            return self.MINIMUM(x.right)
        y = x.parent
        while y != None and y.right == x:
            x = y
            y = x.parent
        return y

    def DELETE(self, z):
        if z.left == None:
            self.__TRANSPLANT(z, z.right)
        elif z.right == None:
            self.__TRANSPLANT(z, z.left)
        else:
            y = self.MINIMUM(z.right)
            if y.parent != z:
                self.__TRANSPLANT(y, y.right)
                y.right = z.right
                y.right.parent = y
            self.__TRANSPLANT(z, y)
            y.left = z.left
            y.left.parent = y

    def __TRANSPLANT(self, u, v):
        if u.parent == None:
            self.root = v
        elif u == u.parent.left:
            u.parent.left = v
        else:
            u.parent.right = v
        if v != None:
            v.parent = u.parent

# main function
def main_solution(keys):
    tree = BST()
    for key in keys:
        tree.INSERT(key)

    min_key = tree.MINIMUM().key
    max_key = tree.MAXIMUM().key
    successor_key = None

    if tree.root:
        successor_key = tree.SUCCESSOR(tree.root).key if tree.SUCCESSOR(tree.root) else None

    return {"min_key": min_key, "max_key": max_key, "successor_key": successor_key}

