# import necessary packages
from collections import defaultdict

# main function
def main_solution(ladders, snakes):
    graph = defaultdict(list)
    lmap = {}
    smap = {}
    for (s, e) in ladders:
        lmap[s] = e
    for (s, e) in snakes:
        smap[s] = e
    maxn = 100
    for i in range(1, maxn):
        for j in range(1, 7):
            if j + i in lmap:
                graph[i].append(lmap[i + j])
            elif j + i in smap:
                graph[i].append(smap[i + j])
            elif j + i <= maxn:
                graph[i].append(i + j)

    visited = {}
    queue = []
    queue.append(1)
    visited[1] = 0
    route = defaultdict(list)

    while len(queue) > 0:
        cur = queue.pop(0)

        if cur == maxn:
            return visited[cur]

        for n in graph[cur]:
            if n not in visited:
                queue.append(n)
                visited[n] = visited[cur] + 1
                route[n] = route[cur][:]
                route[n].append(n)
            elif visited[n] > visited[cur] + 1:
                visited[n] = visited[cur] + 1
                route[n] = route[cur][:]
                route[n].append(n)
    return -1

