        self.length = size
        self.fst_free = fst_free
        self.__iter_spot = 0
        self.x_min = float('inf')
        self.x_max = float('-inf')
        self.y_min = float('inf')
        self.y_max = float('-inf')
        self.lowest_y = (float('inf'), float('inf'))
        if input is not None:
