            self.lowest_y = vertex
        if vertex[1] > self.y_max:
            self.y_max = vertex[1]
        self.list[self.fst_free] = vertex
        self.fst_free += 1
        if self.fst_free == self.length:
            self.__grow()

    def __grow(self):
        old = self.list
        self.list = [None] * (self.length * 2)
        self.length *= 2
        for i in range(len(old)):
            self.list[i] = old[i]

