        try:
            return float(self.lowest_y[0] - x[0]) / float(self.lowest_y[1] - x[1])
        except ZeroDivisionError:
            if x[0] > self.lowest_y[0] or x == self.lowest_y:
                return float('inf')
            else:
                return float('-inf')

