import itertools

# all class and function definitions in the code file, if any
def fact(n):
    f = 1
    while n > 1:
        f *= n
        n -= 1
    return f

def nCr(n, r):
    if n >= r:
        return fact(n) // (fact(r) * fact(n - r))
    else:
        raise ValueError('n must be greater than r!')

def nPr(n, r):
    if n >= r:
        return fact(n) // fact(n - r)
    else:
        raise ValueError('n must be greater than r!')

def lexcomb(n, res_len, lex):
    if n >= nCr(len(lex), res_len):
        raise ValueError('not that many combinations!')
    res = ""
    while len(res) < res_len:
        thesePerms = nCr(len(lex) - 1, res_len - len(res) - 1)
        if n > thesePerms - 1:
            lex = lex[1:]
            n -= thesePerms
        else:
            res += lex[0]
            lex = lex[1:]
    return res

def lexperm(n, lex, res=""):
    if n >= fact(len(lex)):
        raise ValueError('not that many permutations!')
    f = fact(len(lex) - 1)
    nth_element = n // f
    rem = n % f
    res += str(lex[nth_element])
    newlex = lex[:nth_element] + lex[nth_element + 1:]
    if len(newlex) > 1:
        res = lexperm(rem, newlex, res)
        return res
    else:
        return res + str(newlex[0])

def sublexperm(n, res_len, lex):
    if n > nPr(len(lex), res_len):
        raise ValueError('not that many permutations!')
    c_num = n % nCr(len(lex), res_len)
    c = lexcomb(c_num, res_len, lex)
    p_num = n // nCr(len(lex), res_len)
    res = lexperm(p_num, c)
    return res

# main function
def main_solution(n):
    # Convert input to integer
    n = int(n)

    # Generate all permutations of length 4 from '123456789'
    lex = '123456789'
    res = sublexperm(n, 4, lex)

    # Remove used digits from lex
    for l in res:
        lex = lex.replace(l, '')

    # Check for valid pandigital products
    products = set()
    for l in lex:
        test = str(int(res) // int(l))
        t = list(test + res + l)
        t.sort()
        if int(res) % int(l) == 0 and ''.join(t) == '123456789':
            products.add(int(res))

    # Return the sum of unique products
    return sum(products)

