import string

# main function
def main_solution(input_string):
    # Convert the input string to a format suitable for palindrome checking
    def clean_string(s):
        symbols = string.punctuation + ' '
        for symbol in symbols:
            s = s.replace(symbol, '')
        return s.lower()

    # Recursive function to check if a string is a palindrome
    def is_palindrome(p, r=None, i=None):
        if r is None:
            r = ''.join(list(reversed(p)))
            i = 0
            return is_palindrome(p, r, i)
        elif i == len(p) - 1:
            return p[i] == r[i]
        else:
            if p[i] == r[i]:
                i += 1
                return is_palindrome(p, r, i)
            else:
                return False

    # Clean the input string
    cleaned_string = clean_string(input_string)

    # Check if the cleaned string is a palindrome
    result = is_palindrome(cleaned_string)

