# import necessary packages
import random

# all class and function definitions in the code file, if any
class FibonacciMachine:
    def __init__(self, tape):
        self._tape = tape
        self._blank_symbol = '*'
        self._transitions = {}

    def _is_fibonacci(self, number, memory_1, memory_2):
        return number == (memory_1 + memory_2)

    def run(self):
        symbol_at_head = self._tape[0]
        if symbol_at_head != '1':
            return {
                'tape': self._tape,
                'message': 'Is it not fibonacci',
                'output': 'Rejected',
                'transitions': self._transitions,
            }

        state_counter, memory_1, memory_2 = 0, 0, 0
        for i in range(len(self._tape)):
            try:
                number = int(self._tape[i])
            except ValueError:
                return {
                    'tape': self._tape,
                    'message': 'Hey Human, I just accept numbers.',
                    'output': 'Rejected',
                    'transitions': self._transitions,
                }

            if i > 1:
                memory_1 = int(self._tape[i-2])
                memory_2 = int(self._tape[i-1])
            else:
                memory_1 = number
                memory_2 = number

            if not self._is_fibonacci(number, memory_1, memory_2) and i > 1:
                return {
                    'tape': self._tape,
                    'message': 'Is it not fibonacci',
                    'output': 'Rejected',
                    'transitions': self._transitions,
                }

            previous_state = state_counter
            state_counter += 1
            self._transitions[f'q{previous_state}->q{state_counter}'] = f'{symbol_at_head},{number},R'

        self._transitions[f'q{state_counter}->qf'] = '#,#,R'
        return {
            'tape': self._tape,
            'message': 'Work done! Is fibonacci.',
            'output': 'Accepted',
            'transitions': self._transitions,
        }

# main function
def main_solution(tape):
    # tape (str): A string of numbers separated by '|' representing the tape of the Fibonacci machine.
    fib_machine = FibonacciMachine(tape.split('|'))
    result = fib_machine.run()
    return {
        'tape': result['tape'],
        'message': result['message'],
        'output': result['output']
    }

