# import necessary packages
from abc import ABCMeta, abstractmethod

# all class and function definitions in the code file, if any
class Expression(metaclass=ABCMeta):
    """抽象表达式"""

    @abstractmethod
    def interpreter(self, var):
        pass


class VarExpression(Expression):
    """变量解析器"""

    def __init__(self, key):
        self.__key = key

    def interpreter(self, var):
        return var.get(self.__key)


class SymbolExpression(Expression):
    """运算符解析器，运算符的抽象类"""

    def __init__(self, left, right):
        self._left = left
        self._right = right


class AddExpression(SymbolExpression):
    """加法解析器"""

    def __init__(self, left, right):
        super().__init__(left, right)

    def interpreter(self, var):
        return self._left.interpreter(var) + self._right.interpreter(var)


class SubExpression(SymbolExpression):
    """减法解析器"""

    def __init__(self, left, right):
        super().__init__(left, right)

    def interpreter(self, var):
        return self._left.interpreter(var) - self._right.interpreter(var)


class Stack:
    """封装一个堆栈类"""

    def __init__(self):
        self.items = []

    def isEmpty(self):
        return len(self.items) == 0

    def push(self, item):
        self.items.append(item)

    def pop(self):
        return self.items.pop()

    def peek(self):
        if not self.isEmpty():
            return self.items[len(self.items) - 1]

    def size(self):
        return len(self.items)


class Calculator:
    """计算器类"""

    def __init__(self, text):
        self.__expression = self.parserText(text)

    def parserText(self, expText):
        # 定义一个栈，处理运算的先后顺序
        stack = Stack()
        left = right = None # 左右表达式
        idx = 0
        while(idx < len(expText)):
            if (expText[idx] == '+'):
                left = stack.pop()
                idx += 1
                right = VarExpression(expText[idx])
                stack.push(AddExpression(left, right))
            elif(expText[idx] == '-'):
                left = stack.pop()
                idx += 1
                right = VarExpression(expText[idx])
                stack.push(SubExpression(left, right))
            else:
                stack.push(VarExpression(expText[idx]))
            idx += 1
        return stack.pop()

    def run(self, var):
        return self.__expression.interpreter(var)


# main function
def main_solution(expression_str, variable_values):
    """
    Main function to evaluate a mathematical expression using a calculator.

    Parameters:
    expression_str (str): A string representing the mathematical expression to be evaluated.
    variable_values (dict): A dictionary mapping variable names to their corresponding float values.

    Returns:
    float: The result of the evaluated expression.
    """
    # Convert the expression string to a list of tokens
    new_exp = []
    pre_idx = 0
    for i in range(len(expression_str)):
        if expression_str[i] in ['+', '-']:
            new_exp.append(expression_str[pre_idx:i].strip())
            new_exp.append(expression_str[i])
            pre_idx = i + 1
    new_exp.append(expression_str[pre_idx:].strip())

    # Create the calculator and run the expression
    calculator = Calculator(new_exp)
    result = calculator.run(variable_values)
    return result

