def solve(board):
    return solve_(board, 0, 0, len(board))

def solve_(board, i, j, size):
    if i >= size or j >= size:
        return check(board, len(board))
    if board[i][j] > 0:
        if i == size-1 and j == size-1:
            return check(board, len(board))
        x, y = next(i, j, size)
        if x > i:
            if not check_row(board, i, size):
                return False
        return solve_(board, x, y, size)
    else:
        for value in range(1, size + 1):
            board[i][j] = value * -1
            x, y = next(i, j, size)
            if y > j and i == size-1:
                if not check_col(board, j, size):
                    continue
            if solve_(board, x, y, size):
                return True
    return False

def next(i, j, size):
    if j < size - 1:
        return i, j + 1
    else:
        return i + 1, 0

def check_row(board, row, size):
    hash = {}
    for col in range(0, size):
        value = abs(board[row][col])
        if value not in range(1, size + 1):
            return False
        elif value in hash:
            return False
        hash[value] = value
    return True

def check_col(board, col, size):
    hash = {}
    for row in range(0, size):
        value = abs(board[row][col])
        if value not in range(1, size + 1):
            return False
        elif value in hash:
            return False
        hash[value] = value
    return True

def check(board, size):
    for row in range(0, size):
        if not check_row(board, row, size):
            return False
    for col in range(0, size):
