# import necessary packages
import copy
import math

# Constants
EMPTY = None
X = "X"
O = "O"

# Function to create an empty Tic-Tac-Toe table
def createTable():
    return [[EMPTY, EMPTY, EMPTY],
            [EMPTY, EMPTY, EMPTY],
            [EMPTY, EMPTY, EMPTY]]

# Function to determine the current player
def playeris(Table):
    countx = sum(row.count(X) for row in Table)
    county = sum(row.count(O) for row in Table)
    return X if countx <= county else O

# Function to get all possible actions (empty cells)
def actions(Table):
    return [(i, j) for i in range(3) for j in range(3) if Table[i][j] == EMPTY]

# Function to get the result of taking an action
def result(Table, action):
    newTable = copy.deepcopy(Table)
    newTable[action[0]][action[1]] = playeris(newTable)
    return newTable

# Function to check if a player has won by rows
def row_win(Table, player):
    return any(all(cell == player for cell in row) for row in Table)

# Function to check if a player has won by columns
def col_win(Table, player):
    return any(all(Table[i][j] == player for i in range(3)) for j in range(3))

# Function to check if a player has won by diagonals
def diag_win(Table, player):
    return all(Table[i][i] == player for i in range(3)) or all(Table[i][2 - i] == player for i in range(3))

# Function to determine the winner
def winneris(Table):
    for player in [X, O]:
        if row_win(Table, player) or col_win(Table, player) or diag_win(Table, player):
            return player
    return EMPTY

# Function to determine if the game is over
def terminal(Table):
    return winneris(Table) != EMPTY or not any(EMPTY in row for row in Table)

# Function to calculate the utility of the table
def utility(Table):
    winner = winneris(Table)
    return 1 if winner == X else -1 if winner == O else 0

# Minimax algorithm to determine the optimal action
def minimax(Table):
    if terminal(Table):
        return EMPTY

    def max_value(Table):
        if terminal(Table):
            return utility(Table)
        v_max = -math.inf
        for action in actions(Table):
            v_max = max(v_max, min_value(result(Table, action)))
        return v_max

    def min_value(Table):
        if terminal(Table):
            return utility(Table)
        v_min = math.inf
        for action in actions(Table):
            v_min = min(v_min, max_value(result(Table, action)))
        return v_min

    if playeris(Table) == X:
        v = -math.inf
        for action in actions(Table):
            t = min_value(result(Table, action))
            if t > v:
                v = t
                opt_action = action
    else:
        v = math.inf
        for action in actions(Table):
            t = max_value(result(Table, action))
            if t < v:
                v = t
                opt_action = action
    return opt_action

