# import necessary packages
import math

# main function
def main_solution(n):
    # Convert the input to an integer if it's not already
    n = int(n)

    # Calculate the logarithm base 10 of n factorial
    def factLog10(n):
        if n != 0:
            return (math.log(2 * math.pi * n) / 2 + n * (math.log(n) - 1)) / math.log(10)
        else:
            return 0

    # Calculate the number of digits in n factorial
    def factorialDigits(n):
        return math.ceil(factLog10(n))

