# import necessary packages
import random

# all class and function definitions in the code file, if any
class Node:
    def __init__(self, name):
        self.name = name
        self.neighbors = []

    __slots__ = ('name', 'neighbors')

    def __str__(self):
        result = self.name + ' : '
        for n in self.neighbors:
            result += n.name + ', '
        return result[:-1]

def buildWordGraph(words):
    w = {}
    for word in words:
        for i in range(len(word)):
            wcard = word[:i] + '*' + word[i + 1:]
            if wcard in w:
                w[wcard].append(word)
            else:
                w[wcard] = [word]

    for key in w:
        wordlist = w[key]
        for w1 in wordlist:
            for w2 in wordlist:
                if w1 != w2:
                    inputGraph(w1, w2)

def inputGraph(word1, word2):
    if word1 not in Graph:
        node = Node(word1)
        node.neighbors.append(Node(word2))
        Graph[word1] = node
    else:
        neighbors = Graph[word1].neighbors
        if word2 not in [x.name for x in neighbors]:
            neighbors.append(Node(word2))

    if word2 not in Graph:
        node = Node(word2)
        node.neighbors.append(Node(word1))
        Graph[word2] = node
    else:
        neighbors = Graph[word2].neighbors
        if word1 not in [x.name for x in neighbors]:
            neighbors.append(Node(word1))

class Queue:
    def __init__(self):
        self.queue = []

    def enqueue(self, item):
        self.queue.append(item)

    def dequeue(self):
        return self.queue.pop(0)

    def empty(self):
        return self.queue == []

def bfs(start, finish, Graph):
    parents = {}
    q = Queue()
    q.enqueue(start)
    parents[start.name] = None

    while not q.empty():
        node = q.dequeue()
        for neighbor in node.neighbors:
            n = neighbor.name
            if n not in parents:
                parents[n] = node.name
                if n == finish.name:
                    return parents
