def complemento(letra):
    if len(letra) == 1:
        complemento = '-' + letra
        return complemento
    elif (letra[0] == '-'):
        return letra[1]
    else:
        raise ValueError(f"error, literal invalido {letra}")

def hay_unidad(S):
    for x in S:
        if len(x) == 1:
            return x[0]
    return None

def unit_propagate(S, I):
    unidad = hay_unidad(S)
    while ([] not in S) and (unidad != None):
        Comple = complemento(unidad)
        S = [c for c in S if unidad not in c]
        count = 0
        for c in S:
            if Comple in c:
                c = [x for x in c if x != Comple]
                S[count] = c
            count += 1

        if '-' in unidad:
            I[unidad] = 0
        else:
            I[unidad] = 1
        unidad = hay_unidad(S)
    return S, I

def DPLL(S,I):
    S, I = unit_propagate(S,I)
    if [] in S:
