# import necessary packages
import random

# all class and function definitions in the code file, if any
class MatExcept(Exception):
    pass

class Matrix:

    def __init__(self, m, n = None):
        self.mat = []

        if type(m) == list and type(m[0]) is list and n is None:
            self.m = len(m)
            self.n = len(m[0])

            self.init_mat()
            for i in range(self.m):
                for j in range(self.n):
                    self[i, j] = m[i][j]

        elif type(m) is list and n is None:
            self.m = len(m)
            self.n = 1

            self.init_mat()
            for i in range(self.m):
                self[i, 0] = m[i]

        else:
            self.m = m
            self.n = n
            self.init_mat()

    def init_mat(self):
        for i in range(self.m):
            for j in range(self.n):
                self.mat.append(0)        

    def __getitem__(self, idx):
        linear_index = idx[1] * self.m + idx[0]      
        return self.mat[linear_index]

    def __setitem__(self, idx, c):
        if idx[0] >= self.m or idx[0] < 0: raise MatExcept("Matrix: row out of range")
        if idx[1] >= self.n or idx[1] < 0: raise MatExcept("Matrix: col out of range")        

        linear_index = idx[1] * self.m + idx[0]
        self.mat[linear_index] = c

    def __add__(self, m2):
        if self.m == m2.m and self.n == m2.n:
            new_mat = []
            for i in range(len(self.mat)):
                new_mat.append(self.mat[i] + m2.mat[i])

            mnew = Matrix(self.m, self.n)
            mnew.mat = new_mat
            return mnew

        else:
            raise MatExcept("Matrix: addition not same size")

    def __sub__(self, m2):
        if self.m == m2.m and self.n == m2.n:
            new_mat = []
            for i in range(len(self.mat)):
                new_mat.append(self.mat[i] - m2.mat[i])

            mnew = Matrix(self.m, self.n)
            mnew.mat = new_mat
            return mnew

        else:
            raise MatExcept("Matrix: subtraction not same size") 

    def __mul__(self, m2):
        if self.n == m2.m:
            mulmat = Matrix(self.m, m2.n)
            for i in range(mulmat.m):
                for j in range(mulmat.n):
                    for m in range(self.n):
                        mulmat[i, j] += self[i, m] * m2[m, j]
            return mulmat       
        else:
            raise MatExcept("Matrix: multiplication columns diff then rows")

    def scalar(self, k):
        mat_new = []
        for m in self.mat:
            mat_new.append(m * k)

        mres = Matrix(self.m, self.n)
        mres.mat = mat_new

        return mres

    def transpose(self):
        tmat = Matrix(self.n, self.m)

        for i in range(self.m):
            for j in range(self.n):
                tmat[j, i] = self[i, j]
        return tmat

    def __str__(self):
        s = ""
        for i in range(self.m):
            for j in range(self.n):
                s += str(self[i, j]) + " "
            s += "\n"

        return s

def levenshtein(seq1, seq2):
    size_x = len(seq1) + 1
    size_y = len(seq2) + 1
    matrix = Matrix(size_x, size_y)

    for x in range(size_x):
        matrix [x, 0] = x

    for y in range(size_y):
        matrix [0, y] = y

    for x in range(1, size_x):
        for y in range(1, size_y):
            if seq1[x-1] == seq2[y-1]:
                matrix [x,y] = min(
                    matrix[x-1, y] + 1,
                    matrix[x-1, y-1],
                    matrix[x, y-1] + 1
                )
            else:
                matrix [x,y] = min(
                    matrix[x-1,y] + 1,
                    matrix[x-1,y-1] + 1,
                    matrix[x,y-1] + 1
                )
    return (matrix[size_x - 1, size_y - 1])

# main function
def main_solution(seq1, seq2):
    # Convert input strings to lists of characters
    seq1 = list(seq1)
    seq2 = list(seq2)

    # Calculate the Levenshtein distance
    distance = levenshtein(seq1, seq2)

    # Return the distance as an integer
    return distance

