# import necessary packages
import random

# all class and function definitions in the code file, if any
class ToyRobot:
    def __init__(self):
        self.dim = 6
        self.pointer_x = 0
        self.pointer_y = 0
        self.saved_direction = 'EAST'
        self.dirs = ['NORTH', 'SOUTH', 'EAST', 'WEST', 'NORTH EAST', 'SOUTH EAST', 'NORTH WEST', 'SOUTH WEST']
        self.table = {}
        self.intialise()

    def intialise(self):
        for i in range(self.dim):
            for j in range(self.dim):
                self.table[i, j] = 0

    def validation(self, num):
        return 0 <= num < self.dim

    def obstruction(self, xx, yy):
        x = int(xx)
        y = int(yy)
        return self.table[x, y] != 2

    def set_place(self, xx, yy, direction):
        x = int(xx)
        y = int(yy)
        if self.validation(x) and self.validation(y) and self.obstruction(x, y):
            self.table[x, y] = 1
            self.pointer_x = x
            self.pointer_y = y
            self.saved_direction = direction

    def set_move(self):
        moves = {
            'NORTH': (0, 1), 'SOUTH': (0, -1), 'EAST': (1, 0), 'WEST': (-1, 0),
            'NORTH EAST': (1, 1), 'SOUTH EAST': (1, -1), 'NORTH WEST': (-1, 1), 'SOUTH WEST': (-1, -1)
        }
        dx, dy = moves[self.saved_direction]
        new_x, new_y = self.pointer_x + dx, self.pointer_y + dy
        if self.validation(new_x) and self.validation(new_y) and self.obstruction(new_x, new_y):
            self.table[new_x, new_y] = 1
            self.pointer_x, self.pointer_y = new_x, new_y

    def set_left(self):
        idx = self.dirs.index(self.saved_direction)
        self.saved_direction = self.dirs[(idx - 1) % len(self.dirs)]

    def set_right(self):
        idx = self.dirs.index(self.saved_direction)
        self.saved_direction = self.dirs[(idx + 1) % len(self.dirs)]

# main function
def main_solution(initial_x, initial_y, initial_direction, commands):
    robot = ToyRobot()
    robot.set_place(initial_x, initial_y, initial_direction)

    for command in commands:
        if command == 'MOVE':
            robot.set_move()
        elif command == 'LEFT':
            robot.set_left()
        elif command == 'RIGHT':
            robot.set_right()

    return {
        "final_x": robot.pointer_x,
        "final_y": robot.pointer_y,
        "final_direction": robot.saved_direction
    }

