    max_p = max(plist)
    ubound = 10**(int(math.log10(max_p))+2)
    ind = [True]*(ubound - max_p+1)
    for p in plist:
        start = p - max_p % p
        if start == 0:
            start += p
        for j in range(start, len(ind), p):
            ind[j] = False
    for j in range(1, len(ind)):
        if ind[j]:
            ret_val.append(max_p + j)
    return ret_val

