    if iscomplete(sb.CurrentGameBoard):
        return sb
    else:
        BoardArray = sb.CurrentGameBoard
        size = len(BoardArray)
        for row in range(size):
            for col in range(size):
                if BoardArray[row][col] == 0:
                    for val in range(1, size + 1):
