# import necessary packages
import random

# all class and function definitions in the code file, if any
def rotate(numbers):
    x = []
    for n in range(len(str(numbers))):
        x.append(str(numbers)[n])
    y = x.pop()
    x.insert(0, y)
    return int("".join(x))

def isprime(number):
    if number < 2:
        return False
    if number == 2:
        return True
    if number % 2 == 0:
        return False
    for x in range(3, int(number**0.5)+1, 2):
        if number % x == 0:
            return False
    return True

def iscircular(number):
    primes = []
    for i in range(len(str(number))):
        if number % 2 == 0:
            return False
        elif not isprime(number):
            return False
        else:
            primes.append(number)
            number = rotate(number)
    return primes

# main function
def main_solution(limit):
    circulars = [2]
    for i in range(3, limit, 2):
        if i not in circulars:
            primes = iscircular(i)
            if primes:
                for p in primes:
                    if p not in circulars:
                        circulars.append(p)
    return len(circulars)

