    def LegalValuesOfNeighbors(self):
        count = 0 
        for neighbor in self.getNeighbors():
            count += len(neighbor.legalValues)
        return count

# main function
def main_solution(board_size, source_position, target_position, all_colors):
    # Convert JSON serializable inputs to original input variables
    variables = []
    for i in range(board_size):
        for j in range(board_size):
            variables.append(Variable((i, j), '0'))

    source_var = Variable.getVarByPos(source_position, variables)
