# import necessary packages
import re
from functools import partial

# all class and function definitions in the code file, if any
class Infix(object):
    def __init__(self, func):
        self.func = func
    def __or__(self, other):
        return self.func(other)
    def __ror__(self, other):
        return Infix(partial(self.func, other))
    def __call__(self, v1, v2):
        return self.func(v1, v2)

@Infix
def implies(p, q):
    return not p or q

@Infix
def iff(p, q):
    return (p |implies| q) and (q |implies| p)

def extract_variables(expression):
    sorted_variable_set = sorted(set(re.findall(r'\b[a-z]\b', expression)))
    return sorted_variable_set

def truth_table(expression):
    variables = extract_variables(expression)
    rows = 2 ** len(variables)
    width = len(variables)
    list1 = list()
    for ii in range(rows):
        current = bin(ii)[2:].zfill(width)
        thisList = list()
        for letter in str(current):
            if letter == '1':
                letter = 'True'
                thisList.append(letter)
            else:
                letter = 'False'
                thisList.append(letter)
        for xx in range(len(variables)):
            exec(variables[xx] + ' = ' + thisList[xx])

        thisList.append(eval(expression))
        list1.append(thisList)

    for xx in range(rows):
        for ii in range(len(variables)):
            if list1[xx][ii] == 'True':
                list1[xx][ii] = True
            if list1[xx][ii] == 'False':
                list1[xx][ii] = False

    return list1[::-1]

def count_satisfying(expression):
    list1 = truth_table(expression)
    count = 0
    for xx in range(len(list1)):
        list2 = list1[xx]
        if (list2[len(list2)-1] == True):
            count = count + 1

    return count

def is_tautology(expression):
    list1 = truth_table(expression)
    count = 0
    for xx in range(len(list1)):
        list2 = list1[xx]
        if (list2[len(list2)-1] == True):
            count = count + 1
    if (count == len(list1)):
        return True
    return False

def are_equivalent(expr1, expr2):
    variables1 = extract_variables(expr1)
    variables2 = extract_variables(expr2)
    if (variables1 != variables2):
        return False
    list1 = truth_table(expr1)
    list2 = truth_table(expr2)
    if (list1 != list2):
        return False

    return True

# main function
def main_solution(expression1, expression2):
    # Convert input expressions to boolean expressions
    expr1 = expression1
    expr2 = expression2

    # Check if the expressions are equivalent
    result = are_equivalent(expr1, expr2)

    # Return the result as a boolean
    return result

