# import necessary packages
import random

# all class and function definitions in the code file, if any
class Node:
    def __init__(self, data=None, next=None):
        self.data = data
        self.next = next

    def __str__(self):
        return str(self.data)

class LinkedList:
    def __init__(self, head=None):
        self.head = head

    def __len__(self):
        curr = self.head
        counter = 0
        while curr is not None:
            counter += 1
            curr = curr.next
        return counter

    def __str__(self):
        data_list = []
        head = self.head
        while head:
            data_list.append(str(head.data))
            head = head.next
        return ' '.join(data_list)

    def append(self, data):
        new_node = Node(data)
        if not self.head:
            self.head = new_node
        else:
            head = self.head
            while head.next:
                head = head.next
            head.next = new_node

    def the_last_k_node(self, k):
        if k <= 0:
            return None
        if not self.head:
            return None
        pre = self.head
        for i in range(0, k):
            if pre.next:
                pre = pre.next
            else:
                return None
        p = self.head
        while pre.next:
            pre = pre.next
            p = p.next
        return p

def merge_to_sorted_list(l1, l2):
    if not l1.head:
        return l2.head
    if not l2.head:
        return l1.head

    p1 = l1.head
    p2 = l2.head
    p_head = None
    p3 = Node()

    while p1 and p2:
        if p1.data <= p2.data:
            if not p_head:
                p_head = p1
            p3.next = p1
            p1 = p1.next
        else:
            if not p_head:
                p_head = p2
            p3.next = p2
            p2 = p2.next
        p3 = p3.next

    if p1:
        p3.next = p1
    elif p2:
        p3.next = p2
    return p_head

# main function
def main_solution(list1, list2, k):
    # Convert input strings to LinkedList objects
    l1 = LinkedList()
    l2 = LinkedList()

    for data in list1.split():
        l1.append(int(data))

    for data in list2.split():
        l2.append(int(data))

    # Merge the two sorted lists
    merged_head = merge_to_sorted_list(l1, l2)
    merged_list = LinkedList(merged_head)

    # Find the last k-th node in the merged list
    last_k_node = merged_list.the_last_k_node(k)

    # Return the data of the last k-th node
    return last_k_node.data if last_k_node else None

