# import necessary packages
import random

# all class and function definitions in the code file, if any
def findModulo(a, b, c):
    if a == 0:
        return 0
    if b == 0:
        if c == 1:
            return 0
        return 1
    temp = 0
    if b % 2 == 0:
        temp = findModulo(a, b / 2, c) % c
        temp = (temp * temp) % c
    else:
        temp = a % c
        temp = (temp * (findModulo(a, b - 1, c) % c)) % c
    return (temp + c) % c

def findPowerTerms(x):
    s = 0
    while x % 2 == 0:
        s += 1
        x = x / 2
    return s, x

def isMillerRabinPrime(n):
    if n < 2:
        return False
    if n == 2 or n == 3:
        return True
    s, d = findPowerTerms(n - 1)
    a = 2
    if findModulo(a, d, n) == 1:
        return True
    for i in range(s):
        if findModulo(a, (2 ** i) * d, n) == n - 1:
            return True
    return False

def isTruePrime(x):
    if x <= 1:
        return False
    if x <= 3:
        return True
    if x % 2 == 0 or x % 3 == 0:
        return False
    i = 5
    while (i * i <= x):
        if x % i == 0 or x % (i + 2) == 0:
            return False
        i = i + 6
    return True

# main function
def main_solution(n):
