import random

# all class and function definitions in the code file, if any
def is_exact(n):
    orig = n
    i = 1
    while True:
        if n % i == 0:
            n //= i
        else:
            break
        i += 1
    if n == 1:
        return [orig, i - 1]
    else:
        return 'Not Exact'

def prime_divisors(num):
    factors = [1]
    final = []
    d = 2
    while d * d <= num:
        while num > 1:
            while num % d == 0:
                factors.append(d)
                num = num / d
            d += 1
    final_set = set(factors)
    final = list(final_set)
    return final

def subArraySum(arr, sum):
    n = len(arr)
    for i in range(n):
        curr_sum = arr[i]
        j = i + 1
        while j <= n:
            if curr_sum == sum:
                return 1
            if curr_sum > sum or j == n:
                break
            curr_sum = curr_sum + arr[j]
            j += 1
    return 0

