# import necessary packages
import random

# all class and function definitions in the code file, if any
class Node(object):
    def __init__(self, name):
        self.name = str(name)
    def getName(self):
        return self.name
    def __str__(self):
        return self.name

class Edge(object):
    def __init__(self, src, dest):
        self.src = src
        self.dest = dest
    def getSource(self):
        return self.src
    def getDestination(self):
        return self.dest
    def __str__(self):
        return str(self.src) + '->' + str(self.dest)

class Digraph(object):
    def __init__(self):
        self.nodes = set([])
        self.edges = {}

    def addNode(self, node):
        if node in self.nodes:
            raise ValueError('Duplicate node')
        else:
            self.nodes.add(node)
            self.edges[node] = []

    def addEdge(self, edge):
        src = edge.getSource()
        dest = edge.getDestination()
        if not(src in self.nodes and dest in self.nodes):
            raise ValueError('Node not in graph')
        self.edges[src].append(dest)

    def childrenOf(self, node):
        return self.edges[node]

    def hasNode(self, node):
        return node in self.nodes

    def __str__(self):
        res = ''
        for k in self.edges:
            for d in self.edges[k]:
                res = res + str(k) + '->' + str(d) + '\n'
        return res[:-1]

class Graph(Digraph):
    def addEdge(self, edge):
        Digraph.addEdge(self, edge)
        rev = Edge(edge.getDestination(), edge.getSource())
        Digraph.addEdge(self, rev)

def getNodes():
    nodes = []
    nodes.append(Node("ABC"))
    nodes.append(Node("ACB"))
    nodes.append(Node("BAC"))
    nodes.append(Node("BCA"))
    nodes.append(Node("CAB"))
    nodes.append(Node("CBA"))
    return nodes

def add_edges(nodes, graph):
    for n in nodes:
        copy = nodes[:]
        s1 = n.getName()[0:2]
        s1r = s1[::-1]
        s2 = n.getName()[1:]
        s2r = s2[::-1]
        copy.remove(n)
        findEdges(n, [s1r, s2r], copy, graph)

def findEdges(node, pairs, others, graph):
    for n in others:
        s1 = n.getName()[0:2]
        s2 = n.getName()[1:]
        if s1 == pairs[0]:
            edge = Edge(node, n)
            if node not in graph.childrenOf(n):
                graph.addEdge(edge)
        elif s2 == pairs[1]:
            edge = Edge(node, n)
            if node not in graph.childrenOf(n):
                graph.addEdge(edge)

