    nodes = getNodes()
    start_node = None
    end_node = None

    for node in nodes:
        if node.getName() == start_node_name:
            start_node = node
        if node.getName() == end_node_name:
            end_node = node

    if not start_node or not end_node:
        raise ValueError('Node not found')

    g = Graph()
    for n in nodes:
        g.addNode(n)
    add_edges(nodes, g)

    # Find the path from start_node to end_node
    path = findPath(g, start_node, end_node)

    if path:
        return printPath(path)
    else:
        return "No path found"

def findPath(graph, start, end, path=[]):
    path = path + [start]
    if start == end:
        return path
    for node in graph.childrenOf(start):
        if node not in path:
            newpath = findPath(graph, node, end, path)
            if newpath: return newpath
    return None

def printPath(path):
    result = ''
    for i in range(len(path)):
        if i == len(path) - 1:
            result = result + str(path[i])
        else:
            result = result + str(path[i]) + '->'
    return result

