class DisjointSet:
    def __init__(self):
        """
        unbalanced DisjointSet
        """
        self.pi = {}

    def union(self, x, y):
        pi_x = self.find(x)
        pi_y = self.find(y)
        self.pi[pi_y] = pi_x

    def find(self, x):
        if x not in self.pi:
            self.pi[x] = x
        if self.pi[x] != x:
            self.pi[x] = self.find(self.pi[x])
        return self.pi[x]

class Solution:
    def regionsBySlashes(self, grid: List[str]) -> int:
        m, n = len(grid), len(grid[0])
        ds = DisjointSet()
        T, R, B, L = range(4)  # top, right, bottom, left
        for i in range(m):
            for j in range(n):
                e = grid[i][j]
                if e == "/" or e == " ":
                    ds.union((i, j, B), (i, j, R))
                    ds.union((i, j, T), (i, j, L))
                if e == "\\" or e == " ":  # not elif
                    ds.union((i, j, T), (i, j, R))
                    ds.union((i, j, B), (i, j, L))
                # nbr
                if i - 1 >= 0:
                    ds.union((i, j, T), (i-1, j, B))
                if j - 1 >= 0:
                    ds.union((i, j, L), (i, j-1, R))

        return len(set(
            ds.find(x)
            for x in ds.pi.keys()
        ))

