class Sapper:
    def __init__(self, rows, columns, bombs_number):
        self.rows = rows
        self.columns = columns
        self.bombs_number = bombs_number
        self.field = [['x'] * self.columns for _ in range(self.rows)]
        self.bombs = [[0] * self.columns for _ in range(self.rows)]

    def generate_bombs(self):
        generated = 0
        while generated < self.bombs_number:
            row = random.randint(0, self.rows - 1)
            column = random.randint(0, self.columns - 1)
            if self.bombs[row][column] == 0:
                self.bombs[row][column] = -1
                generated += 1

    def win_condition(self):
        pairs = list(zip(sum(self.field, []), sum(self.bombs, [])))
        return pairs.count(('?', -1)) == self.bombs_number

    def count_bombs(self):
        for i in range(self.rows):
            for j in range(self.columns):
                if self.bombs[i][j] > -1:
                    for di in [-1, 0, 1]:
                        for dj in [-1, 0, 1]:
                            if 0 <= i + di < self.rows and 0 <= j + dj < self.columns and self.bombs[i + di][j + dj] == -1:
                                self.bombs[i][j] += 1

    def open(self, row, column):
        if row < 0 or row >= self.rows or column < 0 or column >= self.columns or self.field[row][column] != 'x':
            return
        if self.bombs[row][column] > 0:
            self.field[row][column] = str(self.bombs[row][column])
        elif self.bombs[row][column] == 0:
            self.field[row][column] = '0'
            for di in [-1, 0, 1]:
                for dj in [-1, 0, 1]:
                    self.open(row + di, column + dj)

    def set_flag(self, row, column):
        if self.field[row][column] == 'x':
            self.field[row][column] = '?'
        elif self.field[row][column] == '?':
            self.field[row][column] = 'x'

# main function
def main_solution(rows, columns, bombs_number, actions):
    game = Sapper(rows, columns, bombs_number)
    game.generate_bombs()
    game.count_bombs()

    for action in actions:
        row, column, action_type = action
        if action_type == 'Open':
            if game.bombs[row][column] == -1:
                return "LOST"
            game.open(row, column)
        else:
            game.set_flag(row, column)

        if game.win_condition():
            return "WON"

    return "IN_PROGRESS"

