    BARAQUE = 3
    TIERCE = 2
    NENETTE = 1
    AUTRE = 0

    def __ge__(self, other):
        if self.__class__ is other.__class__:
            return self.value >= other.value
        return NotImplemented

    def __gt__(self, other):
        if self.__class__ is other.__class__:
            return self.value > other.value
        return NotImplemented

    def __le__(self, other):
        if self.__class__ is other.__class__:
            return self.value <= other.value
        return NotImplemented

    def __lt__(self, other):
        if self.__class__ is other.__class__:
            return self.value < other.value
        return NotImplemented

class Combinaison:
    def __init__(self, elements):
        self.elements = sorted(elements, reverse=True)
        self.valeur, self.type_comb = self.trouver_valeur(self.elements)

    def est_nenette(self):
        return self.elements == [2, 2, 1]

    def __lt__(self, other):
        if self.valeur < other.valeur:
            return True
        elif self.valeur == other.valeur:
            if self.type_comb.value < other.type_comb.value:
                return True
            elif self.type_comb.value == other.type_comb.value:
                return self.elements < other.elements
        return False

    def __eq__(self, other):
        return self.elements == other.elements

    def __gt__(self, other):
        if self.valeur > other.valeur:
            return True
        elif self.valeur == other.valeur:
            if self.type_comb.value > other.type_comb.value:
                return True
            elif self.type_comb.value == other.type_comb.value:
                return self.elements > other.elements
        return False

    def __str__(self):
        return ''.join(map(str, self.elements))

    @staticmethod
