        if representant == [4, 2, 1]:
            return 10, TypeComb.LE421
        elif representant in [[6, 1, 1], [5, 1, 1], [4, 1, 1], [3, 1, 1], [2, 1, 1]]:
            return representant[0], TypeComb.FICHE
        elif representant in [[2, 2, 2], [3, 3, 3], [4, 4, 4], [5, 5, 5], [6, 6, 6], [1, 1, 1]]:
            return 7 if representant == [1, 1, 1] else representant[0], TypeComb.BARAQUE
        elif representant in [[6, 5, 4], [5, 4, 3], [4, 3, 2], [3, 2, 1]]:
            return 2, TypeComb.TIERCE
        elif representant == [2, 2, 1]:
            return 4, TypeComb.NENETTE
        else:
            return 1, TypeComb.AUTRE

