        elif win_or_not == "O":
            return 1
        elif win_or_not == "Tie":
            return 0
    if AI:
        best_score = -40360
        for i in range(len(grid)):
            for j in range(len(grid[i])):
                if grid[i][j] == " ":
                    grid[i][j] = "O"
                    temp_score = DFS_minimax(grid, False)
                    grid[i][j] = " "
                    best_score = max(temp_score, best_score)
        return best_score
    else:
        best_score = 40360
        for i in range(len(grid)):
            for j in range(len(grid[i])):
                if grid[i][j] == " ":
                    grid[i][j] = "X"
                    temp_score = DFS_minimax(grid, True)
                    grid[i][j] = " "
                    best_score = min(temp_score, best_score)
        return best_score

