    # Convert the grid to a list of lists if it's not already
    if not isinstance(grid, list) or not all(isinstance(row, list) for row in grid):
        raise ValueError("Input grid must be a list of lists.")

    # Check if the grid is a 3x3 grid
    if len(grid) != 3 or not all(len(row) == 3 for row in grid):
        raise ValueError("Input grid must be a 3x3 grid.")

    # Check if the grid contains only valid characters (' ', 'X', 'O')
    valid_chars = {' ', 'X', 'O'}
    if not all(all(cell in valid_chars for cell in row) for row in grid):
        raise ValueError("Grid must contain only ' ', 'X', or 'O'.")

    # Determine the best move for the AI
