Given a structure definition in a programming language, where each field has a specific type and the structure can be either packed or unpacked, what is the total size of the structure in bytes, and what are the offsets of each field within the structure?

The input and output requirements are as follows:

Input:
  `struct_name` (str): The name of the struct.
  `fields` (list of dict): A list of dictionaries where each dictionary represents a field in the struct. Each dictionary contains:
    - `name` (str): The name of the field.
    - `type` (str): The type of the field, represented as a string that can be evaluated to create the corresponding type object (e.g., "Integer(32)").
  `packed` (bool): A boolean indicating whether the struct is packed or not.

Output:
  `return` (dict): A dictionary containing:
    - `struct_name` (str): The name of the struct.
    - `size` (int): The total size of the struct in bytes.
    - `field_offsets` (dict): A dictionary where the keys are field names and the values are the offsets of the fields within the struct.

Given the following input:

{'struct_name': 'Struct_21', 'fields': [{'name': 'field_0', 'type': 'Integer(16)'}], 'packed': True}

Can you predict the output without writing any code? Please reason and put your final answer in the following json format: {"output": <your output>}, where <your output> should strictly match the the output requirement as specified.

Tip: Here is a reference code snippet for this question. You can refer to this code to guide your reasoning but not copy spans of code directly.

# import necessary packages
from abc import ABC, abstractmethod
from collections import namedtuple
import random

# all class and function definitions in the code file, if any
# they will be used in the main_solution function, you may need to modify them to meet the requirements of the main_solution function (optional)
class Type(ABC):
    @abstractmethod
    def size(self):
        ...

class Integer(Type):
    def __init__(self, size):
        assert size % 8 == 0, "Integer size must be multiple of 8"
        self._size = size

    def size(self):
        return self._size // 8

class Pointer(Type):
    def __init__(self, target_type):
        self.target_type = target_type

    def offset(self, amount):
        return self.target_type.size() * amount

    def size(self):
        return 8

class Struct(Type):
    Field = namedtuple("Field", ["name", "type"])

    def __init__(self, name, fields, *, packed=False):
        self.name = name
        assert len(fields) != 0, "Empty struct"
        assert len(set(fields)) == len(fields), "Duplicate field name"
        self.fields = fields
        self.packed = packed

    def _field_offsets(self):
        offset = 0
        for field in self.fields:
            field_size = field.type.size()
            if not self.packed and offset != 0:
                offset = align(offset, to=field_size)
            yield field, offset
            offset += field_size

    def field_offset(self, name):
        for field, offset in self._field_offsets():
            if field.name == name:
                return offset

    def field_type(self, name):
        for field in self.fields:
            if field.name == name:
                return field.type

    def size(self):
        greatest_alignment = 0

        for field, offset in self._field_offsets():
            field_size = field.type.size()
            if field_size > greatest_alignment:
                greatest_alignment = field_size

        subtotal = offset + field_size
        return align(subtotal, to=greatest_alignment)

class Array(Type):
    def __init__(self, element_type, length):
        assert length >= 0, "Negative array length"
        self.element_type = element_type
        self.length = length

    def index_offset(self, index):
        assert abs(index) < self.length, "Index out of bounds"
        index = (self.length + index) % self.length
        return index * self.element_type.size()

    def size(self):
        return self.element_type.size() * self.length

class Function(Type):
    def __init__(self, argument_types, return_type):
        self.argument_types = argument_types
        self.return_type = return_type

    def size(self):
        return 8  # pointer

def align(value, to):
    if value % to == 0:
        return value
    return value + (to - (value % to))

# main function
def main_solution(struct_name, fields, packed):
    # all input arguments of the main_solution function should be json serializable (no self-defined objects, functions, np.array, set, tuple, etc.)
    # if you need to invoke functions that require non-json serializable inputs, like those defined in the reference code file, you need to convert them (optional)
    fields_list = [Struct.Field(name=field['name'], type=eval(field['type'])) for field in fields]
    struct_instance = Struct(name=struct_name, fields=fields_list, packed=packed)

    # return, the returned value must be json serializable (no self-defined objects, functions, np.array, set, tuple, etc.)
    return {
        "struct_name": struct_instance.name,
        "size": struct_instance.size(),
        "field_offsets": {field.name: struct_instance.field_offset(field.name) for field in fields_list}
    }

