Given a template string with placeholders for variables, how can we replace these placeholders with specific values provided in a dictionary to generate a complete and meaningful message? Specifically, what is the resulting message after substituting the variables in the template with their corresponding values?

The input and output requirements are as follows:

Input:
  `template` (str): A string representing the template with placeholders for variables. Placeholders can be in the form `{variable_name}` for required variables or `[optional_part]` for optional parts.
  `variables` (Dict[str, str]): A dictionary where keys are variable names (as they appear in the template) and values are the corresponding values to be substituted in the template.

Output:
  `return` (str): A string where all the placeholders in the template have been replaced with the corresponding values from the `variables` dictionary. If any required variables are missing, a `KeyError` will be raised.

Given the following input:

{'template': 'Hello {name}, your order number is {order_number}[ and your tracking number is {tracking_number}].', 'variables': {'name': 'AYdGG', 'order_number': '996458', 'tracking_number': '4FXKGD0ZDo'}}

Can you predict the output without writing any code? Please reason and put your final answer in the following json format: {"output": <your output>}, where <your output> should strictly match the the output requirement as specified.

Tip: Here is a reference code snippet for this question. You can refer to this code to guide your reasoning but not copy spans of code directly.

# import necessary packages
import re
import itertools
import glob
from typing import List, Sequence, Set, Tuple, Dict, Iterator

# all class and function definitions in the code file, if any
class Part:
    def fill_known(self, variables) -> Sequence["Part"]:
        return [self]

    def optional_variables(self, ) -> Set["Part"]:
        return set()

    def required_variables(self, ) -> Set["Part"]:
        return set()

    def contains_optionals(self, variables: Set["Part"]=None):
        return False

    def append_variables(self, variables: List[str]):
        pass


class Literal(Part):
    def __init__(self, text: str):
        self.text = text

    def __str__(self):
        return self.text


class Required(Part):
    def __init__(self, var_name, var_formatting=None):
        self.var_name = var_name
        self.var_formatting = var_formatting

    def __str__(self):
        if self.var_formatting is None:
            return '{' + self.var_name + '}'
        else:
            return '{' + self.var_name + ':' + self.var_formatting + '}'

    def fill_known(self, variables):
        if self.var_name in variables:
            return Template.parse(str(self).format(**variables)).parts
        return [self]

    def required_variables(self, ):
        return {self.var_name}

    def append_variables(self, variables):
        variables.append(self.var_name)


class Optional(Part):
    def __init__(self, sub_template: "Template"):
        self.sub_template = sub_template

    def __str__(self):
        return '[' + str(self.sub_template) + ']'

    def fill_known(self, variables):
        new_opt = self.sub_template.fill_known(variables)
        if len(new_opt.required_variables()) == 0:
            return Template.parse(str(new_opt)).parts
        return [Optional(new_opt)]

    def optional_variables(self, ):
        return self.sub_template.required_variables()

    def contains_optionals(self, variables=None):
        if variables is None and len(self.optional_variables()) > 0:
            return True
        return len(self.optional_variables().intersection(variables)) > 0

    def append_variables(self, variables):
        variables.extend(self.sub_template.ordered_variables())


class Template:
    def __init__(self, parts: Sequence[Part]):
        self.parts = tuple(parts)

    @classmethod
    def parse(cls, text: str) -> "Template":
        parts = []
        for optional_parts in re.split(r'(\[.*?\])', text):
            if len(optional_parts) > 0 and optional_parts[0] == '[' and optional_parts[-1] == ']':
                if '[' in optional_parts[1:-1] or ']' in optional_parts[1:-1]:
                    raise ValueError(f'Can not parse {text}, because unmatching square brackets were found')
                parts.append(Optional(Template.parse(optional_parts[1:-1])))
            else:
                for required_parts in re.split(r'(\{.*?\})', optional_parts):
                    if len(required_parts) > 0 and required_parts[0] == '{' and required_parts[-1] == '}':
                        if ':' in required_parts:
                            var_name, var_type = required_parts[1:-1].split(':')
                        else:
                            var_name, var_type = required_parts[1:-1], ''
                        parts.append(Required(var_name, var_type))
                    else:
                        parts.append(Literal(required_parts))
        return Template(parts)

    def __str__(self):
        return ''.join([str(p) for p in self.parts])

    def optional_variables(self, ) -> Set[str]:
