# import necessary packages
import math

# main function
def main_solution(n, x, y):
    # Convert the input variables to the required format
    n = int(n)
    x = int(x)
    y = int(y)

    # Helper function to solve the problem
    def solve(n, x, y):
        if n == 1:
            if x == 0 and y == 0:
                return 0
            elif x == 0 and y == 1:
                return 1
            elif x == 1 and y == 0:
                return 2
            else:
                return 3
        half = pow(2, n - 1)
        if x >= half and y >= half:
            return 3 * pow(half, 2) + solve(n - 1, x - half, y - half)
        elif x >= half and y < half:
            return 2 * pow(half, 2) + solve(n - 1, x - half, y)
        elif x < half and y >= half:
            return 1 * pow(half, 2) + solve(n - 1, x, y - half)
        else:
            return solve(n - 1, x, y)

    # Calculate the result
    result = solve(n, x, y)

    # Return the result
    return result

