# import necessary packages
import random

# all class and function definitions in the code file, if any
class MyPlayer:
    def __init__(self, payoff_matrix, number_of_iterations=None):
        self.opponent_move_record = []
        self.my_last_turn = None
        self.tactic = None
        self.found_tactic = None
        self.changed = False
        self.iterations_available = False
        self.steps = 0

        self.matrix_coop1 = payoff_matrix[0][0][0]
        self.matrix_coop2 = payoff_matrix[1][0][0]
        self.matrix_def1 = payoff_matrix[0][1][0]
        self.matrix_def2 = payoff_matrix[1][1][0]

        if number_of_iterations:
            self.iterations = number_of_iterations
            self.iterations_available = True
        else:
            self.iterations_available = False

        self.get_basic_tactic()

    def record_opponents_move(self, opponent_move):
        if opponent_move:
            self.opponent_move_record.append(True)
        else:
            self.opponent_move_record.append(False)

    def get_basic_tactic(self):
        if (self.matrix_coop1 + self.matrix_coop2) < (self.matrix_def1 + self.matrix_def2):
            self.basic_tactics = True
        else:
            self.basic_tactics = False
        self.tactic = self.basic_tactics

    def opponent_same_tactic(self):
        opponent_basic_move = self.opponent_move_record[0]
        opponent_same_tactic = False

        for i in range(1, self.steps):
            if self.opponent_move_record[i] == opponent_basic_move:
                opponent_same_tactic = True
            else:
                opponent_same_tactic = False
                break

        if opponent_same_tactic and self.opponent_move_record[-1]:
            if self.matrix_coop2 > self.matrix_def2:
                self.basic_tactics = True
                self.changed = True
            elif self.matrix_coop2 < self.matrix_def2:
                self.basic_tactics = False
                self.basic_tactics = True
            else:
                self.get_basic_tactic()

        elif opponent_same_tactic and not self.opponent_move_record[-1]:
            if self.matrix_coop1 > self.matrix_coop2:
                self.basic_tactics = False
                self.changed = True
            elif self.matrix_def1 < self.matrix_def2:
                self.basic_tactics = True
                self.changed = True
            else:
                self.get_basic_tactic()

    def get_opponent_tactic(self):
        if not self.changed:
            if (self.opponent_move_record[-1] == self.opponent_move_record[-2] == self.opponent_move_record[-3] == self.my_last_turn):
                if self.matrix_coop2 < self.matrix_def2:
                    self.found_tactic = False
                else:
                    self.found_tactic = True
                self.tactic = self.found_tactic
                self.changed = True
        else:
            if (self.opponent_move_record[-1] == self.opponent_move_record[-2] and self.my_last_turn != self.opponent_move_record[-1]):
                self.tactic = self.basic_tactics
                self.changed = False

    def opponent_cheating_check(self):
        for i in range(self.steps-1, self.steps-5, -1):
            if self.my_last_turn != self.opponent_move_record[i]:
                self.get_basic_tactic()
                self.changed = False
                break

    def move(self):
        if self.steps == 5 or self.steps == 6:
            self.get_opponent_tactic()
        elif self.steps == 10 and not self.changed:
            self.opponent_same_tactic()
        elif self.steps > 12 and self.steps % 5 == 0 and self.changed:
            self.opponent_cheating_check()

        self.steps += 1
        self.my_last_turn = self.tactic
        return self.tactic

# main function
def main_solution(payoff_matrix, number_of_iterations=None):
    player = MyPlayer(payoff_matrix, number_of_iterations)
    for _ in range(15):  # Simulate 15 moves
        opponent_move = random.choice([True, False])
        player.record_opponents_move(opponent_move)
        player_move = player.move()

    # Convert the final tactic to a JSON serializable output
    return {"final_tactic": player_move}

