def main_solution(expression: str, variables: dict = None) -> Any:
    """
    Evaluates a given mathematical expression with optional variables.

    :param expression: A string representing the mathematical expression to evaluate.
    :param variables: A dictionary containing variable names as keys and their corresponding values.
    :return: The result of the evaluated expression.
    """
    if variables is None:
        variables = {}
    try:
        return eval_(ast.parse(expression, mode='eval').body, variables)
    except UnsetValueException:
        return None

