def main_solution(board_size, whose_move):
    """
    Determines the winner of a checkers game based on the current state of the board and whose turn it is.

    Parameters:
    board_size (int): The size of the board (e.g., 8 for an 8x8 board).
    whose_move (int): The player whose turn it is (1 for RED, 2 for BLACK).

    Returns:
    str: The winner of the game ("Black" or "Red").
    """
    state = State(board_size=board_size, whose_move=Player(whose_move))
    return state.get_winner()

