# import necessary packages
import heapq
import random

# all class and function definitions in the code file, if any
class Grid(object):
    def __init__(self, lines):
        self.lines = [list(l) for l in lines]

    def __str__(self):
        return "\n".join([''.join(l) for l in self.lines])

    def iswalkable(self, x, y):
        return self.get(x, y) != "#"

    def set(self, x, y, v):
        if x < 0 or y < 0:
            return
        if y >= len(self.lines) or x >= len(self.lines[y]):
            return
        self.lines[y][x] = v

    def get(self, x, y):
        if x < 0 or y < 0:
            return "#"
        if y >= len(self.lines) or x >= len(self.lines[y]):
            return "#"
        return self.lines[y][x]

def findKeys(grid, start, passable, verbose=False):
    if verbose:
        print("Start from", start)
    first = (0, start)
    possibleEnds = {}
    h = []
    heapq.heappush(h, first)
    visited = {}

    while h:
        node = heapq.heappop(h)

        if verbose:
            print("at", node[1])
        dis = node[0]
        loc = node[1]
        if loc in visited:
            if verbose:
                print("Already visited", loc)
            continue
        visited[loc] = True
        neighbours = [
            (loc[0] + 1, loc[1]),
            (loc[0] - 1, loc[1]),
            (loc[0], loc[1] + 1),
            (loc[0], loc[1] - 1)
        ]

        for n in neighbours:
            c = grid.get(n[0], n[1])
            priority = dis + 1
            if n in visited:
                if verbose:
                    print("Been here before", n)
                continue

            if c == "#":
                # "#" is a wall, not interesting, but can't move here.
                continue
            elif c in passable:
                # Normal squares are visitable, but not interesting checkpoints.
                heapq.heappush(h, (priority, n))
            else:
                # Other things are interesting, keys/locked doors.
                if verbose:
                    print("found", c, "at dis", priority)
                if c == c.upper():
                    if verbose:
                        print("Going to a locked door %s isn't helpful." % c)
                    continue
                possibleEnds[c] = (priority, n, c)

    if verbose:
        print("Completed search")
    return possibleEnds

# main function
def main_solution(grid_lines, start_position):
    # Convert JSON serializable inputs to original input variables
    grid = Grid(grid_lines)
    start = tuple(start_position)

    keyCount = sum(1 for line in grid_lines for c in line if c.islower())

    first = (0, start, "")
    h = []
    heapq.heappush(h, first)
    visited = {}

    while h:
        node = heapq.heappop(h)
        dis, loc, keys = node

        keyString = ''.join(sorted(keys)) + str(loc[0]) + "," + str(loc[1])
        if keyString in visited:
            continue
        visited[keyString] = dis

        if len(keys) == keyCount:
            return dis

        passable = {'.': True, '@': True}
        for k in keys:
            passable[k] = True
            passable[k.upper()] = True

        nextStages = findKeys(grid, loc, passable)
        for k, s in nextStages.items():
            dis2, loc2, key = s
            n = (dis + dis2, loc2, keys + key)
            heapq.heappush(h, n)

    return -1  # In case no solution is found

