        self._player_locations = [None, None]
        self._parity = 0
        self._board = [[0 for _ in range(3)] for _ in range(3)]

    def actions(self):
        return [(i, j) for i in range(3) for j in range(3) if self._board[i][j] == 0]

    def result(self, action):
        new_state = GameState()
        new_state._board = [row[:] for row in self._board]
        new_state._board[action[0]][action[1]] = 1
        new_state._player_locations = self._player_locations[:]
        new_state._player_locations[self._parity] = action
        new_state._parity = 1 - self._parity
        return new_state

    def terminal_test(self):
