# import necessary packages
import random

# all class and function definitions in the code file, if any
class GoLCell:
    def __init__(self, state):
        self.state = state

    def getState(self):
        return self.state

    def isDead(self):
        return not self.state

    def isAlive(self):
        return self.state

    def die(self):
        self.state = 0
        return

    def live(self):
        self.state = 1
        return

    def __str__(self):
        if self.isAlive():
            return '#'
        return '-'

    def __repr__(self):
        return self.__str__()

class GoLBoard:
    def __init__(self, board):
        self.generation = 0
        self.board = board

    def update(self):
        temp_board = []
        for i in range(len(self.board)):
            temp_board.append([])
            row = self.board[i]
            for j in range(len(row)):
                cell = self.board[i][j]
                temp_board[i].append(GoLCell(cell.getState()))
                temp_cell = temp_board[i][j]
                neighborsSum = self.getNeighborsSum(i, j)
                if cell.isAlive():
                    if (neighborsSum != 2) and (neighborsSum != 3):
                        temp_cell.die()
                elif cell.isDead():
                    if (neighborsSum == 3):
                        temp_cell.live()
        self.board = temp_board
        self.generation += 1
        return

    def getNeighborsSum(self, x, y):
        total = 0
        deltas = [-1, 0, 1]
        for i in deltas:
            for j in deltas:
                newCellX = x + i
                newCellY = y + j
                if not ((newCellX == x) and (newCellY == y)):
                    if (newCellX >= 0) and (newCellY >= 0):
                        try:
                            total += self.board[newCellX][newCellY].getState()
                        except:
                            total += 0
        return total

    def getGeneration(self):
        return self.generation

    def isBoardDead(self):
        for row in self.board:
            for cell in row:
                if cell.isAlive():
                    return False
        return True

    def __str__(self):
        rep = 'Generation ' + str(self.generation) + ': \n'
        for row in self.board:
            for column in row:
                rep += str(column)
                rep += ' '
            rep += '\n'
        return rep

    def __repr__(self):
        rep = ''
        for row in self.board:
            for column in row:
                rep += str(column)
                rep += ' '
            rep += '\n'
        return rep

def makeRandomBoard(fillPercent=30, width=3, height=3):
    board = []
    threshold = fillPercent * 0.01
    for i in range(height):
        board.append([])
        for j in range(width):
            n = random.random()
            if n < threshold:
                board[i].append(GoLCell(1))
            else:
                board[i].append(GoLCell(0))
    return board

def parseBoard(boardString, live, dead):
    b = boardString.split('\n')
    board = []
    for i in range(len(b)):
        row = b[i]
        board.append([])
        for cell in row:
            if cell == live:
                board[i].append(GoLCell(1))
            elif cell == dead:
                board[i].append(GoLCell(0))
            elif cell == ' ':
                pass
    return board

def makeBoard(liveCells, width, height):
    board = []
    for i in range(height):
        board.append([])
        for j in range(width):
            if (i, j) in liveCells:
                board[i].append(GoLCell(1))
            else:
                board[i].append(GoLCell(0))
    return board

# main function
def main_solution(board_type, fill_percent=None, width=None, height=None, live_cells=None, board_string=None, live_char='#', dead_char='-'):
    if board_type == 'random':
        board = makeRandomBoard(fill_percent, width, height)
    elif board_type == 'custom':
        board = makeBoard(live_cells, width, height)
    elif board_type == 'string':
        board = parseBoard(board_string, live_char, dead_char)
    else:
        raise ValueError("Invalid board type")

    gol_board = GoLBoard(board)
    gol_board.update()
    return gol_board.getGeneration()

