    x_count = sum(row.count(X) for row in board)
    o_count = sum(row.count(O) for row in board)
    return X if x_count == o_count else O

# Function to get all possible actions
def actions(board):
    return [(i, j) for i in range(3) for j in range(3) if board[i][j] == EMPTY]

# Function to get the result of an action
def result(board, action):
    new_board = copy.deepcopy(board)
    i, j = action
    if new_board[i][j] != EMPTY:
        raise Exception("Invalid action")
    new_board[i][j] = player(board)
    return new_board

# Function to determine the winner
def winner(board):
    for i in range(3):
        if board[i][0] == board[i][1] == board[i][2] != EMPTY:
            return board[i][0]
        if board[0][i] == board[1][i] == board[2][i] != EMPTY:
            return board[0][i]
    if board[0][0] == board[1][1] == board[2][2] != EMPTY:
        return board[1][1]
    if board[0][2] == board[1][1] == board[2][0] != EMPTY:
        return board[1][1]
    return None

# Function to check if the game is over
def terminal(board):
    return winner(board) is not None or not any(EMPTY in row for row in board)

# Function to get the utility of the board
def utility(board):
    win = winner(board)
    return 1 if win == X else -1 if win == O else 0

