from itertools import count, dropwhile

# all class and function definitions in the code file, if any
def triangles():
    for n in count(1):
        yield n * (n + 1) / 2

def pentagons():
    for n in count(1):
        yield n * (3*n - 1) / 2

def hexagons():
    for n in count(1):
        yield n * (2*n - 1)

def trianglepentagonhexagons():
    triang_iter = triangles()
    pentag_iter = pentagons()
    for hexag in hexagons():
        for pentag in dropwhile(lambda p: p < hexag, pentag_iter):
            if pentag == hexag:
                for triang in dropwhile(lambda t: t < hexag, triang_iter):
                    if triang == hexag:
                        yield hexag
                    break
            break

