            self.tape.insert(0, self.blank)
        else:
            self.pos -= 1

    def move_right(self):
        self.pos += 1
        if self.pos >= len(self.tape): 
            self.tape.append(self.blank)

    def exit_value(self, value):
        sys.exit(value)

