# import necessary packages
import random

# all class and function definitions in the code file, if any
class Link:
    empty = ()
    def __init__(self, first, rest=empty):
        assert isinstance(rest, Link) or rest is Link.empty
        self.first = first
        self.rest = rest

    def __getitem__(self, i):
        if i == 0:
            return self.first
        else:
            return self.rest[i-1]

    def __len__(self):
        if self.rest is Link.empty:
            return 1
        else:
            return 1 + len(self.rest)

def link_expressions_2(s):
    if s.rest is Link.empty:
        rest = ''
    else:
        rest = ' ,' + link_expressions_2(s.rest)
    return 'Link({0}{1})'.format(str(s.first), str(rest))

Link.__repr__ = link_expressions_2

def map_link_(f, s):
    if s is Link.empty:
        return Link.empty
    elif s.rest is Link.empty:
        return Link(f(s.first))
    else:
        return Link(f(s.first), map_link_(f, s.rest))

def extent_link(s, t):
    if s is Link.empty:
        return t
    else:
        return Link(s.first, extent_link(s.rest, t))

def filter_link_(f, s):
    if s is Link.empty:
        return s
    else:
        filtered = filter_link_(f, s.rest)
        if f(s.first):
            return Link(s.first, filtered)
        else:
            return filtered

def set_contains(s, v):
    if s.first == v:
        return True
    elif s.first != v and s.rest == Link.empty:
        return False
    else:
        return set_contains(s.rest, v)

def adjoin_set(s, v):
    if set_contains(s, v):
        return s
    else:
        return Link(v, s)

