        self.qtd = qtd

    def acabou(self):
        return sum(self.montes) == 0

    def tira(self, monte, qtd):
        if self.montes[monte] >= qtd:
            self.montes[monte] -= qtd
            return True
        return False

    def move_ai(self):
        atual = list(self.montes)
        if sum(atual) <= 10:
            return self.negamax(atual, 1, 10)[1:]
        else:
            if len(self.nao_vazios(atual)) == 3:
                opcoes = self.deixa_diferente(atual)
                return opcoes[randint(0, len(opcoes) - 1)]
            else:
                return self.deixa_igual(atual)

    def nao_vazios(self, atual):
        return [i for i in range(3) if atual[i] > 0]

    def deixa_diferente(self, jogo):
        opcoes = []
        for i in range(3):
            for j in range(1, jogo[i] + 1):
                jogo[i] -= j
                if jogo[self.outros_dois(i)[0]] != jogo[i] and jogo[self.outros_dois(i)[1]] != jogo[i]:
                    opcoes.append([i, j])
                jogo[i] += j
        return opcoes

    def deixa_igual(self, jogo):
        nao_vazios = self.nao_vazios(jogo)
        if jogo[nao_vazios[0]] > jogo[nao_vazios[1]]:
            return nao_vazios[0], jogo[nao_vazios[0]] - jogo[nao_vazios[1]]
        elif jogo[nao_vazios[1]] > jogo[nao_vazios[0]]:
            return nao_vazios[1], jogo[nao_vazios[1]] - jogo[nao_vazios[0]]
        else:
            return nao_vazios[0], jogo[nao_vazios[0]]

    def outros_dois(self, monte):
        return (1, 2) if monte == 0 else (0, 2) if monte == 1 else (0, 1)

    def negamax(self, atual, jogador, profundidade):
        if sum(atual) == 0 or profundidade == 0:
            return (1, None, None) if jogador == 1 else (-1, None, None)
        value = -100
        bestValue = -100
        bestMont = -1
        bestQtd = -10
        for i in self.nao_vazios(atual):
            for j in range(1, atual[i] + 1):
                atual[i] -= j
                value = -self.negamax(atual, 2 if jogador == 1 else 1, profundidade - 1)[0]
                if value > bestValue:
                    bestValue = value
                    bestMont = i
                    bestQtd = j
                atual[i] += j
        return bestValue, bestMont, bestQtd

