# import necessary packages
import re
from typing import List, Dict

# all class and function definitions in the code file, if any
class Token(str):
    def __new__(cls, text: str) -> 'Token':
        if not re.match(r'^[a-z]+(-[a-z])*$', text):
            raise ValueError("Invalid token")
        return super(Token, cls).__new__(cls, text)

class Word:
    def __init__(self, first_occurrence: int, last_occurrence: int, text: Token) -> None:
        if not (first_occurrence <= last_occurrence and first_occurrence >= 0 and last_occurrence >= 0):
            raise ValueError("Invalid occurrence indices")
        self.first_occurrence = first_occurrence
        self.last_occurrence = last_occurrence
        self.text = text

    def __lt__(self, other: 'Word') -> bool:
        return (self.last_occurrence - self.first_occurrence) < (other.last_occurrence - other.first_occurrence)

def tokens_to_words(tokens: List[Token]) -> List[Word]:
    first_occurrences = {}
    last_occurrences = {}

    for i, token in enumerate(tokens):
        if token not in first_occurrences:
            first_occurrences[token] = i
            last_occurrences[token] = i
        else:
            last_occurrences[token] = i

    words = []
    for token in first_occurrences.keys():
        words.append(Word(first_occurrence=first_occurrences[token], last_occurrence=last_occurrences[token], text=token))

    return words

def tokenize(text: str) -> List[Token]:
    return [Token(part.lower()) for part in text.split() if re.match(r'^[a-z]+(-[a-z])*$', part)]

def find_top(words: List[Word], limit: int) -> List[Word]:
    sorted_words = sorted(words, reverse=True)
    return sorted_words[:limit]

# main function
def main_solution(text: str, limit: int) -> List[str]:
    # Convert the input text to tokens
    tokens = tokenize(text)

    # Convert tokens to words with their occurrences
    words = tokens_to_words(tokens)

    # Find the top 'limit' words based on the defined order
    top_words = find_top(words, limit)

    # Return the text of the top words as a list of strings
    return [word.text for word in top_words]

