# import necessary packages
from collections import defaultdict

# all class and function definitions in the code file, if any
class Stack:
    def __init__(self):
        self.stack = []

    def push(self, value):
        self.stack.append(value)

    def pop(self):
        if self.size() > 0:
            return self.stack.pop()
        else:
            return None

    def size(self):
        return len(self.stack)


class Graph:
    def __init__(self):
        self.vertices = defaultdict(set)

    def add_vertex(self, vertex):
        self.vertices[vertex]

    def add_edge(self, v1, v2):
        if v1 in self.vertices and v2 in self.vertices:
            self.vertices[v1].add(v2)
        else:
            raise IndexError("That vertex does not exist!")


def earliest_ancestor(ancestors, starting_node):
    graph = Graph()
    for parent, child in ancestors:
        graph.add_vertex(parent)
        graph.add_vertex(child)
        graph.add_edge(child, parent)

    stack = Stack()
    stack.push([starting_node])
    longest_path = []
    earliest_ancestor_node = -1

    while stack.size() > 0:
        path = stack.pop()
        current_node = path[-1]

        if (len(path) > len(longest_path)) or (len(path) == len(longest_path) and current_node < earliest_ancestor_node):
            longest_path = path
            earliest_ancestor_node = current_node

        for neighbor in graph.vertices[current_node]:
            new_path = path + [neighbor]
            stack.push(new_path)

    return earliest_ancestor_node if earliest_ancestor_node != starting_node else -1

# main function
def main_solution(ancestors, starting_node):
    # all input arguments of the main_solution function should be json serializable
    # return, the returned value must be json serializable
    return earliest_ancestor(ancestors, starting_node)

