        self._states = states.copy()
        self._alphabet = alphabet.copy()
        self._transitions = {}
        self._initial_state = initial_state.copy()
        self._final_states = final_states.copy()
        self._epsilon = '&'
        self._alphabet.add(self._epsilon)
