class TreeNode:
    def __init__(self, x):
        self.val = x
        self.left = None
        self.right = None

class Solution:
    def DoesTree1haveTree2(self, pRoot1, pRoot2):
        if pRoot2 is None:
            return True
        if pRoot1 is None:
            return False
        if pRoot1.val != pRoot2.val:
            return False
        return self.DoesTree1haveTree2(pRoot1.left, pRoot2.left) and self.DoesTree1haveTree2(pRoot1.right, pRoot2.right)

    def HasSubtree(self, pRoot1, pRoot2):
        if pRoot1 is None or pRoot2 is None:
            return False
        return self.DoesTree1haveTree2(pRoot1, pRoot2) or self.HasSubtree(pRoot1.left, pRoot2) or self.HasSubtree(pRoot1.right, pRoot2)

# main function
def main_solution(tree1_json, tree2_json):
    # Convert JSON strings to TreeNode objects
    def json_to_tree(json_data):
        if not json_data:
            return None
        root = TreeNode(json_data["val"])
        root.left = json_to_tree(json_data["left"])
        root.right = json_to_tree(json_data["right"])
        return root

    tree1 = json_to_tree(json.loads(tree1_json))
    tree2 = json_to_tree(json.loads(tree2_json))

    # Check if tree2 is a subtree of tree1
    solution = Solution()
    result = solution.HasSubtree(tree1, tree2)

    # Return the result as a JSON serializable output
    return result

