# import necessary packages
import random

# all class and function definitions in the code file, if any
class GraphNode(object):
    def __init__(self, value, adj=None, reverseAdj=None):
        self.value = value
        self.adj = [] if adj is None else adj
        self.reverseAdj = [] if reverseAdj is None else reverseAdj

    def addForward(self, node):
        self.adj.append(node)

    def addReverse(self, node):
        self.reverseAdj.append(node)

    def getAdj(self, reverse):
        return self.adj if not reverse else self.reverseAdj

class SCC(object):
    def __init__(self, clauses):
        self.nodes = {}
        self.nodeCount = len(clauses)

        for clause in clauses:
            val1, val2 = clause

            if val1 not in self.nodes:
                self.nodes[val1] = GraphNode(val1)
                self.nodes[-val1] = GraphNode(-val1)

            if val2 not in self.nodes:
                self.nodes[val2] = GraphNode(val2)
                self.nodes[-val2] = GraphNode(-val2)

            self.nodes[-val1].addForward(self.nodes[val2])
            self.nodes[val2].addReverse(self.nodes[-val1])

            self.nodes[-val2].addForward(self.nodes[val1])
            self.nodes[val1].addReverse(self.nodes[-val2])

    def loop1(self):
        seen = set()
        order = []

        def dfs(node, seen):
            for adj in node.getAdj(True):
                if adj not in seen:
                    seen.add(adj)
                    dfs(adj, seen)
            order.append(node)

        for node in self.nodes.values():
            if node not in seen:
                seen.add(node)
                dfs(node, seen)

        return order

    def loop2(self, order):
        seen = set()
        sccs = {}
        component = 0

        def dfs(node, seen):
            seen.add(node)
            for adj in node.getAdj(False):
                if adj not in seen:
                    dfs(adj, seen)
            sccs[node.value] = component

        while order:
            v = order.pop()
            if v not in seen:
                component += 1
                dfs(v, seen)

        return sccs

    def check2SAT(self, sccs):
        for i in range(1, self.nodeCount + 1):
            if i not in sccs:
                continue
            if sccs[i] == sccs[-i]:
                return False
        return True

# main function
def main_solution(clauses):
    scc = SCC(clauses)
    order = scc.loop1()
    sccs = scc.loop2(order)
    isSatisfied = scc.check2SAT(sccs)
    return isSatisfied

