        for m in motions:
            direction = m[0]
            distance = int(m[1:])
            if direction == 'U':
                segments.append(Segment(x, Interval(y, y + distance)))
                y += distance
            elif direction == 'D':
                segments.append(Segment(x, Interval(y - distance, y)))
                y -= distance
            elif direction == 'L':
                segments.append(Segment(Interval(x - distance, x), y))
                x -= distance
            elif direction == 'R':
                segments.append(Segment(Interval(x, x + distance), y))
                x += distance
        return cls(segments)

