# import necessary packages
import random

# all class and function definitions in the code file, if any
class HuffmanNode:
    def __init__(self, char, freq, left, right):
        self.char = ord(char)
        self.freq = freq
        self.left = left
        self.right = right

    def set_left(self, node):
        self.left = node

    def set_right(self, node):
        self.right = node

    def is_leaf(self):
        return self.left is None and self.right is None

def comes_before(a, b):
    if a.freq == b.freq:
        return a.char < b.char
    return a.freq < b.freq

def combine(a, b):
    new_node_char = chr(a.char) if a.char < b.char else chr(b.char)
    left, right = (a, b) if comes_before(a, b) else (b, a)
    return HuffmanNode(new_node_char, a.freq + b.freq, left, right)

def sort_list(huffman_nodes_list):
    return sorted(huffman_nodes_list, key=lambda node: (node.freq, node.char))

def create_huff_tree(char_freq):
    leaf_nodes = [HuffmanNode(chr(i), freq, None, None) for i, freq in enumerate(char_freq) if freq != 0]
    sorted_nodes = sort_list(leaf_nodes)
    while len(sorted_nodes) > 1:
        min1, min2 = sorted_nodes.pop(0), sorted_nodes.pop(0)
        sorted_nodes.append(combine(min1, min2))
        sorted_nodes = sort_list(sorted_nodes)
    return sorted_nodes[0]

