    point = copy.copy(rect.corner)
    if not point_in_circle(circ, point):
        return False

    point.x += rect.width
    if not point_in_circle(circ, point):
        return False

    point.y -= rect.height
    if not point_in_circle(circ, point):
        return False

    point.x -= rect.width
    if not point_in_circle(circ, point):
        return False

    return True

