# import necessary packages
from collections import defaultdict
import json

# all class and function definitions in the code file, if any
def read_rules(grammar_data, lexicon_data):
    grammar = defaultdict(list)
    lexicon = defaultdict(list)
    for line in grammar_data.split('\n'):
        token = line.rstrip().split(' ')
        if len(token) == 3:
            grammar[token[0]].append(token[1:])
        elif len(token) == 2:
            lexicon[token[0]].append(token[1].lstrip('_'))
        else:
            raise ValueError('Error: read_rules: ' + line)
    return grammar, lexicon

def cky_recognition(s, grammar, lexicon):
    cky = [[[] for j in range(len(s) + 1)] for i in range(len(s))]

    for j in range(len(s) + 1):
        for i in reversed(range(j)):
            if j - i == 1:
                for key in lexicon.keys():
                    if s[i] in lexicon[key]:
                        cky[i][j].append({'head': key})
            else:
                for k in range(i + 1, j):
                    for left in cky[i][k]:
                        for right in cky[k][j]:
                            for candidate in grammar.keys():
                                if exists_in_grammar(candidate, left['head'], right['head'], grammar):
                                    cky[i][j].append({'head': candidate, 'left': left['head'], 'left_place':(i, k), 'right': right['head'], 'right_place':(k, j)})
    return cky

def exists_in_grammar(head, left, right, grammar):
    return [left, right] in grammar[head]

# main function
def main_solution(grammar_data, lexicon_data, sentence):
    # Convert JSON serializable inputs to original input variables
    grammar, lexicon = read_rules(grammar_data, lexicon_data)

    # Core solution code
    cky = cky_recognition(sentence, grammar, lexicon)

    # Convert output to JSON serializable format
    result = cky[0][len(sentence)]
    return json.dumps(result)

