    i, j = action
    if board[i][j] != EMPTY:
        raise Exception('action ({},{}) is not a valid option.'.format(i, j))
    newBoardState = copy.deepcopy(board)
    newBoardState[i][j] = player(board)
    return newBoardState

# Function to determine the winner
def winner(board):
    for i in range(3):
        if board[i][0] == board[i][1] == board[i][2] and board[i][0] != EMPTY:
            return board[i][0]
        if board[0][i] == board[1][i] == board[2][i] and board[0][i] != EMPTY:
            return board[0][i]
    if board[0][0] == board[1][1] == board[2][2] and board[1][1] != EMPTY:
        return board[1][1]
    if board[2][0] == board[1][1] == board[0][2] and board[1][1] != EMPTY:
        return board[1][1]
    return None

# Function to check if the game is over
def terminal(board):
    if winner(board):
        return True
    if sum([row.count(EMPTY) for row in board]) == 0:
        return True
    return False

