    p = winner(board)
    if p == X:
        return 1
    if p == O:
        return -1
    return 0

# Function to get the optimal action for the current player
def minimax(board):
    if terminal(board):
        return None
    bestAction = None
    v = []
    if player(board) == X:
        v = [(action, minValue(result(board, action))) for action in actions(board)]
        bestAction = max(v, key=lambda x: x[1])[0]
    else:
