                res = self.add('1', res, base)
                unified_x, unified_y = self.unify_nums(x_cur, y)
        else:
            while int(x_cur) >= int(y):
                x_cur = self.subtract(x_cur, y, base)
                res = self.add('1', res, base)
        if len(res) > 1:
            res = res.lstrip('0')
        return res, x_cur

    def get_division_remainder(self, x, y, base):
        res = self.divide(x, y, base)[1]
        if len(res) > 1:
            res = res.lstrip('0')
        return res

