class BinTree:
    pass

def nBT(key, left, right):
    T = BinTree()
    T.key = key
    T.left = left
    T.right = right
    return T

def bTEx():
    return (nBT(1, nBT(2, 
                       nBT(4, None, None), 
                       nBT(5, None, None)), 
                   nBT(3, None, 
                       nBT(7, 
                           nBT(15, None, None), 
                           None))))

def printBinTree(B):
    print(pBTR(B))

def pBTR(B):    
    if None != B:
        return "< "+str(B.key)+', '+str(pBTR(B.left))+', '+str(pBTR(B.right))+'>'

# Returns the minimum key of a non-empty BST
# Iterative version
def minBST(B):
    while B.left != None:
        B = B.left
    return B.key

# Returns the maximum key of a non-empty BST
# Iterative version
def maxBST(B):
    while B.right != None:
        B = B.right
    return B.key

# Adds a key to a BST
def addBST(x, B):
    if B == None:
        B = nBT(x, None, None)
    else:
        if x < B.key:
            B.left = addBST(x, B.left)
        else:
            B.right = addBST(x, B.right)
    return B

# Build a BST from successive key insertions into an empty BST
def list2BST(L):
    T = None
    for e in L:
        T = addBST(e, T)
    return T

# Counts the number of keys from B included in [inf; sup]
def nbInter(B, inf, sup):
    if None == B:
