import numbers
import fractions
import math

# all class and function definitions in the code file, if any
class Fract:
    num: int
    den: int
    __match_args__ = ('num', 'den')

    def __init__(self, numerator=None, denominator=None):
        if numerator is None and denominator is not None:
            raise ValueError('Can\'t define denominator without defining numerator')

        if numerator is None:
            self.num = 0
            self.den = 1
            return

        if isinstance(numerator, numbers.Integral):
            if denominator is not None and not isinstance(denominator, numbers.Integral):
                raise TypeError('Numerator must be integer')
            self.init_int(int(numerator), 1 if denominator is None else int(denominator))
            return

        if denominator is not None:
            raise ValueError('Can\'t define denominator if numerator is not integer')

        match numerator:
            case float(f1):
                self.init_float(f1)
            case Fract():
                self.init_fract(numerator)
            case fractions.Fraction():
                self.init_fraction(numerator)
            case [int(n), int(d)]:
                self.init_int(n, d)
            case _:
                raise TypeError('Unsupported Fract init value')

    def init_int(self, numerator: int, denominator: int):
        if denominator == 0:
            raise ZeroDivisionError('Denominator can\'t be 0')
        self.num = numerator
        self.den = 1 if denominator is None else denominator
        self.normalize()

    def init_fract(self, f: 'Fract'):
        self.num = f.numerator
        self.den = f.denominator

    def init_fraction(self, f: fractions.Fraction):
        self.num = f.numerator
        self.den = f.denominator

    def init_float(self, f: float):
        epsilon = 1e-6

        if math.isnan(f):
            raise ValueError('Cannot convert NaN to integer ratio')
        if math.isinf(f):
            raise OverflowError('Cannot convert Infinity to integer ratio')

        if f == 0.0:
            self.num = 0
            self.den = 1
            return

        sign = 1
        if f < 0:
            sign = -1
            f = -f

        off = math.floor(f)
        f -= off
        if f <= epsilon:
            self.num = off * sign
            self.den = 1
            return

        infNum = 0; infDen = 1
        supNum = 1; supDen = 0
        while True:
            rNum = infNum + supNum
            rDen = infDen + supDen

            r = rNum / rDen
            if abs(r - f) < epsilon:
                self.num = (rNum + off * rDen) * sign
                self.den = rDen
                return

            if r < f:
                infNum = rNum
                infDen = rDen
            else:
                supNum = rNum
                supDen = rDen

    def normalize(self):
        if self.den < 0:
            self.num = -self.num
            self.den = -self.den
        if (p := math.gcd(self.num, self.den)) > 1:
            self.num //= p
            self.den //= p

    def __str__(self):
        if self.den == 1:
            return str(self.num)
        else:
            return str(self.num)+'/'+str(self.den)

    def __repr__(self):
        if self.den == 1:
            return f'Fract({self.num})'
        else:
            return f'Fract({self.num}, {self.den})'

    @property
    def numerator(self):
        return self.num

    @property
    def denominator(self):
        return self.den

# main function
def main_solution(numerator: int, denominator: int):
    # Convert JSON serializable inputs to the original input variables
    fract = Fract(numerator, denominator)

    # Return the fraction in a JSON serializable format
    return {"numerator": fract.numerator, "denominator": fract.denominator}

