def main_solution(array, n):
    # Convert JSON serializable inputs to original input variables
    array = [Atom(AtomType[item['type']], item['value']) for item in array]

    # Core logic
    result = infixes(array, n)

    # Convert output to JSON serializable format
    result = [[{'type': atom.type.name, 'value': atom.value} for atom in sublist] for sublist in result]

    return result

