# import necessary packages
import math
from collections import Counter

# all class and function definitions in the code file, if any
def prod(iterable):
    """ Product of the iterable """
    result = 1
    for i in iterable:
        result *= i
    return result

def primes_sieve(n):
    a = [True] * (n+1)
    a[0] = a[1] = False

    for i, is_prime in enumerate(a):
        if is_prime:
            yield i
            for j in range(i*i, n+1, i):
                a[j] = False

def get_primes(n):
    """ Get primes >=1 and <=n """
    return list(primes_sieve(n))

def factorize(n, primes=None):
    if primes and primes[-1] < math.sqrt(n): raise Exception('No enough primes')
    if not primes: primes = get_primes(n)

    factors = []
    for i in range(2, int(math.sqrt(n))+1):
        while n % i == 0:
            factors.append(i)
            n /= i

    if n != 1: factors.append(n)

    return factors

def geometric_series_sum(a, r, n):
    """ 
    Sum of the geometric series
    a: init value
    r: ratio
    n: number of series
    """
    if isinstance(a, int) and isinstance(r, int):
        return a * (1 - (r ** n)) / (1 - r)
    else:
        return 1.0 * a * (1 - (r ** n)) / (1 - r)

def number_of_divisors(n, primes=None, factors=None):
    if factors:
        factors = [x for x in factors if x != 1]
        assert prod(factors) == n
    else:
        factors = factorize(n, primes)

    counter = Counter(factors)
    counter.update(counter.keys())
    p = prod(counter.values())

    return p

def divisors_sum(n, primes=None, factors=None):
    if factors:
        factors = [x for x in factors if x != 1]
        assert prod(factors) == n
    else:
        factors = factorize(n, primes)

    counter = Counter(factors)
    s = prod([geometric_series_sum(1, k, v+1) for k, v in counter.items()])

    return s

# main function
def main_solution(n):
    # Convert input to JSON serializable format
    n = int(n)

    # Calculate the number of divisors and the sum of divisors
    num_divisors = number_of_divisors(n)
    sum_divisors = divisors_sum(n)

    # Return the result in JSON serializable format
    return {"number_of_divisors": num_divisors, "sum_of_divisors": sum_divisors}

