# Definition for a binary tree node.
class TreeNode:
    def __init__(self, x):
        self.val = x
        self.left = None
        self.right = None

# all class and function definitions in the code file, if any
class Solution:
    def check(self, left, right):
        if left.val != right.val:
            return False
        if left.left and right.right:
            if not self.check(left.left, right.right):
                return False
        elif left.left or right.right:
            return False
        if left.right and right.left:
            if not self.check(left.right, right.left):
                return False
        elif left.right or right.left:
            return False
        return True

    def isSymmetric(self, root):
        if not root:
            return True
        if root.left is None and root.right is None:
            return True
        if root.left is None or root.right is None:
            return False
        return self.check(root.left, root.right)

# main function
def main_solution(tree_structure):
