# import necessary packages
import random

# all class and function definitions in the code file, if any
class Graph:
    def __init__(self, vertices):
        self.V = vertices
        self.graph = [[0 for column in range(vertices)] for row in range(vertices)]

    def isSafe(self, v, colour, c):
        for i in range(self.V):
            if self.graph[v][i] == 1 and colour[i] == c:
                return False
        return True

    def graphColourUtil(self, m, colour, v):
        if v == self.V:
            return True

        for c in range(1, m+1):
            if self.isSafe(v, colour, c):
                colour[v] = c
                if self.graphColourUtil(m, colour, v+1):
                    return True
                colour[v] = 0

    def graphColouring(self, m):
        colour = [0] * self.V
        if not self.graphColourUtil(m, colour, 0):
            return False, []
        return True, colour

# main function
def main_solution(vertices, adjacency_matrix, m):
    # Convert JSON serializable inputs to original input variables
    graph = Graph(vertices)
    graph.graph = adjacency_matrix

    # Call the original function
    result, colors = graph.graphColouring(m)

    # Convert the output to JSON serializable format
    if result:
        return {"result": "success", "colors": colors}
    else:
        return {"result": "failure", "colors": []}

