# import necessary packages
import random

# all class and function definitions in the code file, if any
def is_palindrome(num):
    return str(num) == str(num)[::-1]

def reverse(num):
    return int(str(num)[::-1])

def is_prime(num):
    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(num**0.5) + 1, 2):
        if num % i == 0:
