class cell:
    def __init__(self, num=0, val=BLANK, position=(0,0), adj=[]):
        self.num = num
        self.val = val
        self.position = position
        self.adjacent = adj
        self.counted = False

class board:
    def __init__(self, m, n):
        self.row = m
        self.col = n
        self.moves = []
        self.cells = []
        num = 0
        for x in range(self.row):
            for y in range(self.col):
                adj = []
                if (num % self.col) != 0:
                    adj.append(num - 1)
                    if num >= self.col:
                        adj.append(num - (self.col+1))
                    if num + (self.col-1) < self.row*self.col:
                        adj.append(num + (self.col-1))
                if ((num+1) % self.col) != 0:
                    adj.append(num + 1)
                    if num >= self.col:
                        adj.append(num - (self.col-1))
                    if num + (self.col+1) < self.row*self.col:
                        adj.append(num + (self.col+1))
                if (num - self.col) >= 0:
                    adj.append(num-self.col)
                if (num + self.col) < self.row*self.col:
                    adj.append(num + self.col)
                self.cells.append(cell(num=num, position=(x,y), adj=adj))
                num += 1

