        if c.val == self.hStone:
            hCount += 1
            if combCheck and not c.counted:
                hC.append(c)
                c.counted = True
        elif c.val != self.hStone:
            if hCount == numStones:
                if combCheck:
                    self.humanScore += len(hC)
                else:
                    self.humanScore += weight
            elif combCheck:
                for x in hC:
                    x.counted = False
            hC = []
            hCount = 0
        if c.val == self.cStone:
            cCount += 1
            if combCheck and not c.counted:
                cC.append(c)
                c.counted = True
        elif c.val != self.cStone:
            if cCount == numStones:
                if combCheck:
                    self.computerScore += len(cC)
                else:
                    self.computerScore += weight
            elif combCheck:
                for x in cC:
                    x.counted = False
            cC = []
            cCount = 0
        return hCount, cCount, hC, cC

