def main_solution(m, n, moves):
    # Initialize the game with the given board dimensions
    g = game(m, n)

    # Apply the moves to the board
    for move in moves:
        if move['player'] == 'Human':
            g.makeMove(move['cellNo'], g.hStone)
        else:
