# import necessary packages
import re

# main function
def main_solution(word, arity):
    # Convert arity to integer if it's not already
    arity = int(arity)

    # Function to check if the word is valid based on the given arity
    def is_valid(word, arity):
        word_in = word.strip()
        if re.match(r'^(.*?)(\,\s\,)(.*)$', word_in):
            return False
        if arity == 0:
            re_a = None
        else:
            re_a = re.match(r'^([a-zA-Z_\s]*?)((\()[a-zA-Z_\s\,\)]+)', word_in)
            if re_a is None:
                return False
        while re_a is not None:
            if arity == 1:
                re_a = re.match(r'^(.*?)((\()([a-zA-Z_\s]+)(\)))(.*)$', word_in)
            else:
                re_a = re.match(r'^(.*?)((\()(([a-zA-z_\s]+\,)+)([a-zA-Z_\s]+\)))(.*)$', word_in)
            if re_a:
                b = re_a.group(4)
                if b.count(',') == (arity - 1):
                    word_in = word_in.replace(re_a.group(2), '')
                else:
                    break
        re_x = re.match(r'^([a-zA-z_]+)$', word_in)
        if re_x:
            return True
        else:
            return False

    # Return the validity of the word as a boolean
    return is_valid(word, arity)

