def formNewState(world, i, j, player):
    newState = []
    for k in range(3):
        if k == i:
            row = world[i]
            l = list(row)
            l[j] = player
            newState.append("".join(l))
        else:
            newState.append(world[k])
    return newState

def isWinState(world):
    winner = None
    win_patterns = [
        [(0, 0), (0, 1), (0, 2)],
        [(1, 0), (1, 1), (1, 2)],
        [(2, 0), (2, 1), (2, 2)],
