# import necessary packages
import random

# all class and function definitions in the code file, if any
def count_on_row(board, row):
    return sum(board[row])

def count_on_col(board, col):
    return sum([row[col] for row in board])

def count_pieces(board):
    return sum([sum(row) for row in board])

def add_piece(board, row, col):
    return board[0:row] + [board[row][0:col] + [1,] + board[row][col+1:]] + board[row+1:]

def is_goal(board, N):
    return count_pieces(board) == N and \
        all([count_on_row(board, r) <= 1 for r in range(0, N)]) and \
        all([count_on_col(board, c) <= 1 for c in range(0, N)])

def solve(initial_board, N):
    fringe = [initial_board]
    while len(fringe) > 0:
        for s in successors3(fringe.pop(), N):
            if is_goal(s, N):
                return s
            fringe.append(s)
    return False

def successors3(board, N):
    new_board3 = [add_piece(board, r, r) for r in range(0, N)]
    x = len(new_board3) - 1
    while -1 < x < len(new_board3):
        if board == new_board3[x] or count_pieces(new_board3[x]) > N:
            new_board3.pop(x)
        x -= 1
    return new_board3

# main function
def main_solution(N):
    initial_board = [[0 for _ in range(N)] for _ in range(N)]
    solution = solve(initial_board, N)
    if solution:
        return {"solution": solution}
    else:
        return {"solution": "No solution found"}

