    # Convert JSON serializable inputs to original input variables
    num_banks = int(num_banks)
    line_size = int(line_size)
    line = int(line)

    # Initialize the appropriate banking policy
    if policy_type == "consecutive":
        policy = BankingPolicyConsecutive(num_banks, line_size)
    elif policy_type == "prime":
        policy = BankingPolicyPrime(num_banks, line_size)
    elif policy_type == "skew":
        policy = BankingPolicySkew(num_banks, line_size)
