    def row_length(self, n: int) -> int:
        if n < 0 or n >= self.rows:
            raise IndexError(f'row {n} out of range ({self.rows} rows total)')

        return (n + 1) * 2 - 1

    @staticmethod
    def triangular_number(n: int) -> int:
        return n ** 2

