                      (2, 3):  1, (3, 2):  1, (2, 4):  5, (4, 2):  5,
                      (3, 4):  5, (4, 3):  5}
        self.goal = 4

    def is_state(self, state):
        return state in self.graph

    def start(self):
        return 0

    def actions(self, state):
