    """
    Solves a simple problem using Uniform Cost Search (UCS).

    :param initial_state: The initial state of the problem.
    :type initial_state: int
    :return: The final state after solving the problem.
    :rtype: int
    """
    problem = SimpleProblem()
    counter = itertools.count()
    frontier = queue.PriorityQueue()
    frontier.put((0, counter, Node(initial_state, 0)))
    explored = set([])

    while not frontier.empty():
        node = frontier.get()[2]
        explored.add(node.state)
