        if not self.size_is_same(mat):
            raise ArithmeticError("unmatched sizes")
        r = self.get_row_num()
        c = self.get_col_num()
        ls = [[0 for _ in range(c)] for _ in range(r)]
        for i in range(r):
            for j in range(c):
                ls[i][j] = self.get_item(i, j) + mat.get_item(i, j)
        return Matrix(ls)

