def prime_reduce(n):
    """For an integer n, return n if it is prime,
    or else its lowest divisor and the quotient"""  
    if n == 2:
        return [2]
    if n % 2 == 0:
        return [2, n // 2]
    for i in range(3, floor(sqrt(n))+1, 2): 
        if n % i == 0:
            return [i, n // i]
    return [n]

