# import necessary packages
import random
import math

# all class and function definitions in the code file, if any
class Board_State:
    state = None
    cost = math.inf
    size = 0

    def __init__(self, state):
        self.state = state
        self.size = len(state)
        self.cost = self.compute_conflict()

    def compute_conflict(self):
        conflict = 0
        for i in range(self.size):
            for j in range(i+1, self.size):
                if self.state[i] == self.state[j] or self.state[i] + i == self.state[j] + j or self.state[i] - i == self.state[j] - j:
                    conflict += 1
        return conflict

def next_best_state(board):
    best_state = board
    moves = []
    for i in range(board.size):
        start = board.state[i]
        for j in range(1, board.size + 1):
            if j != start:
                moves.append([i, j])
    random.shuffle(moves)
    for move in moves:
        i, j = move
        start = board.state[i]
        board.state[i] = j
        new_board = Board_State(list(board.state))
        if new_board.cost <= best_state.cost:
            best_state = new_board
        board.state[i] = start
    return best_state

def Hill_Climber(cur_board, iter_limit=10000):
    next_board = next_best_state(cur_board)
    if cur_board.cost != next_board.cost:
        return Hill_Climber(next_board)
    if next_board.state == cur_board.state or iter_limit == 0:
        return next_board
    return Hill_Climber(next_board, iter_limit - 1)

# main function
def main_solution(board_length, initial_state):
    initial_board = Board_State(initial_state)
    final_board = Hill_Climber(initial_board)
    return final_board.cost

