        if p1 is None:
            self.a = a
            self.b = b
            self.c = c
        if p2 is not None and p1 is not None:
            self.p1 = p1
            self.p2 = p2
            self.a = p2.y - p1.y
            self.b = p1.x - p2.x
            self.c = -self.a * p1.x - self.b * p1.y

