import math
import copy

# all class and function definitions in the code file, if any
class Rectangle:
    def __init__(self, width, height, corner):
        self.width = width
        self.height = height
        self.corner = corner

class Circle:
    def __init__(self, center, radius = 0):
        self.center = center
        self.radius = radius

class Point:
    def __init__(self, x = 0, y = 0):
        self.x = x
        self.y = y

def point_in_circle(Circle: Circle, Point: Point):
    distance = math.sqrt(((Point.x - Circle.center.x)**2) + ((Point.y - Circle.center.y)**2))
    if Circle.center.x == Point.x or Circle.center.y == Point.y:
        return True
    elif distance <= Circle.radius:
        return True
    else:
        return False

def rect_in_circle(circ: Circle, rect: Rectangle):
    point = copy.copy(rect.corner)
    if not point_in_circle(circ, point):
        return False

    point.x += rect.width
    if not point_in_circle(circ, point):
        return False

    point.y -= rect.height
    if not point_in_circle(circ, point):
        return False

    point.x -= rect.width
    if not point_in_circle(circ, point):
        return False

    return True

def rect_circle_overlap(rect: Rectangle, circ: Circle):
    point = copy.copy(rect.corner)
    if point_in_circle(circ, point):
        return True

    point.x += rect.width
    if point_in_circle(circ, point):
        return True

    point.y -= rect.height
    if point_in_circle(circ, point):
        return True

    point.x -= rect.width
    if point_in_circle(circ, point):
        return True

    return False

