    # Check if the rectangle is entirely within the circle
    is_rect_in_circle = rect_in_circle(circle, rect)

    # Check if any part of the rectangle overlaps with the circle
    is_rect_circle_overlap = rect_circle_overlap(rect, circle)

    # Return JSON serializable outputs
    return {
        "is_rect_in_circle": is_rect_in_circle,
