class DSF:
    def __init__(self, sets):
        self.parent = np.zeros(sets, dtype=int) - 1

    def find(self, i):
        if self.parent[i] < 0:
            return i
        return self.find(self.parent[i])

    def union(self, i, j):
        root_i = self.find(i)
        root_j = self.find(j)
        if root_i != root_j:
            self.parent[root_j] = root_i
            return 1
        return 0

def connected_components(g):
    vertices = len(g)
    components = vertices
    s = DSF(vertices)
    for v in range(vertices):
        for edge in g[v]:
            components -= s.union(v, edge)
    return components

def graph(vertices, edges, duplicate=True):
    g = [[] for _ in range(vertices)]
    n = 0
    while n < edges:
        s = random.randint(0, vertices - 1)
        d = random.randint(0, vertices - 1)
        if s < d and d not in g[s]:
            g[s].append(d)
            if duplicate:
                g[d].append(s)
            n += 1
    for i in range(len(g)):
