def main_solution(current_floor, called_floors, selected_floors):
    class Callbacks:
        def __init__(self, current_floor):
            self.current_floor = current_floor
            self.motor_direction = None

    elevator = ElevatorLogic()
    elevator.callbacks = Callbacks(current_floor)

    for floor, direction in called_floors:
        elevator.on_called(floor, direction)

    for floor in selected_floors:
        elevator.on_floor_selected(floor)

    elevator.on_ready()

    next_floor = elevator.get_next_destination_floor()
    if next_floor == -1:
        next_floor = elevator.get_next_destination_floor_cp(elevator.destination_direction_cache, (UP | DOWN), 1)

    return {"next_floor": next_floor}

