# import necessary packages
import math
import random

# all class and function definitions in the code file, if any
class Vector:
    def __init__(self, *args):
        self.mData = [float(scalar) for scalar in args]
        self.mDim = len(self.mData)

    def __str__(self):
        return f"<Vector{self.mDim}: {' '.join(map(str, self.mData))}>"

    def __len__(self):
        return self.mDim

    def __getitem__(self, item_index):
        return self.mData[item_index]

    def __setitem__(self, key, value):
        self.mData[key] = float(value)

    def copy(self):
        return Vector(*self.mData)

    def __eq__(self, other):
        if isinstance(other, Vector) and len(other) == len(self):
            return all(self[i] == other[i] for i in range(len(self)))
        return False

    def __add__(self, other):
        if isinstance(other, Vector) and len(other) == len(self):
            return Vector(*[self[i] + other[i] for i in range(len(self))])
        raise TypeError(f"You can only add another Vector{self.mDim} to this Vector{self.mDim}")

    def __sub__(self, other):
        if isinstance(other, Vector) and len(other) == len(self):
            return self + (-other)
        raise TypeError(f"You can only subtract another Vector{self.mDim} from this Vector{self.mDim}")

    def __neg__(self):
        return Vector(*[-scalar for scalar in self.mData])

    def __mul__(self, other):
        if isinstance(other, (int, float)):
            return Vector(*[scalar * other for scalar in self.mData])
        return NotImplemented

    def __rmul__(self, other):
        return self * other

    def __truediv__(self, other):
        if isinstance(other, (int, float)):
            if other == 0:
                raise ZeroDivisionError("You can't divide a vector by 0")
            return self * (1 / other)
        raise TypeError(f"You can only divide this Vector{self.mDim} by a scalar")

    @property
    def magnitudeSq(self):
        return sum(scalar ** 2 for scalar in self.mData)

    @property
    def magnitude(self):
        return math.sqrt(self.magnitudeSq)

    @property
    def normalized(self):
        if not self.isZero:
            return self / self.magnitude
        return self.copy()

    @property
    def isZero(self):
        return all(scalar == 0 for scalar in self.mData)

    @property
    def i(self):
        return tuple(int(scalar) for scalar in self.mData)

class Vector2(Vector):
    def __init__(self, x, y):
        super().__init__(x, y)

    @property
    def x(self):
        return self.mData[0]

    @x.setter
    def x(self, value):
        self.mData[0] = float(value)

    @property
    def y(self):
        return self.mData[1]

    @y.setter
    def y(self, value):
        self.mData[1] = float(value)

    @property
    def degrees(self):
        return math.atan2(self.y, self.x) * (180 / math.pi)

    @property
    def radians(self):
        return math.atan2(self.y, self.x)

    @property
    def perpendicular(self):
        return Vector2(-self.y, self.x)

class Vector3(Vector):
    def __init__(self, x, y, z):
        super().__init__(x, y, z)

    @property
    def x(self):
        return self.mData[0]

    @x.setter
    def x(self, value):
        self.mData[0] = float(value)

    @property
    def y(self):
        return self.mData[1]

    @y.setter
    def y(self, value):
        self.mData[1] = float(value)

    @property
    def z(self):
        return self.mData[2]

    @z.setter
    def z(self, value):
        self.mData[2] = float(value)

    @property
    def vector2NoZ(self):
