def cross(vect1, vect2):
    if isinstance(vect1, Vector3) and isinstance(vect2, Vector3):
        return Vector3(
            vect1.y * vect2.z - vect1.z * vect2.y,
            vect1.z * vect2.x - vect1.x * vect2.z,
            vect1.x * vect2.y - vect1.y * vect2.x
