    if not node:
        return None
    return {
        "data": node._data,
        "left": tree_to_dict(node._left),
        "right": tree_to_dict(node._right)
    }

def dict_to_tree(d):
    if not d:
        return None
    return TreeNode(d["data"], dict_to_tree(d["left"]), dict_to_tree(d["right"]))

