    elif a == 'j':  # +j * ?
        if b == 'i':
            return 'K'
        elif b == 'j':
            return '-'
        elif b == 'k':
            return 'i'
        elif b == 'I':
            return 'k'
        elif b == 'J':
            return '1'
        elif b == 'K':
