def mult_str(S):
    x = '1'
    for c in S:
        x = mult(x, c)
    return x

def greedy(S, L, ss, needles, start=0):
    if len(needles) == 0:
        return start >= len(S)
    elif start >= len(S):
        return False
    elif len(needles) == 1:
        return mult_special(S, L, ss, start) == needles

    x = '1'
    needle = needles[0]

    for i in range(start, len(S)):
