In a fantasy game, the hero encounters various enemies in a dungeon. Each enemy has specific attributes such as type, position, level, and health. The hero's attack power is also known. Given the type of enemy, its position, level, and the hero's attack power, what is the outcome of the hero's attack on the enemy, including whether the enemy is defeated, the damage dealt, and the remaining health of the enemy?

The input and output requirements are as follows:

Input:
  `enemy_type` (str): The type of enemy, which can be one of "Goblin", "Skeleton", or "Arachnid".
  `position` (list of int): The position of the enemy on the grid, represented as a list of two integers [row, col].
  `level` (int): The level of the enemy, which affects its stats.
  `hero_attack` (int): The attack power of the hero.

Output:
  `return` (dict): A dictionary containing the following keys:
    - `defeated` (bool): Indicates whether the enemy was defeated.
    - `damage_dealt` (int): The amount of damage dealt to the enemy.
    - `remaining_health` (int): The remaining health of the enemy after the attack.

Given the following input:

{'enemy_type': 'Skeleton', 'position': [4, 7], 'level': 4, 'hero_attack': 1}

Can you predict the output without writing any code? Please reason and put your final answer in the following json format: {"output": <your output>}, where <your output> should strictly match the the output requirement as specified.

Tip: Here is a reference code snippet for this question. You can refer to this code to guide your reasoning but not copy spans of code directly.

# import necessary packages
import math
from random import randint
import random
import collections

# all class and function definitions in the code file, if any
class Enemy(object):
    def __init__(self, name, character, position, tile, health, attack, avoid):
        self.name = name
        self.character = character
        self.position = position
        self.tile = tile
        self.health = health
        self.attack = attack
        self.avoidance = avoid

    def set_position(self, position):
        self.position = position

    def set_tile(self, tile):
        self.tile = tile

    def defend_attack(self, hero_attack):
        if randint(1, 100) <= self.avoidance:
            return False, 0
        starting_health = self.health
        self.health = self.health - hero_attack
        if self.health < 1:
            return True, starting_health
        else:
            return False, starting_health - self.health

class Skeleton(Enemy):
    def __init__(self, level, position):
        stat = base = 2
        for i in range(1, level):
            stat += math.floor(math.sqrt(level * base))
        chance_to_dodge = 30
        Enemy.__init__(self, "Skeleton", 'S', position, '.', stat, stat, chance_to_dodge)

class Goblin(Enemy):
    def __init__(self, level, position):
        stat = base = 3
        for i in range(1, level):
            stat += math.floor(math.sqrt(level * base))
        chance_to_dodge = 40
        Enemy.__init__(self, "Goblin", 'G', position, '.', stat, stat, chance_to_dodge)

class Arachnid(Enemy):
    def __init__(self, level, position):
        stat = base = 1
        for i in range(1, level):
            stat += math.floor(math.sqrt(level * base))
        chance_to_dodge = 20
        Enemy.__init__(self, "Arachnid", 'A', position, '.', stat, stat, chance_to_dodge)

def init_enemy(enemy_type, position, level):
    if enemy_type == 'Goblin':
        return Goblin(level, position)
    elif enemy_type == 'Skeleton':
        return Skeleton(level, position)
    elif enemy_type == 'Arachnid':
        return Arachnid(level, position)

# main function
def main_solution(enemy_type, position, level, hero_attack):
    # Convert JSON serializable inputs to original input variables
    enemy = init_enemy(enemy_type, tuple(position), level)

    # Core logic to determine if the enemy is defeated and the damage dealt
    defeated, damage_dealt = enemy.defend_attack(hero_attack)

    # Convert outputs to JSON serializable format
    return {
        "defeated": defeated,
        "damage_dealt": damage_dealt,
        "remaining_health": enemy.health
    }

