# import necessary packages
import random

# all class and function definitions in the code file, if any
def series_to_graph(s):
    g = {}
    for i in range(len(s)):
        v = []
        for j in range(i+1, i+4):
            if j >= len(s):
                break
            if s[j]-s[i] > 3:
                break
            v.append(s[j])

        g[s[i]] = v

    return g

def find_all_paths(g, start=None, end=None, path=[]):
    if not start:
        start = min(g.keys())
    if not end:
        end = max(g.keys())

    path = path + [start]
    if start == end:
        return [path]
    if start not in g:
        return []
    paths = []
    for v in g[start]:
        if v not in path:
            newpaths = find_all_paths(g, v, end, path)
            for newpath in newpaths:
                paths.append(newpath)
    return paths

def split(s, d):
    result = []
    left = 0

    for i in range(len(s)-1):
        if s[i+1] - s[i] == d:
            result.append(s[left:i+1])
            left = i + 1

    result.append(s[left:])

    return result

# main function
def main_solution(adapter_sequence):
    # Convert the input list to a JSON serializable format
    adapter_sequence = list(adapter_sequence)

    # Split the sequence into independent graphs
    graphs = [series_to_graph(x) for x in split(adapter_sequence, 3)]

    # Calculate the total number of paths
    cnt = 1
    for g in graphs:
        cnt *= len(find_all_paths(g))

    # Return the result as a JSON serializable output
    return cnt

