# import necessary packages
import numpy as np
from typing import List, Tuple

# all class and function definitions in the code file, if any
class Board:
    def __init__(self, row: int, col: int) -> None:
        self._row = row
        self._col = col
        self._board = np.zeros((row, col), dtype=int)
        self._black_stone = -1
        self._white_stone = 1

    def place_stone(self, move: Tuple[int, int], symbol: str) -> None:
        if symbol == 'X':
            self._board[move[0]][move[1]] = self._black_stone
        else:
            self._board[move[0]][move[1]] = self._white_stone

    def is_full(self) -> bool:
        return np.all(self._board != 0)

    def in_the_bound(self, pos: Tuple[int, int]) -> int:
        if 0 <= pos[0] < self._row and 0 <= pos[1] < self._col:
            return 1
        return 0

class Gomoku(Board):
    def __init__(self, bd_sz: List[int] = [15, 15], win_cond: int = 5, rule: int = 0, reward: int = 1) -> None:
        super().__init__(row=bd_sz[0], col=bd_sz[1])
        self.__win_cond = win_cond
        self.__rule = rule
        self.__reward = reward
        self._now_player = -1

    @property
    def now_player(self) -> int:
        return self._now_player

    @now_player.setter
    def now_player(self, player_name: str) -> None:
        if player_name == 'X':
            self._now_player = self._black_stone
        else:
            self._now_player = self._white_stone

    def is_win(self) -> bool:
        if self.free_cond():
            return True
        return False

    def free_cond(self) -> bool:
        return self.straight_exam([0, 1]) or \
               self.straight_exam([1, 0]) or \
               self.diagonal_exam([1, 1]) or \
               self.diagonal_exam([1, -1])

    def straight_exam(self, movement: List[int]) -> bool:
        susp_axis_increment = np.array([1, 1]) - np.array(movement)
        init = np.array([0, 0])
        while init.max() < self._row:
            if self.check_connect(init, movement) == 1:
                return True
            init += susp_axis_increment
        return False

    def diagonal_exam(self, movement: List[int]) -> bool:
        susp_axis_sets = []
        for i in range(self._row):
            susp_axis_sets.append([0, i])

        flag = int((1 - movement[1]) / 2)
        for i in range(1, self._row):
            susp_axis_sets.append([i, flag * (self._row - 1)])

        for tup in susp_axis_sets:
            if self.check_connect(tup, movement) == 1:
                return True
        return False

    def check_connect(self, start_point: List[int], movement: List[int]) -> int:
        num_in_row = 0
        susp_row = start_point[0]
        susp_col = start_point[1]
        while self.in_the_bound((susp_row, susp_col)) == 1:
            assert (susp_row < self._row)
            assert (susp_col < self._col)
            if self._board[susp_row][susp_col] == self._now_player:
                num_in_row += 1
            else:
                num_in_row = 0

            if num_in_row > self.__win_cond - 1:
                return 1

            susp_row += movement[0]
            susp_col += movement[1]
        return 0

    def gomoku_respond(self, move: Tuple[int, int], symbol: str) -> Tuple[List[List[int]], int, bool, str]:
        self.place_stone(move, symbol)
        self._now_player = 1
        if symbol == 'X':
            self._now_player = -1

        if self.is_win():
            return self._board.tolist(), self.__reward, True, symbol
        if self.is_full():
            return self._board.tolist(), 0, True, 'nobody'
        return self._board.tolist(), 0, False, None

    def decide_side(self) -> str:
        if np.random.randint(100) > 49:
            return 'X'
        return 'O'

# main function
def main_solution(board_size: List[int], win_condition: int, rule: int, reward: int, moves: List[Tuple[int, int, str]]) -> Tuple[List[List[int]], int, bool, str]:
    game = Gomoku(bd_sz=board_size, win_cond=win_condition, rule=rule, reward=reward)
    for move in moves:
        result = game.gomoku_respond(move[:2], move[2])
        if result[2]:  # If the game is over
            return result
    return game._board.tolist(), 0, False, None

