from copy import copy

# all class and function definitions in the code file, if any
class EnumMetaClass:
    def __init__(self, name, bases, dict):
        for base in bases:
            if base.__class__ is not EnumMetaClass:
                raise TypeError("Enumeration base class must be enumeration")
        bases = [x for x in bases if x is not Enum]
        self.__name__ = name
        self.__bases__ = bases
        self.__dict = {}
        for key, value in list(dict.items()):
            self.__dict[key] = EnumInstance(name, key, value)

    def __getattr__(self, name):
        if name == "__members__":
            return [x for x in list(self.__dict.keys()) if len(x) < 2 or x[:2] != "__"]

        try:
            return self.__dict[name]
        except KeyError:
            for base in self.__bases__:
                try:
                    return getattr(base, name)
                except AttributeError:
                    continue

        raise AttributeError(name)

    def valid(self, name):
        if name in self.__dict:
            return self.__dict[name]
        else:
            raise ValueError("Specified name not in enum")

    def getWithValue(self, value):
        try:
            for k in self.__dict:
                if k[0] == "_":
                    continue
                if self.__dict[k].value() == value:
                    return self.__dict[k]
        except KeyError:
            for base in self.__bases__:
                try:
                    return base.getWithValue(value)
                except AttributeError:
                    continue

        raise AttributeError(value)

    def __repr__(self):
        s = self.__name__
        if self.__bases__:
            s = s + "(" + string.join([x.__name__ for x in self.__bases__], ", ") + ")"
        if self.__dict:
            list = []
            for key, value in list(self.__dict.items()):
                if key[0] == "_":
                    continue
                list.append("%s: %s" % (key, value.value()))
            s = "%s: {%s}" % (s, string.join(list, ", "))
        return s

    def name(self):
        return self.__name__

    def list(self, separator=", "):
        return separator.join(self.__members__)

    def __iter__(self):
        values = [self.__dict[x] for x in self.__members__ if x[0] != "_"]
        for base in self.__bases__:
            values.extend(list(base.__iter__(self)))
        return iter(sorted(values))


class EnumInstance:
    def __init__(self, classname, enumname, value):
        self.__classname = classname
        self.__enumname = enumname
        self.__value = value

    def __repr__(self):
        return "EnumInstance(%s, %s, %s)" % (
            repr(self.__classname),
            repr(self.__enumname),
            repr(self.__value),
        )

    def __str__(self):
        return "%s.%s" % (self.__classname, self.__enumname)

    def __cmp__(self, other):
        if other == None:
            return 1

        try:
            if isinstance(other, EnumInstance):
                return cmp(self.__value, other.__value)
        except TypeError:
            pass
        return cmp(self.__value, other)

    def name(self):
        return self.__enumname

    def value(self):
        return self.__value


Enum = EnumMetaClass("Enum", (), {})

def check_enum(option, opt, value):
    try:
        return option.enum.valid(value)
    except ValueError:
        raise OptionValueError(
            "'%s' is an invalid type for %s (valid types are %s)"
            % (value, option, ", ".join(option.enum.__members__))
