# import necessary packages
import math

# all class and function definitions in the code file, if any
def divide(x, y):
    return (x * 1.0) / (y * 1.0)

def lowestCommonDenominator(numerator, denominator):
    gcd = math.gcd(numerator, denominator)
    return denominator // gcd

def getVariations(num):
    for i in range(1, num):
        for j in range(1, num):
            yield (i*10 + num, num*10 + j), (i, j)

# main function
def main_solution(max_digit):
    numerator = 1
    denominator = 1
    for i in range(1, max_digit + 1):
        for calc, test in getVariations(i):
            result = divide(*calc)
            if result == divide(*test):
                numerator *= test[0]
                denominator *= test[1]
    final_denominator = lowestCommonDenominator(numerator, denominator)
    return final_denominator

