class Grammar:

    def __init__(self, N, E, P, S):
        self.N = N
        self.E = E
        self.P = P
        self.S = S

    def is_terminal(self, value):
        return value in self.E

    def is_non_terminal(self, value):
        return value in self.N

    @staticmethod
    def get_symbols_from_string(string):
        symbols = []
        for i in range(len(string)):
            if string[i].isalpha():
                symbols.append(string[i])
        return symbols

    def is_regular(self):
        used_in_rhs = {}
        not_allowed_in_rhs = []

        for rule in self.P:
            lhs = rule[0]
            rhs = rule[1]
            has_terminal = False
            has_non_terminal = False
            if len(rhs) > 2:
                return False
            for char in rhs:
                if self.is_non_terminal(char):
                    if not (lhs == self.S and char == self.S):
                        used_in_rhs[char] = True
                    has_non_terminal = True
                elif self.is_terminal(char):
