                        return False
                    has_terminal = True
                if char == 'e':
                    not_allowed_in_rhs.append(lhs)

            if has_non_terminal and not has_terminal:
                return False

        for char in not_allowed_in_rhs:
            if char in used_in_rhs:
                return False

        return True

