# import necessary packages
import re

# all class and function definitions in the code file, if any
def hasNumbers(inputString):
    return any(char.isdigit() for char in inputString)

# main function
def main_solution(function):
    # Convert the input function string to a list of terms
    arrayPlusMinus = []
    if "+" in function or "-" in function:
        for i in range(len(function)):
            if function[i] == "+":
                arrayPlusMinus.append("+")
            elif function[i] == "-":
                arrayPlusMinus.append("-")

        array = re.split(r'\+|\-', function)

        count = 0
        for var in array:
            if "^" in var:
                varArray = var.split("^")
                number = varArray[1]
                varArray[1] = str(int(varArray[1]) - 1)
                if hasNumbers(varArray[0]):
                    firstNumber = re.findall(r'\d+', varArray[0])
                    number = int(firstNumber[0]) * int(number)
                    number = str(number)

                var = number + "x" + "^" + varArray[1]
                array[count] = var
            elif "^" not in var:
                if var == "x":
                    array[count] = "1"
                else:
                    array[count] = "0"

            count += 1

        result = []
        for i in range(len(array)):
            if i == len(array) - 1:
                result.append(array[i])
            else:
                result.append(array[i] + " " + arrayPlusMinus[i])

        return " ".join(result)

    elif function == "x":
