# all class and function definitions in the code file, if any
class BSTNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

    # Insert the given value into the tree
    def insert(self, value):
        if self.value is None:
            self.value = value
        elif value < self.value:
            if self.left is None:
                self.left = BSTNode(value)
            else:
                self.left.insert(value)
        else:
            if self.right is None:
                self.right = BSTNode(value)
            else:
                self.right.insert(value)

    # Return True if the tree contains the value, False if it does not
    def contains(self, target):
        if target == self.value:
            return True
        elif target < self.value:
            if self.left is None:
                return False
            return self.left.contains(target)
        else:
            if self.right is None:
                return False
            return self.right.contains(target)

    # Return the maximum value found in the tree
    def get_max(self):
        if self.right:
            return self.right.get_max()
        else:
            return self.value

    # Call the function `fn` on the value of each node
    def for_each(self, fn):
        fn(self.value)
        if self.left:
            self.left.for_each(fn)
        if self.right:
            self.right.for_each(fn)

# main function
def main_solution(values, target):
    # Convert JSON serializable inputs to original input variables
    root = BSTNode(values[0])
    for value in values[1:]:
        root.insert(value)

    # Perform the required operations
    contains_target = root.contains(target)
    max_value = root.get_max()

    # Convert outputs to JSON serializable format
    result = {
        "contains_target": contains_target,
        "max_value": max_value
    }

    return result

