# main function
def main_solution(n, board):
    res = 0

    def pass_zero(board):
        i = 0
        while i < n:
            if 0 in board[i]:
                board[i].remove(0)
            else:
                i += 1

        for i in range(n):
            for _ in range(n - len(board[i])):
                board[i].append(0)
        return board

    def squeeze(board):
        i = 0
        board = pass_zero(deepcopy(board))

        for i in range(n):
