                    board[i][j] *= 2
                    board[i][j + 1] = 0

        board = pass_zero(deepcopy(board))
        return board

    def rotate(cnt, board):
        for _ in range(cnt):
            new_board = [[0 for _ in range(n)] for _ in range(n)]
            for i in range(n):
                for j in range(n):
                    new_board[i][j] = board[j][n - i - 1]
            board = new_board
        return board

