# pair: (N, N) -> N
def pair(x, y):
    mxy = max(x, y)
    return mxy * mxy + mxy + x - y

# unpair: N -> (N, N)
def unpair(z):
    m = int(z ** 0.5)
    ml = z - m * m
    if ml < m:
        return ml, m
    else:
        return m, m * m + m + m - z

class Expression:
    @classmethod
    def from_num(cls, value):
        maxType = 5  # 5 is the number of operations.
        m = value % maxType
        value //= maxType
        if m == 0:
            return Num.from_num(value)
        elif m == 1:
            return Add.from_num(value)
        elif m == 2:
            return Sub.from_num(value)
        elif m == 3:
            return Mult.from_num(value)
        elif m == 4:
            return Div.from_num(value)

class Num(Expression):
    def __init__(self, value):
        self.value = value
    @classmethod
    def from_num(cls, value):
        return cls(value)
    def eval(self):
        return self.value
    def __str__(self):
        return str(self.value)

class Add(Expression):
    def __init__(self, left, right):
        self.left = left
        self.right = right
    @classmethod
    def from_num(cls, value):
        l, r = unpair(value)
        return cls(Expression.from_num(l), Expression.from_num(r))
    def eval(self):
        return self.left.eval() + self.right.eval()
    def __str__(self):
        return "(" + str(self.left) + " + " + str(self.right) + ")"

class Sub(Expression):
    def __init__(self, left, right):
        self.left = left
        self.right = right
    @classmethod
    def from_num(cls, value):
        l, r = unpair(value)
        return cls(Expression.from_num(l), Expression.from_num(r))
    def eval(self):
        return self.left.eval() - self.right.eval()
    def __str__(self):
        return "(" + str(self.left) + " - " + str(self.right) + ")"

class Mult(Expression):
    def __init__(self, left, right):
        self.left = left
        self.right = right
    @classmethod
    def from_num(cls, value):
        l, r = unpair(value)
        return cls(Expression.from_num(l), Expression.from_num(r))
    def eval(self):
