class Div(Expression):
    def __init__(self, left, right):
        self.left = left
        self.right = right
    @classmethod
    def from_num(cls, value):
        l, r = unpair(value)
        return cls(Expression.from_num(l), Expression.from_num(r))
    def eval(self):
        r = self.right.eval()
        if r == 0:
            return 0
        return self.left.eval() / r
    def __str__(self):
        return "(" + str(self.left) + " / " + str(self.right) + ")"

operations = [
    "==",
    "!=",
    "<",
    ">",
    "<=",
    ">="
]

class Equation():
    def __init__(self, comparison, left, right):
        self.comparison = comparison
        self.left = left
        self.right = right
    @classmethod
    def from_num(cls, value):
        maxOp = 2
        opN = value % maxOp
        op = operations[opN]
        value //= maxOp
        l, r = unpair(value)
        left = Expression.from_num(l)
        right = Expression.from_num(r)
        return cls(op, left, right)
    def eval(self):
        left = self.left.eval()
        right = self.right.eval()
        if self.comparison == "==":
            return left == right
        elif self.comparison == "!=":
            return left != right
        elif self.comparison == "<":
            return left < right
        elif self.comparison == ">":
            return left > right
        elif self.comparison == "<=":
            return left <= right
        elif self.comparison == ">=":
            return left >= right
        else:
            raise Exception("Unknown comparison: " + self.comparison)
    def __str__(self):
        return str(self.left) + " " + str(self.comparison) + " " + str(self.right)

# main function
