def reverseString(s):
    if len(s) == 0:
        return s
    else:
        return reverseString(s[1:]) + s[0]

def naturalNumberSum(n):
    if n == 1:
        return 1
    else:
        return n + naturalNumberSum(n - 1)

def power(a, b):
    if b == 0:
        return 1
    else:
        return a * power(a, b - 1)

def factorial(n):
    if n == 1:
        return 1
    else:
        return n * factorial(n - 1)

def sumOfArray(arr):
    if len(arr) == 1:
        return arr[0]
    else:
        return arr[0] + sumOfArray(arr[1:])

def reverseArray(array):
    if len(array) == 1:
        return array
    return [array[-1]] + reverseArray(array[:-1])

