class Stack:
    def __init__(self):
        self.top = -1
        self.stack = []

    def isempty(self):
        return self.top == -1

    def peek(self):
        return self.stack[-1]

    def pop(self):
        if not self.isempty():
            self.top -= 1
            return self.stack.pop()

    def push(self, element):
        self.top += 1
        self.stack.append(element)

class Interpreter:
    def __init__(self, expression):
        self.infix = ''.join(expression.split(' '))
        self.postfix = None
        self.operators = {'+': 0, '-': 0, '/': 1, '*': 1, '^': 2}
        self.output = ''
        self.stack = Stack()
        self.infixtopostfix()

    def getpostfix(self):
        return self.postfix

    def notgreater(self, char):
        try:
            a = self.operators[char]
            b = self.operators[self.stack.peek()]
            return a <= b
        except KeyError:
            return False

    def infixtopostfix(self):
        for char in self.infix:
            if char not in self.operators and not char == '(' and not char == ')':
                self.output += char
            elif char == '(':
                self.stack.push(char)
            elif char == ')':
                while not self.stack.isempty() and self.stack.peek() != '(':
                    a = self.stack.pop()
                    self.output += a
                else:
                    self.stack.pop()
            else:
                while not self.stack.isempty() and self.notgreater(char):
                    self.output += self.stack.pop()
                self.stack.push(char)
        while not self.stack.isempty():
            self.output += self.stack.pop()
        self.postfix = self.output

