def get_first_non_matching_pair(word1, word2):
    """
    "abc", "bdc" -> (a,b)
    "ab", "abc" -> ('',c)
    "abc", "ab" -> ('c','')
    :return:
    """
    for i in range(min(len(word1), len(word2))):
        if word1[i] != word2[i]:
            return (word1[i], word2[i])

    if len(word1) > len(word2):
        return (word1[len(word2)] , '')
    elif len(word2) > len(word1):
