# Helper function to perform XOR operation
def xor(a, b):
    return (a or b) and not (a and b)

# Function to multiply two quaternions
def quaternion(a, b):
    negative = False
    if xor(a[0] == '-', b[0] == '-'):
        negative = True
        a = a.replace('-', '')
        b = b.replace('-', '')
