# import necessary packages
import random

# all class and function definitions in the code file, if any
class Node:
    def __init__(self, data):
        self.left = None
        self.right = None
        self.data = data

    def insert(self, data):
        if self.data:
            if int(data.split()[0]) < int(self.data.split()[0]):
                if self.left is None:
                    self.left = Node(data)
                else:
                    self.left.insert(data)
            elif int(data.split()[0]) > int(self.data.split()[0]):
                if self.right is None:
                    self.right = Node(data)
                else:
                    self.right.insert(data)
        else:
            self.data = data

    def Inorder(self, root):
        inorder_lst = []
        if root:
            inorder_lst = self.Inorder(root.left)
            inorder_lst.append(root.data)
            inorder_lst = inorder_lst + self.Inorder(root.right)
        return inorder_lst

    def Search_ID(self, ID_search):
        if int(ID_search) == int(self.data.split()[0]):
            return self.data
        elif int(ID_search) < int(self.data.split()[0]):
            if self.left is not None:
                return self.left.Search_ID(ID_search)
        else:
            if self.right is not None:
                return self.right.Search_ID(ID_search)
        return None

# main function
def main_solution(employee_records, search_id):
    # Convert the list of employee records into a BST
    if not employee_records:
        return None

    root = Node(employee_records[0])
    for record in employee_records[1:]:
        root.insert(record)

    # Search for the employee record by ID
    result = root.Search_ID(search_id)

    # Return the result as a JSON serializable string
    return result if result else "Employee not found"

