    def get_value(self):
        return self.value

class MatEnTripletas():
    def __init__(self, fila, col, value):
        self.filas = fila
        self.columnas = col
        self.lista = []
        tripleta = Tripleta(fila, col, value)
        self.lista.append(tripleta)

    def cant(self):
