        c = MatEnTripletas(ma, na, 0)
        i = 1
        j = 1
        k = 0
        while((i <= p) and (j <= q)):
            ti = self.retorna_tripleta(i)
            tj = matriz.retorna_tripleta(j)
            fi = ti.get_fila()
            fj = tj.get_fila()
            k = k + 1
            aux = self.comparar(fi, fj)
            if(aux == -1):
                c.asigna_tripleta(ti, k)
                i = i + 1
            elif(aux == 1):
                c.asigna_tripleta(tj, k)
                j = j + 1
            elif(aux == 0):
