                    vj = tj.get_value()
                    ss = vi + vj
                    if (ss != 0):
                        tx = Tripleta(fi, ci, ss)
                        c.asigna_tripleta(tx, k)
                    else:
                        k = k - 1
                    i = i + 1
                    j = j + 1
        while(i <= p):
            ti = self.retorna_tripleta(i)
            k = k + 1
            c.asigna_tripleta(ti, k)
            i = i + 1
        while(j <= q):
