# import necessary packages
import copy
import random

# Constants
X = "X"
O = "O"
EMPTY = None

# Function to determine the player
def player(board):
    count = sum(cell is not EMPTY for row in board for cell in row)
    return X if count % 2 == 0 else O

# Function to get available actions
def actions(board):
    return [(i, j) for i in range(3) for j in range(3) if board[i][j] == EMPTY]

# Function to get the result of an action
def result(board, action):
    new_board = copy.deepcopy(board)
    new_board[action[0]][action[1]] = player(board)
    return new_board

# Function to determine the winner
def winner(board):
    lines = [
        [(0, 0), (0, 1), (0, 2)],
        [(1, 0), (1, 1), (1, 2)],
        [(2, 0), (2, 1), (2, 2)],
        [(0, 0), (1, 0), (2, 0)],
        [(0, 1), (1, 1), (2, 1)],
        [(0, 2), (1, 2), (2, 2)],
        [(0, 0), (1, 1), (2, 2)],
        [(0, 2), (1, 1), (2, 0)],
    ]
    for line in lines:
        if board[line[0][0]][line[0][1]] == board[line[1][0]][line[1][1]] == board[line[2][0]][line[2][1]] != EMPTY:
            return board[line[0][0]][line[0][1]]
    return None

# Function to check if the game is over
def terminal(board):
    return winner(board) is not None or not any(EMPTY in row for row in board)

# Function to evaluate the utility of the board
def utility(board):
    win = winner(board)
    return 1 if win == X else -1 if win == O else 0

# Minimax algorithm
def minimax(board):
    if terminal(board):
        return None
    if player(board) == X:
        return max_value(board)[1]
    else:
        return min_value(board)[1]

def max_value(board):
    if terminal(board):
        return utility(board), None
    v = -float('inf')
    move = None
    for action in actions(board):
        v2, _ = min_value(result(board, action))
        if v2 > v:
            v, move = v2, action
    return v, move

def min_value(board):
    if terminal(board):
        return utility(board), None
    v = float('inf')
    move = None
    for action in actions(board):
        v2, _ = max_value(result(board, action))
        if v2 < v:
            v, move = v2, action
    return v, move

# Main function
def main_solution(board):
    if terminal(board):
        return utility(board)
    else:
        return minimax(board)

