    for r in primes[6:ind_p]:
        if p % r == 0 or q % r == 0:
            return False
    for r in primes[ind_p:ind_q]:
        if q % r == 0:
            return False
    return True

def find_family(primes, primes_strings, primes_sum_mod, primes_squared):
    L = len(primes)
    prime_twins = [{j for j in range(1, i) if is_both_prime(i, j, primes, primes_strings, primes_sum_mod, primes_squared)} for i in range(L)]
