        StatesCount = self.bayesian_network.variables[X].no_states
        e = evidence.copy()
        Q = [0] * StatesCount

        for i in range(StatesCount):
            e[X] = i
            Q[i] = self._enumerate_all(self.topo_order, e)
        alpha = 1/sum(Q)

