# import necessary packages
from math import sqrt
from itertools import combinations_with_replacement as comb

# all class and function definitions in the code file, if any
def isPrime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(sqrt(n)+1), 2):
        if n % i == 0:
            return False
    return True

class GeneratePrime(object):
    def __init__(self, maximum):
        self.number = 0
        self.index = 0
        self.cache = []
        self.maximum = maximum

    def __iter__(self):
        self.index = 0
        return self

    def getCache(self):
        return self.cache

    def __next__(self):
        if self.number > self.maximum:
            raise StopIteration
        if len(self.cache) > self.index:
            toReturn = self.cache[self.index]
            self.index += 1
            return toReturn
        while(not isPrime(self.number)):
            self.number += 1
        toReturn = self.number
        self.cache.append(toReturn)
        self.number += 1
        self.index += 1
        return toReturn

def goldbach(n):
    listOfPrimeToN = []
    iterator = GeneratePrime(n)
    for num in iterator:
        if num >= n:
            break
        listOfPrimeToN.append(num)
    listToCheck = list(comb(listOfPrimeToN, 2))
    for elem in listToCheck:
        if elem[0] + elem[1] == n:
            return elem

