# import necessary packages
import numpy as np
from numpy import random as r
import math

# all class and function definitions in the code file, if any
class TicTacToe:
    def __init__(self):
        self.board = np.zeros(9)
        self.dimension = int(math.sqrt(self.board.shape[0]))
        self.lastValidIndex = self.dimension - 1
        self.over = False
        self.turn = 1

    def action(self, move):
        self.board[self.dimension * move[0] + move[1]] = self.turn
        self.turn = self.turn * -1
        self.isWinner()

    def isWinner(self):
        for row in range(self.dimension):
            if self.checkHori(row, "x") or self.checkHori(row, "o"):
                self.over = True
                return
        for col in range(self.dimension):
            if self.checkVert(col, "x") or self.checkVert(col, "o"):
                self.over = True
                return
        if self.checkDiag("left", "x") or self.checkDiag("left", "o") or self.checkDiag("right", "x") or self.checkDiag("right", "o"):
            self.over = True
            return

    def checkHori(self, row, playerToCheck):
        if self.dimension > row:
            properView = self.normalShape()
            xHoriWin = np.array([1, 1, 1])
            yHoriWin = np.array([-1, -1, -1])
            toCheck = properView[row]
            if playerToCheck == "x":
                return np.array_equal(toCheck, xHoriWin)
            else:
                return np.array_equal(toCheck, yHoriWin)
        return False

    def checkVert(self, col, playerToCheck):
        if self.dimension > col:
            properView = self.normalShape()
            xVertWin = np.array([1, 1, 1])
            yVertWin = np.array([-1, -1, -1])
            toCheck = properView[:, col]
            if playerToCheck == "x":
                return np.array_equal(toCheck, xVertWin)
            else:
                return np.array_equal(toCheck, yVertWin)
        return False

    def checkDiag(self, dir, playerToCheck):
        properView = self.normalShape()
        xFlatWin = np.array([1, 1, 1])
        yFlatWin = np.array([-1, -1, -1])
        if dir == "left":
            toCheck = properView.diagonal()
        else:
            toCheck = np.fliplr(properView).diagonal()
        if playerToCheck == "x":
            return np.array_equal(toCheck, xFlatWin)
        else:
            return np.array_equal(toCheck, yFlatWin)

    def normalShape(self):
        return self.board.reshape(self.dimension, self.dimension)

# main function
def main_solution(moves):
    game = TicTacToe()
    for move in moves:
        game.action(move)
        if game.over:
            break
    return game.over

