def initial_state():
    return [[EMPTY, EMPTY, EMPTY],
            [EMPTY, EMPTY, EMPTY],
            [EMPTY, EMPTY, EMPTY]]

# Function to determine the current player
def player(board):
    if board == initial_state():
        return X
    flat_board = [cell for row in board for cell in row]
    num_x = flat_board.count('X')
    num_o = flat_board.count('O')
    if num_x > num_o:
        return O
    return X

