class Vector:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    @staticmethod
    def subtract(v1, v2):
        return Vector(v1.x - v2.x, v1.y - v2.y)

    @staticmethod
    def add(v1, v2):
        return Vector(v1.x + v2.x, v1.y + v2.y)

    @staticmethod
    def divide(v, scalar):
        return Vector(v.x / scalar, v.y / scalar)

    @staticmethod
    def rotate(v, angle):
        return Vector(v.x * math.cos(angle) - v.y * math.sin(angle), v.x * math.sin(angle) + v.y * math.cos(angle))

    @staticmethod
    def multiply(v, scalar):
        return Vector(v.x * scalar, v.y * scalar)

    def magnitude(self):
        return math.sqrt(self.x ** 2 + self.y ** 2)

def degreesToRadians(degrees):
    return math.pi / 180 * degrees

def line(start, end):
    full = Vector.subtract(end, start)
    distance = full.magnitude()
    if distance < 4:
        return

    half = Vector.divide(full, 2)
    A = Vector.add(half, start)
    rotate = Vector.rotate(half, degreesToRadians(90))
    rotate = Vector.multiply(rotate, 2 / 3)
    B = Vector.add(rotate, A)

    line(start, A)
    line(A, B)
    line(B, A)
    line(A, end)

def flake(start, end):
    side = Vector.subtract(end, start)
    a = start
    b = end
    for _ in range(6):
        line(a, b)
        side = Vector.rotate(side, degreesToRadians(60))
        a = b
        b = Vector.add(side, a)

