# import necessary packages
import random

# all class and function definitions in the code file, if any
def cross(a, b):
    return [s+t for s in a for t in b]

rows = 'ABCDEFGHI'
cols = '123456789'
boxes = cross(rows, cols)

row_units = [cross(r, cols) for r in rows]
column_units = [cross(rows, c) for c in cols]
square_units = [cross(rs, cs) for rs in ('ABC','DEF','GHI') for cs in ('123','456','789')]
d_units = [[rows[i]+cols[i] for i in range(9)]] + [[rows[i]+cols[8-i] for i in range(9)]]
unitlist = row_units + column_units + square_units + d_units
units = dict((s, [u for u in unitlist if s in u]) for s in boxes)
peers = dict((s, set(sum(units[s],[]))-set([s])) for s in boxes)

def assign_value(values, box, value):
    if values[box] == value:
        return values
    values[box] = value
    return values

def naked_twins(values):
    twins = []
    for b1 in [box for box in values.keys() if len(values[box]) == 2]:
        for b2 in peers[b1]:
            if set(values[b1]) == set(values[b2]):
                if {b1,b2} not in twins:
                    twins.append({b1,b2})

    vals = []
    for t in twins:
        b1, b2 = list(t)
        for l1 in units[b1]:
            if b2 in l1:
                vals.append((values[b1],l1))

    for twin_args in vals:
        twin = twin_args[0]
        peer_units  = twin_args[1]
        for p in peer_units:
            if values[p] != twin:
                for t in twin:
                    assign_value(values, p, values[p].replace(t,''))  

    return values

def grid_values(grid):
    chars = []
    digits = '123456789'
    for c in grid:
        if c in digits:
            chars.append(c)
        if c == '.':
            chars.append(digits)
    return dict(zip(boxes, chars))

def eliminate(values):
    solved_values = [box for box in values.keys() if len(values[box]) == 1]
    for box in solved_values:
        digit = values[box]
        for peer in peers[box]:
            assign_value(values, peer, values[peer].replace(digit,''))
    return values

def only_choice(values):
    for unit in unitlist:
        for digit in '123456789':
            dplaces = [box for box in unit if digit in values[box]]
            if len(dplaces) == 1:
                assign_value(values, dplaces[0], digit)
    return values

def reduce_puzzle(values):
    stalled = False
    while not stalled:
        solved_values_before = len([box for box in values.keys() if len(values[box]) == 1])
        values = eliminate(values)
        values = only_choice(values)
        values = naked_twins(values)
        solved_values_after = len([box for box in values.keys() if len(values[box]) == 1])
        stalled = solved_values_before == solved_values_after
        if len([box for box in values.keys() if len(values[box]) == 0]):
            return False
    return values

def search(values):
    values = reduce_puzzle(values)
    if values == False:
        return False
    if all(len(values[box]) == 1 for box in boxes):
        return values
    _, b = min((len(values[s]), s) for s in boxes if len(values[s]) > 1)
    for v in values[b]:
        tmp_values = values.copy()
        assign_value(tmp_values, b, v)
        result = search(tmp_values)
        if result:
            return result
    return False

# main function
def main_solution(grid):
    values = grid_values(grid)
    values = search(values)
    if values:
        return {k: values[k] for k in values if len(values[k]) == 1}
    return {}

