# import necessary packages
import math

# all class and function definitions in the code file, if any
def get_pentagonal(n):
    """Returns the first n pentagonal numbers."""
    return [((i * ((3 * i) - 1)) / 2) for i in range(1, n + 1)]

def is_pentagonal(p):
    n = ((math.sqrt((24 * p) + 1) + 1) / 6)
    if float(n).is_integer():
        return True
    else:
        return False

# main function
def main_solution(n):
    p_list = get_pentagonal(n)
    for i in p_list:
        for j in p_list:
            if i < j:
                if is_pentagonal(i + j) and is_pentagonal(j - i):
                    return {"D": int(j - i)}
    return {"D": None}

