# import necessary packages
import random

# all class and function definitions in the code file, if any
class Node:
    def __init__(self, data, children=[]):
        self.data = data
        self.children = children

    def __repr__(self):
        if self.children == []:
            return 'Leaf ' + str(self.data)
        else:
            return 'Node ' + str(self.data) + ' ' + str(self.children)

    def find_stack(self, data):
        to_visit = [self]
        while to_visit:
            curr = to_visit.pop()
            if curr.data == data:
                return curr
            to_visit.extend(curr.children)

class Tree:
    def __init__(self, root):
        self.root = root

    def __repr__(self):
        return "<Tree root={root}>".format(root=self.root)

    def find_in_tree(self, data):
        return self.root.find_stack(data)

