# import necessary packages
import math
import random

# all class and function definitions in the code file, if any
def is_hepta(x):
    sol = solve_quad(5, -3, -2 * x)[1]
    if sol is not None and sol > 0 and sol % 1 == 0:
        return True
    return False

def is_octa(x):
    sol = solve_quad(3, -2, -x)[1]
    if sol is not None and sol > 0 and sol % 1 == 0:
        return True
    return False

def is_square(x):
    return math.sqrt(x) % 1 == 0

def check_fam(x):
    """
    Returns 0 if x is a triangle number, 1 if square, ... , 5 if octagonal.
    """
    func_arr = [is_triangle, is_square, is_penta, is_hexa, is_hepta, is_octa]
    for i in range(len(func_arr)):
        if func_arr[i](x):
            return i
    return None

def find_cyclic_chain(fam_map, x, fams_found):
    result = []
    # base case when x does not belong to a family or if we've already seen
    # this family.
    if x not in fam_map:
        return result
    if fams_found[fam_map[x]]:
        # all hexagonal numbers are also triangular
        if fam_map[x] == 0 and not fams_found[3]:
            fams_found[3] = True 
        else:
            return result
    result.append(x)
    fams_found[fam_map[x]] = True
    longest = []
    start = (x % 100) * 100
    # return longest possible chain
    # e.g. for numbers between 1800 to 1899
    for i in range(start, start + 100):
        chain = find_cyclic_chain(fam_map, i, list(fams_found))
        if len(chain) > len(longest):
            longest = chain
    return result + longest

def solve_quad(a, b, c):
    discriminant = b**2 - 4*a*c
    if discriminant < 0:
        return None, None
    sqrt_discriminant = math.sqrt(discriminant)
    return (-b + sqrt_discriminant) / (2*a), (-b - sqrt_discriminant) / (2*a)

def is_triangle(x):
    sol = solve_quad(1, 1, -2 * x)[1]
    if sol is not None and sol > 0 and sol % 1 == 0:
        return True
    return False

def is_penta(x):
    sol = solve_quad(3, -1, -2 * x)[1]
    if sol is not None and sol > 0 and sol % 1 == 0:
        return True
    return False

def is_hexa(x):
    sol = solve_quad(2, -1, -x)[1]
    if sol is not None and sol > 0 and sol % 1 == 0:
        return True
    return False

# main function
def main_solution(start_number):
    fam_map = {}
    for i in range(1000, 10000):
        fam = check_fam(i)
        if fam is not None:
            fam_map[i] = fam
    chain = find_cyclic_chain(fam_map, start_number, [False] * 6)
    if len(chain) == 6 and chain[len(chain) - 1] % 100 == start_number // 100:
        return {"chain": chain, "sum": sum(chain)}
    return {"chain": [], "sum": 0}

