# all class and function definitions in the code file, if any
class Environment:
    def __init__(self, parent, bindings={}):
        self.parent = parent
        self.bindings = bindings

    def define(self, name, arg):
        self.bindings[name] = arg

    def set(self, name, arg):
        if name in self.bindings:
            self.bindings[name] = arg
        if self.parent is None:
            raise EvaluationError
        self.parent.set(name, arg)

    def find(self, item):
        if item in self.bindings:
            return self.bindings[item]
        if self.parent is None:
            raise EvaluationError("an error occurred")
        return self.parent.find(item)


class Function:
    def __init__(self, func, env):
        self.params = func[0]
        self.expression = func[1]
        self.env = env

    def get_params(self):
        return self.params

    def get_expression(self):
        return self.expression

    def get_env(self):
        return self.env


class EvaluationError(Exception):
    """Exception to be raised if there is an error during evaluation."""
    pass


def tokenize(source):
    tokens = []
    temp = ''
    comment = False
    com = ''
    for letter in source:
        if comment:
            com = com + letter
            if '\n' in com:
                comment = False
                com = ''
        elif letter.isspace():
            if len(temp) > 0:
                tokens.append(temp)
                temp = ''
        elif letter is '(' or letter is ')':
            if len(temp) > 0:
                tokens.append(temp)
                temp = ''
            tokens.append(letter)
        elif letter is ';':
            comment = True
        else:
            temp = temp + letter
    if len(temp) > 0:
        tokens.append(temp)
    return tokens


