        float(s)
        return True
    except ValueError:
        return False


def parse(tokens):
    def check_valid(tokens):
        open = 0
        close = 0
        for t in tokens:
            if t == "(":
                open+=1
            if t == ')':
                close+=1
        if open == close:
            return True
        return False

    def build_list(tokens):
        if tokens[0] == ')':
            raise SyntaxError

        if tokens[0] == '(':
            out = []
            tokens.pop(0)
            try:
                while tokens[0] != ')':
                    out.append(build_list(tokens))
                    tokens.pop(0)
            except IndexError:
                raise SyntaxError

            return out

        if is_number(tokens[0]):
            return num(tokens[0])

        if isinstance(tokens[0], str):
            return tokens[0]

    if check_valid(tokens):
        ans = build_list(tokens)
        return ans
    raise SyntaxError


def prod(iterable):
    p = 1
    for n in iterable:
        p *= n
    return p


def div(iterable):
    p = float(iterable[0])
    for n in iterable[1:]:
        p /= n
    return p


carlae_builtins = {
    '+': sum,
    '-': lambda args: -args[0] if len(args) == 1 else (args[0] - sum(args[1:])),
    '*': lambda args: args[0] if len(args) == 1 else prod(args),
    '/': lambda args: args[0] if len(args) == 1 else div(args)
}


def evaluate(tree, env=None):
    def ev_func(func, variables):
        params = func.get_params()
        expression = func.get_expression()
        env = Environment(func.get_env)
        for p in range(len(params)):
            env.define(params[p], variables[p])
        return ev(expression, env)

    def ev(tree, env):
        if type(tree) is float:
            return tree

        if type(tree) is int:
            return tree

        if type(tree) is str:
            return env.find(tree)

        if isinstance(tree, list):
            if tree[0] == 'lambda':
                return Function(tree[1:], env)

            if tree[0] in carlae_builtins:
                func = tree[0]
                out = []
                for t in tree[1:]:
                    out.append(ev(t, env))
                return carlae_builtins[func](out)

            if tree[0] == 'define':
                name = tree[1]
                out = ev(tree[2], env)
                env.define(name, out)
                return env.bindings[name]

            if isinstance(tree[0], Function):
                variables = tree[1:]
                return ev_func(env.find(tree[0]), variables)

            if type(tree[0]) is str:
                func = env.find(tree[0])
                if isinstance(func, Function):
                    return ev_func(func, tree[1:])

    par = Environment(None, carlae_builtins)
    if env is None:
        env = Environment(par, {})
    return ev(tree, env)

