        if dr == 'right':
            tmp.LeftChild = pivot.RightChild
            if pivot.RightChild:
                pivot.RightChild.parent = tmp
            pivot.RightChild = tmp
            if tmp.parent:
                if tmp.parent.LeftChild == tmp:
                    tmp.parent.LeftChild = pivot
                else:
                    tmp.parent.RightChild = pivot
        elif dr == 'left':
            tmp.RightChild = pivot.LeftChild
            if pivot.LeftChild:
                pivot.LeftChild.parent = tmp
            pivot.LeftChild = tmp
            if tmp.parent:
                if tmp.parent.LeftChild == tmp:
                    tmp.parent.LeftChild = pivot
                else:
                    tmp.parent.RightChild = pivot
        else:
            return
        pivot.parent = tmp.parent
        tmp.parent = pivot
        if tmp == self.__root:
            self.__root = pivot

    def __recoler(self, tmp):
        p = tmp.parent
        if not p or not p.red:
            return
        grand_p = p.parent
        if grand_p:
            uncle = grand_p.RightChild if grand_p.LeftChild == p else grand_p.LeftChild
