# all class and function definitions in the code file, if any
class Minesweeper:
    """Implement the rules of Minesweeper :D"""

    def __init__(self, rows, cols, number_of_mines):
        """Set up a random minefield"""

        self.DEFEAT = -1
        self.INPROGRESS = 0
        self.VICTORY = 1

        self._first_move_has_been_made = False
        self.game_status = self.INPROGRESS

