# import necessary packages
from typing import List, Dict

# all class and function definitions in the code file, if any
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def list_to_tree(lst: List[int]) -> TreeNode:
    if not lst:
        return None
    root = TreeNode(lst[0])
    queue = [root]
    i = 1
    while queue and i < len(lst):
        node = queue.pop(0)
        if lst[i] is not None:
            node.left = TreeNode(lst[i])
            queue.append(node.left)
        i += 1
        if i < len(lst) and lst[i] is not None:
            node.right = TreeNode(lst[i])
            queue.append(node.right)
        i += 1
    return root

def tree_to_list(root: TreeNode) -> List[int]:
    if not root:
        return []
    queue = [root]
    lst = []
    while queue:
        node = queue.pop(0)
        if node:
            lst.append(node.val)
            queue.append(node.left)
            queue.append(node.right)
        else:
            lst.append(None)
    while lst[-1] is None:
        lst.pop()
    return lst

class Solution:
    def isSubStructure(self, A: TreeNode, B: TreeNode) -> bool:
        def dfs(A, B):
            if B is None:
                return True
            if A is None:
                return False
            return A.val == B.val and dfs(A.left, B.left) and dfs(A.right, B.right)

        if A is None or B is None:
            return False
        return dfs(A, B) or self.isSubStructure(A.left, B) or self.isSubStructure(A.right, B)

