# import necessary packages
import re
import copy

# all class and function definitions in the code file, if any
class Piece:
    def __init__(self, color):
        self.color = color
        self.name = ""

    def moves_from_position(self, board, position):
        return []

    def moved(self):
        pass

class Rook(Piece):
    def __init__(self, color):
        super().__init__(color)
        self.name = "R" if color == 0 else "r"

class Knight(Piece):
    def __init__(self, color):
        super().__init__(color)
        self.name = "N" if color == 0 else "n"

class Bishop(Piece):
    def __init__(self, color):
        super().__init__(color)
        self.name = "B" if color == 0 else "b"

class King(Piece):
    def __init__(self, color):
        super().__init__(color)
        self.name = "K" if color == 0 else "k"

class Queen(Piece):
    def __init__(self, color):
        super().__init__(color)
        self.name = "Q" if color == 0 else "q"

class Pawn(Piece):
    def __init__(self, color):
        super().__init__(color)
        self.name = "P" if color == 0 else "p"

class Game:
    def _build_board(self):
        board = []
        for i in range(8):
            column = []
            for j in range(8):
                column.append([])
            board.append(column)

        piece_order = [Rook, Knight, Bishop, King, Queen, Bishop, Knight, Rook]

        for i in range(8):
            board[i][0] = piece_order[i](0)
            board[i][7] = piece_order[i](1)

            board[i][1] = Pawn(0)
            board[i][6] = Pawn(1)
        return board

    def __init__(self):
        self.current_player = 0
        self.finished = False
        self.board = self._build_board()

    def _make_move(self, move):
        new_board = copy.deepcopy(self.board)
        current = move[0]
        target = move[1]
        new_board[target[0]][target[1]] = new_board[current[0]][current[1]]
        new_board[target[0]][target[1]].moved()
        new_board[current[0]][current[1]] = []
        return new_board

    def _find_king(self, player, board):
        for i in range(8):
            for j in range(8):
                p = board[i][j]
                if type(p) == King:
                    if p.color == player:
                        return [i, j]
        return 0

    def _in_check(self, board, player):
        king_location = self._find_king(player, board)
        for i in range(8):
            for j in range(8):
                current_piece = board[i][j]
                if current_piece != []:
                    if current_piece.color != player:
                        if current_piece.moves_from_position(
                                board, [i, j]).__contains__(king_location):
                            return True
        return False

    def _in_checkmate(self, board, player):
        for i in range(8):
            for j in range(8):
                current_piece = board[i][j]
                if current_piece != []:
                    if current_piece.color == player:
                        possible_moves = current_piece.moves_from_position(
                            board, [i, j])
                        for move in possible_moves:
                            new_board = self._make_move([[i, j], move])
                            if not self._in_check(new_board, player):
                                return False
        return True

    def _format_move(self, m):
        formatted_move = []
        if re.fullmatch("\w\d\s\w\d", m):
            m = m.split()
            for i in m:
                m1 = ord(i[0].lower()) - 97
                m2 = int(i[1]) - 1
                if m1 < 0 or m1 > 7 or m2 < 0 or m2 > 7:
                    return
                formatted_move.append([m1, m2])
        return formatted_move

    def _puts_self_in_check(self, move, player):
        new_board = self._make_move(move)
        return self._in_check(new_board, player)

    def _legal_move(self, move):
        current = move[0]
        target = move[1]
        moving_piece = self.board[current[0]][current[1]]
        target_piece = self.board[target[0]][target[1]]

        if not moving_piece:
            return False

        if moving_piece.color != self.current_player:
            return False

        if not moving_piece.moves_from_position(self.board,
                                                current).__contains__(target):
            return False

        if self._puts_self_in_check(move, self.current_player):
            return False

        return True

    def _game_finished(self):
        if self._in_check(self.board, self.current_player):
            if self._in_checkmate(self.board, self.current_player):
                return True
        return False

# main function
def main_solution(move_input):
    game = Game()
    formatted_move = game._format_move(move_input)
    if not formatted_move:
        return {"error": "Invalid move format"}
    if not game._legal_move(formatted_move):
        return {"error": "Illegal move"}
    game.board = game._make_move(formatted_move)
    game._switch_player()
    if game._game_finished():
        return {"result": "checkmate"}
    return {"result": "continue"}

