# import necessary packages
import random
from enum import Enum

# all class and function definitions in the code file, if any
class GameState(Enum):
    winning = 1
    losing = 2
    unfinished = 3

def __make_cell():
    return {'bomb': False, 'hypothetic_bomb': False, 'nbombs_neighborhood': 0, 'hidden': True}

def is_bomb(cell):
    return cell['bomb']

def is_hypothetic_bomb(cell):
    return cell['hypothetic_bomb']

def is_revealed(cell):
    return not cell['hidden']

def number_of_bombs_in_neighborhood(cell):
    return cell['nbombs_neighborhood']

def reveal(cell):
    cell['hidden'] = False

def set_hypothetic(cell):
    if not is_revealed(cell):
        cell['hypothetic_bomb'] = True

def unset_hypothetic(cell):
    if not is_revealed(cell):
        cell['hypothetic_bomb'] = False

def neighborhood(x, y, height, width):
    neib = []
    for i in (x-1, x, x+1):
        for j in (y-1, y, y+1):
            if i == x and j == y:
                continue
            if 0 <= i < height and 0 <= j < width:
                neib.append((i, j))
    return neib

def __make_grid(width, height, nbombs):
    coords = [(x, y) for y in range(width) for x in range(height)]
    random.shuffle(coords)
    grid = [[__make_cell() for y in range(width)] for x in range(height)]
    for i in range(nbombs):
        x, y = coords[i]
        grid[x][y]['bomb'] = True
        for neighbor in neighborhood(x, y, height, width):
            x1, y1 = neighbor
            grid[x1][y1]['nbombs_neighborhood'] += 1
    return grid

def make_game(width, height, nbombs):
    return {'width': width, 'height': height, 'nbombs': nbombs, 'grid': __make_grid(width, height, nbombs)}

def get_state(game):
    for j in range(game['width']):
        for i in range(game['height']):
            if is_bomb(game['grid'][i][j]) and is_hypothetic_bomb(game['grid'][i][j]):
                return GameState.winning
    for j in range(game['width']):
        for i in range(game['height']):
            if is_revealed(game['grid'][i][j]) and is_bomb(game['grid'][i][j]):
                return GameState.losing
            if not is_revealed(game['grid'][i][j]) and not is_bomb(game['grid'][i][j]):
                return GameState.unfinished
    return GameState.winning

