# import necessary packages
import math

# all class and function definitions in the code file, if any
def is_prime(number):
    if number < 0:
        return 0
    elif number == 2 or number == 3:
        return 1
    elif number % 2 == 0 or number % 3 == 0 or number == 1:
        return 0
    else:
        start = 5
        while start <= int(math.sqrt(number)):
            if number % start == 0:
                return 0
            if number % (start + 2) == 0:
                return 0
            start += 6
        return 1

def is_prime_trunck(number):
    special_char = ['2', '3', '5', '7']
    if number < 0:
        return 0
    elif number == 2 or number == 3:
        return 1
    elif number % 2 == 0 or number % 3 == 0 or number == 1:
        return 0
    elif str(number)[-1:] not in special_char or str(number)[:1] not in special_char:
        return 0
    else:
        start = 5
        while start <= int(math.sqrt(number)):
            if number % start == 0:
                return 0
            if number % (start + 2) == 0:
                return 0
            start += 6
        return 1

def is_right_trunckable(number):
    trunckable = 1
    number = str(number)[:-1]
    while number:
        if not is_prime(int(number)):
            trunckable = 0
            break
        number = str(number)[:-1]
    return trunckable

def is_left_trunckable(number):
    trunckable = 1
    number = str(number)[1:]
    while number:
        if not is_prime(int(number)):
            trunckable = 0
            break
        number = str(number)[1:]
    return trunckable

# main function
def main_solution(limit):
    prime_numbers = []
    trunckable_primes = []

    for x in range(1, limit + 1):
        if is_prime_trunck(x):
            prime_numbers.append(x)

    prime_numbers = [num for num in prime_numbers if num not in [2, 3, 5, 7]]

    for num in prime_numbers:
        if is_right_trunckable(num) and is_left_trunckable(num):
            trunckable_primes.append(num)

    return sum(trunckable_primes)

