            if num_used < len(num_tuple):
                rpn_list.extend(make_rpn_formula(num_tuple, num_used + 1, opr_used, formula + [num_tuple[num_used]]))
            rpn_list.extend(make_rpn_formula(num_tuple, num_used, opr_used + 1, formula + ['+']))
