    m = Map(n_preys, x_min, x_max, catch_distance)

    mov = lambda x, y: {"dx": x * np.cos(y * 2.0 * np.pi), "dy": x * np.sin(y * 2.0 * np.pi)}
    st.cauchy.a = 0
    st.cauchy.b = 2
    m.Set_Predator_Generator(st.cauchy.rvs, np.random.uniform)
    m.Set_Predator_Movement(mov)
