from collections import deque

# Constants
JONES = 1
TIGER = 2
MONKEY = 3
COCKROACH = 4

passengers = {JONES, TIGER, MONKEY, COCKROACH}
invalid = ({TIGER, MONKEY}, {MONKEY, COCKROACH})

