def check(solution):
    left = passengers.copy()
    right = set()

    for p in solution:
        if p in left:
            if JONES not in left:
                return False
            right.add(p)
            left.remove(p)
            if p != JONES:
                right.add(JONES)
                left.remove(JONES)
        else:
            if JONES not in right:
                return False
            left.add(p)
            right.remove(p)
            if p != JONES:
                left.add(JONES)
                right.remove(JONES)
        if left in invalid or right in invalid:
            return False
    if not left:
        return True
    return False

# Function to solve the problem
def solve():
    q = deque()
    q.append([])
    while q:
        s = q.popleft()
        if check(s):
            return s
        for p in passengers:
            n = s.copy()
            n.append(p)
            q.append(n)

# Main function
def main_solution():
    solution = solve()
    return [str(p) for p in solution]

