# import necessary packages
import random

# main function
def main_solution(n):
    """
    Solves the N queens problem and returns the solution as a list of lists.

    Args:
    n (int): The size of the chessboard and the number of queens.

    Returns:
    list: A list of lists where each sublist represents the position of a queen on the chessboard.
    """
    if n < 4:
        return []  # No solution exists for n < 4

    sol = []

    for row in range(n):
        sol.append([row, -1])

    def reset(i):
        """reset the way of solution if failure"""
        for row in range(i, n):
            sol[row][1] = -1

    def check_column(j):
        """check if the column is already taken"""
        for i in range(n):
            if j == sol[i][1]:
                return True
        return False

    def validation(i, j):
        """check column and diagonal"""
        if (check_column(j)):
            return False
        row = 0
        while(row < i):
            if abs(sol[row][1] - j) == abs(row - i):
                return False
            row += 1
        return True

    def recursive(i):
        """backtracking to find solutions"""
        for j in range(n):
            reset(i)
            if validation(i, j):
                sol[i][1] = j
                if (i == n - 1):
                    return sol
                else:
                    result = recursive(i + 1)
                    if result:
                        return result
        return None

    return recursive(0)

