import random

# all class and function definitions in the code file, if any
class node:
    def __init__(self, coord, steps=None, state=None):
        self.coord = coord
        self.next = []
        self.state = state
        self.N = None
        self.E = None
        self.S = None
        self.W = None
        self.steps = steps

    def find_neighbours(self):
        neighbours = [self.N, self.E, self.S, self.W]
        for each in reversed(neighbours):
            if each is None:
                neighbours.remove(each)
        return neighbours

    def __str__(self):
        return self.state

