            new_node.S = old_node
            old_node.N = new_node
            old_node.next.append(new_node)
        elif _y > y:
            new_node.N = old_node
            old_node.S = new_node
            old_node.next.append(new_node)
        elif _x < x:
            new_node.E = old_node
            old_node.W = new_node
            old_node.next.append(new_node)
        elif _x > x:
            new_node.W = old_node
            old_node.E = new_node
            old_node.next.append(new_node)
