    y = initial_y

    # Newton's method implementation
    F_mat = np.matrix([[F(x, y)], [G(x, y)]])
    J = np.matrix([[dFdx(x, y), dFdy(x, y)], [dGdx(x, y), dGdy(x, y)]])
    Jinv = inv(J)
    xyn = np.array([[x], [y]])

