import numpy as np

# all class and function definitions in the code file, if any
def function1(x):
    return np.power(x, 3) - 2 * x - 5

def function1_d(x):
    return 3 * np.power(x, 2) - 2

def function2(x):
    return np.exp(-x) - x

def function2_d(x):
    return -np.exp(-x) - 1

def function3(x):
    return x * np.sin(x) - 1

def function3_d(x):
    return x * np.cos(x) + np.sin(x)

def function4(x):
    return np.power(x, 3) - 3 * np.power(x, 2) + 3 * x - 1

def function4_d(x):
    return 3 * np.power(x, 2) - 6 * x + 3

def newton(fun, fun_d, i=0):
    x_current = i
    while True:
        x_next = x_current - fun(x_current)/fun_d(x_current)
        error = np.abs(x_next - x_current)
        if error < 0.000000001:
            return x_next
        else:
            x_current = x_next

def secant(fun, i1=0, i2=0.01):
    x_current = i1
    x_previous = i2
    while True:
        x_next = x_current - (fun(x_current)*(x_current-x_previous))/(fun(x_current)-fun(x_previous))
        error = np.abs(x_next - x_current)
        if error < 0.000000001:
            return x_next
        else:
            x_previous = x_current
            x_current = x_next

# main function
def main_solution(method, function_index, initial_guess=0, second_guess=0.01):
    # Convert JSON serializable inputs to the original input variables
    functions = [function1, function2, function3, function4]
    derivatives = [function1_d, function2_d, function3_d, function4_d]

    if method == "newton":
        result = newton(functions[function_index], derivatives[function_index], initial_guess)
    elif method == "secant":
        result = secant(functions[function_index], initial_guess, second_guess)
    else:
        raise ValueError("Invalid method specified. Choose 'newton' or 'secant'.")

