def euclidgcd(a, m):
    a = a % m
    if a == 0:
        return (m, 0, 1)
    else:
        d, y, x = euclidgcd(m % a, a)
        return (d, x - (m // a) * y, y)

def multiplicativeinverse(a, m):
    a = a % m
    d, x, y = euclidgcd(a, m)
    if d != 1:
        return 0
    else:
