def allprimesin(n):
    output = []
    i = 2
    while n != 1:
        if n % i == 0:
            output.append(i)
            while n % i == 0:
                n = n // i
            i = 2
        i = i + 1
    return output

def vp(p, n):
    output = 0
    while n % p == 0:
        n = n // p
        output = output + 1
    return output

def power(a, b):
    output = 1
    for i in range(0, b):
        output = output * a
    return output

def solver(b, m):
