import random

# all class and function definitions in the code file, if any
def shuffled_string(s1, s2, s, i, i1, i2, s_out): 
    if i1 >= len(s1): 
        if s[i] != s2[i2]:
            return False
        else:
            if i == len(s) - 1:
                return True
            s_out.append(s2[i2].upper())
            return shuffled_string(s1, s2, s, i+1, i1, i2+1, s_out)

    if i2 >= len(s2): 
        if s[i] != s1[i1]:
            return False
        else:
            if i == len(s) - 1:
                return True
            s_out.append(s1[i1])
            return shuffled_string(s1, s2, s, i+1, i1+1, i2, s_out)

    if s[i] == s1[i1] and s[i] != s2[i2]:
        s_out.append(s1[i1])
        return shuffled_string(s1, s2, s, i+1, i1+1, i2, s_out)
    elif s[i] == s2[i2] and s[i] != s1[i1]:
        s_out.append(s2[i2].upper())
        return shuffled_string(s1,s2,s, i+1, i1, i2+1, s_out)
    elif s[i] == s1[i1] and s[i] == s2[i2]:
        shuffled_1 = shuffled_string(s1, s2, s, i+1, i1+1, i2, list(s_out) + [s1[i1]])
        shuffled_2 = shuffled_string(s1,s2,s,i+1,i1, i2+1, list(s_out) + [s2[i2]])
        if shuffled_1 == True:
            return True
        elif shuffled_2 == True:
            return True
        else:
            return False
    else:
        return False

def shuffled(s1, s2, s):
    if len(s) != len(s1) + len(s2):
        return False

    s_out = []
    ret = shuffled_string(s1, s2, s, 0, 0, 0, s_out)
    return s_out, ret    

# main function
def main_solution(s1, s2, s):
    # Convert input variables if necessary
    s1 = str(s1)
    s2 = str(s2)
    s = str(s)

    # Call the core function
    result, is_shuffled = shuffled(s1, s2, s)

