                    self.y = y.as_integer_ratio()[0]
            else:
                self.x = x
                self.y = y

            mgcd = math.gcd(self.x, self.y)
            if mgcd > 1:
                self.x /= mgcd
                self.y /= mgcd
            if y < 0:
                self.x = -self.x
                self.y = -self.y
        else:
