# all class and function definitions in the code file, if any
class Board:
    WINNING_COMBOS = (
        (1, 2, 3),
        (4, 5, 6),
        (7, 8, 9),
        (1, 4, 7),
        (2, 5, 8),
        (3, 6, 9),
        (1, 5, 9),
        (3, 5, 7)
    )

    def __init__(self):
        self.squares = [None] * 9
        self.winner_piece = None

    def get_square(self, num):
        return self.squares[num - 1]

    def set_square(self, num, piece):
        self.squares[num - 1] = piece

    def squares_equal(self, square_nums):
        token = self.get_square(square_nums[0])
        if not token:
            return False
        for i in range(1, len(square_nums)):
            if self.get_square(square_nums[i]) != token:
                return False
        return True

    def get_possible_moves(self):
        return [i + 1 for i in range(9) if self.squares[i] is None]

    def copy(self):
        new_board = Board()
        new_board.squares = self.squares.copy()
        return new_board

    def game_won(self):
        for combo in Board.WINNING_COMBOS:
            if self.squares_equal(combo):
                self.winner_piece = self.get_square(combo[0])
                return True
        return False

class PerfectAI:
    def __init__(self, piece):
        self.piece = piece

    def minimax(self, is_players_turn, board, level=0):
        best_score = -999 if is_players_turn else 999
        best_move = -1
        possible = board.get_possible_moves()

        if board.game_won():
            if board.winner_piece == self.piece:
                best_score = 100
            elif board.winner_piece:
                best_score = -100
        elif not possible:
            best_score = 0
        else:
            for move in possible:
                temp_board = board.copy()
                temp_board.set_square(move, self.piece if is_players_turn else ('O' if self.piece == 'X' else 'X'))
                score, m = self.minimax(not is_players_turn, temp_board, level=(level + 1))
                if is_players_turn:
                    if score > best_score:
                        best_score = score - level
                        best_move = move
                else:
                    if score < best_score:
                        best_score = score + level
                        best_move = move
        return best_score, best_move

# main function
def main_solution(moves):
    board = Board()
    ai = PerfectAI('X')
    for move in moves:
        board.set_square(move['position'], move['piece'])
        if board.game_won():
