        self.initial = ((0, 0, 0), (0, 0, 0), (0, 0, 0))

    def player(self, state):
        x_count = 0
        o_count = 0
        for row in state:
            for move in row:
                if move == 'X':
                    x_count += 1
                elif move == 'O':
                    o_count += 1
        if x_count <= o_count:
