        i = action[0]
        j = action[1]
        new_state = [list(row) for row in state]
        new_state[i][j] = p
        new_state = tuple(map(tuple, new_state))
        return new_state

    def terminal_test(self, state):
        p = self.player(state)
        p = 'X' if p == 'O' else 'O'
        for row in state:
            if row.count(p) == 3:
