    nr_val, nc_val = grid_size['rows'], grid_size['columns']
    g = grid(nr_val, nc_val)
    player1 = player1
    player2 = player2

    # Main logic of the game
    i = 0
    player = [player1, player2]

    while any(g[0][j] == 0 for j in range(nc(g))):
        p = i % 2 + 1
        c = ia_win(g, p) if player[p - 1] == 'ia1' else ia_aleat(g)
