# import necessary packages
import random

# all class and function definitions in the code file, if any
class HexCoords:
    """
    (q, r, s) define cube coordinates where q+r+s == 0
    (q, r) define axial coordinates where implicitly s := -q -r

    Individual coordinates may not be modified because they might break
    the constraint q+r+s == 0
    """
    _Neighbors = ((+1, 0), (-1, 0), (0, +1), (0, -1), (+1, -1), (-1, +1))

    __slots__ = ('_q', '_r')  # save some memory by avoiding __dict__

    def __init__(self, q, r, s=None):
        if s is not None and q + r + s != 0:
            raise ValueError('Invalid coordinates: q+r+s not equal to zero.')
        self._q = q
        self._r = r

    def __getitem__(self, index):
        return (self._q, self._r, self.s)[index]

    def __iter__(self):
        return iter((self._q, self._r, self.s))

    def __hash__(self):
        return hash((self._q, self._r))

    @property
    def q(self):
        return self._q

    @property
    def r(self):
        return self._r

    @property
    def s(self):
        return -self.q - self.r

    def adjacent(self, other):
        delta = self - other
        return (delta.q, delta.r) in self.__class__._Neighbors

    def distance(self, other):
        return len(self - other)

    @property
    def neighbors(self):
        return [self + n for n in self.__class__._Neighbors]

    def rotate(self, n=+1, rot_center=None):
        """ n=+1 means 1 step (60 degrees) in clockwise direction """
        if rot_center is None:
            rot_center = HexCoords(0, 0)
        rel_coords = self - rot_center
        sign = (-1) ** abs(n)
        # shift coordinates n steps to the right
        newcoords = [sign * rel_coords[(i - n) % 3] for i in range(3)]
        return HexCoords(*newcoords) + rot_center

    @staticmethod
    def round(qfloat, rfloat):
        """ Rounds float coordinates to the nearest integer hex.
        :returns: HexCoords instance with integer coordinates. """
        sfloat = -qfloat - rfloat
        q_int, r_int, s_int = (round(c) for c in (qfloat, rfloat, sfloat))
        deltas = abs(q_int - qfloat), abs(r_int - rfloat), abs(s_int - sfloat)

        # adjust largest delta
        if deltas[0] >= max(deltas[1], deltas[2]):
            q_int = -r_int - s_int
        elif deltas[1] >= max(deltas[0], deltas[2]):
            r_int = -q_int - s_int
        elif deltas[2] >= max(deltas[0], deltas[1]):
            s_int = -q_int - r_int
        return HexCoords(q_int, r_int, s_int)

    def __repr__(self):
        return f'HexCoords({self.q}, {self.r}, {self.s})'

    def __eq__(self, other):
        if isinstance(other, self.__class__):
            return self._q == other._q and self._r == other._r
        elif other == 0:
            return self._q == self._r == 0
        else:
            raise TypeError(f'Invalid operand type {type(other)}')

    def __add__(self, other):
        if isinstance(other, self.__class__):
            return self.__class__(self.q + other.q, self.r + other.r)
        elif (len(other) == 2 or
              len(other) == 3 and sum(other) == 0):
            return self.__class__(self.q + other[0], self.r + other[1])
        else:
            raise TypeError('Invalid operand.')

    def __neg__(self):
        return self.__class__(-self.q, -self.r)

    def __sub__(self, other):
        return self + (-other)

    def __len__(self):
        return (abs(self.q) + abs(self.r) + abs(self.s)) // 2

# main function
def main_solution(q1, r1, q2, r2):
    """
    Calculate the distance between two hex coordinates and determine if they are adjacent.

    :param q1: Integer, q coordinate of the first hex.
    :param r1: Integer, r coordinate of the first hex.
    :param q2: Integer, q coordinate of the second hex.
    :param r2: Integer, r coordinate of the second hex.
    :return: Dictionary with keys 'distance' and 'is_adjacent'.
    """
    hex1 = HexCoords(q1, r1)
    hex2 = HexCoords(q2, r2)

    distance = hex1.distance(hex2)
    is_adjacent = hex1.adjacent(hex2)

    return {'distance': distance, 'is_adjacent': is_adjacent}

