        return self.store[k[0]][k[1]]

    def __setitem__(self, k, val):
        assert k[0] in range(self.size[0]) and k[1] in range(self.size[1])
        self.store[k[0]][k[1]] = val

    def transpose(self):
        dim = self.size
        output = Mat([[0 for i in range(0, dim[0])] for q in range(0, dim[1])])
        for row in range(0, dim[0]):
