def matrix_matrix_mul(A, B):
    assert A.size[1] == B.size[0]
    store = [[0] * B.size[1] for i in range(0, A.size[0])]
    for width in range(0, A.size[0]):
        for height in range(0, B.size[1]):
            sum = 0
            for index in range(0, A.size[1]):
