# all class and function definitions in the code file, if any
class Vehicle:
    def __init__(self, name, xBegin, yBegin, length, orientation):
        self.name = name
        self.xBegin = xBegin
        self.yBegin = yBegin
        self.length = length
        self.orientation = orientation

    def move(self, direction):
        if self.orientation == 'H':
            self.xBegin += direction
        elif self.orientation == 'V':
            self.yBegin += direction

    def dominantCoordinate(self):
        return self.xBegin if self.orientation == 'H' else self.yBegin

class RushHour:
    def __init__(self, board):
        self.initBoard = board.replace("\n", "")
        self.size = int(math.sqrt(len(self.initBoard)))
        self.vehicles = self.getVehicles(self.initBoard)
        if self.size % 2 == 0:
            self.yGoal = self.size // 2 - 1
        else:
            self.yGoal = self.size // 2
        self.moves = dict()

    def getVehicles(self, board):
        names = []
        vehicles = []
        for i in range(len(board)):
            x = i % self.size
            y = i // self.size
            if board[i] != '.' and board[i] not in names:
                vehicles.append(Vehicle(board[i], x, y, 1, 'N'))
                names.append(board[i])
            elif board[i] in names:
                index = names.index(board[i])
                car = vehicles[index]
                car.length += 1
                if x == car.xBegin:
                    car.orientation = 'V'
                else:
                    car.orientation = 'H'
        return vehicles

    def getBoard(self, vehicles):
        board = [['.' for _ in range(self.size)] for _ in range(self.size)]
        for vehicle in vehicles:
            for i in range(vehicle.length):
