# import necessary packages
import random
from itertools import chain, cycle

# all class and function definitions in the code file, if any
def expmod(base, exp, mod):
    if exp == 0:
        return 1
    elif exp % 2 == 0:
        return (expmod(base, exp//2, mod) ** 2) % mod
    else:
        return (base * expmod(base, exp-1, mod)) % mod

def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

def factors_of(n):
    f = 2
    for step in chain([0,1,2,2], cycle([4,2,4,2,4,6,2,6])):
        f += step
        if f*f > n:
            if n != 1:
                yield n
            break
        if n % f == 0:
            yield f
            while n % f == 0:
                n //= f

def isPrime(n, k=2, bases=[]):
    if n & 1 == 0:
        return n == 2
    factors = list(factors_of(n))
    if not bases:
        for _ in range(k):
            while True:
                a = random.randint(1, n-1)
                if a not in bases:
                    break
            if expmod(a, n-1, n) != 1:
                return False
            for factor in factors:
                if expmod(a, (n-1)//factor, n) == 1:
                    return False
        return True
    else:
        for a in bases:
            if expmod(a, n-1, n) != 1:
                return False
            for factor in factors:
                if expmod(a, (n-1)//factor, n) == 1:
                    return False
        return True

# main function
def main_solution(n, k, bases):
    # Convert bases from list of strings to list of integers
    bases = list(map(int, bases))

    # Call the isPrime function
    result = isPrime(n, k, bases)

    # Return the result as a boolean
    return result

