Given a deck of cards of a prime size, a series of shuffle instructions, and a number of times these shuffles should be applied, what card will be at a specified position in the deck after all shuffles have been performed?

The input and output requirements are as follows:

Input:
  `deck_size` (int): The size of the deck, which must be a prime number.
  `shuffle_instructions` (list of str): A list of shuffle instructions, where each instruction is a string describing the shuffle operation.
  `number_of_applications` (int): The number of times the shuffle operations should be applied.
  `position` (int): The position in the deck for which the card should be found after all shuffles.

Output:
  `return` (int): The card at the specified position after all shuffles have been applied.

Given the following input:

{'deck_size': 11, 'shuffle_instructions': ['cut 8', 'deal with increment 9', 'deal with increment 2', 'deal with increment 3'], 'number_of_applications': 8, 'position': 3}

Can you predict the output without writing any code? Please reason and put your final answer in the following json format: {"output": <your output>}, where <your output> should strictly match the the output requirement as specified.

Tip: Here is a reference code snippet for this question. You can refer to this code to guide your reasoning but not copy spans of code directly.

# import necessary packages
import re
from dataclasses import dataclass

# Fermat's little theorem gives a simple inv:
# Meaning (a * inv(a, n)) % n = 1
def inv(a, n): return pow(a, n - 2, n)

@dataclass
class Shuffle:
    a: int
    b: int

    def forward(self, idx, size):
        return (self.a * idx + self.b) % size

    def backward(self, idx, size):
        return ((idx - self.b)*inv(self.a, size)) % size

    def compose(self, other, size):
        return Shuffle((self.a * other.a) % size, (self.a * other.b + self.b) % size)

    def apply(self, number_of_applications, size):
        Ma = pow(self.a, number_of_applications, size)
        Mb = (self.b * (Ma - 1) * inv(self.a - 1, size)) % size
        return Shuffle(Ma, Mb)

@dataclass
class Deck:
    shuffler: Shuffle
    size: int

    def at(self, position):
        return self.shuffler.backward(position, self.size)

    def where(self, card):
        return self.shuffler.forward(card, self.size)

    @classmethod
    def new_deck(cls, size):
        return cls(identity_shuffle(), size)

    @staticmethod
    def parse_shuffler(line):
        line = line.strip()
        cut_n_match = re.compile('cut (.+)').match(line)
        deal_with_incr_match = re.compile('deal with increment (.+)').match(line)
        if line == 'deal into new stack':
            return new_stack_shuffle()
        elif cut_n_match:
            return cut_n_cards_shuffle(int(cut_n_match.group(1)))
        elif deal_with_incr_match:
            return with_n_increments_shuffle(int(deal_with_incr_match.group(1)))
        else:
            assert False, "Could not parse line"

    def shuffle(self, line):
        new_shuffle = Deck.parse_shuffler(line)
        combined = new_shuffle.compose(self.shuffler, self.size)
        return Deck(combined, self.size)

    def reshuffle(self, number_of_applications):
        return Deck(self.shuffler.apply(number_of_applications, self.size), self.size)

def identity_shuffle():
    return Shuffle(1, 0)

def new_stack_shuffle():
    return Shuffle(-1, -1)

def cut_n_cards_shuffle(n):
    return Shuffle(1, -n)

def with_n_increments_shuffle(n):
    return Shuffle(n, 0)

# main function
def main_solution(deck_size: int, shuffle_instructions: list, number_of_applications: int, position: int):
    deck = Deck.new_deck(deck_size)
