# import necessary packages
import math
import random

# all class and function definitions in the code file, if any
class Heuristic:
    def evaluate(self, state):
        pass

class PowerHeuristic(Heuristic):
    def name(self):
        return "PowerHeuristic"

    def distance(self, a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def evaluate(self, state):
        if len(state.dirt_locations) == 0:
            return 0

        dists = []
        for dirt_loc in state.dirt_locations:
            for robot in range(len(state.robots)):
                dists.append((self.distance(state.robots[robot], dirt_loc), dirt_loc, robot))
        dists.sort(reverse=True)

        matches = []
        while len(dists) > 0:
            worst_dirt = dists[0][1]
            x = []
            for i in range(len(dists)):
                if dists[i][1] == worst_dirt:
                    x.append(dists[i])
            x.sort()
            matches.append(x[0])
            for xi in x:
                dists.pop(dists.index(xi))

        rank = 0
        power = len(matches)             
        for dist, dirt_loc, robot in matches:
            rank += pow(dist, power)
            power -= 1

        return rank

# main function
def main_solution(dirt_locations, robots):
    # Convert input arguments to the required format
    class State:
        def __init__(self, dirt_locations, robots):
            self.dirt_locations = dirt_locations
            self.robots = robots

    state = State(dirt_locations, robots)

    # Use the PowerHeuristic to evaluate the state
    heuristic = PowerHeuristic()
    result = heuristic.evaluate(state)

    # Return the result as a JSON serializable output
    return result

