        self.item = item
        self.marks = set()
        self.child = None

    def visit(self, node):
        if node in self.marks:
            return self.child
        if self.item == node.item:
            self.child = node
        if self.child:
            return self.child
        self.marks.add(node)
        for c in node.children:
            self.child = self.visit(c)
            if self.child:
                return self.child
        return self.child

