class Stack():
    def __init__(self):
        self.items = []

    def isEmpty(self):
        return self.items == []

    def peek(self):
        return self.items[-1]

    def push(self, item):
        self.items.append(item)

    def pop(self):
        return self.items.pop()

    def size(self):
        return len(self.items)

    def __str__(self):
        return str(self.items)

class MultiwayTree():
    def __init__(self, pyTree):
        if pyTree != "":
            self.data = None
            self.children = []
            s = Stack()
            s.push(pyTree[0])
            del pyTree[0]
            while not s.isEmpty():
                self.addChildren(pyTree, self.children, s)

    def addChildren(self, pyTree, children, s):
        char = pyTree[0]
        if char == "[":
            char_after = pyTree[1]
            if char_after == "]":
                del pyTree[0]
                del pyTree[1] 
                return 
            elif char_after.isalnum():
                children.append(MultiwayTree(pyTree))
            elif char_after == "[":
                s.push(pyTree[0])
                del pyTree[0]
                children.append(MultiwayTree(pyTree))
        elif char.isalnum():
            self.data = char
            del pyTree[0]
            self.addChildren(pyTree, children, s)
        elif char == "]":
            s.pop()
            del pyTree[0]
            return
        else:
            del pyTree[0]
            self.addChildren(pyTree, children, s)

    def isIsomorpicTo(self, otherTree):
        same = True
        if len(self.children) == len(otherTree.children):
            if self.children == []:
                return True
            else:
                child_idx = 0
                while child_idx < len(self.children):
                    same = self.children[child_idx].isIsomorpicTo(otherTree.children[child_idx])
                    if same == False:
                        return same
                    else:
                        child_idx += 1
        else:
            return False
        return same

