# import necessary packages
import math
import random

# all class and function definitions in the code file, if any
class Position(object):
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def getX(self):
        return self.x

    def getY(self):
        return self.y

    def getNewPosition(self, angle, speed):
        old_x, old_y = self.getX(), self.getY()
        angle = float(angle)
        delta_y = speed * math.cos(math.radians(angle))
        delta_x = speed * math.sin(math.radians(angle))
        new_x = old_x + delta_x
        new_y = old_y + delta_y
        return Position(new_x, new_y)

class RectangularRoom(object):
    def __init__(self, width, height):
        self.width = width
        self.height = height
        self.tiles = width * height
        self.cleanTiles = []

    def cleanTileAtPosition(self, pos):
        cleanPos = Position(int(pos.x), int(pos.y))
        if not((cleanPos.x, cleanPos.y) in [(p.x, p.y) for p in self.cleanTiles]):
            self.cleanTiles.append(cleanPos)

    def isTileCleaned(self, m, n):
        for pos in self.cleanTiles:
            if (pos.x, pos.y) == (m, n):
                return True
        return False

    def getNumTiles(self):
        return self.tiles

    def getNumCleanedTiles(self):
        return len(self.cleanTiles)

    def getRandomPosition(self):
        return Position(self.width*random.random(), self.height*random.random())

    def isPositionInRoom(self, pos):
        return pos.x >= 0 and pos.x < self.width and pos.y >= 0 and pos.y < self.height

class Robot(object):
    def __init__(self, room, speed):
        self.room = room
        self.position = Position(4, 4)
        self.direction = math.pi/2
        self.speed = speed
        self.room.cleanTileAtPosition(self.position)

    def getRobotPosition(self):
        return self.position

    def getRobotDirection(self):
        return self.direction

    def setRobotPosition(self, position):
        self.position = position

    def setRobotDirection(self, direction):
        self.direction = direction

class StandardRobot(Robot):
    def updatePositionAndClean(self):
        newPosition = self.position.getNewPosition(self.getRobotDirection(), self.speed)
        while not(self.room.isPositionInRoom(newPosition)):
            self.direction = random.random() * 360
            newPosition = self.position.getNewPosition(self.direction, self.speed)
        self.position = newPosition
        self.room.cleanTileAtPosition(self.position)

# main function
def main_solution(width, height, speed, min_coverage):
    room = RectangularRoom(width, height)
    robot = StandardRobot(room, speed)
    cleaned_tiles = room.getNumCleanedTiles()
    total_tiles = room.getNumTiles()
    while cleaned_tiles / total_tiles < min_coverage:
        robot.updatePositionAndClean()
        cleaned_tiles = room.getNumCleanedTiles()
    return cleaned_tiles

