        return x < len(self.grid[0]) - 3

    def is_far_from_top(self, y):
        return y >= 3

    def is_far_from_bottom(self, y):
        return y < len(self.grid) - 3

    def is_quite_far_from_bottom(self, y):
        return y < len(self.grid) - 2

    def is_at_top(self, y):
        return y == 0

    def is_very_far_from_bottom(self, y):
        return y < len(self.grid) - 4

    def play_if_possible(self, x, y):
        if self.grid[y][x] == '.':
            return x
        return None

