    # Alignements horizontaux, le noeud (x,y) étant le plus à gauche
    if grille.is_far_from_right(x):
        # Alignement horizontal de trois jetons consécutifs
        if all(symbole == grille.grid[y][x + i + 1] for i in range(2)):
