    """Alignement vertical"""
    symbole = grille.grid[y][x]
    # Alignement vertical de trois jetons consécutifs, le noeud (x,y) étant le plus haut
    if grille.is_quite_far_from_bottom(y) and not (grille.is_at_top(y)):
