                    my_play = check_verticale(grille, x, y)
                    if my_play is not None:
                        return my_play

                    my_play = check_oblique_montante(grille, x, y)
                    if my_play is not None:
                        return my_play

                    my_play = check_oblique_descendante(grille, x, y)
                    if my_play is not None:
