    # Aucun coup urgent, alors renvoyer -1
    return None

# main function
def main_solution(grid, player_symbol='X', opponent_symbol='O'):
    # Convert the grid to a list of lists if it's not already
    if isinstance(grid, str):
        grid = [list(row) for row in grid.split('\n')]

    # Create the Grille object
    grille = Grille(grid)

    # Call the function to look for obvious steps
    result = look_for_obvious_steps(grille, player_symbol, opponent_symbol)

    # Return the result
    return result

