# import necessary packages
import random

# all class and function definitions in the code file, if any
class EmptyValue:
    pass

class BinarySearchTree:

    # Attributes:
    # - root (object): the root value stored in the BST, or EmptyValue if the tree is empty
    # - left (BinarySearchTree): the left subtree, or None if the ENTIRE tree is empty
    # - right (BinarySearchTree): the right subtree, or None if the ENTIRE tree is empty

    def __init__(self, root=EmptyValue):
        self.root = root
        if self.is_empty():
            self.left = None
            self.right = None
        else:
            self.left = BinarySearchTree()
            self.right = BinarySearchTree()

    def is_empty(self):
        return self.root is EmptyValue

    def insert(self, item):
        if self.is_empty():
            self.root = item
            self.left = BinarySearchTree()
            self.right = BinarySearchTree()
        elif item < self.root:
            self.left.insert(item)
        else:
            self.right.insert(item)

    def __contains__(self, item):
        # the fact that you only need to check one tree each time comes from the property of BST
        if self.is_empty():
            return False
        elif item == self.root:
            return True
        elif item < self.root:
            return self.left.__contains__(item)
        else:
            return self.right.__contains__(item) # or 'return item in self.right', because __contains__ is a special form of 'in'

# main function
def main_solution(tree_structure, search_item):
    # Convert the tree_structure list to a BinarySearchTree object
    bst = BinarySearchTree()
    for item in tree_structure:
        bst.insert(item)

    # Check if the search_item is in the BST
    result = search_item in bst

    # Return the result
    return result

