def isPalindromeString(pstring):
    n = len(pstring)
    if n < 1:
        return False
    start, last = 0, n - 1
    while start < last:
        if pstring[start] != pstring[last]:
            return False
        start += 1
        last -= 1
    return True

def isPalindromeLinkedList(head):
    if head is None or head.next is None:
        return True

    # Find the middle of the linked list
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next

    # Reverse the second half of the linked list
    prev = None
    while slow:
        next_node = slow.next
        slow.next = prev
        prev = slow
        slow = next_node

    # Compare the first half and the reversed second half
    while prev:
        if head.value != prev.value:
            return False
        head = head.next
        prev = prev.next
    return True

