class state:
    def __init__(self, x, y, terrain):
        self.x = x
        self.y = y
        self.terrain = terrain

class search_node:
    def __init__(self, status, cost):
        self.status = status
        self.cost = cost
        self.g = None
        self.h = None
        self.f = None
        self.parent = None
        self.kids = []

def heuristic(s1, s2):
    return abs(s2.x - s1.x) + abs(s2.y - s1.y)

def solution(s1, sf):
    return s1.x == sf.x and s1.y == sf.y

def generate_all_successors(s, board):
    successors = []
    if s.x > 0:
        successors.append(board[s.y][s.x-1])
    if s.x < (len(board[s.y]) - 1):
        successors.append(board[s.y][s.x+1])
    if s.y > 0:
        successors.append(board[s.y-1][s.x])
    if s.y < (len(board) - 1):
        successors.append(board[s.y+1][s.x])
    return successors

def attach_and_eval(C, P, sf):
    C.parent = P
    C.g = P.g + C.cost
    C.h = heuristic(C.status, sf)
    C.f = C.g + C.h

def propagate_path_improvement(P):
    for c in P.kids:
        if P.g + c.cost < c.g:
            c.parent = P
            c.g = P.g + c.cost
            c.f = c.g + c.h
            propagate_path_improvement(c)

def cost(terrain):
    if terrain == 'w':
        return 100
    elif terrain == 'm':
        return 50
    elif terrain == 'f':
        return 10
    elif terrain == 'g':
        return 5
    elif terrain == 'r':
        return 1
    else:
        return 1

def best_first_search(start, end, board):
    closed = []
    open = []
    ni = board[start[1]][start[0]]
    nf = board[end[1]][end[0]]
    ni.g = 0
    ni.h = heuristic(ni.status, nf.status)
    ni.f = ni.h
    open.append(ni)

    while open:
        X = open.pop()
        closed.append(X)
        if solution(X.status, nf.status):
            return 'SUCCEED'
        successors = generate_all_successors(X.status, board)
        for s in successors:
            X.kids.append(s)
            if s not in open and s not in closed:
                attach_and_eval(s, X, nf.status)
                open.append(s)
                open.sort(key=lambda e: e.f, reverse=True)
            elif X.g + s.cost < s.g:
                attach_and_eval(s, X, nf.status)
                if s in closed:
                    propagate_path_improvement(s)
    return 'FAIL'

