    """
    Recursively place queens on the board.
    """
    for y in range(len(tab)):
        if isOk(tab, r, y):
            tab[r] = y
            if r < len(tab) - 1:
                fix(tab, r + 1)
            else:
                return [[y, tab[y]] for y in range(len(tab))]
    return None

