class Game:
    def __init__(self, player_colour, comp_colour, side_length):
        self.player = player_colour
        self.comp = comp_colour
        self.side = side_length
        self.half = int(self.side / 2)
        self.board = []

    def create_board(self):
        row = [BORDER] * (self.side + 2)
        self.board.append(row)
        for r in range(self.side):
            row = [BORDER] + [EMPTY] * self.side + [BORDER]
            self.board.append(row)
        self.board.append([BORDER] * (self.side + 2))
        self.board[self.half][self.half] = WHITE
        self.board[self.half][self.half + 1] = BLACK
        self.board[self.half + 1][self.half] = BLACK
        self.board[self.half + 1][self.half + 1] = WHITE

    def check_legal_move(self, currP, currO, x, y):
        tempx, tempy = x, y
        moved = False
        if 0 < x < self.side + 1 and 0 < y < self.side + 1:
            for y1 in range(-1, 2):
                for x1 in range(-1, 2):
                    if not (y1 == 0 and x1 == 0):
                        while self.board[tempy + y1][tempx + x1] == currO:
                            tempy += y1
                            tempx += x1
                            moved = True
                        if moved and self.board[tempy + y1][tempx + x1] == currP:
                            return [y1, x1]
                        tempx, tempy = x, y
                        moved = False
        return False

    def execute_move(self, currP, x, y, direction):
        while self.board[y + direction[0]][x + direction[1]] not in [EMPTY, BORDER]:
            self.board[y][x] = currP
            x += direction[1]
            y += direction[0]

    def comp_turn(self):
        potential_moves = []
        for r in range(1, self.side + 1):
            for c in range(1, self.side + 1):
                if self.board[r][c] == EMPTY and self.check_legal_move(self.comp, self.player, c, r):
                    potential_moves.append([c, r])
        if potential_moves:
            comp_move = potential_moves[randrange(len(potential_moves))]
            direction = self.check_legal_move(self.comp, self.player, comp_move[0], comp_move[1])
            self.execute_move(self.comp, comp_move[0], comp_move[1], direction)

    def check_done(self, currP, currO):
        for r in range(1, self.side + 1):
            for c in range(1, self.side + 1):
                if self.board[r][c] == EMPTY and self.check_legal_move(currP, currO, c, r):
                    return False
        return True

    def check_win(self):
        player_points = sum(row.count(self.player) for row in self.board)
        comp_points = sum(row.count(self.comp) for row in self.board)
        if player_points > comp_points:
            return [self.player, player_points]
        elif player_points < comp_points:
            return [self.comp, comp_points]
        return 0

# main function
def main_solution(player_colour, comp_colour, side_length):
    game = Game(player_colour, comp_colour, side_length)
    game.create_board()

    while True:
        if not game.check_done(game.player, game.comp):
            game.comp_turn()
        else:
            break

        if not game.check_done(game.comp, game.player):
            game.comp_turn()
        else:
            break

    result = game.check_win()
    if result == 0:
        return "tie"
    elif result[0] == game.player:
        return "player"
    else:
        return "computer"

