from copy import deepcopy

# Function to rotate the key 90 degrees clockwise
def rotate_key(key):
    M = len(key)
    ret = [[0] * M for _ in range(M)]
    for r in range(M):
        for c in range(M):
            ret[c][M - 1 - r] = key[r][c]
    return ret

# Main function to determine if the key can unlock the lock
def main_solution(key, lock):
    N = len(lock)
    M = len(key)
    L = N + 2 * M
    globe = [[0] * L for _ in range(L)]

    # Copy the lock onto the globe
    for r in range(M, M + N):
        for c in range(M, M + N):
            globe[r][c] = lock[r - M][c - M]

    keys = [key, rotate_key(key), rotate_key(rotate_key(key)), rotate_key(rotate_key(rotate_key(key)))]

    for key in keys:
        for R in range(M + N):
            for C in range(M + N):
                # Apply the key to the globe
                for r in range(M):
                    for c in range(M):
                        globe[R + r][C + c] ^= key[r][c]

                # Check if the lock is unlocked
                success = True
                for r in range(M, M + N):
                    for c in range(M, M + N):
                        if globe[r][c] == 0:
