        self.children = []

class Tree:
    def __init__(self):
        self._rootNode = Node(".")

class Trie(Tree):
    EOW = ")"

    def findChild(self, node, char):
        charCheck = False
        for Cnode in node.children:
            if Cnode.value == char:
                charCheck = Cnode
        if char == ".":
            return node.children
        return charCheck

