# all class and function definitions in the code file, if any
class Solution:
    def validTicTacToe(self, board):
        """
        :type board: List[str]
        :rtype: bool
        """
        def validation(char):
            char = char + char + char

            for row in board:
                if row == char:
                    return True

            if  char == board[0][0] + board[1][0] + board[2][0]:
                return True
            if  char == board[0][1] + board[1][1] + board[2][1]:
                return True
            if  char == board[0][2] + board[1][2] + board[2][2]:
