            if  char == board[0][0] + board[1][1] + board[2][2]:
                return True
            if  char == board[0][2] + board[1][1] + board[2][0]:
                return True

            return False

        O = 0
        X = 0
        for row in board :
            O += row.count('O')
            X += row.count('X')

        if X == O:
