class Waythff:
    goldenRatio = (1 + math.sqrt(5)) / 2  # 1.618
    maxPlayer = True
    minPlayer = False

    def isSafe(self, counter1, counter2):
        if counter1 > counter2:
            for i in range(0, counter2 + 1):
                c2 = math.floor(self.goldenRatio * i)
                c1 = math.floor((self.goldenRatio + 1) * i)
                if c1 == counter1 and c2 == counter2:
                    return True
        else:
            for i in range(0, counter1 + 1):
                c1 = math.floor(self.goldenRatio * i)
                c2 = math.floor((self.goldenRatio + 1) * i)
                if c1 == counter1 and c2 == counter2:
                    return True
        return False

