        if node.counter1 == 0:
            tmp = node.counter2
            node.counter2 -= node.counter2
            return " Select normal position by reduce counter2: " + str(tmp)
        elif node.counter2 == 0:
            tmp = node.counter1
            node.counter1 -= node.counter1
            return " Select normal position by reduce counter2: " + str(tmp)
        if node.counter2 == node.counter1:
