        if tmp == 2:
            tmp = random.randint(1, node.counter2)
            if node.counter2 - tmp != node.counter1:
                node.counter2 -= tmp
                return " Select normal position by reduce counter2: " + str(tmp)
            else:
                tmp = 1
        if tmp == 1:
            tmp = random.randint(1, node.min())
            node.counter1 -= tmp
            node.counter2 -= tmp
            return " Select normal position by reduce two counters: " + str(tmp)

    def selectGoldPositionPlaying(self, node):
        for i in range(1, node.counter1):
            if (node.counter1 - i) != node.counter2 and self.isSafe(node.counter1 - i, node.counter2):
                node.counter1 -= i
                return True
        for i in range(1, node.counter2):
            if node.counter1 != (node.counter2 - i) and self.isSafe(node.counter1, node.counter2 - i):
                node.counter2 -= i
                return True
        for i in range(1, node.min()):
            if self.isSafe(node.counter1 - i, node.counter2 - i):
                node.counter2 -= i
                node.counter1 -= i
                return True
        return False

