# import necessary packages
from collections import defaultdict
import math

# SparseVector class definition
class SparseVector:

    def __init__(self, d):
        """
        :param d: the dimension
        :type d: int
        """
        self._st = defaultdict(float)
        self._d = d

    def get_st(self):
        return self._st

    def get_d(self):
        return self._d

    def put(self, i, value):
        if i < 0 or i >= self.get_d():
            raise AttributeError('Illegal index')
        if value == 0.0:
            del self.get_st()[i]
        else:
            self.get_st()[i] = value

    def get(self, i):
        if i < 0 or i >= self.get_d():
            raise AttributeError('Illegal index')
        if i in self.get_st():
            return self.get_st()[i]
        else:
            return 0.0

    def nnz(self):
        return len(self.get_st())

    def dimension(self):
        return self.get_d()

    def dot_spv(self, that):
        if self.get_d() != that.get_d():
            raise AttributeError('Vector lengths disagree')
        _sum = 0.0
        if len(self.get_st()) <= len(that.get_st()):
            for i in self.get_st().keys():
                if i in that.get_st():
                    _sum += self.get(i) * that.get(i)
        else:
            for i in that.get_st().keys():
                if i in self.get_st():
                    _sum += self.get(i) * that.get(i)
        return _sum

    def dot(self, that):
        _sum = 0.0
        for i in self.get_st().keys():
            _sum += that[i] * self.get(i)
        return _sum

    def magnitude(self):
        return math.sqrt(self.dot_spv(self))

    def scale(self, alpha):
        c = SparseVector(self.get_d())
        for i in self.get_st().keys():
            c.put(i, alpha * self.get(i))
        return c

    def plus(self, that):
        if self.get_d() != that.get_d():
            raise AttributeError('Vector lengths disagree')
        c = SparseVector(self.get_d())
        for i in self.get_st().keys():
            c.put(i, self.get(i))
        for i in that.get_st().keys():
            c.put(i, that.get(i) + c.get(i))
        return c

    def __repr__(self):
        return f'<SparseVector(st={self.get_st()}, d={self.get_d()})>'

# main function
def main_solution(vector_a, vector_b):
    """
    Computes the dot product and the sum of two sparse vectors.

    :param vector_a: A dictionary representing the non-zero indices and values of the first sparse vector.
    :type vector_a: dict
    :param vector_b: A dictionary representing the non-zero indices and values of the second sparse vector.
    :type vector_b: dict
    :return: A dictionary containing the dot product and the sum of the two vectors.
    :rtype: dict
