def exp(a, n, p):
    temp_n = n  # used to convert n to binary
    temp_a = a  # this will be the power of a
    result = 1

    while temp_n != 0:
        if temp_n % 2 == 1:
            result = (result * temp_a) % p
        temp_a = (temp_a * temp_a) % p
        temp_n //= 2

    return result

def computeGCD(x, y):
    if x > y:
        small = y
    else:
        small = x
    for i in range(1, small + 1):
        if (x % i == 0) and (y % i == 0):
            gcd = i

    return gcd

