# all class and function definitions in the code file, if any
class Graph:
    def __init__(self):
        self._vertices = set()
        self._edges = set()

    def add_vertex(self, v):
        self._vertices.add(v)

    def add_edge(self, e):
        x, y = min(e), max(e)
        if x not in self._vertices:
            self.add_vertex(x)
        if y not in self._vertices:
            self.add_vertex(y)
        self._edges.add((x, y))

    def get_vertices(self):
        return self._vertices

    def get_edges(self):
        return self._edges

    def adj_to(self, v):
        neighbours = set()
        for x, y in self._edges:
            if x == v: neighbours.add(y)
            if y == v: neighbours.add(x)
        return neighbours

def spanning_edges(G, root):
    visited = set()
    todo = [(root, None)]
    E = set()
    while todo:
        cur, e = todo.pop()
        if cur in visited: continue
        if e:
            E.add((min(e), max(e)))
        visited.add(cur)
        for n in G.adj_to(cur):
            if n not in visited:
                todo.append((n, (cur, n)))
    return E

def connected_components(G):
    C = []
    visited = set()
    for v in G.get_vertices():
        if v not in visited:
            span = spanning_edges(G, v)
            component = set()
            for x in span:
                for y in x:
                    component.add(y)
                    visited.add(y)
            C.append(component)
    C.sort(key=min)
    return C

