# import necessary packages
import json

# all class and function definitions in the code file, if any
class Tree(object):
    def __init__(self, x):
        self.value = x
        self.left = None
        self.right = None

def isMirror(lst, rst):
    if not (lst and rst):
        if not lst and not rst:
            return True
        else:
            return False
    elif lst.value == rst.value:
        return isMirror(lst.left, rst.right) & isMirror(lst.right, rst.left)
    else:
        return False

def isTreeSymmetric(t):
    if t is None:
        return True
    else:
        return isMirror(t.left, t.right)

# main function
def main_solution(tree_json):
    # Convert JSON string to Tree object
    def json_to_tree(json_data):
        if json_data is None:
            return None
        node = Tree(json_data['value'])
        node.left = json_to_tree(json_data['left'])
        node.right = json_to_tree(json_data['right'])
        return node

    # Convert JSON input to Tree object
    tree = json_to_tree(json.loads(tree_json))

    # Check if the tree is symmetric
    result = isTreeSymmetric(tree)

    # Return the result as a boolean
    return result

