# all class and function definitions in the code file, if any
class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        return self.items.pop()

    def is_empty(self):
        return self.items == []

    def peek(self):
        if not self.is_empty():
            return self.items[-1]

    def get_stack(self):
        return self.items

# main function
def main_solution(baseTen, string, parString):
    # Convert decimal to binary
    s = Stack()
    binary = ''
    while baseTen > 0:
        r = baseTen % 2
        baseTen = baseTen // 2
        s.push(r)
    while not s.is_empty():
        binary += str(s.pop())

    # Reverse the string
    reverse = ''
    for x in string:
        s.push(x)
    while not s.is_empty():
        reverse += str(s.pop())

    # Check parenthesis balance
    def parMatch(p1, p2):
        if p1 == '(' and p2 == ')':
            return True
        elif p1 == '[' and p2 == ']':
            return True
        elif p1 == '{' and p2 == '}':
            return True
        else:
            return False

    index = 0
    is_bal = True
    s = Stack()
    if parString == '':
        is_bal = False
        return {"binary": binary, "reverse": reverse, "is_balanced": is_bal}
    if parString[-1] in '{[(':
