                    is_bal = True
                else:
                    is_bal = False
                    return {"binary": binary, "reverse": reverse, "is_balanced": is_bal}
            index += 1
        if not s.is_empty():
            return {"binary": binary, "reverse": reverse, "is_balanced": False}
        if s.is_empty() and is_bal:
            return {"binary": binary, "reverse": reverse, "is_balanced": True}

