# import necessary packages
import random

# all class and function definitions in the code file, if any
class Link:
    empty = ()

    def __init__(self, first, rest=empty):
        assert rest is Link.empty or isinstance(rest, Link)
        self.first = first
        self.rest = rest

    def __getitem__(self, i):
        if i == 0:
            return self.first
        else:
            return self.rest[i-1]

    def __len__(self):
        return 1 + len(self.rest)

    def __repr__(self):
        if self.rest:
            rest_str = ', ' + repr(self.rest)
        else:
            rest_str = ''
        return 'Link({0}{1})'.format(self.first, rest_str)

class Tree:
    def __init__(self, entry, branches=()):
        self.entry = entry
        for branch in branches:
            assert isinstance(branch, Tree)
        self.branches = list(branches)

    def __repr__(self):
        if self.branches:
            branches_repr = ', ' + repr(self.branches)
        else:
            branches_repr = ''
        return 'Tree({0}{1})'.format(self.entry, branches_repr)

class BinaryTree(Tree):
    empty = Tree(None)
    empty.is_empty = True

    def __init__(self, entry, left=empty, right=empty):
        Tree.__init__(self, entry, (left, right))
        self.is_empty = False

    @property
    def left(self):
        return self.branches[0]

    @property
    def right(self):
        return self.branches[1]

def set_contains(s, v):
    if s.is_empty:
        return False
    elif s.entry == v:
        return True
    elif s.entry < v:
        return set_contains(s.right, v)
    else:
        return set_contains(s.left, v)

def adjoin_set(s, v):
    if s.is_empty:
        return BinaryTree(v)
    elif s.entry == v:
        return s
    elif s.entry < v:
        return BinaryTree(s.entry, s.left, adjoin_set(s.right, v))
    else:
        return BinaryTree(s.entry, adjoin_set(s.left, v), s.right)

# main function
def main_solution(elements, operation, value=None):
    """
    Perform set operations on a binary search tree.

    Args:
    elements (list): A list of integers representing the initial set of elements.
    operation (str): The operation to perform, either "contains" or "adjoin".
    value (int): The value to check for containment or to adjoin to the set. Required if operation is "contains" or "adjoin".

    Returns:
    dict: A dictionary with the result of the operation.
          If operation is "contains", the dictionary will have a single key "contains" with a boolean value.
          If operation is "adjoin", the dictionary will have a single key "adjoined" with the new set as a list of integers.
    """
    if operation not in ["contains", "adjoin"]:
        raise ValueError("Invalid operation. Must be 'contains' or 'adjoin'.")

    if operation == "contains" and value is None:
        raise ValueError("Value is required for 'contains' operation.")

    if operation == "adjoin" and value is None:
        raise ValueError("Value is required for 'adjoin' operation.")

    # Convert list of elements to a binary search tree
    tree = BinaryTree.empty
    for element in elements:
        tree = adjoin_set(tree, element)

    if operation == "contains":
        result = set_contains(tree, value)
        return {"contains": result}

    elif operation == "adjoin":
        new_tree = adjoin_set(tree, value)
        # Convert the new tree back to a list of elements
        def tree_to_list(t):
            if t.is_empty:
                return []
            return tree_to_list(t.left) + [t.entry] + tree_to_list(t.right)

        new_elements = tree_to_list(new_tree)
        return {"adjoined": new_elements}

