        root = treeInsert(root, key)

    if operation == "depth":
        return treeDepth(root)
    elif operation == "has_key":
        return treeHasKey(root, keys[0]) is not None
    elif operation == "remove":
        root = treeRemove(root, keys[0])
        return treeHasKey(root, keys[0]) is None
    else:
