# import necessary packages
import math
import random

# all class and function definitions in the code file, if any
class Board(object):
    def __init__(self, blocks):
        self.blocks = blocks
        self.N = int(math.sqrt(len(blocks)))

    def dimension(self):
        return self.N

    def hamming(self):
        hamming = 0
        for i in range(len(self.blocks)):
            if self.blocks[i] != 0 and self.blocks[i] != i + 1:
                hamming += 1
        return hamming

    def manhattan(self):
        manhattan = 0
        for i in range(len(self.blocks)):
            if self.blocks[i] != 0 and self.blocks[i] != i + 1:
                row_dis = abs(i // self.N - (self.blocks[i] - 1) // self.N)
                col_dis = abs(i % self.N - (self.blocks[i] - 1) % self.N)
                manhattan += (row_dis + col_dis)
        return manhattan

    def isGoal(self):
        return self.hamming() == 0

    def twin(self):
        twinblocks = self.blocks.copy()
        if twinblocks[0] != 0 and twinblocks[1] != 0:
            self._swap(twinblocks, 0, 1)
        else:
            self._swap(twinblocks, len(twinblocks) - 1, len(twinblocks) - 2)
        return Board(twinblocks)

    def _swap(self, arr, a, b):
        arr[a], arr[b] = arr[b], arr[a]

    def __eq__(self, other):
        if other == None:
            return False
        if type(self).__name__ != type(other).__name__:
            return False
        if self.N != other.N:
            return False
        return self.blocks == other.blocks

    def __iter__(self):
        neighbors = []
        zero_index = self.blocks.index(0)
        row_move = [-1, 1, 0, 0]
        col_move = [0, 0, -1, 1]
        for i in range(4):
            arr = self.blocks.copy()
            row_index = zero_index // self.N + row_move[i]
            col_index = zero_index % self.N + col_move[i]
            if row_index < self.N and row_index >= 0 and col_index < self.N and col_index >= 0:
                newindex = row_index * self.N + col_index
                self._swap(arr, zero_index, newindex)
                neighbors.append(Board(arr))
        return iter(neighbors)

    def toString(self):
        string = ''
        for i in range(len(self.blocks)):
            s = str(self.blocks[i]) + '  '
            if (i + 1) % self.N == 0:
                s += '\n'
            string += s
        return string

# main function
def main_solution(blocks):
    board = Board(blocks)
    hamming_distance = board.hamming()
    manhattan_distance = board.manhattan()
    is_goal = board.isGoal()
    return {"hamming_distance": hamming_distance, "manhattan_distance": manhattan_distance, "is_goal": is_goal}

