def main_solution(hands):
    """
    Determine the winner of a poker round given two hands.

    Input:
        hands (str): A string representing two poker hands separated by a space.
                     Each hand consists of 5 cards in the format "5H 5C 6S 7S KD".

    Output:
        return (int): The index of the winning hand (0 for the first hand, 1 for the second hand).
    """
    poker = Poker()
    poker.load(hands)
    return poker.compare()

