    return abs(d2 - d1) < epsilon

def roundHalfUp(d):
    rounding = decimal.ROUND_HALF_UP
    return int(decimal.Decimal(d).to_integral_value(rounding=rounding))

def isPrime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    max_val = int(math.sqrt(n))
    for i in range(3, max_val + 1, 2):
        if n % i == 0:
            return False
    return True

