    if isPrime(n):
        return False
    prime_sum = 0
    n_copy = n
    while n != 1:
        for i in range(2, n_copy + 1):
            if isPrime(i) and n % i == 0:
                prime_sum += getDigitSum(i)
                n //= i
                break
    return prime_sum == getDigitSum(n_copy)

def nthSmithNumber(n):
