# all class and function definitions in the code file, if any
def gcd(a, b):
    while b != 0:
        temp = b
        b = a % b
        a = temp
    return a

def is_primes(n):
    if n < 2:
        return False
    for i in range(2, n):
        if n % i == 0:
            return False
    return True

def thua_so_nguyen_to_va_mu_cua_no(n):
    i = 2
    array_tsnt = []
    while n > 1:
        if n % i == 0:
            n = int(n / i)
            array_tsnt.append(i)
        else:
            i += 1
    if len(array_tsnt) == 0:
        array_tsnt.append(n)
    count = {}
    for i in array_tsnt:
        if i in count:
            count[i] += 1
        else:
            count[i] = 1
    return count

def thang_du_binh_phuong(p):
    if p <= 2 or p % 2 == 0:
        return -1
    array_origin = []
    array_contain_surplus = []
    result = []
    count_tdpb = (p - 1) // 2
    for i in range(1, p):
        array_origin.append(i)
        surplus = (i * i) % p
        array_contain_surplus.append(surplus)
    for value in array_contain_surplus:
        if value in array_contain_surplus:
            array_contain_surplus.remove(value)
    array_origin.sort()
    array_contain_surplus.sort()
    length_array_origin = len(array_origin)
    length_array_surplus = len(array_contain_surplus)
    count_temp = 0
    for i in range(length_array_origin):
        for j in range(length_array_surplus):
            if array_contain_surplus[j] == array_origin[i]:
                result.append(array_origin[i])
                count_temp += 1
        if count_temp == count_tdpb:
            break
    return result

