    if a % p == 0:
        return 0
    elif not is_primes(p) or p % 2 == 0:
        return 0
    else:
        if a < p:
            array_tdpb = thang_du_binh_phuong(p)
            if array_tdpb[0] == -1:
                return 0
            for i in range(len(array_tdpb)):
                if a == array_tdpb[i]:
                    return 1
            return -1
        else:
            a = a % p
