def generate_polygonal_numbers(n, limit):
    """Generate polygonal numbers of type n up to the given limit."""
    if n == 3:
        return list(filter(lambda x: x >= 1000 and x < 10000, map(lambda n: n * (n + 1) // 2, range(1, limit))))
    elif n == 4:
        return list(filter(lambda x: x >= 1000 and x < 10000, map(lambda n: n * n, range(1, limit))))
    elif n == 5:
        return list(filter(lambda x: x >= 1000 and x < 10000, map(lambda n: n * (3 * n - 1) // 2, range(1, limit))))
    elif n == 6:
        return list(filter(lambda x: x >= 1000 and x < 10000, map(lambda n: n * (2 * n - 1), range(1, limit))))
    elif n == 7:
        return list(filter(lambda x: x >= 1000 and x < 10000, map(lambda n: n * (5 * n - 3) // 2, range(1, limit))))
    elif n == 8:
        return list(filter(lambda x: x >= 1000 and x < 10000, map(lambda n: n * (3 * n - 2), range(1, limit))))
    else:
        return []

def dfs(results, ps, indexLeft, currentResult):
    """Depth-first search to find cyclic sets of polygonal numbers."""
    currentP = currentResult[-1]
    for idx in indexLeft:
        for nextP in ps[idx]:
            if currentP % 100 == nextP // 100:
                _currentResult = currentResult + [nextP]
                if len(_currentResult) == 6:
                    if nextP % 100 == _currentResult[0] // 100:
                        results.append(_currentResult)
                else:
                    _indexLeft = indexLeft[:]
                    _indexLeft.remove(idx)
                    dfs(results, ps, _indexLeft, _currentResult)

