        elif op['operation'] == 'append':
            ll.append(op['item'])
        elif op['operation'] == 'insert':
            ll.insert(op['pos'], op['item'])
        elif op['operation'] == 'remove':
            ll.remove(op['item'])
        elif op['operation'] == 'search':
            ll.search(op['item'])
