def genMoves(x, y, a, b, n):
    newMoves = []
    offsets = [[a, b], [b, a], [-a, -b], [-b, -a], [-a, b], [a, -b], [-b, a], [b, -a]]
    for o in offsets:
        nx = x + o[0]
        ny = y + o[1]
        if isWithinRange(nx, ny, n):
            newMoves.append([nx, ny])
    return newMoves

def KnightMoves(a, b, n):
    moveTuples = [[0, 0]]
    g = Graph()
    while len(moveTuples) > 0:
        new = moveTuples[:]
        moveTuples = []
        for x, y in new:
            v = Vertex(f"{x},{y}")
            nm = genMoves(x, y, a, b, n)
            for nmm in nm:
                if f"{nmm[0]},{nmm[1]}" not in g.vertList:
                    moveTuples.append(nmm)
                    g.addEdge(v, Vertex(f"{nmm[0]},{nmm[1]}"))
    return g

# main function
def main_solution(a, b, n):
    g = KnightMoves(a, b, n)
    start = None
    end = None
    for k in g.getAllVertices():
        if k.vid == '0,0':
            start = k
        elif k.vid == f"{n-1},{n-1}":
            end = k
    if start is None or end is None:
        return -1
    bread_first_search(start)
    return print_path(start, end)

