    def add(self, order, client_id):
        self._orders.append((client_id, order))

    def delete(self, order_to_delete):
        self._orders = [(client_id, order) for (client_id, order) in self._orders if order != order_to_delete]

    def orders(self):
        return [order for (_, order) in self._orders]

    def highest_buy_order(self):
        buy_prices = [order.price for (_, order) in self._orders if order.price is not None and order.buy_sell == 'buy']
        return max(buy_prices) if buy_prices else None

    def lowest_sell_order(self):
        sell_prices = [order.price for (_, order) in self._orders if order.price is not None and order.buy_sell == 'sell']
