class Sudoku_Solver(object):
    def __init__(self, matrix):
        self.matrix = matrix

    def used_in_row(self, i, size, number):
        for k in range(size):
            if (self.matrix[i][k] == number):
                return True
        return False

    def used_in_col(self, j, size, number):
        for k in range(size):
            if (self.matrix[k][j] == number):
                return True
        return False

    def used_in_box(self, i_start_box, j_start_box, size, number):
        box_size = int(math.sqrt(size))
        for k1 in range(box_size):
            for k2 in range(box_size):
                if self.matrix[i_start_box+k1][j_start_box+k2] == number:
                    return True
        return False

    def isSafe(self, i, j, size, number):
        return not self.used_in_row(i, size, number) and not self.used_in_col(j, size, number) and not self.used_in_box(i - i%int(math.sqrt(size)), j - j%int(math.sqrt(size)), size, number)

    def find_empty_box(self, l, size):
        for row in range(size):
            for col in range(size):
                if (self.matrix[row][col] == -1):
                    l[0] = row
                    l[1] = col
                    return True
        return False

    def solveSudoku(self, size):
        l = [0,0]
        if not self.find_empty_box(l, size):
            return True

        row = l[0]
        col = l[1]
        for number in range(1, size + 1):
            if self.isSafe(row, col, size, number):
                self.matrix[row][col] = number
                if self.solveSudoku(size):
                    return True
                self.matrix[row][col] = -1

        return False

