You are given a question that requires some input and output variables as follows:

Given the specifications for low-precision number formats, what are the string representations of the fixed point, floating point, and block floating point formats when configured with the provided parameters?

The input and output requirements are as follows:

Input:
  `wl` (int): Word length of each fixed point number.
  `fl` (int): Fractional length of each fixed point number.
  `clamp` (bool): Whether to clamp unrepresentable numbers.
  `symmetric` (bool): Whether to make the representable range symmetric.
  `exp` (int): Number of bits allocated for exponent in floating point format.
  `man` (int): Number of bits allocated for mantissa in floating point format.
  `bfp_wl` (int): Word length of the tensor in block floating point format.
  `bfp_dim` (int): Block dimension to share exponent in block floating point format.

Output:
  `return` (dict): A dictionary containing the string representations of the fixed point, floating point, and block floating point formats.
    - `fixed_point` (str): String representation of the fixed point format.
    - `floating_point` (str): String representation of the floating point format.
    - `block_floating_point` (str): String representation of the block floating point format.

Given the following input:

{'wl': 11, 'fl': 4, 'clamp': False, 'symmetric': False, 'exp': 3, 'man': 1, 'bfp_wl': 6, 'bfp_dim': 5}

Can you predict the output without writing any code? Please reason and put your final answer in the following json format: {"output": <your output>}, where <your output> should strictly match the the output requirement as specified.

Tip: Here is a reference code snippet for this question. You can refer to this code to guide your reasoning but not copy spans of code directly.

# import necessary packages
import random

# all class and function definitions in the code file, if any
class Number:
    def __init__(self):
        pass

    def __str__(self):
        raise NotImplemented


class FixedPoint(Number):
    def __init__(self, wl, fl, clamp=True, symmetric=False):
        assert wl > 0, "invalid bits for word length: {}".format(wl)
        assert fl > 0, "invalid bits for fractional length: {}".format(fl)
        assert type(clamp) == bool, "invalid type for clamping choice: {}".format(
            type(clamp)
        )
        assert type(symmetric) == bool, "invalid type for symmetric: {}".format(
            type(symmetric)
        )
        self.wl = wl
        self.fl = fl
        self.clamp = clamp
        self.symmetric = symmetric

    def __str__(self):
        return "FixedPoint (wl={:d}, fl={:d})".format(self.wl, self.fl)

    def __repr__(self):
        return "FixedPoint (wl={:d}, fl={:d})".format(self.wl, self.fl)


class FloatingPoint(Number):
    def __init__(self, exp, man):
        assert 8 >= exp > 0, "invalid bits for exponent:{}".format(exp)
        assert 23 >= man > 0, "invalid bits for mantissa:{}".format(man)
        self.exp = exp
        self.man = man

    def __str__(self):
        return "FloatingPoint (exponent={:d}, mantissa={:d})".format(self.exp, self.man)

    def __repr__(self):
        return "FloatingPoint (exponent={:d}, mantissa={:d})".format(self.exp, self.man)


class BlockFloatingPoint(Number):
    def __init__(self, wl, dim=-1):
        assert wl > 0 and isinstance(wl, int), "invalid bits for word length:{}".format(
            wl
        )
        assert dim >= -1 and isinstance(dim, int), "invalid dimension"
        self.wl = wl
        self.dim = dim

    def __str__(self):
        return "BlockFloatingPoint (wl={:d}, dim={:d})".format(self.wl, self.dim)

    def __repr__(self):
        return "BlockFloatingPoint (wl={:d}, dim={:d})".format(self.wl, self.dim)

# main function
def main_solution(wl, fl, clamp, symmetric, exp, man, bfp_wl, bfp_dim):
    # Convert JSON serializable inputs to original input variables
    clamp = bool(clamp)
    symmetric = bool(symmetric)
    bfp_dim = int(bfp_dim)

    # Create instances of the number formats
    fixed_point = FixedPoint(wl, fl, clamp, symmetric)
    floating_point = FloatingPoint(exp, man)
    block_floating_point = BlockFloatingPoint(bfp_wl, bfp_dim)

    # Return the string representations of the number formats
    return {
        "fixed_point": str(fixed_point),
        "floating_point": str(floating_point),
        "block_floating_point": str(block_floating_point)
    }

