import itertools
import copy

# Constants for colors
R = 0
V = 1
B = 2

# Class representing a constraint
class Contrainte:
    def __init__(self, poids, couples):
        self.poids = poids
        self.couples = couples

# Function to get the number of variables present in the constraints
def getNbVariables(contraintes):
    nbVar = 0
    for c in contraintes:
        for couple in c.couples:
            if couple[0] + 1 > nbVar:
                nbVar = couple[0] + 1
    return nbVar

# Function to sort constraints by descending order of weight
def trier(contraintes):
    return sorted(contraintes, key=lambda x: x.poids / len(x.couples), reverse=True)

# Function to check if an assignment satisfies the constraint
def assignationPossible(assignation, contrainte):
    for i in range(len(contrainte.couples)):
        if assignation[contrainte.couples[i][0]] != contrainte.couples[i][1]:
            return True
    return False

# Function to filter out assignments that do not satisfy the constraint
def trouverAssignationsPossibles(assignations, contrainte):
    assignations[:] = [x for x in assignations if assignationPossible(x, contrainte)]
    return assignations

# Function to generate all possible assignments with nbVar variables and 3 colors (R, V, B)
def genererAssignations(nbVar):
    return list(itertools.product(range(3), repeat=nbVar))

# Greedy algorithm implementation
def glouton(contraintes):
    contraintes = trier(contraintes)
    nbVar = getNbVariables(contraintes)

    # Generate all possible assignments
    assignations = genererAssignations(nbVar)
    maxPoids = 0

    # For each constraint
    for c in contraintes:
        copieAssignations = copy.deepcopy(assignations)
        if trouverAssignationsPossibles(copieAssignations, c):
            assignations = copieAssignations
            maxPoids += c.poids

