def eratosthenes_sieve(n: int) -> list:
    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False
    primes = []
    for index in range(2, n + 1):
        if sieve[index]:
            primes.append(index)
            for a in range(index * index, n + 1, index):
                sieve[a] = False
    return primes

def is_prime(n: int) -> bool:
    if n <= 1:
        return False
    for q in range(2, int(n ** .5) + 1):
        if n % q == 0:
            return False
    return True

def is_truncatable_prime(n: int) -> bool:
    s = str(n)
    if not is_prime(n):
        return False
    for i in range(len(s)):
        if not is_prime(int(s[i:])):
            return False
        if not is_prime(int(s[:len(s) - i])):
            return False
    return True

# main function
def main_solution(max_limit: int):
    # all input arguments of the main_solution function should be json serializable (no self-defined objects, functions, np.array, set, tuple, etc.)
    primes = eratosthenes_sieve(max_limit)
    truncatable_primes = []

    for prime in primes:
        if prime in (2, 3, 5, 7):
            continue
        if is_truncatable_prime(prime):
            truncatable_primes.append(prime)

