# import necessary packages
import random

# all class and function definitions in the code file, if any
class Nodo:
    def __init__(self, valor):
        self.info = valor
        self.hijos = []

class Arboln:
    def __init__(self):
        self.__raiz = None

    def insertar(self, valor, val_padre=None, pos_hijo=0):
        if self.__raiz is None:
            self.__raiz = Nodo(valor)
            return True

        if val_padre == self.__raiz.info:
            padre = self.__raiz
        else:
            padre = self.__buscar(val_padre, self.__raiz.hijos, 0)

        if padre is not None:
            padre.hijos.insert(pos_hijo, Nodo(valor))
            return True

        return False

    def __buscar(self, valor, hermanos=None, pos=0):
        if pos >= len(hermanos):
            return None

        if hermanos[pos].info == valor:
            return hermanos[pos]

        nodo = self.__buscar(valor, hermanos[pos].hijos)
        if nodo is not None:
            return nodo

        nodo = self.__buscar(valor, hermanos, pos + 1)
        if nodo is not None:
            return nodo

        return None

    def padre_mas_hijos(self, nodos=None, pos=0):
        if nodos is None:
            if self.__raiz is None:
                return None
            nodos = [self.__raiz]
            self.__mayorpadre = self.__raiz

        if pos >= len(nodos):
            return 0

        if len(nodos[pos].hijos) > len(self.__mayorpadre.hijos):
            self.__mayorpadre = nodos[pos]

        self.padre_mas_hijos(nodos[pos].hijos)
        self.padre_mas_hijos(nodos, pos + 1)

        return self.__mayorpadre.info

# main function
def main_solution(insert_values, parent_values):
    """
    Main function to solve the problem of finding the parent node with the most children in an n-ary tree.

    Input:
    - insert_values (list of int): List of values to be inserted into the tree.
    - parent_values (list of int): List of parent values corresponding to the insert_values.

    Output:
    - return (int): The value of the parent node with the most children.
    """
    arbol = Arboln()
    for i, value in enumerate(insert_values):
        parent_value = parent_values[i] if parent_values[i] is not None else None
        arbol.insertar(value, parent_value)

    return arbol.padre_mas_hijos()

