# all class and function definitions in the code file, if any
class Group(object):

    def __init__(self, group, grtype):
        self._group = group
        self._grtype = grtype
        if len(self._group) == 0:
            raise Exception("Group not contain any elements")

        self.binop = lambda x, y: (x + y) % len(self._group)
        self._abelian = self._is_abelian(self._group)
        self._properties = {}

    def set_binop(self, binop):
        ''' set user binary operation over group
        '''
        self.binop = binop

    def __mul__(self, group):
        ''' Product of two groups
        '''
        pass

    def __add__(self, othergroup):
        ''' Addition of two groups. Groups must be abelian
        '''
        if self.is_abelian() is False or othergroup.is_abelian is False:
            raise Exception("Both groups must be abelian")

    def __str__(self):
        return self._grtype

    def name(self):
        return self._grtype

    def replace(self, item):
        pass

    def is_abelian(self):
        return self._abelian

    def _is_abelian(self, group):
        for item1 in group:
            for item2 in group:
                # Check Commutativity
                commut = all([self.binop(item1[i], item2[i]) == self.binop(
                    item2[i], item1[i]) for i in range(len(item1))])
                if commut is False:
                    return False
                # Check closure
                closure = all(
                    [self.binop(item1[i], item2[i]) in item1
                        for i in range(len(item1))])
                if closure is False:
                    return False
                # Check identity
                ident = all(
                    [self.binop(item1[i], 1) == self.binop(1, item1[i])
