# import necessary packages
import numpy as np
import scipy.linalg as sp
import random

# all class and function definitions in the code file, if any
def Minor(A, i, j):
    N = A.shape[0]
    minor = np.zeros((N-1, N-1))
    cork = 0
    for k in range(N):
        if k == i:
            cork = 1
        else:
            corh = 0
            for h in range(N):
                if h == j:
                    corh = 1
                else:
                    minor[k-cork][h-corh] = A[k][h]
    return minor

def Det(A):
    N = A.shape[0]
    if N == 2:
        return A[0,0]*A[1,1] - A[0,1]*A[1,0]
    elif N > 2:
        det = 0
        for i in range(N):
            det += ((-1)**i) * A[0][i] * Det(Minor(A, 0, i))
        return det

def Cofactors(A, Transpose=True):
    N = A.shape[0]
    cofactors = np.zeros((N, N))
    for i in range(N):
        for j in range(N):
            cofactors[i][j] = ((-1)**(i+j)) * Det(Minor(A, i, j))
    if Transpose:
        transpose = np.zeros((N, N))
        for k in range(N):
            for l in range(N):
                transpose[l, k] = cofactors[k, l]
        return transpose
    else:
        return cofactors

def Invert(A):
    N = A.shape[0]
    if N == 2:
        invert = (1/Det(A)) * np.array([[A[1,1], -A[0,1]], [-A[1,0], A[0,0]]])
    else:
        invert = (1/Det(A)) * Cofactors(A, True)
    return invert

def Matrix_multiplication(A, B):
    AShape = A.shape
    BShape = B.shape
    Product = np.zeros((AShape[0], BShape[1]))
    for i in range(AShape[0]):
        for j in range(BShape[0]):
            for k in range(len(B)):
                Product[i][j] += A[i][k] * B[k][j]
    return Product

def Gauss_Elimination(A):
    N = A.shape
    I = np.identity(N[0])
    for i in range(N[0]):
        pivot = A[i, i]
        for z in range(N[1]):
            A[i, z] = A[i, z] / pivot
            I[i, z] = I[i, z] / pivot
        for u in range(N[0]):
            if u != i:
                scalefactor = A[u, i]
                A[u] -= scalefactor * A[i]
                I[u] -= scalefactor * I[i]
    return I

def Max_error(inv, A):
    N = A.shape[0]
    Identity = np.identity(N)
    B = inv(A)
    ide = Matrix_multiplication(A, B)
    diff = ide - Identity
    return np.max(abs(diff))

def Lin_solver(A, b):
    return np.dot(Invert(A), b)

def LU_lin_solver(A, b):
    lu, piv = sp.lu_factor(A)
    return sp.lu_solve((lu, piv), b)

def SVD_lin_solver(A, b):
    U, Sigma, VT = np.linalg.svd(A)
    UT = np.transpose(U)
    w = np.dot(UT, b)
    S = np.diag(Sigma)
    c = np.linalg.solve(S, w)
    V = np.transpose(VT)
    x = np.dot(V, c)
    return x

def Lin_error(LS, A, b):
    x = LS(A, b)
    return np.max(abs(b - np.dot(A, x)))

def Wire_vector(R_drum, r):
    return R_drum - r

def cosz(r):
    return np.sqrt((r[0]**2) + (r[1]**2)) / np.linalg.norm(r)

def sinz(r):
