import math

# all class and function definitions in the code file, if any
class Player:
    def __init__(self, letter):
        self.letter = letter

    def get_move(self, game):
        pass

class RandomComputerPlayer(Player):
    def __init__(self, letter):
        super().__init__(letter)

    def get_move(self, game):
        spot = random.choice(game.available_moves())
        return spot

class UnbeatableComputerPlayer(Player):
    def __init__(self, letter):
        super().__init__(letter)

    def get_move(self, game):
        if len(game.available_moves()) == 9:
            spot = random.choice(game.available_moves())
        else:
            spot = self.minimax(game, self.letter)['position']
        return spot

    def minimax(self, state, player):
        max_player = self.letter
        other_player = 'O' if player == 'X' else 'X'

        if state.current_winner == other_player:
            return {'position': None, 'score': 1 * (state.num_empty_spots() + 1) if other_player == max_player else -1 * (state.num_empty_spots() + 1)}
        elif not state.empty_spots():
            return {'position': None, 'score': 0}

        if player == max_player:
            best = {'position': None, 'score': -math.inf}
        else:
            best = {'position': None, 'score': math.inf}

        for possible_move in state.available_moves():
            state.make_move(possible_move, player)
            simulate_score = self.minimax(state, other_player)
            state.board[possible_move] = ' '
            state.current_winner = None
            simulate_score['position'] = possible_move

            if player == max_player:
                if simulate_score['score'] > best['score']:
                    best = simulate_score
            else:
                if simulate_score['score'] < best['score']:
                    best = simulate_score

        return best

class TicTacToe:
    def __init__(self):
        self.board = [' ' for _ in range(9)]
        self.current_winner = None

    def available_moves(self):
        return [i for i, spot in enumerate(self.board) if spot == ' ']

    def empty_spots(self):
        return ' ' in self.board

    def num_empty_spots(self):
        return self.board.count(' ')

    def make_move(self, spot, letter):
        if self.board[spot] == ' ':
            self.board[spot] = letter
            if self.winner(spot, letter):
                self.current_winner = letter
            return True
        return False

    def winner(self, spot, letter):
        row_ind = spot // 3
        row = self.board[row_ind*3:(row_ind+1)*3]
        if all([s == letter for s in row]):
            return True
        col_ind = spot % 3
        column = [self.board[col_ind+i*3] for i in range(3)]
        if all([s == letter for s in column]):
            return True
        if spot % 2 == 0:
            diagonal1 = [self.board[i] for i in [0, 4, 8]]
            if all([s == letter for s in diagonal1]):
                return True
            diagonal2 = [self.board[i] for i in [2, 4, 6]]
            if all([s == letter for s in diagonal2]):
                return True
        return False

