            new_x[i] = (a[i][n]-sum)/a[i][i]

            E = abs((new_x[i]-old_x[i])/new_x[i])

            if E > big_error:
                big_error = E
            rel_error = big_error

        if rel_error <= e:
            return new_x

        for i in range(n):
            old_x[i] = new_x[i]

