    elif operation == "conjugate":
        result = complex1.conjugate()
    elif operation == "argument":
        result = complex1.argument()
    else:
        raise ValueError("Invalid operation")

    # Convert the result to JSON serializable output
    if isinstance(result, complex_number):
        return {"real": result.real, "imag": result.imag}
    else:
