    if check(game) == 100:
        return 100 - depth, 0
    if check(game) == -100:
        return depth - 100, 0
    if check(game) == 0:
        return 0, 0
    maximum = -10000
    minimum = 10000
    trickmaxmove = 0
    tricksumminmove = 0
    trickmat = [[-10000 for x in range(3)] for x in range(3)]

    for x in range(3):
        for y in range(3):
            if game[x][y] == -100:
                if move_whose:
                    game[x][y] = 1
                else:
