class Tile:
    """A tile in a Sudoku puzzle"""
    UNKNOWN = '.'
    CHOICES = '123456789'

    def __init__(self, value: str, row: int, col: int):
        self.value = value
        self.row = row
        self.col = col
        self.candidates = set(Tile.CHOICES) if value == Tile.UNKNOWN else set()

    def set_value(self, value: str):
        self.value = value
        self.candidates = set()

    def could_be(self, value: str) -> bool:
        return value in self.candidates

    def eliminate(self, values: set) -> bool:
        """Eliminate values from candidates"""
        new_candidates = self.candidates - values
        if new_candidates != self.candidates:
            self.candidates = new_candidates
            return True
        return False

class Group:
    """A group of 9 Sudoku tiles"""

    def __init__(self, title: str, tiles: Sequence[Tile]):
        self.title = title
        self.tiles = tiles

    def is_consistent(self) -> bool:
        """A group is consistent if it has no duplicates,
        every tile has at least one candidate, and
        every value has a place to go.
        """
        can_place = set()
        used = set()
        for tile in self.tiles:
            # At least one candidate?
            if len(tile.candidates) == 0:
                return False
            # Duplicate checking
            if tile.value in used:
                return False
            elif tile.value != Tile.UNKNOWN:
                used.add(tile.value)
