# import necessary packages
from typing import List

# all class and function definitions in the code file, if any
class Solution:
    def solve(self, board: List[List[str]]) -> None:
        """
        Do not return anything, modify board in-place instead.
        """
        if len(board) < 1:
            return
        di = [(1, 0), (-1, 0), (0, 1), (0, -1)]
        n = len(board)
        m = len(board[0])

        def helper(di, i, j, positions, board, n, m):
            if i < 0 or i >= n or j < 0 or j >= m or board[i][j] == 'X' or board[i][j] == '#':
                return
            if board[i][j] == 'O':
                positions.add((i, j))
                board[i][j] = '#'
                for p in di:
                    helper(di, i + p[0], j + p[1], positions, board, n, m)

        edge = [(i, 0) for i in range(n)] + [(i, m - 1) for i in range(n)] + [(0, j) for j in range(m)] + [(n - 1, j) for j in range(m)]

        for i in range(n):
            for j in range(m):
                positions = set()
                if board[i][j] == 'X':
                    continue
                helper(di, i, j, positions, board, n, m)
                if len(positions) > 0:
                    flag = any(k in edge for k in positions)
                    if not flag:
                        for k in positions:
                            board[k[0]][k[1]] = 'X'

        for i in range(n):
            for j in range(m):
                if board[i][j] == '#':
                    board[i][j] = 'O'

