# import necessary packages
import random

# all class and function definitions in the code file, if any
def Sum(Term, a, Next, b):
    """ 这是一个高阶的求和抽象，Σf(n)= f(a)+...+f(b),a,b是范围，term是求和的方程式，next是a的变换函数
        scheme 定义如下
        (define (<name> a b)
            (if (> a b)
                0
                (+ (<term> a)
                    (<name> (<next> a) b)
                )
            )
        )
    """
    if a > b:
        return 0
    else:
        return Term(a) + Sum(Term, Next(a), Next, b)

def pi(a, b):
    def Term(num):
        return 1.0 / (num * (num + 2))
    def Next(num):
        return num + 4
    return Sum(Term, a, Next, b) * 8

def cube_sum(a, b):
    def cube(num):
        return num * num * num
    def Next(num):
        return num + 1
    return Sum(cube, a, Next, b)

# main function
def main_solution(a, b, operation):
    """
    Main function to compute either the pi sum or the cube sum based on the operation specified.

    Parameters:
    a (int): The starting integer of the range.
    b (int): The ending integer of the range.
    operation (str): The operation to perform, either "pi" or "cube".

    Returns:
    float: The result of the specified operation.
    """
    if operation == "pi":
        return pi(a, b)
    elif operation == "cube":
        return cube_sum(a, b)
