# import necessary packages
import copy

# all class and function definitions in the code file, if any
def sat_solver(cnf, prop):
    clause_sat = True

    for n in range(0, len(cnf)):
        if len(cnf[n]) == 0:
            return []
        elif len(cnf[n]) > 1 or isinstance(cnf[n][0], str):
            clause_sat = False

    if clause_sat:
        return prop

    ap = -1
    for n in range(0, len(prop)):
        if prop[n] < 0:
            ap = n
            break

    prop[n] = True
    trueResult = sat_solver(sub(copy.deepcopy(cnf), ap, True), list(prop))

    prop[n] = False
    falseResult = sat_solver(sub(copy.deepcopy(cnf), ap, False), list(prop))

    if len(trueResult) < 1:
        return falseResult
    else:
        return trueResult

def sub(cnf, ap, value):
    for i in range(0, len(cnf)):
        empty_clause = True
        for j in range(0, len(cnf[i])):
            literal = cnf[i][j]

            if isinstance(literal, bool):
                empty_clause = not(literal)
            else:
                length = len(literal)
                if literal[length-1] == str(ap):
                    truth_value = value
                    if length > 1:
                        truth_value = not(value)

                    if truth_value:
                        cnf[i] = [True]
                        empty_clause = False
                        break
                    else:
                        literal = cnf[i][j] = False

                if isinstance(literal, str):
                    empty_clause = False

        if empty_clause:
            cnf[i] = []
    return cnf

