# import necessary packages
from scipy.special import binom

# all class and function definitions in the code file, if any
class Graph:
    def __init__(self, people, connections):
        self.people = people
        self.connections = connections

class Connection:
    def __init__(self, between):
        self.between = between

class Clustering(object):
    def __init__(self, graph):
        self.graph = graph

    def findTriangles(self):
        triplets = 0
        triangles = 0
        for node in self.graph.people:
            trianglesHere = 0
            connected = []
            for connection in self.graph.connections:
                if connection.between[0] == node:
                    connected.append(connection.between[1])
            triplets += binom(len(connected), 2)
            for connection in self.graph.connections:
                if connection.between[0] in connected:
                    if connection.between[1] in connected:
                        trianglesHere += 1
            triangles += trianglesHere / 2
        if triplets == 0:
            return 0
        else:
            return triangles / triplets

# main function
def main_solution(people, connections):
    # Convert JSON serializable inputs to original input variables
    graph = Graph(people, [Connection(conn) for conn in connections])
    clustering = Clustering(graph)

    # Calculate the clustering coefficient
    clustering_coefficient = clustering.findTriangles()

    # Return the result as a JSON serializable output
    return clustering_coefficient

