# import necessary packages
from math import sqrt
import random

# all class and function definitions in the code file, if any
class Cell:
    def __init__(self, index, state):
        self.index = index
        self.state = state

class Board:
    def __init__(self, state):
        self.state = state

    def size(self):
        return len(self.state)

    def side_len(self):
        return int(sqrt(self.size()))

    def x_has_next_turn(self):
        as_string = ''.join([cell.state for cell in self.state])
        return as_string.count('X') <= as_string.count('O')

    def symbols_in_turn_order(self):
        return ('X', 'O') if self.x_has_next_turn() else ('O', 'X')

    def children(self):
        as_string = ''.join([cell.state for cell in self.state])
        symbol = self.symbols_in_turn_order()[0]

        def replace_cell(i):
            char_list = list(as_string)
            char_list[i] = symbol
            return ''.join(char_list)

        return [Board([Cell(i, state) for i, state in enumerate(replace_cell(i))])
                for i, char in enumerate(as_string) if char == ' ']

    def is_win(self):
        return any(check_line(line) for line in self.all_lines())

    def is_draw(self):
        return all([cell.state != ' ' for cell in self.state])

    def is_leaf_and_score(self):
        if self.is_win():
            return True, 1.0
        elif self.is_draw():
            return True, 0.0
        return False, None

    def row_lines(self):
        as_string = ''.join([cell.state for cell in self.state])
        side_len = self.side_len()
        return [as_string[i * side_len: (i + 1) * side_len] for i in range(side_len)]

    def col_lines(self):
        as_string = ''.join([cell.state for cell in self.state])
        side_len = self.side_len()
        return [as_string[i::side_len] for i in range(side_len)]

    def zig_line(self):
        return [''.join([cell.state for cell in self.state])[::self.side_len() + 1]]

    def zag_line(self):
        side_len = self.side_len()
        size = self.size()
        return [''.join([cell.state for cell in self.state])[-side_len:-size:-(side_len - 1)]]

    def all_lines(self):
        return self.row_lines() + self.col_lines() + self.zig_line() + self.zag_line()

    def score_line(self, line):
        active_symbol, unactive_symbol = self.symbols_in_turn_order()
        return (line.count(active_symbol) + line.count(unactive_symbol)) / (self.side_len() * 2.0)

    def heur_score(self):
        return max([self.score_line(line) for line in self.all_lines()])

def check_line(line):
    def is_match(left, right):
        if left == right:
            return left
        return False
    match = is_match(line[0], line[1])
    for char in line[2:]:
        match = is_match(match, char)
        if not match:
            break
    return match and match != ' '

# main function
def main_solution(board_string):
    # Convert the input string to a Board object
    board = Board([Cell(i, state) for i, state in enumerate(board_string)])

    # Check if the board is a win, draw, or neither
    is_leaf, score = board.is_leaf_and_score()

    # Return the result as a dictionary
    return {
        "is_leaf": is_leaf,
        "score": score
    }

