def cleaveHelper(string, words, lst):
    if len(string) == 0:
        return lst
    if len([i for i in words if i in string]) == 0:
        return None
    else:
        letter = string[0]
        options = []
        for word in words:
            l = len(word)
            if string[:l] == word:
                options.append(word)
        if len(options) == 1:
            l = len(options[0])
            lst.append(options[0])
            string = string[l:]
            return cleaveHelper(string, words, lst)
        else:
            for option in options:
                l = len(option)
                result = cleaveHelper(string[l:], words, lst + [option])
                if result:
                    return result

# main function
def main_solution(input_string, word_list):
    # Convert input_string to a string if it's not already
    input_string = str(input_string)

    # Convert word_list to a list of strings if it's not already
    word_list = [str(word) for word in word_list]

    # Call the cleaveHelper function to process the input
    result = cleaveHelper(input_string, word_list, [])

    # Prepare the output
    if result:
        return ' '.join(result)
    else:
        return "Cleaving stalled: Word not found"

