    def __init__(self, funcs):
        self.funcs = funcs

    def value_at(self, x):
        sum_ = 0
        for f in self.funcs:
            sum_ += f(x)

        return sum_

    def derivative_at(self, x):
        sum_ = 0
        for f in self.funcs:
            sum_ += f.derivative_at(x)
        return sum_

    def symbolic_deriv(self, var_name='x'):
        dstring = None
        for f in self.funcs:
            if not dstring:
                dstring = f.symbolic_deriv(var_name)
            else:
                dstring = dstring + " + " + f.symbolic_deriv(var_name)

        return dstring

