# import necessary packages
import random

# all class and function definitions in the code file, if any
class Queue():
    def __init__(self):
        self.queue = []
    def enqueue(self, value):
        self.queue.append(value)
    def dequeue(self):
        if self.size() > 0:
            return self.queue.pop(0)
        else:
            return None
    def size(self):
        return len(self.queue)

class Graph:
    def __init__(self):
        self.vertices = {}

    def add_vertex(self, vertex_id):
        if vertex_id not in self.vertices:
            self.vertices[vertex_id] = set()

    def add_edge(self, v1, v2):
        if v1 in self.vertices and v2 in self.vertices:
            self.vertices[v1].add(v2)
        else:
            raise IndexError("nonexistent vertex")    

    def get_ancestors(self, vertex_id):
        return self.vertices[vertex_id]        

# main function
def main_solution(ancestors, starting_node):
    # Convert ancestors list of tuples to a graph
    g = Graph()
    for pair in ancestors:
        g.add_vertex(pair[0]) # parent
        g.add_vertex(pair[1]) # child
        g.add_edge(pair[1], pair[0]) 

    # Breadth-first search to find the earliest ancestor
    q = Queue()
    q.enqueue([starting_node])
    visited = set()

    earliest_ancestor = -1

    while q.size() > 0:
        path = q.dequeue()
        v = path[-1]

        if v not in visited:
            visited.add(v)
            parents = g.get_ancestors(v)

            if len(parents) == 0:
                if v != starting_node:
                    earliest_ancestor = v
            else:
                for parent in parents:
                    new_path = list(path)
                    new_path.append(parent)
                    q.enqueue(new_path)

    return earliest_ancestor

