        T = celsius_to_kelvin(t)
        T_T20 = T / celsius_to_kelvin(20)
        return (ps / psr) * np.power(T_T20, -1. / 2.) * (9. + 28e3 * x_W * np.exp(-4.17 * (np.power(T_T20, -1. / 3.) - 1.)))

