# import necessary packages
import random

# all class and function definitions in the code file, if any
def CheckVer(board, kind, position, steps_win, number_columns):
    # Check vertically
    x = position + number_columns * (steps_win - 1)
    if x >= len(board):
        return False
    for i in range(1, steps_win):
        k = position + number_columns * i
        if str(board[k]) != kind:
            return False
    return True

def CheckHor(board, kind, position, steps_win, number_columns):
    # Check horizontal
    x = position + steps_win - 1
    if x >= number_columns:
        return False
    for i in range(1, steps_win):
        k = position + i
        if str(board[k]) != kind:
            return False
    return True

def CheckCrsR(board, kind, position, steps_win, number_columns, number_rows):
    # Check cross right
    x = position + (number_columns + 1) * (steps_win - 1)
    if x >= len(board):
        return False
    for i in range(1, steps_win):
        k = position + (number_columns + 1) * i
        if str(board[k]) != kind:
            return False
    return True

def CheckCrsL(board, kind, position, steps_win, number_columns, number_rows):
    # Check cross left
    x = position + number_rows * (steps_win - 1)
    if x >= len(board):
        return False
    for i in range(1, steps_win):
        k = position + number_rows * i
        if str(board[k]) != kind:
            return False
    return True

def CheckWin(board, player, steps_win, number_columns, number_rows):
    # Check win or lose
    for i in range(len(board)):
        if board[i] == player:
            if CheckVer(board, player, i, steps_win, number_columns):
                return True
            if CheckHor(board, player, i, steps_win, number_columns):
                return True
            if CheckCrsR(board, player, i, steps_win, number_columns, number_rows):
                return True
            if CheckCrsL(board, player, i, steps_win, number_columns, number_rows):
                return True
    return False

# main function
def main_solution(board, steps_win, number_rows, number_columns, AI_player, hu_player):
    # Convert board to list if it's not already
    if isinstance(board, str):
        board = list(board)

    # Check if AI wins
    if CheckWin(board, AI_player, steps_win, number_columns, number_rows):
        return "AI_wins"

    # Check if human player wins
    if CheckWin(board, hu_player, steps_win, number_columns, number_rows):
        return "Human_wins"

    # If no one wins, return "Tie"
    return "Tie"

