import numpy as np
import math

# board model
board = np.zeros((3, 3))

def available(currentBoard, row, col):
    return currentBoard[row][col] == 0

def board_full(currentBoard):
    for i in range(3):
        for j in range(3):
            if currentBoard[i][j] == 0:
                return False
    return True

def check_winner_temp(player):
    # vertical winner
    for i in range(3):
        if board[0][i] == player and board[1][i] == player and board[2][i] == player:
            return True

    # horizontal winner
    for i in range(3):
        if board[i][0] == player and board[i][1] == player and board[i][2] == player:
            return True

    # desc diagonal winner
    if board[2][0] == player and board[1][1] == player and board[0][2] == player:
        return True

    # asc diagonal winner
    if board[0][0] == player and board[1][1] == player and board[2][2] == player:
        return True

    return False

def minimax(depth, maximizing, player):
    nextPlayer = player % 2 + 1
    # if AI won, return 1
    if check_winner_temp(player):
        return [1, depth]
    # if other player won, return -1
    if check_winner_temp(nextPlayer):
        return [-1, depth]
    # in case of a tie, return 0
    if board_full(board):
        return [0, depth]

    if maximizing:
        bestScore = -1 * math.inf
        bestDepth = math.inf

        for i in range(3):
            for j in range(3):
                if available(board, i, j):
                    board[i][j] = player
                    bestMove = minimax(depth + 1, False, player)
                    board[i][j] = 0
                    if bestMove[0] > bestScore or (bestMove[0] == bestScore and bestMove[1] < bestDepth):
                        bestScore = bestMove[0]
                        bestDepth = bestMove[1]
        return [bestScore, bestDepth]
    else:
        bestScore = math.inf
        bestDepth = math.inf

        for i in range(3):
            for j in range(3):
                if available(board, i, j):
                    board[i][j] = nextPlayer
                    bestMove = minimax(depth + 1, True, player)
                    board[i][j] = 0
                    if bestMove[0] < bestScore or (bestMove[0] == bestScore and bestDepth > bestMove[1]):
                        bestScore = bestMove[0]
                        bestDepth = bestMove[1]
        return [bestScore, bestDepth]

def computerMove(player):
    bestScore = -1 * math.inf
    bestPosition = [-100, -100]
    bestDepth = math.inf

    for i in range(3):
        for j in range(3):
            if available(board, i, j):
                board[i][j] = player
                bestMove = minimax(0, False, player)
                board[i][j] = 0
                if bestMove[0] > bestScore or (bestMove[0] == bestScore and bestDepth > bestMove[1]):
                    bestScore = bestMove[0]
                    bestPosition = [i, j]

    board[bestPosition[0]][bestPosition[1]] = player

def main_solution(board_state, player):
    global board
    board = np.array(board_state)
    computerMove(player)
    return board.tolist()

