    results = []

    # Loop through each value of k
    for ki in k:
        p = np.poly1d([1, 2, ki + 1, ki + 1, ki])  # Characteristic polynomial
        c = p.c

        r = np.zeros((len(c), len(c) - 1))

        try:
            for i in range(len(r[1])):
                r[0][i] = c[2 * i + 1]  # Filling first row of the Routh matrix
