                except IndexError:
                    pass
            else:
                try:
                    for j in range(int(i / 2), len(c)):
                        r[i][j] = r[1][j - int(i / 2)]
                except IndexError:
                    pass

        det_array = np.array([])
        for i in range(2, len(c)):
            z = np.zeros((i, i))
            for j in range(0, i):
