        self.k = k
        self.dfs(root, [])
        return list(self.ret)

    def dfs(self, root, path):
        if not root:
            return
        if not root.left and not root.right:
            if len(path) >= self.k:
                self.ret.add(path[-self.k])
            return
        self.dfs(root.left, path + [root.val])
        self.dfs(root.right, path + [root.val])

