class Node():
    """节点元素定义"""
    def __init__(self, key, p=None, left=None, right=None):
        self.key = key
        self.p = p
        self.left = left
        self.right = right

def treeInsert(tree, node):
    """二叉搜索树的插入算法"""
    y = None
    root = tree.root
    while root:
        y = root
        if node.key < root.key:
            root = root.left
        else:
            root = root.right
    node.p = y
    if y is None:  # empty tree
        tree.root = node
    elif node.key < y.key:
        y.left = node
    else:
        y.right = node

def treeDelete(T, z):
    """二叉搜索树的删除算法"""
    if z.left is None:
        transplant(T, z, z.right)
    elif z.right is None:
        transplant(T, z, z.left)
    else:
        y = treeMinimum(z.right)
        if y.p != z:
            transplant(T, y, y.right)
            y.right = z.right
            y.right.p = y
        transplant(T, z, y)
        y.left = z.left
        y.left.p = y

