        if not 1 <= int(d) <= 9:
            return False

        self.grid[x][y] = d
        # Remove this value from the cell unit.
        # If another cell becomes single-valued in the process, recurse.
        singles = [(x, y)]
        while singles:
            x, y = singles.pop()
