# import necessary packages
import random
import math

# all class and function definitions in the code file, if any
# they will be used in the main_solution function, you may need to modify them to meet the requirements of the main_solution function (optional)

def is_prime(x, t=5):
    """Takes a number and the number of times to run the test."""
    if x < 2:
        return False
    elif x < 4:
        return True
    elif even(x):
        return False
    else:
        s, d = as_2sd(x - 1)
        return do_tests(x, s, d, t)

def even(n):
    """Returns True for even numbers."""
    return n % 2 == 0

def do_tests(n, s, d, t):
    """Returns True only if the number passes t tests."""
    for i in range(t):
        if is_composite(n, s, d):
            return False
    return True

def as_2sd(d):
    """Returns a number in the form (2 ^ s) * d."""
    s = 0
    while even(d):
        s += 1
        d //= 2
    return [s, d]

def is_composite(n, s, d):
    """Miller-Rabin test. Returns True if n is composite."""
    a = random.randint(2, n)
    if pow(a, d, n) == 1:
        return False
    for r in range(s):
        ind = (2 ** r) * d
        if pow(a, ind, n) == n - 1:
            return False
    return True

# main function
def main_solution(number, test_count=5):
