# import necessary packages
import random

# all class and function definitions in the code file, if any
def count_on_row(board, row):
    return sum(board[row])

def count_on_col(board, col):
    return sum([row[col] for row in board])

def count_pieces(board):
    return sum([sum(row) for row in board])

def add_piece3(board, row, col):
    if board[row][col] == 1 or sum(board[row]) != 0 or sum(row[col] for row in board) != 0:
        return -1
    return board[0:row] + [board[row][0:col] + [1,] + board[row][col+1:]] + board[row+1:]

def successors3(board):
    values = []
    for r in range(len(board)):
        if sum(board[r]) == 0 and (r == 0 or sum(board[r-1]) != 0):
            for c in range(len(board)):
                values.append(add_piece3(board, r, c))
    valid = list(filter(lambda a: a != -1, values))
    return list(filter(lambda a: sum(map(sum, a)) <= len(board), valid))

def is_goal(board):
    N = len(board)
    return count_pieces(board) == N and \
        all([count_on_row(board, r) <= 1 for r in range(N)]) and \
        all([count_on_col(board, c) <= 1 for c in range(N)])

def solve(initial_board):
    fringe = [initial_board]
    while len(fringe) > 0:
        for s in successors3(fringe.pop()):
            if is_goal(s):
                return s
            fringe.append(s)
    return False

