# all class and function definitions in the code file, if any
class Calculadora:
    def __init__(self, num1=0, num2=0, Zn=0):
        self.num1 = num1
        self.num2 = num2
        self.Zn = Zn

    def imprimirSumaMod(self):
        if self.Zn > 0:
            if self.num1 < 0:
                resultadoDiv = self.num1 / self.Zn
                cociente = resultadoDiv + (abs(resultadoDiv.__round__()))
                multiplicacionDiv = cociente * self.Zn
                return (multiplicacionDiv.__round__() + (self.num2 % self.Zn)) % self.Zn
            elif self.num2 < 0:
                resultadoDiv = self.num2 / self.Zn
                cociente = resultadoDiv + (abs(resultadoDiv.__round__()))
                multiplicacionDiv = cociente * self.Zn
                return (multiplicacionDiv.__round__() + (self.num1 % self.Zn)) % self.Zn
            else:
                return (self.num1 + self.num2) % self.Zn
        else:
