# all class and function definitions in the code file, if any
class Node:
    def __init__(self, item, children=None):
        self.item = item
        self.children = children if children is not None else []
    def __str__(self):
        return str(self.item)

    def add(self, child):
        node = Node(child)
        self.children.append(node)
        return self

class Tree:
    class CurrentMinMax:
        def __init__(self):
            self.minimum = None
            self.maximum = None
    def __init__(self, item):
        self.root = Node(item)

    def _is_balanced(self, current_node, current_level, minmax):
        if current_node is not None:
            if len(current_node.children) == 0:
                if minmax.minimum is None or current_level < minmax.minimum:
                    minmax.minimum = current_level
                if minmax.maximum is None or current_level > minmax.maximum:
                    minmax.maximum = current_level
                if minmax.maximum - minmax.minimum > 1:
                    return False
            for c in current_node.children:
                if not self._is_balanced(c, current_level + 1, minmax):
                    return False
        return True

    def is_balanced(self):
        return self._is_balanced(self.root, 0, Tree.CurrentMinMax())

    def is_balanced_nonrecursive(self):
        stack = [self.root]
        levels = [0]
        current_min = sys.maxsize
        current_max = 0
        current_level = 0
        while len(stack) > 0:
            n = stack.pop()
            current_level = levels.pop()
            for c in n.children:
                stack.append(c)
                levels.append(current_level + 1)
            if len(n.children) == 0:
                if current_level < current_min:
                    current_min = current_level
                if current_level > current_max:
                    current_max = current_level
        return current_max - current_min < 2

