# import necessary packages
import random

# all class and function definitions in the code file, if any
class TicTacToe:
    def __init__(self):
        self.current_player = 'X'
        self.board = [['-' for _ in range(3)] for _ in range(3)]

    def move(self, spot):
        if 1 <= spot <= 9:
            row = (spot - 1) // 3
            col = (spot - 1) % 3
            if self.board[row][col] == '-':
                self.board[row][col] = self.current_player
                return True
        return False

    def boardFull(self):
        return all(cell != '-' for row in self.board for cell in row)

    def gameDone(self):
        for i in range(3):
            if all(self.board[i][j] == self.current_player for j in range(3)):  # row check
                return self.current_player
            if all(self.board[j][i] == self.current_player for j in range(3)):  # col check
                return self.current_player
        if all(self.board[i][i] == self.current_player for i in range(3)):  # downward diagonal
            return self.current_player
        if all(self.board[2 - i][i] == self.current_player for i in range(3)):  # upward diagonal
            return self.current_player
        if self.boardFull():
            return 'tie'
        return ''

# main function
def main_solution(moves):
    game = TicTacToe()
    players = ['X', 'O']
    move_index = 0

    for move in moves:
        game.current_player = players[move_index % 2]
        if not game.move(move):
            return "invalid move"
        move_index += 1
        if game.gameDone():
            break

    result = game.gameDone()
    return result if result else "ongoing"

