def check(pile):
    # checks that the pile is fully settled, i.e. all cells are less than 3
    for i in range(len(pile)):
        for j in range(len(pile[i])):
            if pile[i][j] > 3:
                return False
    return True

def simple(val, rows, cols):
    # makes a pile where all of the cells have the same value
    pile = []
    for i in range(rows):
        r = []
        for j in range(cols):
            r.append(val)
        pile.append(r)
