    np_board = np.array(board)
    pos = ['X', 'O']
    for p in pos:
        if (np.all(np_board == p, axis=1).any() or
            np.all(np_board == p, axis=0).any() or
            np.all(np.diag(np_board) == p) or
            np.all(np.fliplr(np_board).diagonal() == p)):
            return p
    return None

