    self.stack = []

  def push (self, item):
    self.stack.append (item)

  def pop (self):
    return self.stack.pop()

  def peek (self):
    return self.stack[-1]

  def is_empty (self):
    return (len(self.stack) == 0)

  def size (self):
    return (len(self.stack))

class Node (object):
    def __init__ (self, data = None, lchild = None, rchild = None):
      self.data = data
      self.lchild = lchild
      self.rchild = rchild
    def __str__ (self):
      return '(' + str(self.data) + ')'

class Tree (object):
  def __init__ (self):
    self.root = Node()

  def create_tree (self, expr):
    operators = {'-', '+', '*', '/', '//', '%', '**'}
    expr = expr.split(' ')
    stack = Stack()
    current = self.root
    for c in expr:    
      if c == '(':
        node = Node()
        current.lchild = node
        stack.push(current)
        current = current.lchild
      elif c in operators:
        current.data = c
        stack.push(current)
        node = Node()
        current.rchild = node
        current = current.rchild
      elif c == ')':
        if not stack.is_empty():
          current = stack.pop()
      elif c != ' ':
        current.data = c
        current = stack.pop()

  def evaluate (self, aNode):
    if aNode.lchild == None and aNode.rchild == None:
      return str(aNode.data)
    else:
      return eval(f'{self.evaluate(aNode.lchild)} {aNode.data} {self.evaluate(aNode.rchild)}')

  def pre_order (self, aNode):
    if aNode.lchild == None and aNode.rchild == None:
      return str(aNode.data)
    else:
      return f'{aNode.data} {self.pre_order(aNode.lchild)} {self.pre_order(aNode.rchild)}'

  def post_order (self, aNode):
    if aNode.lchild == None and aNode.rchild == None:
      return str(aNode.data)
    else:
      return f'{self.post_order(aNode.lchild)} {self.post_order(aNode.rchild)} {aNode.data}'

# main function
def main_solution(expression):
  # Create expression tree
  expr_tree = Tree()
  expr_tree.create_tree(expression)

  # Evaluate the expression
  result = expr_tree.evaluate(expr_tree.root)

  # Get the prefix and postfix versions of the expression
  prefix_expr = expr_tree.pre_order(expr_tree.root)
  postfix_expr = expr_tree.post_order(expr_tree.root)

  # Return the result, prefix expression, and postfix expression
  return {
    "result": float(result),
    "prefix_expression": prefix_expr,
    "postfix_expression": postfix_expr
  }

