import numpy as np
import collections

# all class and function definitions in the code file, if any
class game():
    def __init__(self, player_colour):
        self.checkMate = False
        self.board = self.setupBoard()
        self.check = False
        self.playerColour = player_colour
        self.peices = [[' ♖ ', ' ♘ ', ' ♗ ', ' ♕ ', ' ♔ ', ' ♙ '], [' ♜ ', ' ♞ ', ' ♝ ', ' ♛ ', ' ♚ ', ' ♟ ']]

    def setupBoard(self):
        board = np.empty((11, 11), dtype=object)
        board[0, [i for i in range(2, 10)]] = ' = '
        board[9, [i for i in range(9)]] = ' = '
        board[0][-1] = '| '
        board[9][-1] = '  '
        for c, y in enumerate(range(1, 11)):
            for j, x in enumerate(range(11)):
                if x == 0:
                    board[y][x] = str(8 - c)
                elif (x == 1 or x == 10) and y < 10:
                    board[y][x] = '|'
                elif y == 10 and x < 10:
                    board[y][x] = ' ' + chr(97 + j - 2) + ' '
                elif y < 9:
                    board[y][x] = [' - ' if (x + y + 1) % 2 == 0 else ' x '][0]

        peices = [[' ♖ ', ' ♘ ', ' ♗ ', ' ♕ ', ' ♔ ', ' ♗ ', ' ♘ ', ' ♖ '], [' ♜ ', ' ♞ ', ' ♝ ', ' ♛ ', ' ♚ ', ' ♝ ', ' ♞ ', ' ♜ ']]
        for c, y in enumerate([1, -3]):
            for x in range(2, 10):
                board[y][x] = peices[c][x - 2]

        board[2][[i for i in range(2, 10)]] = ' ♙ '
        board[-4][[i for i in range(2, 10)]] = ' ♟ '

        board[-1][[0, 1, -1]] = ' '
        board[0][1] = ''
        board[0][0] = '|'
        board[-1][0] = ' '
        board[-2][0] = ' '
        board[-2][-2] = ' = '

        return board

    def search(self, yStart, xStart, colour, direction, yEnd=None, xEnd=None):
        targets = self.peices[[0 if colour == 'white' else 1][0]]
        if direction == 'diagonal':
            incrementList = [(1, 1), (1, -1), (-1, 1), (-1, -1)]
        if direction == 'linear':
            incrementList = [(-1, 0), (0, -1), (1, 0), (0, 1)]
        squareList = []

        for yInc, xInc in incrementList:
            peiceFound = False
            while not peiceFound:
                y, x = (yStart + yInc, xStart + xInc)
                if self.board[y][x] in (' = ', '|') or self.board[y][x] in self.peices[0] or self.board[y][x] in self.peices[1]:
                    if (y, x) == (yEnd, xEnd) and self.board[y][x] in targets:
                        return True
                    peiceFound = True
                elif (y, x) == (yEnd, xEnd):
                    return True

                if xInc > 0:
                    xInc += 1
                if yInc > 0:
                    yInc += 1
                if xInc < 0:
                    xInc -= 1
                if yInc < 0:
                    yInc -= 1

                squareList.append((y, x))

        if yEnd is not None:
            return False
        else:
            return squareList

    def pawnSearch(self, yStart, xStart, colour, yEnd=None, xEnd=None):
        targets = self.peices[[0 if colour == 'white' else 1][0]]
        limit = 1
        c = 0
        peiceFound = False
        if colour == 'white':
            if yStart == 7:
                limit = 2
            increment = (-1, 0)
            take = [(-1, -1), (-1, 1)]
        if colour == 'black':
            if yStart == 2:
                limit = 2
            increment = (1, 0)
            take = [(1, -1), (1, 1)]
        yInc = increment[0]
        xInc = increment[1]

        if self.board[yEnd][xEnd] in targets:
            for coords in take:
                yInc = coords[0]
                xInc = coords[1]
                y, x = (yStart + yInc, xStart + xInc)

                if (y, x) == (yEnd, xEnd):
                    return True
            return False
