                if self.board[y][x] in (' = ', '|') or self.board[y][x] in self.peices[0] or self.board[y][x] in self.peices[1]:
                    return False
                elif (y, x) == (yEnd, xEnd):
                    return True

                if yInc > 0:
                    yInc += 1
                if yInc < 0:
                    yInc -= 1
                c += 1

    def knightSearch(self, yStart, xStart, colour, yEnd=None, xEnd=None):
        targets = self.peices[[0 if colour == 'white' else 1][0]]
        increment = [(-2, 1), (-1, 2), (-2, -1), (-1, -2), (2, 1), (2, -1), (1, -2), (1, 2)]
        for i in increment:
            y, x = (yStart + i[0], xStart + i[1])
            if self.board[y][x] in (' - ', ' x ') or self.board[y][x] in targets:
                if (y, x) == (yEnd, xEnd):
                    return True

    def inCheck(self, colour):
        targets = self.peices[[0 if colour == 'white' else 1][0]]
        breaking = False
        king = [' ♚ ' if colour == 'white' else ' ♔ '][0]

        for y in range(1, 9):
            for x in range(2, 10):
                if self.board[y][x] == king:
                    self.kingPos = (y, x)
                    breaking = True
                    break
            if breaking:
                break

        for y in range(1, 9):
            for x in range(2, 10):
                if self.board[y][x] in targets:
                    if self.ruleCheck(y, x, self.kingPos[0], self.kingPos[1], checking=True):
                        return True

        return False

    def ruleCheck(self, yStart, xStart, yEnd, xEnd, checking=False):
        peice = self.board[yStart][xStart]
        if ord(peice[1:2]) <= 9817:
            colour = 'black'
        else:
            colour = 'white'

        if not checking:
            self.check = self.inCheck(colour)

        if peice in (' ♖ ', ' ♜ '):
            if self.search(yStart, xStart, colour, 'linear', yEnd, xEnd):
