            return False
        if peice in (' ♕ ', ' ♛ '):
            if (self.search(yStart, xStart, colour, 'diagonal', yEnd, xEnd) or self.search(yStart, xStart, colour, 'linear', yEnd, xEnd)):
                if self.check:
                    return not (self.search(yEnd, xEnd, colour, 'diagonal', self.kingPos[0], self.kingPos[1]) or self.search(yEnd, xEnd, colour, 'linear', self.kingPos[0], self.kingPos[1]))
