# import necessary packages
import random

# all class and function definitions in the code file, if any
class RecursiveBkt:

    def __init__(self, n):
        self.n = n
        self.primes = self.get_primes(n)
        self.sum = [None]*(n//2)
        self.index = 1

    @staticmethod
    def is_prime(n):
        if n == 2:
            return True
        if n == 0 or n == 1 or n % 2 == 0:
            return False

        d = 3
        while d * d <= n:
            if n % d == 0:
                return False
            d += 2
        return True

    def get_primes(self, n):
        primes = [2]
        d = 3
        while d <= n:
            if self.is_prime(d):
                primes.append(d)
            d += 2
        return primes

    def consistent(self, k):
        for i in range(0, k):
            if self.sum[k] == self.sum[i]:
                return False
        return True

    def solution(self, k):
        if k == self.n // 2 - 1:
            return True
        return False

    def print_sol(self, k):
        string = str(self.index) + ". "
        self.index += 1
        string += str(self.sum[0] + 1)

        for i in range(1, self.n // 2):
            string += " + "
            string += str(self.sum[i] + 1)

        string += " = " + str(self.n)
        return string

    def bkt(self, k):
        for i in range(0, self.n // 2):
            self.sum[k] = i
            if self.consistent(k):
                if self.solution(k):
                    return self.print_sol(k)
                else:
                    result = self.bkt(k + 1)
                    if result:
                        return result
        return None

