import random

# all class and function definitions in the code file, if any
class PermutationError(Exception):
    def __init__(self, message):
        self.message = message

class Permutation:
    def __init__(self, *args, length=None):
        self.args = [i for i in args]
        self.length = len(args)
        self._length = length
        if length is None:
            if 0 in args or not all(isinstance(i, int) for i in args) or self.length != len(set(self.args)):
                raise PermutationError('Cannot generate permutation from these arguments')
            if self.length == 0:
                self.nb_of_cycles = 0
            else:
                L = self.cycle()
                self.nb_of_cycles = len(L)
        elif length < 0:
            raise PermutationError('Cannot generate permutation from these arguments')
        elif self.length == 0:
            self.args = list(range(1, length + 1))
            L = self.cycle()
            self.nb_of_cycles = len(L)
        elif length != self.length or 0 in args or not all(isinstance(i, int) for i in args) or self.length != len(set(self.args)):
            raise PermutationError('Cannot generate permutation from these arguments')
        else:
            L = self.cycle()
            self.nb_of_cycles = len(L)

    def __len__(self):
        return len(self.args)

    def __repr__(self):
        output = 'Permutation('
        for i in range(len(self.args)):
            if i == len(self.args) - 1:
                output += f'{self.args[i]}'
            else:
                output += f'{self.args[i]}, '
        output += ')'
        return output

    def cycle(self):
        l = self.args
        M = {i: l[i - 1] for i in range(1, len(l) + 1)}
        L = []
        h = []
        m = 1
        while True:
            h = []
            while True:
                if M[m] not in h:
                    m = M[m]
                    h.append(m)
                else:
                    break
            L.append(h)
            for i in l:
                t = 0
                for j in range(len(L)):
                    if i in L[j]:
                        t = 1
                        break
                if t == 0:
                    m = i
                    break

            if sum(1 for i in range(len(L)) for _ in range(len(L[i]))) == len(l):
                break
        for i in range(len(L)):
            t = L[i].index(max(L[i]))
            L[i] = L[i][t:] + L[i][:t]
        return L

    def __str__(self):
        if len(self.args) == 0 and not self._length:
            output = '()'
        else:
            output = '('
            t = self.cycle()
            t.sort(key=lambda x: x[0])
            for i in range(len(t)):
                for j in range(len(t[i])):
                    if j == len(t[i]) - 1:
                        output += f'{t[i][j]}'
                    else:
                        output += f'{t[i][j]} '
                if i == len(t) - 1:
                    output += ')'
                else:
                    output += ')('
        return output

    def __mul__(self, permutation):
        if self.length != permutation.length:
            raise PermutationError('Cannot compose permutations of different lengths')
        M = {permutation.args[i]: self.args[i] for i in range(len(self.args))}
        l1 = []
        for i in sorted(M):
            l1.append(M[i])
        return Permutation(*l1)

    def __imul__(self, permutation):
        self.args = self.inverse().args
        M = {permutation.args[i]: self.args[i] for i in range(len(self.args))}
        l1 = []
        for i in sorted(M):
            l1.append(M[i])
        self.args = l1
        return Permutation(*self.args)

    def inverse(self):
        l = self.args
        M = {l[i - 1]: i for i in range(1, len(l) + 1)}
        l1 = []
        for i in sorted(M):
            l1.append(M[i])
        return Permutation(*l1)

# main function
