# all class and function definitions in the code file, if any
class Point(object):
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __str__(self):
        return str(f"({self.x},{self.y})")

    def __repr__(self):
        return str(self)

    @property
    def is_origin(self):
        if self.x == 0 and self.y == 0:
            return True

        return False


class Triangle(object):
    def __init__(self, points_string):
        nums = [int(i) for i in points_string.split(',')]
        self.p1 = Point(*nums[:2])
        self.p2 = Point(*nums[2:4])
        self.p3 = Point(*nums[4:])

        self.points = [self.p1, self.p2, self.p3]

