# all class and function definitions in the code file, if any
def pkc(n, k):
    result = 0
    if n == k and n >= 0:
        result = 1
    elif (n >= 1 and k == 0) or k > n or n < 1:
        result = 0
    else:
        result = (n - 1) * pkc(n - 1, k) + pkc(n - 1, k - 1)
    return result

def stir1k(n, k):
    return ((-1) ** (n - k)) * pkc(n, k)

def stir1kRecur(n, k):
    if n == k and n >= 0:
