# all class and function definitions in the code file, if any
class Node():
    def __init__(self, value, left=None, right=None):
        self.value = value
        self.leftChild = left
        self.rightChild = right

    def getRootVal(self):
        return self.value

    def getRightChild(self):
        return self.rightChild

    def getLeftChild(self):
        return self.leftChild

    def setRootVal(self, obj):
        self.value = obj

def depth(atree):
    if atree == None:
        return 0
    nleft = depth(atree.leftChild)
    nright = depth(atree.rightChild)
    if nleft > nright:
        return nleft + 1
    else:
        return nright + 1

def getRootNode(tree, curValue):
    if tree.getRootVal() == curValue:
        return tree
    elif tree.leftChild:
        return getRootNode(tree.leftChild, curValue)
    elif tree.rightChild:
        return getRootNode(tree.rightChild, curValue)

def initTree(root, parentValue, childValue):
    if root.getRootVal() == None:
        root = Node(parentValue)
        root.leftChild = Node(childValue)
    else:
        tmp = getRootNode(root, parentValue)
        if tmp != None:
            node = Node(childValue)
            if tmp.getRootVal() != None:
                if tmp.leftChild == None:
                    tmp.leftChild = node
                elif tmp.rightChild == None:
                    tmp.rightChild = node
    return root

# main function
