from math import log, exp

# all class and function definitions in the code file, if any
class Space(object):
    def to_box(self, x):
        return x

    def from_box(self, x):
        return x

    @property
    def inverse(self):
        space = Space()
        space.to_box = self.from_box
        space.from_box = self.to_box
        return space

class LinSpace(Space):
    def __init__(self, a, b):
        self.params = a, b
        self.a = a
        self.range = b - a
        self.m = 1.0 / self.range 

    def to_box(self, x):
        return self.m * (x - self.a)

    def from_box(self, x):
        return self.range*x + self.a 

class LogSpace(Space):
    def __init__(self, a, b):
        self.params = a, b
        self.m = 1.0 / a
        self.d = log(self.m * b)
        self.A = 1.0 / self.d
        self.C = a

    def to_box(self, x):
        return self.A*log(self.m*x)

    def from_box(self, x):
        return self.C*exp(self.d*x)

class Space2D(object):
    def __init__(self, xspace=None, yspace=None):
        self.xspace = xspace if xspace else Space()
        self.yspace = yspace if yspace else Space()

    def to_box(self, p):
        x, y = p
        return (self.xspace.to_box(x), self.yspace.to_box(y))

    def from_box(self, p):
        x, y = p
        return (self.xspace.from_box(x), self.yspace.from_box(y))

    @property
    def inverse(self):
        return Space2D(self.xspace.inverse, self.yspace.inverse)

class LinSpace2D(Space2D):
    def __init__(self, x1, y1, x2, y2):
        Space2D.__init__(self, LinSpace(x1, x2), LinSpace(y1, y2))

class ComposedSpace(Space2D):
    def __init__(self, *kws):
        self._spaces = tuple(kws)

    def to_box(self, x):
        for space in reversed(self._spaces):
            x = space.to_box(x)
        return x

    def from_box(self, x):
        for space in self._spaces:
            x = space.from_box(x)
        return x

# main function
def main_solution(space_type, params, point):
    """
    Converts a 2D point from its original space to box space and back.

    Parameters:
    space_type (str): Type of space ('LinSpace2D' or 'LogSpace2D').
    params (list): Parameters for the space. For 'LinSpace2D', it should be [x1, y1, x2, y2]. For 'LogSpace2D', it should be [a, b].
    point (list): A 2D point [x, y] in the original space.

    Returns:
    list: The converted 2D point [x, y] in the original space.
    """
    if space_type == 'LinSpace2D':
        space = LinSpace2D(*params)
    elif space_type == 'LogSpace2D':
        space = Space2D(LogSpace(*params), LogSpace(*params))
    else:
        raise ValueError("Invalid space type")

    box_point = space.to_box(point)
    original_point = space.from_box(box_point)
    return original_point

