    return board

# Function to check empty spots on the board
def check_empty_spots(board):
    empty_rows = []
    empty_cols = []
    empty_spots = []
    for row in range(len(board)):
        for col in range(len(board)):
            if board[row][col] == g_empty:
                empty_rows.append(row)
                empty_cols.append(col)
                empty_spots.append([row, col])
    return [empty_rows, empty_cols, empty_spots]

# Class to check for a win
class win_check:
    def __init__(self, board):
        self.board = board

    def horizontal_vertical(self):
        board_len = len(self.board)
        for i in range(board_len):
            if self.board[i].count(g_x) == board_len:
                return g_x
            elif self.board[i].count(g_o) == board_len:
