import math
import numpy as np
import scipy

# all class and function definitions in the code file, if any
def int2bitarray(N, k):
    binary_string = bin(N)
    length = len(binary_string)
    bitarray = np.zeros(k, 'int')
    for i in range(length - 2):
        bitarray[k - i - 1] = int(binary_string[length - i - 1])
    return bitarray

def bitarray2int(bitarray):
    bitstring = "".join([str(i) for i in bitarray])
    return int(bitstring, 2)

def BinaryProduct(X, Y):
    A = X.dot(Y)
    if type(A) != scipy.sparse.csr_matrix:
        return A % 2
    return A.toarray() % 2

def GaussJordan(MATRIX, change=0):
    A = np.copy(MATRIX)
    m, n = A.shape
    if change:
        P = np.identity(m).astype(int)
    pivot_old = -1
    for j in range(n):
        filtre_down = A[pivot_old + 1:m, j]
        pivot = np.argmax(filtre_down) + pivot_old + 1
        if A[pivot, j]:
            pivot_old += 1
            if pivot_old != pivot:
                aux = np.copy(A[pivot, :])
                A[pivot, :] = A[pivot_old, :]
                A[pivot_old, :] = aux
                if change:
                    aux = np.copy(P[pivot, :])
                    P[pivot, :] = P[pivot_old, :]
                    P[pivot_old, :] = aux
