    if type(H) != scipy.sparse.csr_matrix:
        m, n = H.shape
        return [a for a in range(n) if H[i, a]]
    indj = H.indptr
    indi = H.indices
    return [indi[a] for a in range(indj[i], indj[i + 1])]

