        """
        if out_min == 0:
            return None
        if in_min == in_max:
            if value == in_min and out_min == out_max:
                return out_min
            return None

        output = math.pow(out_max / out_min, (value - in_min) / (in_max - in_min)) * out_min
        if clip:
            output = Mapping.clip_value(output, out_min, out_max)
        return output

    @staticmethod
