        (extrapolating if possible)
        """
        if in_min == 0:
            return None
        if (value / in_min) <= 0:
            return None
        if (in_max / in_min) <= 0:
            return None

        output = math.log(value / in_min) / math.log(in_max / in_min) * (out_max - out_min) + out_min
        if clip:
            output = Mapping.clip_value(output, out_min, out_max)
        return output

