# import necessary packages
import random

# all class and function definitions in the code file, if any
class Node:
    """ Classe que define um nodo simples de uma Estrutura de dados: (info, NextNodo)"""

    def __init__(self, data):
        """Construtor do Nodo"""
        self.data = data
        self.nextNode = None

    def getData(self):
        return self.data

    def setData(self, data):
        "Atribui valor ao Dado do nodo"
        self.data = data

    def getNextNode(self):
        "Retorna a referencia do proximo nodo"
        return self.nextNode

    def setNextNode(self, newNode):
        "Ajusta a referencia do proximo nodo"
        self.nextNode = newNode

class List:
    def __init__(self):
        self.firstNode = None
        self.lastNode = None

    def __str__(self):
        if self.isEmpty():
            return "A lista esta vazia!"
        currentNode = self.firstNode
        string = ""
        while currentNode is not None:
            string += str(currentNode.getData())
            currentNode = currentNode.getNextNode()
        return string

    def insertAtBegin(self, value):
        newNode = Node(value) # instancia de um novo nodo
        if self.isEmpty(): #Insersao para Lista vazia
            self.firstNode = self.lastNode = newNode
        else:                   #Insersao para lista nao vazia
            newNode.setNextNode(self.firstNode)
            self.firstNode = newNode

    def insertAtEnd(self, value):
        newNode = Node(value)  #instancia de um novo nodo

        if self.isEmpty():  #Se a lista esta vazia
            self.firstNode = self.lastNode = newNode
        else:
            self.lastNode.setNextNode(newNode)
            self.lastNode = newNode

    def removeFromBegin(self):
        if self.isEmpty():
            return None
        firstNodeValue = self.firstNode.getData()
        if self.firstNode is self.lastNode:
            self.firstNode = self.lastNode = None
        else:
            self.firstNode = self.firstNode.getNextNode()
        return firstNodeValue

    def removeFromEnd(self):
        if self.isEmpty():
            return None
        lastNodeValue = self.lastNode.getData()
        if self.firstNode is self.lastNode:
            self.firstNode = self.lastNode = None
        else:
            currentNode = self.firstNode
            while currentNode.getNextNode() is not self.lastNode:
                currentNode = currentNode.getNextNode()
            currentNode.setNextNode(None)
            self.lastNode = currentNode
        return lastNodeValue

    def isEmpty(self):
        return self.firstNode == None

    def getFirstNode(self):
        return self.firstNode

class Stack(List):
    def push(self, data):
        self.insertAtBegin(data)

    def pop(self):
        return self.removeFromBegin()

class Queue(List):
    def push(self, data):
        self.insertAtEnd(data)

    def pop(self):
        return self.removeFromBegin()

# main function
def main_solution(deck_str, cases_str):
    """
    Main function to determine the winner of a card game.

    Args:
        deck_str (str): A string representing the initial deck of cards.
        cases_str (list of str): A list of strings, each representing a player's deck.

    Returns:
        int: The index of the winning player (1-based), or 0 if Juvenal wins.
    """
    deck = Queue()
    for num in deck_str:
        deck.push(int(num))

    cases = []
    for case in cases_str:
        temp = Queue()
        for i in case:
            temp.push(int(i))
        cases.append(temp)

    vencedor = 0
    for _ in range(1000):
        pivo = deck.pop()
        deck.push(pivo)
        for p in cases:
            if p.isEmpty():
                vencedor = cases.index(p) + 1
                break
            elif pivo == p.getFirstNode().getData():
                p.pop()
            else:
                valor = p.getFirstNode().getData()
                p.push(valor)
                p.removeFromBegin()
        if vencedor > 0:
            break

    return vencedor

