    # Convert input to appropriate types
    task_count = int(task_count)
    actor_count = int(actor_count)
    actor_messages = {name: int(count) for name, count in actor_messages.items()}

    # Task Scheduler
    task_sched = TaskScheduler()
    for _ in range(task_count):
        task_sched.new_task(countdown(10))

    # Actor Scheduler
    actor_sched = ActorScheduler()
    for i in range(actor_count):
        actor_sched.new_actor(f"printer_{i}", printer())

    for name, count in actor_messages.items():
