    def list_allowed_moves(self, chessboard):
        possible_directions = [
            (1, 2), (2, 1), (2, -1), (1, -2),
            (-1, -2), (-2, -1), (-2, 1), (-1, 2),
        ]

        possible_moves = self._list_allowed_moves(possible_directions, chessboard, max_move_length=1)
        return possible_moves

