In a game of Tic-Tac-Toe, a player wins by placing three of their marks in a horizontal, vertical, or diagonal row on a board. Given the dimensions of the board and a sequence of moves, determine if the game is over and, if so, who the winner is. What is the status of the game after the given moves?

The input and output requirements are as follows:

Input:
  `width` (int): The width of the Tic-Tac-Toe board. Must be at least 2.
  `height` (int): The height of the Tic-Tac-Toe board. If not provided, defaults to the width. Must be at least 2.
  `moves` (list of int): A list of integers representing the moves made in the game. Each integer corresponds to a position on the board.

Output:
  `return` (dict): A dictionary containing the following keys:
    - `is_game_over` (bool): Indicates whether the game is over.
    - `winner` (str or None): The winner of the game ('X' or 'O') if the game is over, otherwise None.

Given the following input:

{'width': 4, 'height': 3, 'moves': [8, 6, 9, 10, 12, 7, 2, 3]}

Can you predict the output without writing any code? Please reason and put your final answer in the following json format: {"output": <your output>}, where <your output> should strictly match the the output requirement as specified.

Tip: Here is a reference code snippet for this question. You can refer to this code to guide your reasoning but not copy spans of code directly.

# import necessary packages
import random

# all class and function definitions in the code file, if any
class TicTacToe:
    def __init__(self, width=3, height=None) -> None:
        self.width = max(2, width)
        self.height = self.width if height is None else max(2, height)
        self.roundCounter = 1
        self.isPlaying = True
        self.board = [[Square(y * self.width + x + 1) for x in range(self.width)] for y in range(self.height)]

    def getCurrentPlayer(self):
        return 'X' if self.roundCounter % 2 == 1 else 'O'

    def getSquareByPos(self, position):
        position -= 1
        xPos = position % self.width
        yPos = position // self.width
        return self.board[yPos][xPos]

    def updateBoard(self, position):
        charToPlace = self.getCurrentPlayer()
        self.getSquareByPos(position).setValue(charToPlace)

    def didWin(self, position):
        position -= 1
        xPos = position % self.width
        yPos = position // self.width
        return self.checkSquareInRow(yPos, xPos) or self.checkSquareInCol(yPos, xPos) or self.checkSquareInDiag(yPos, xPos)

    def checkSquareInRow(self, yPos, xPos, xPrev=None):
        if self.board[yPos][xPos].getValue() == self.getCurrentPlayer():
            if xPos != 0 and xPos != self.width - 1 and xPrev is None:
                return self.checkSquareInRow(yPos, xPos - 1, xPos) and self.checkSquareInRow(yPos, xPos + 1, xPos)
            elif xPos != 0 and (xPrev is None or xPos < xPrev):
                return self.checkSquareInRow(yPos, xPos - 1, xPos)
            elif xPos != self.width - 1 and (xPrev is None or xPos > xPrev):
                return self.checkSquareInRow(yPos, xPos + 1, xPos)
            else:
                return True
        else:
            return False

    def checkSquareInCol(self, yPos, xPos, yPrev=None):
        if self.board[yPos][xPos].getValue() == self.getCurrentPlayer():
            if yPos != 0 and yPos != self.height - 1 and yPrev is None:
                return self.checkSquareInCol(yPos - 1, xPos, yPos) and self.checkSquareInCol(yPos + 1, xPos, yPos)
            elif yPos != 0 and (yPrev is None or yPos < yPrev):
                return self.checkSquareInCol(yPos - 1, xPos, yPos)
            elif yPos != self.height - 1 and (yPrev is None or yPos > yPrev):
                return self.checkSquareInCol(yPos + 1, xPos, yPos)
            else:
                return True
        else:
            return False

    def checkSquareInDiag(self, yPos, xPos, vector=None):
        if self.board[yPos][xPos].getValue() == self.getCurrentPlayer() and (yPos == xPos or (self.height - yPos - 1) == xPos):
            if vector is None:
                if yPos == xPos and (self.height - yPos - 1) == xPos:
                    return (self.checkSquareInDiag(yPos - 1, xPos - 1, [-1, -1]) and self.checkSquareInDiag(yPos + 1, xPos + 1, [1, 1])) or (self.checkSquareInDiag(yPos + 1, xPos - 1, [1, -1]) and self.checkSquareInDiag(yPos - 1, xPos + 1, [-1, 1]))
                elif xPos != 0 and xPos != self.width - 1:
                    if yPos == xPos:
                        vector1 = [-1, -1]
                        vector2 = [1, 1]
                    elif (self.height - yPos - 1) == xPos:
                        vector1 = [1, -1]
                        vector2 = [-1, 1]
                    return self.checkSquareInDiag(yPos + vector1[0], xPos + vector1[1], vector1) and self.checkSquareInDiag(yPos + vector2[0], xPos + vector2[1], vector2)
                elif xPos != 0:
                    if yPos == xPos:
                        vector = [-1, -1]
                    elif (self.height - yPos - 1) == xPos:
                        vector = [1, -1]
                    return self.checkSquareInDiag(yPos + vector[0], xPos + vector[1], vector)
                else:
                    vector = [1, 1] if yPos == xPos else [-1, 1]
                    return self.checkSquareInDiag(yPos + vector[0], xPos + vector[1], vector)
            else:
                if xPos != 0 or xPos != self.width - 1:
                    return True
                else:
                    return self.checkSquareInDiag(yPos + vector[0], xPos + vector[1], vector)
        else:
            return False

class Square:
    def __init__(self, initialValue):
        self.value = str(initialValue)
        self.canBePlayed = True

    def getValue(self):
        return self.value

    def setValue(self, newValue):
        self.value = newValue
        if self.value in ['X', 'O']:
            self.canBePlayed = False

# main function
def main_solution(width, height, moves):
    game = TicTacToe(width, height)
    for move in moves:
        if game.isPlaying:
            game.updateBoard(move)
            if game.didWin(move):
                game.isPlaying = False
            else:
                game.roundCounter += 1
        else:
            break
    return {"is_game_over": not game.isPlaying, "winner": game.getCurrentPlayer() if not game.isPlaying else None}

