class Game:
    def __init__(self):
        self.rats = []

    def subscribe(self, observer):
        self.rats.append(observer)
        self.notify()

    def unsubscribe(self, observer):
        self.rats.remove(observer)
        self.notify()

    def notify(self):
        for observer in self.rats:
            observer.update()

