# all class and function definitions in the code file, if any
class Graph: 
    def __init__(self, V, E):
        self.E = set(frozenset((u, v)) for  u, v in E) 
        self._nbrs = {}
        for v in V:
            self.addNode(v)
        for u,v in self.E:
            self.addEgde(u, v)

    def addNode(self, v):
        if v not in self._nbrs:
            self._nbrs[v] = set()

    def addEgde(self, u, v):
        self.E.add(frozenset([u, v]))
        self.addNode(u)
        self.addNode(v)
        self._nbrs[u].add(v)
        self._nbrs[v].add(u)

    def removeEgde(self, u, v):
        e = frozenset([u, v])
        if e in self.E: 
            self.E.remove(e)
            self._nbrs[u].remove(v)
            self._nbrs[v].remove(u)

    def removeNode(self, u):
        todelete = list(self.nbrs(u))
        for v in todelete:
            self.removeEgde(u, v)
        del self._nbrs[u]

    def deg(self, v):
        return len(self._nbrs[v])

    def nbrs(self, v):
        return iter(self._nbrs[v])

    @property
    def m(self):
        return len(self.E)

    @property
    def n(self):
        return len(self._nbrs)

