import numpy as np

# all class and function definitions in the code file, if any
def gauss(A):
    '''Gauss Elimination to find exact root of linear system'''
    m = len(A)
    n = m + 1
    for i in range(m):
        # Find maximum pivot element
        pivots = [abs(A[k][i]) for k in range(i, m)]
        i_max = pivots.index(max(pivots)) + i
        if A[i_max][i] == 0:
            return "The system has no unique root"
        else:
            # Convert matrix into upper triangular matrix
            A[i_max], A[i] = A[i], A[i_max]
            for k in range(i + 1, m):
                f = A[k][i]/A[i][i]
                for j in range(n):
                    A[k][j] -= f*A[i][j]
                A[k][i] = 0
    # Solve equation Ax = b for an upper triangular matrix A    
    x = []
    for i in range(m - 1, -1, -1):
        x.insert(0, A[i][m]/A[i][i])
        for k in range(i - 1, -1, -1):
            A[k][m] -= A[k][i]*x[0]
    return x

# main function
def main_solution(augmented_matrix):
    # Convert input to list of lists for gauss function
    A = np.array(augmented_matrix).tolist()

    # Find rank of coefficient matrix and augmented matrix
    n = len(A[0]) - 1  # number of variables in the system
    B = [row[:-1] for row in A]
    B = np.array(B)
    A = np.array(A)
    rA = np.linalg.matrix_rank(A)
    rB = np.linalg.matrix_rank(B)

    # Solve system
    if rA == rB == n:
        A = A.tolist()
        x = gauss(A)
        return {"solution": x}
    elif rA == rB < n:
        return {"message": f"The system has infinite number of roots depending on {n - rA} parameters"}
    else:
        return {"message": "The system has no root"}

