# import necessary packages
import random
import string

# main function
def main_solution(input_string):
    # Initialize necessary data structures
    table_code = {}
    count_dict = {}
    count_list = []
    haffman = []

    # Count frequency of each character in the input string
    for char in input_string:
        if char in count_dict:
            count_dict[char] += 1
        else:
            count_dict[char] = 1
            table_code[char] = ''

    # Prepare count_list for sorting
    for char, count in count_dict.items():
        count_list.append([[char], count])
    count_list.sort(key=lambda x: x[1])

    # Huffman encoding process
    while len(count_list) > 1:
        pair_sum = count_list[0][1] + count_list[1][1]
        new_pair = [[''.join(count_list[0][0] + count_list[1][0])], pair_sum]
        count_list = [new_pair] + [item for item in count_list[2:] if item[1] < pair_sum] + [item for item in count_list[2:] if item[1] >= pair_sum]
        haffman.append(new_pair)

    # Generate Huffman codes
    set_sign = sorted(set(input_string))
    for k, i in enumerate(haffman):
        for item in set_sign:
            if table_code[item] == '':
                null_code = '0'
                one_code = '1'
                letter_code = ''
                if item in i[0][0]:
                    if item == i[0][0][-1]:
                        letter_code += one_code
                    if item == i[0][0][0]:
                        letter_code += null_code
                if k < len(haffman) - 1:
                    haffman_next_step = haffman[k + 1:]
                    for next_i in haffman_next_step:
                        if item in next_i[0][0]:
                            if item == next_i[0][0][-1]:
                                letter_code = one_code + letter_code
                            else:
                                letter_code = null_code + letter_code
                table_code[item] = letter_code

    # Prepare the encoded string
    encoded_string = ''.join(table_code[char] for char in input_string)

    # Return the encoded string and the Huffman code table
    return {
        "encoded_string": encoded_string,
        "huffman_code_table": table_code
    }

