    def addInterval(self, start, end):
        if start >= end:
            return

        if len(self._m_IntervalList) == 0 or self._m_IntervalList[-1] < start:
            self._m_IntervalList.append(start)
            self._m_IntervalList.append(end)
        elif self._m_IntervalList[0] > end:
