    # Convert input to the required format
    n = int(n)

    # Generate squares of primes less than n
    squaresOfPrimes = [p*p for p in primes(n)]

    # Function to check if a number is square-free
    def sqf(x):
        for p in squaresOfPrimes:
            if x % p == 0:
                return False
        return True

    # Generate unique numbers using binomial coefficients
    uniqueNumbers = set()
    for i in range(1, n + 1):
        for j in range(0, i + 1):
            uniqueNumbers.add(choose(i, j))

    # Filter square-free numbers
    squareFreeNumbers = [x for x in uniqueNumbers if sqf(x)]

    # Return the sum of square-free numbers and the list of square-free numbers
    return {"sum_of_square_free_numbers": sum(squareFreeNumbers), "square_free_numbers": squareFreeNumbers}

