# all class and function definitions in the code file, if any
def primepos(p1, count): 
    if p1 == 1:
        return False
    elif count == int(p1**(1/2)) + 1:
        return True
    else:
        if p1 % count == 0:
            return False
        else:
            return primepos(p1, count + 1)

def reverse(p1): 
    return p1 if len(p1) == 1 else p1[-1] + reverse(p1[:-1])

def is_palindrome(p1):
