# main function
def main_solution(letters, words):
    # Convert the string of letters into an 8x8 grid
    grid = [list(letters[i:i+8]) for i in range(0, 64, 8)]

    # Function to check if a word can be found in the grid
    def find_word(word):
        word_len = len(word)
        # Check horizontally
        for row in grid:
            if word in ''.join(row) or word[::-1] in ''.join(row):
                return True
        # Check vertically
        for col in range(8):
            col_str = ''.join(grid[row][col] for row in range(8))
            if word in col_str or word[::-1] in col_str:
                return True
        # Check diagonally (top-left to bottom-right)
        for i in range(8 - word_len + 1):
            for j in range(8 - word_len + 1):
                diag_str = ''.join(grid[i+k][j+k] for k in range(word_len))
                if word in diag_str or word[::-1] in diag_str:
                    return True
        # Check diagonally (top-right to bottom-left)
        for i in range(8 - word_len + 1):
            for j in range(word_len - 1, 8):
                diag_str = ''.join(grid[i+k][j-k] for k in range(word_len))
                if word in diag_str or word[::-1] in diag_str:
                    return True
        return False

    # Check all words
    for word in words:
        if not find_word(word):
            return False
    return True

