    if node1 not in G or node2 not in G or node2 not in G[node1] or node1 not in G[node2]:
        return G
    del G[node1][node2]
    del G[node2][node1]
    return G

def all_perms(seq):
    if len(seq) == 0:
        return [[]]
    if len(seq) == 1:
        return [seq, []]
    most = all_perms(seq[1:])
    first = seq[0]
    rest = []
    for perm in most:
