def finding_S(maze):
    for rows in maze:
        for spaces in rows:
            if 'S' in spaces:
                return (maze.index(rows), rows.index(spaces))

def finding_E(maze):
    E_value = 'E'
    for rows in maze:
        for spaces in rows:
            if E_value in spaces:
                return True
    return False

def searching_S(maze):
    S_value = 'S'
    for rows in maze:
        for spaces in rows:
            if S_value in spaces:
                return True
    return False

def invalid_char(maze):
    valid = ['S', 'E', ' ', '#']
    spot = 0
    for rows in maze:
        for spaces in rows:
            if spaces not in valid:
                return spot, spaces
        spot += 1
    return spot, '1'

def solve(rows, spaces, given_maze):
    loop = 2
    amount_rows = []
    amount_spaces = []
    for i in range(len(given_maze)):
        amount_rows.append(i)
    for i in range(len(given_maze[0])):
        amount_spaces.append(i)

    while(loop == 2):
        if given_maze[rows][spaces] == 'S' and given_maze[rows][spaces - 1] == ' ':
            spaces -= 1
        if given_maze[rows][spaces] == 'S' and given_maze[rows][spaces + 1] == ' ':
