                rows += 1
                continue
        if rows - 1 in amount_rows and spaces in amount_spaces:
            if given_maze[rows - 1][spaces] == ' ':
                given_maze[rows][spaces] = '^'
                rows -= 1
                continue
        if spaces - 1 in amount_spaces and rows in amount_rows:
