                continue

        if rows in amount_rows and spaces - 1 in amount_spaces:
            if given_maze[rows][spaces - 1] == '>':
                given_maze[rows][spaces] = '.'
                spaces -= 1
                continue
        if spaces + 1 in amount_spaces and rows in amount_rows:
            if given_maze[rows][spaces + 1] == '<':
                given_maze[rows][spaces] = '.'
                spaces += 1
                continue
        if rows + 1 in amount_rows and spaces in amount_spaces:
            if given_maze[rows + 1][spaces] == '^':
                given_maze[rows][spaces] = '.'
                rows += 1
                continue
        if rows - 1 in amount_rows and spaces in amount_spaces:
            if given_maze[rows - 1][spaces] == 'v':
                given_maze[rows][spaces] = '.'
                rows -= 1
                continue

        if " " not in given_maze:
            return "Error: No route could be found from start to end. Maze unsolvable."

    return "\n".join(["".join(row) for row in given_maze])

# main function
def main_solution(maze_str):
    # Convert the input string to a list of lists
    maze = [list(line) for line in maze_str.split('\n') if line.strip()]

    # Check for errors
    if len(maze) == 0:
        return "Error: Specified file contains no maze."

    if finding_E(maze) == False:
        return "Error: No end position found."

    if searching_S(maze) == False:
        return "Error: No start position found."

    position, symbol = invalid_char(maze)
    if position > 0:
        return f"Error: Maze contains invalid characters. Line {position} contains invalid character '{symbol}'."

    # Find the starting point
    letter = finding_S(maze)
    rows = letter[0]
    spaces = letter[1]

    # Solve the maze
    result = solve(rows, spaces, maze)
    return result

