        self.start, self.end = (vals[0], vals[1]) if is_tuple(vals) else (vals, 0)
        self.n_iter = n_iter
        if func is None:
            self.func = annealing_linear if is_tuple(vals) else annealing_no
        else:
            self.func = func
        self.n = 0

    def step(self) -> Number:
        "Return next value along annealed schedule"
        self.n += 1
        return self.func(self.start, self.end, self.n / self.n_iter)

    @property
    def is_done(self) -> bool:
        "Schedule completed"
        return self.n >= self.n_iter

# main function
def main_solution(vals: Union[float, Tuple[float, float]], n_iter: int, func_name: str = 'linear') -> float:
    # Convert func_name to the corresponding annealing function
    func_map = {
        'no': annealing_no,
        'linear': annealing_linear,
        'exp': annealing_exp,
        'cos': annealing_cos,
        'poly': annealing_poly(2)  # Default polynomial degree of 2
    }
    func = func_map.get(func_name, annealing_linear)

    # Create a Stepper instance
    stepper = Stepper(vals, n_iter, func)

    # Get the final value after all iterations
    while not stepper.is_done:
        final_value = stepper.step()

    return final_value

