    global count
    count = 0

    row = LinkedList([i for i in range(n)])
    diagonal1 = [0 for _ in range(2*n)]
    diagonal2 = [0 for _ in range(2*n)]

    dfs(n, row, diagonal1, diagonal2)
    return count

