        self.left = left
        self.right = right

class Solution:
    def isSymmetrical(self, pRoot):
        if not pRoot:
            return True
        else:
            return self._isSymmetrical(pRoot.left, pRoot.right)

    def _isSymmetrical(self, left, right):
        if not left and not right:
            return True
        elif not left or not right:
            return False
        return left.val == right.val and self._isSymmetrical(left.left, right.right) and self._isSymmetrical(left.right, right.left)

