# all class and function definitions in the code file, if any
class BST:
    class __Node:
        def __init__(self, e):
            self.e = e
            self.left = None
            self.right = None

    def __init__(self):
        self.root = None  # 根节点
        self.size = 0     # 树的节点数

    def getSize(self):
        return self.size

    def isEmpty(self):
        return self.size == 0

    def add(self, e):
        self.root = self.__addElement(self.root, e)

    def __addElement(self, node, e):
        if not node:
            self.size += 1
            return self.__Node(e)
        if node.e == e:
            return node
        elif e < node.e:
            node.left = self.__addElement(node.left, e)
        else:
            node.right = self.__addElement(node.right, e)
        return node

    def contains(self, e):
        return self.__myContains(self.root, e)

    def __myContains(self, node, e):
        if node is None:
            return False
        if node.e == e:
            return True
        elif e < node.e:
            return self.__myContains(node.left, e)
        else:
            return self.__myContains(node.right, e)

    def minmum(self):
        if self.size == 0:
            raise Exception("BST is empty")
        return self.__myminmum(self.root).e

    def __myminmum(self, node):
        if node.left is None:
            return node
        return self.__myminmum(node.left)

    def maxmum(self):
        if self.root is None:
            return "BST is empty"
        node = self.root
        while node.right is not None:
            node = node.right
        return node.e

    def remove(self, e):
        def __myremove(node, e):
            if node is None:
                return
            if e < node.e:
                node.left = __myremove(node.left, e)
                return node
            elif e > node.e:
                node.right = __myremove(node.right, e)
                return node
            else:
                if node.left is None:
                    rightNode = node.right
                    node.right = None
                    self.size -= 1
                    return rightNode
                if node.right is None:
                    leftNode = node.left
                    node.left = None
                    self.size -= 1
                    return leftNode
                successor = self.__myminmum(node.right)
                successor.right = self.__myremoveMin(node.right)
                successor.left = node.left
                node.left = node.right = None
                return successor

        self.root = __myremove(self.root, e)

    def __myremoveMin(self, node):
        if node.left is None:
            rightNode = node.right
            node.right = None
            self.size -= 1
            return rightNode
        node.left = self.__myremoveMin(node.left)
        return node

