        elif rank[0] == "J":
            rankl[9] += 1
        elif rank[0] == "Q":
            rankl[10] += 1
        elif rank[0] == "K":
            rankl[11] += 1
        elif rank[0] == "A":
            rankl[12] += 1
    return rankl

def suitcount(userhand):
    suitl = [0, 0, 0, 0]
    for suit in userhand:
        if suit[1] == "C":
            suitl[0] += 1
        if suit[1] == "D":
            suitl[1] += 1
        if suit[1] == "H":
            suitl[2] += 1
        if suit[1] == "S":
            suitl[3] += 1
    return suitl

