            srank = "Flush"
            for c in rstr:
                if c == '1':
                    pos = rstr.index(c)
            for i in range(pos, pos+5):
                if pos <= 8:
                    if int(rstr[i]) == 1:
                        cons += int(rstr[i])
            if pos == 8 and cons == 5:
