                srank = "Royal Flush"
            elif pos <= 8 and cons == 5:
                rank = 2
                srank = "Straight Flush"
            elif pos == 0 and cons == 4 and rstr[12] == '1':
                rank = 2
                srank = "Straight Flush"

    if isflush == 0:
