        if have1 == 1 and pos2 <= 8 and cons == 5:
            rank = 6
            srank = "Straight"
        elif have1 == 1 and pos2 == 0 and cons == 4 and rstr[:4] == '1111' and rstr[12] == '1':
            rank = 6
            srank = "Straight"
