                break
    else:
        note = ''
        for i in NOTE_DICT.items():
            if note_index - 1 == i[1]:
                note += i[0] + SHARP + '/'
            if note_index + 1 == i[1]:
                note += i[0] + FLAT
                break
    octave_number = int(math.floor(((note_integer - 4) / 12.0) + 1))
    return note + str(octave_number)

