# import necessary packages
import copy
import random

# Constants
X = "X"
O = "O"
EMPTY = None

# Function to initialize the board
def initial_state():
    return [[EMPTY, EMPTY, EMPTY],
            [EMPTY, EMPTY, EMPTY],
            [EMPTY, EMPTY, EMPTY]]

# Function to determine the next player
def player(board):
    count_o = sum(row.count(O) for row in board)
    count_x = sum(row.count(X) for row in board)
    return X if count_x == count_o else O

# Function to get all possible actions
def actions(board):
    possible_actions = set()
    for i in range(3):
        for j in range(3):
            if board[i][j] == EMPTY:
                possible_actions.add((i, j))
    return possible_actions

# Function to get the result of an action
def result(board, action):
    new_board = copy.deepcopy(board)
    i, j = action
    new_board[i][j] = player(board)
    return new_board

# Function to determine the winner
def winner(board):
    for i in range(3):
        if board[i][0] == board[i][1] == board[i][2] and board[i][0] in (X, O):
            return board[i][0]
        if board[0][i] == board[1][i] == board[2][i] and board[0][i] in (X, O):
            return board[0][i]
    if board[0][0] == board[1][1] == board[2][2] and board[0][0] in (X, O):
        return board[0][0]
    if board[2][0] == board[1][1] == board[0][2] and board[2][0] in (X, O):
        return board[2][0]
    return None

# Function to check if the game is over
def terminal(board):
    return winner(board) is not None or all(all(cell is not EMPTY for cell in row) for row in board)

# Function to get the utility of the board
def utility(board):
    win = winner(board)
    if win == X:
        return 1
    elif win == O:
        return -1
    else:
        return 0

# Main function to solve the problem
def main_solution(board):
    if terminal(board):
        return utility(board)
    else:
        return minimax(board)

# Function to get the optimal action using minimax algorithm
def minimax(board):
    if terminal(board):
        return None
    if player(board) == X:
        best = -9999
        best_move = None
        for action in actions(board):
            value = min_value(result(board, action))
            if value > best:
                best = value
                best_move = action
        return best_move
    else:
        best = 9999
        best_move = None
        for action in actions(board):
            value = max_value(result(board, action))
            if value < best:
                best = value
                best_move = action
        return best_move

# Helper functions for minimax algorithm
def max_value(board):
    if terminal(board):
        return utility(board)
    v = -999999999
    for action in actions(board):
        v = max(v, min_value(result(board, action)))
    return v

def min_value(board):
