import random

# all class and function definitions in the code file, if any
def find_empty_location(array, index):
    for row in range(len(array)):
        for col in range(len(array)):
            if array[row][col] == '.':
                index[0] = row
                index[1] = col
                return True
    return False

def used_in_row(array, row, num):
    for i in range(len(array)):
        if (array[row][i] == num):
            return True
    return False

def used_in_col(array, col, num):
    for i in range(len(array)):
        if (array[i][col] == num):
            return True
    return False

def used_in_box(array, row, col, num):
    box_size = int(math.sqrt(len(array)))
    for i in range(box_size):
        for j in range(box_size):
            if (array[i + row][j + col] == num):
                return True
    return False

def is_safe(array, row, col, num):
    box_size = int(math.sqrt(len(array)))
    return not used_in_row(array, row, num) and not \
        used_in_col(array, col, num) and not \
        used_in_box(array, row - row % box_size, col - col % box_size, num)

def solve_sudoku(array):
    index = [0, 0]
    if (not find_empty_location(array, index)):
        return True

    row = index[0]
    col = index[1]

    for num in range(1, len(array)+1):
        if num > 9:
            num = chr(num + 55)
        else:
            num = str(num)
        if (is_safe(array, row, col, num)):
            array[row][col] = num
            if (solve_sudoku(array)):
                return True
            array[row][col] = '.'
    return False

# main function
def main_solution(sudoku_grid):
    # Convert the input grid to a list of lists if it's not already
    if isinstance(sudoku_grid, str):
        sudoku_grid = [list(row) for row in sudoku_grid.split(';')]

    # Solve the Sudoku puzzle
    if solve_sudoku(sudoku_grid):
        # Convert the solved grid back to a string format
        solved_grid = ';'.join([''.join(row) for row in sudoku_grid])
        return solved_grid
    else:
        return "No solution exists"

