        return False

    # If there is an unfinished separator, add it to the set
    if current_separator:
        separators.add(current_separator)

    # Check if there is exactly one unique separator
    if len(separators) != 1:
        return False

    # Define vowels
    vowels = 'AEIOU'

    # Check the alternation of consonants and vowels
    for i, letter in enumerate(letters):
        if i % 2 == 0:  # Even index (consonant expected)
            if letter in vowels:
                return False
        else:  # Odd index (vowel expected)
            if letter not in vowels:
                return False

    # Check if the skewer can be split by the separator to match the letters list
    if skewer.split(list(separators)[0]) != letters:
        return False

    return True

