import re

# main function
def main_solution(recipes):
    """
    This function takes a list of recipes, each represented as a string in the format "ingredients (contains allergens)",
    and returns a dictionary mapping allergens to their corresponding ingredients.

    Args:
    recipes (list of str): A list of strings where each string represents a recipe.

    Returns:
    dict: A dictionary where keys are allergens and values are the corresponding ingredients.
    """
    recipere = re.compile(r'((?:\w+ )+)\(contains (\w+(?:, \w+)*)\)')
    wordre = re.compile(r'\w+')
    allergen_dict = {}

    for recipe in recipes:
        match = recipere.match(recipe)
        if match:
            ingredients = set(wordre.findall(match[1]))
            allergens = set(wordre.findall(match[2]))

            for allergen in allergens:
                if allergen not in allergen_dict:
                    allergen_dict[allergen] = ingredients
                else:
                    allergen_dict[allergen] = allergen_dict[allergen] & ingredients

    arr = list()
    for allergen in allergen_dict:
