    boardPairs = {6: 8, 5:9, 4:10, 3: 11, 2: 12, 1: 13, 8:6, 9:5, 10:4, 11:3, 12:2, 13: 1, 0:0, 7:0}
    if player == 1:        
        addSwitch = False
        for x in range(board[position]):
            index = position + 1 + x
            if index > 13:
                index -= 14
            if x == (board[position]-1) and board[index] == 0:
                pair = boardPairs[index]
                if index <= 6:                
                    board[7] += board[pair]
                    board[pair] = 0    
            if addSwitch == False:
                if index == 0:
                    addSwitch = True
                    if (board[position]+position) >= 14:
                         board[(board[position]+position)-13] += 1
                else:
                    board[index] += 1
            else:
                if index == 7:
                    addSwitch = False
                else:
                    board[index+1] += 1
        board[position] = 0
    elif player == 2:
        for x in range(board[position]):
            index = position + 1 + x            
            if index > 13:
                index -= 14
            if x == (board[position] - 1) and board[index] == 0:
                pair = boardPairs[index]
                if index >= 8:
                    board[0] += board[pair]
                    board[pair] = 0
            if index == 7:
                board[index+(board[position]-7)] += 1
            else:
                board[index] += 1
        board[position] = 0
    return board

