    node = T.root
    leftmost = None

    while node is not None:
        if x1 < node.key[1].p1.x:
            if leftmost is None or node.key[1].p1.x < leftmost.key[1].p1.x:
                leftmost = node
            node = node.left
        elif x1 == node.key[1].p1.x:
            leftmost = node
            break
        else:
            node = node.right

    n_crosses = 0
    node = leftmost
    while node is not None and node.key[1].p2.x <= x2:
