# import necessary packages
import random

# all class and function definitions in the code file, if any
class LLnode():
    def __init__(self, data=None):
        self.data = data
        self.next = None

    def add(self, node):
        self.next = node

class LinkedList():
    def __init__(self):
        self.head = None

    def __iter__(self):
        curNode = self.head
        while curNode is not None:
            yield curNode.data
            curNode = curNode.next

    def __str__(self):
        return str(list(self))

    def from_arr(self, arr):
        if len(arr) == 0:
            return
        self.head = node = LLnode(arr[0])
        for a in arr[1:]:
            next = LLnode(a)
            node.next = next
            node = next

    def getTail(self):
        if self.head is None:
            return None
        curNode = self.head
        while curNode.next is not None:
            curNode = curNode.next
        return curNode

    def append(self, data):
        newNode = LLnode(data)
        tailNode = self.getTail()
        if tailNode is not None:
            tailNode.add(newNode)
        else:
            self.head = newNode

    def prepend(self, data):
        newNode = LLnode(data)
        oldHead = self.head
        self.head = newNode
        if oldHead is not None:
            self.head.next = oldHead

    def reverse(self):
        if self.head is None or self.head.next is None:
            return
        prv = None
        cur = self.head
        while cur is not None:
            nxt = cur.next
            cur.next = prv
            prv = cur
            cur = nxt
        self.head = prv

class TNode():
    def __init__(self, data, parent=None):
        self.parent = parent
        self.children = []
        self.data = data

    def addChild(self, childNode):
        if childNode is not None:
            self.children.append(childNode)
            childNode.parent = self

class Tree():
    def __init__(self):
        self.root = None

    def add(self, data, parentNode=None):
        newNode = TNode(data)
        if parentNode is not None:
            parentNode.addChild(newNode)
        elif self.root is None:
            self.root = newNode
        else:
            raise Exception('Bad parent node provided')
        return newNode

    def traverse(self, method='dfs', order="postorder"):
        dataList = []
        if method == 'dfs':
            self._dfs(self.root, dataList, order)
        else:
            self._bfs(self.root, dataList)
        return dataList

    def _dfs(self, node, datalist, order='preorder'):
        if order == 'preorder':
            datalist.append(node.data)
        for i, child_node in enumerate(node.children):
            self._dfs(child_node, datalist, order)
            if order == 'inorder' and i != len(node.children) - 1:
                datalist.append(node.data)
        if order == 'postorder':
            datalist.append(node.data)

