            past_var[var] = [csp.domains[var]]
        value = conflicts(var, csp.domains[var], n, csp, past_var[var], board)
        if len(past_var[var]) >= x: past_var[var].pop(0)
        csp.domains[var] = value
        board.set_queen(var, value, csp.constraints)
    return False

