def main_solution(num_missionaries, num_cannibals, boat_capacity):
    # Set the problem constraints
    State.set_problem_constraints(num_missionaries, num_cannibals, boat_capacity)

    # Initialize the initial state
    initial_state = State(State.total_missionaries, State.total_cannibals, 1)

    # Perform A* search to find the shortest path
    a_star_queue = Queue()
    initial_path = Path()
    initial_path.appendState(initial_state)
    a_star_queue.enqueue(initial_path)

