    def isSafe(board, row, col):
        ''' test if placed queen is "in check" '''
        for x in range(N):
            if board[row][x] == 1 or board[x][col] == 1:
                return False

        for x in range(N):
            for y in range(N):
                if (x + y) == (row + col) or (x - y) == (row - col):
                    if board[x][y] == 1:
                        return False

        return True

    # Function to format the solution
    def solved(board):
        ''' return the positions of the queens '''
        queens = []
        for row in range(N):
            for col in range(N):
                if board[row][col] == 1:
                    queens.append([row, col])
        return queens

    # Solve the N-Queens problem and return the result
    result = nQueen(board, 0)
    return result if result else "No solution found"

