    elif regex_type == "Epsilon":
        regex = Epsilon()
    elif regex_type == "Alternative":
        regex = Alternative(Char(regex_chars[0]), Char(regex_chars[1]))
    elif regex_type == "Repetition":
        regex = Repetition(Alternative(Char(regex_chars[0]), Char(regex_chars[1])))
    elif regex_type == "Sequence":
