            return 0
        return 1

    def check_blocks(self, row, col):
        row *= 3
        col *= 3
        uniq_digits = set()
        for i in range(row, row + 3):
            for j in range(col, col + 3):
                uniq_digits.add(self.board[i][j])
        if(len(uniq_digits) == 9):
