# import necessary packages
import math
import itertools

# Function to check if a number is prime
def is_prime(num):
    if num < 3 or num % 2 == 0:
        return (num == 2)
    else:
        return all(num % i != 0 for i in range(3, int(num**0.5 + 2), 2))

# Function to check if a number is truncatable from both left and right
def is_truncable(n):
    aux = n
    while len(n) > 1:
        n = n[:-1]
        if not is_prime(int(n)):
            return False
    n = aux
    while len(n) > 1:
        n = n[1:]
        if not is_prime(int(n)):
            return False
    return True

# Main function to find the sum of the only eleven truncatable primes
def main_solution():
    last_ls = ['3','7']
    in_ls = last_ls + ['2', '5']
    midders = ['3','7','1','9']
    finded = 0
    suma = 0
    repeater = 0
    while True:
        for item in itertools.product(midders, repeat=repeater):
            for i in itertools.permutations(in_ls, 1):
                for l in itertools.permutations(last_ls, 1):
                    posible_truncable = ''.join(list(i) + list(item) + list(l))
                    if is_prime(int(posible_truncable)):
                        if is_truncable(posible_truncable):
                            finded += 1
                            suma += int(posible_truncable)
                            if finded == 11:
                                return suma
        repeater += 1

