# import necessary packages
import itertools

# Generator functions to create the polygonal numbers we want
def triangular():
    n = 0
    while True:
        n += 1
        yield int(n * (n + 1) / 2)

def square():
    n = 0
    while True:
        n += 1
        yield n ** 2

def pentagonal():
    n = 0
    while True:
        n += 1
        yield int(n * (3 * n - 1) / 2)

def hexagonal():
    n = 0
    while True:
        n += 1
        yield n * (2 * n - 1)

def heptagonal():
    n = 0
    while True:
        n += 1
        yield int(n * (5 * n - 3) / 2)

def octagonal():
    n = 0
    while True:
        n += 1
        yield n * (3 * n - 2)

# Iterator to give us only 4-digit numbers
def four_digit(g):
    return itertools.takewhile(lambda x: len(str(x)) == 4, itertools.dropwhile(lambda x: len(str(x)) < 4, g))

# Simple function to confirm cyclicity
def is_cyclic(d1, d2):
    return d1 % 100 == int(d2 / 100)

# Given a number and a set, return the subset that is cyclic with the provided number
def get_cyclic_subset(number, starting_set):
    return [n for n in starting_set if is_cyclic(number, n)]

# Main function
def main_solution(start_with):
    # Prepare our sets of polygonals
    tri = sorted(list(four_digit(triangular())))
    squ = sorted(list(four_digit(square())))
    pen = sorted(list(four_digit(pentagonal())))
    hex = sorted(list(four_digit(hexagonal())))
    hep = sorted(list(four_digit(heptagonal())))
    oct = sorted(list(four_digit(octagonal())))

    sets = {'tri': tri, 'squ': squ, 'pen': pen, 'hex': hex, 'hep': hep, 'oct': oct}

    # First assemble the different ordering/sequences of possible polygonal numbers
    combos = itertools.permutations(sets.keys(), 6)
    polygonal_sequences = set()
    for n, i in enumerate(combos):
        if i[0] == start_with:  # By picking only those that start with the specified polygonal type
            polygonal_sequences.add(i)

    # For each sequence of polygonals
    results = []
    for sequence in polygonal_sequences:
        seq = list(sequence)
        set0 = sets[seq[0]]
        for n0 in set0:
            set1 = get_cyclic_subset(n0, sets[seq[1]])
            for n1 in set1:
                set2 = get_cyclic_subset(n1, sets[seq[2]])
                for n2 in set2:
                    set3 = get_cyclic_subset(n2, sets[seq[3]])
                    for n3 in set3:
                        set4 = get_cyclic_subset(n3, sets[seq[4]])
                        for n4 in set4:
                            set5 = get_cyclic_subset(n4, sets[seq[5]])
                            for n5 in set5:
                                if is_cyclic(n5, n0):  # Having got to this point, we need to confirm the last number is cyclic with the first
                                    r = [n0, n1, n2, n3, n4, n5]
                                    results = r
                                    break

    # Calculate the sum of the cyclic sequence
    sum_result = sum(results)
    return sum_result

