# import necessary packages
from collections import deque
import sys

# all class and function definitions in the code file, if any
class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class BinarySearchTree:
    NODE_CLASS = TreeNode
    DEFAULT_TO_ROOT = object()

    def __init__(self):
        self.root = None
        self.size = 0

    def insert(self, value):
        self._insert_node(self.root, value)

    def _insert_node(self, node, value):
        if not self.root:
            self.size += 1
            self.root = self.NODE_CLASS(value)
            return

        if value < node.value:
            if node.left:
                self._insert_node(node.left, value)
            else:
                self.size += 1
                node.left = self.NODE_CLASS(value)
        elif value > node.value:
            if node.right:
                self._insert_node(node.right, value)
            else:
                self.size += 1
                node.right = self.NODE_CLASS(value)
        elif value == node.value:
            raise ValueError('value is duplicate')

    def is_valid(self):
        def inorder_traverse(node):
            if not node:
                return None

            yield from inorder_traverse(node.left)
            yield node.value
            yield from inorder_traverse(node.right)

        previous_value = -sys.maxsize
        for value in inorder_traverse(self.root):
            if previous_value >= value:
                return False
            previous_value = value

        return True

    def is_balanced(self):
        tree = {'is_balanced': True}

        def _height(node):
            if not tree['is_balanced']:
                return 0

            if not node:
                return -1
            if (not node.left) and (not node.right):
                return 0

            left_height = _height(node.left)
            right_height = _height(node.right)
            if abs(left_height - right_height) > 1:
                tree['is_balanced'] = False

            return 1 + max(left_height, right_height)

        _height(self.root)
        return tree['is_balanced']

# main function
def main_solution(values):
    bst = BinarySearchTree()
    for value in values:
        bst.insert(value)

    is_valid_bst = bst.is_valid()
    is_balanced_bst = bst.is_balanced()

    return {"is_valid": is_valid_bst, "is_balanced": is_balanced_bst}

