import random

# all class and function definitions in the code file, if any
def matrix_print(matrix):
    for row in matrix:
        for elem in row:
            print(elem, end=' ')
        print()

def input_validation(user_row, user_column, matrix):
    try:
        int_row = int(user_row)
        int_column = int(user_column)
    except ValueError:
        return False

    if int_row not in range(0, 3) or int_column not in range(0, 3):
        return False

    if matrix[int_row][int_column] in ['X', '0']:
        return False

    return True

def win_validation(matrix, player):
    diagonal_counter = 0
    diagonal_sec_counter = 0
    column_counter = [0, 0, 0]
    for row_index in range(len(matrix)):
        line_counter = 0
        if matrix[row_index][row_index] == player:
            diagonal_counter += 1
        if diagonal_counter == 3:
            return True
        for column_index in range(len(matrix)):
            if matrix[row_index][column_index] == player:
                line_counter += 1
                if (row_index + column_index) == 2:
                    diagonal_sec_counter += 1
                    if diagonal_sec_counter == 3:
                        return True
                column_counter[column_index] += 1
                if column_counter[column_index] == 3:
                    return True
            else:
                line_counter = 0
        if line_counter == 3:
            return True
    return False

def check_available_positions(matrix):
    for row_index in range(len(matrix)):
        for column_index in range(len(matrix)):
            if matrix[row_index][column_index] not in ['X', '0']:
                return False
    return True

