# import necessary packages
import random

# all class and function definitions in the code file, if any
class Modulo:
    def __init__(self, max_value, invalid_value):
        self.max_value = max_value
        self.invalid_value = invalid_value

    def wrap_correction(self, value):
        if value == self.invalid_value:
            return self.max_value
        return value % (self.max_value + 1)

    def cmp(self, a, b):
        a = self.wrap_correction(a)
        b = self.wrap_correction(b)
        if a == b:
            return 0
        elif a < b:
            return -1
        else:
