            # enumerate neighbors
            if turn & 1 == 0:  # mouse's turn
                for dr, dc in DIRECTIONS:
                    for k in range(mouseJump + 1):
                        nr = mr + dr * k  # next row
                        nc = mc + dc * k  # next col

