    return math.floor(h) == h

def is_hexagonal_number(n):
    h = (math.sqrt(8*n+1)+1.0)/4.0
    return math.floor(h) == h

def triangle_numbers_between(min, max):
    lst = []
    for n in generate_triangle_numbers():
