            new_list = numbers[:]
            new_test_funcs = test_funcs[:]
            lst = find_cyclic_numbers(c, new_test_funcs, new_list)
            if lst:
                return lst
    return None

# main function
def main_solution(min_value, max_value):
    for n in triangle_numbers_between(min_value, max_value):
        for combination in itertools.permutations([
            is_square_number,
            is_pentagonal_number,
