# import necessary packages
import random
import math

# all class and function definitions in the code file, if any
class Path:
    def __init__(self, nodes, cost):
        self.nodes = nodes
        self.cost = cost

class Graph:
    def __init__(self, node_count):
        self.node_count = node_count
        self.nodes = [i for i in range(self.node_count)]
        self.adj_mat = {i: [None] * node_count for i in range(node_count)}
        self.conns = {}
        self.finalized = False

    def connect(self, a, b, cost):
        assert not self.finalized
        self.adj_mat[a][b] = cost
        self.adj_mat[b][a] = cost

    def finalize(self):
        assert not self.finalized
        self.finalized = True
        for i in range(self.node_count):
            self.conns[i] = [j for j in range(self.node_count) if i != j and self.adj_mat[i][j] is not None]
        self.shortest_paths = {}
        for n_from in range(self.node_count):
            for n_to in range(n_from + 1, self.node_count):
                path = self.find_shortest_path(n_from, n_to)
                key0 = str(n_from) + str(n_to)
                key1 = str(n_to) + str(n_from)
                self.shortest_paths[key0] = path
                path_rev = Path(path.nodes.copy(), path.cost)
                path_rev.nodes.reverse()
                self.shortest_paths[key1] = path_rev

    def cost(self, a, b):
        assert self.finalized
        return self.adj_mat[a][b]

    def find_shortest_path(self, start, end):
        assert self.finalized
        dist = {v: math.inf for v in self.nodes}
        prev = {v: None for v in self.nodes}
        dist[start] = 0
        q = self.nodes.copy()

        while q:
            u = min(q, key=lambda v: dist[v])
            q.remove(u)
            if u == end:
                break
            for v in self.conns[u]:
                alt = dist[u] + self.cost(u, v)
                if alt < dist[v]:
