# import necessary packages
from typing import List

# all class and function definitions in the code file, if any
class Solution:
    def getPrefix(self, prefix: str) -> set:
        if prefix in self.prefixHashTable:
            return self.prefixHashTable[prefix]
        else:
            return set([])

    def go(self, step: int, wordSquare: List[str], ans: List[List[str]]) -> None:
        if step == self.n:
            ans.append(wordSquare[:])
            return
        prefix = ''.join([w[step] for w in wordSquare])
        for w in self.getPrefix(prefix):
            wordSquare.append(w)
            self.go(step+1, wordSquare, ans)
            wordSquare.pop()

    def build(self, word: List[str]) -> None:
        self.prefixHashTable = {}
        for w in word:
            for prefix in (w[:i] for i in range(1, len(w))):
                self.prefixHashTable.setdefault(prefix, set()).add(w)

    def wordSquares(self, words: List[str]) -> List[List[str]]:
        self.words = words
        self.n = len(words[0])
        self.build(self.words)
        ans = []
        for w in words:
            wordSquare = [w]
            self.go(1, wordSquare, ans)
        return ans

