def get_clauses(prop_formula):
    cnf = str(to_cnf(prop_formula))
    clauses = cnf.strip().split('&')
    clauses = [clause.strip().strip('()') for clause in clauses]
    clauses_list = [clause.split('|') for clause in clauses]
    clauses_list = [[literal.strip() for literal in clause] for clause in clauses_list]

    for clause in clauses_list:
        if len(clause) > 1 and any(len(literal) == 1 for literal in clause[1:]):
