        ret = set()
        for i in range(len(self._matrice_adjacence)):
            for j in range(len(self._matrice_adjacence)):
                if self._matrice_adjacence[i][j] == 1 and j > i:
                    ret.add((i, j))
        return ret

    def boucles(self):
        ret = set()
        for i in range(len(self._matrice_adjacence)):
            if self._matrice_adjacence[i][i] == 1:
                ret.add((i, i))
        return ret

