def r(a: List[int]) -> set:
    if len(a) == 1:
        return set(a)

    if len(a) == 2:
        x, y = a[0], a[1]
        res = set([x + y, x - y, x * y])
        if y != 0:
            res.add(x / y)
        return res

    reachable = set()

    for offset in range(1, len(a)):
        rl = r(a[:offset])
        rr = r(a[offset:])

        for left in rl:
            for right in rr:
                reachable.update(r([left, right]))

    return reachable

# main function
def main_solution(numbers: List[int]) -> bool:
    # Convert the input list to a set of reachable values
    reachable = r(numbers)
    # Check if 24 is in the set of reachable values
    return 24 in reachable

