        character_index = 0
        for rail in self.rails:
            for rail_index in range(len(rail)):
                if rail[rail_index] == '?':
                    rail[rail_index] = text[character_index]
                    character_index += 1

    def _get_plaintext_from_rails(self, length):
        plaintext = ""
