import math

# all class and function definitions in the code file, if any
# they will be used in the main_solution function, you may need to modify them to meet the requirements of the main_solution function (optional)
class Linear():
    def __init__(self, m, b):
        self.m = m
        self.b = b

    def evaluate(self, x):
        return self.m * x + self.b

    def angle(self):
        return math.atan2(self.m, 1)

class Quadratic():
    def __init__(self, a, b, c):
        self.a = a
        self.b = b
        self.c = c
        if self.a == 0:
            self.a = 0.00000000000001

    def evaluate(self, x):
        return (self.a * x ** 2 + self.b * x + self.c)

    def vertex(self):
        x = -self.b / (2 * self.a)
        y = self.a * x**2 + self.b * x + self.c
        return (x, y)

    def roots(self):
        if (self.b**2 - 4 * self.a * self.c) < 0:
            return []
        solutions = set()
        solutions.add((-self.b + math.sqrt(self.b**2 - 4 * self.a * self.c)) / (self.a * 2))
        solutions.add((-self.b - math.sqrt(self.b**2 - 4 * self.a * self.c)) / (self.a * 2))
        return solutions

class QuadraticBezier():
    def __init__(self, P0, P1, P2):
        self.P0 = P0
        self.P1 = P1
        self.P2 = P2

    def evaluate(self, t):
        x = math.pow(1-t, 2) * self.P0[0] + 2*(1-t)*t*self.P1[0] + math.pow(t, 2) * self.P2[0]
        y = math.pow(1-t, 2) * self.P0[1] + 2*(1-t)*t*self.P1[1] + math.pow(t, 2) * self.P2[1]
        return (x, y)

    def solve(self, pt):
        (x, y) = pt
        quadx = Quadratic(self.P0[0] - 2*self.P1[0] + self.P2[0], -2 * self.P0[0] + 2 * self.P1[0], self.P0[0] - x)
        quady = Quadratic(self.P0[1] - 2*self.P1[1] + self.P2[1], -2 * self.P0[1] + 2 * self.P1[1], self.P0[1] - y)
        rootx = quadx.roots()
        rooty = quady.roots()
        solutions = set()
        for root in rootx:
            if root in rooty and 0 <= root <= 1:
                solutions.add(root)
        return solutions

