    temp_quad = Quadratic(quad.a, quad.b - line.m, quad.c - line.b)
    roots = temp_quad.roots()
    if roots == []:
        return None
    int_pts = set()
    for root in roots:
        int_pts.add((root, quad.evaluate(root)))
    return int_pts

