    return result

def is_multi_subset(A, B):
    for elem in A:
        if A.count(elem) > B.count(elem):
            return False
    return True

def difference(A, B):
    diffset = []
    all_elems = set(A)
    for elem in all_elems:
        n = A.count(elem) - B.count(elem)
        if n > 0:
            for _ in range(n):
                diffset.append(elem)
    diffset.sort()
    return diffset

def Place(dist_l, X, width):
    if not dist_l:
        return X

    y = dist_l[-1]
    # place on left
    tmp = delta2({y}, X)
    if is_multi_subset(tmp, dist_l):
        X.add(y)
        L_left = difference(dist_l, tmp)
        res_left = Place(L_left, X, width)
        if res_left:
            return res_left
        X.remove(y)

    # place on right
    tmp = delta2({width - y}, X)
