# import necessary packages
import math
from random import randint

# all class and function definitions in the code file, if any
def LSB_one(n):
    #find the least significant one bit
    for i in range(n):
        if (n >> i) & 1 == 1:
            return i

def miller_rabin(n):
    if n == 2 or n == 3:
        return True
    a = randint(2, n - 1)
    k = LSB_one(n - 1)
    q = (n - 1) >> k
    x = pow(a, q, n)
    if x == 1 or x == n - 1:
        return True
    for j in range(k - 1):
        x = pow(x, 2, n)
        if x == n - 1:
            return True
    return False

