# import necessary packages
import json

# all class and function definitions in the code file, if any
class TreeNode:
    def __init__(self, x):
        self.val = x
        self.left = None
        self.right = None

class Solution:
    def isSymmetrical(self, pRoot):
        if pRoot is None:
            return True
        return self.checkMetrical(pRoot.left, pRoot.right)

    def checkMetrical(self, node_left, node_right):
        if node_left is None and node_right is None:
            return True
        if node_left is None or node_right is None:
            return False
        if node_right.val != node_left.val:
            return False
        return self.checkMetrical(node_left.left, node_right.right) \
               and self.checkMetrical(node_left.right, node_right.left)

# main function
def main_solution(tree_structure):
    # Convert the JSON serializable input to the original input variables
    def build_tree(node_list):
        if not node_list:
            return None
        nodes = [TreeNode(val) if val is not None else None for val in node_list]
        n = len(nodes)
        for i in range(n):
            if nodes[i] is not None:
                left_index = 2 * i + 1
                right_index = 2 * i + 2
                if left_index < n:
                    nodes[i].left = nodes[left_index]
                if right_index < n:
                    nodes[i].right = nodes[right_index]
        return nodes[0]

    root = build_tree(tree_structure)
    solution = Solution()
    result = solution.isSymmetrical(root)

    # Convert the result to a JSON serializable output
    return result

