# Function to determine the initial state of the board
def initial_state():
    return [[EMPTY, EMPTY, EMPTY],
            [EMPTY, EMPTY, EMPTY],
            [EMPTY, EMPTY, EMPTY]]

# Function to determine the next player
def player(board):
    count = sum(1 for row in board for status in row if status != EMPTY)
    return X if count % 2 == 0 else O

# Function to get all possible actions on the board
def actions(board):
    return {(i, j) for i, row in enumerate(board) for j, status in enumerate(row) if status == EMPTY}

# Function to get the result of an action on the board
def result(board, action):
    cloneBoard = copy.deepcopy(board)
    cloneBoard[action[0]][action[1]] = player(board)
    return cloneBoard

# Function to determine the winner of the game
def winner(board):
    possibilities = (
        ((0, 0), (0, 1), (0, 2)), # Rows
        ((1, 0), (1, 1), (1, 2)), 
        ((2, 0), (2, 1), (2, 2)), 
        ((0, 0), (1, 0), (2, 0)), # Columns
        ((0, 1), (1, 1), (2, 1)), 
        ((0, 2), (1, 2), (2, 2)), 
        ((0, 0), (1, 1), (2, 2)), # Diagonals
        ((0, 2), (1, 1), (2, 0))  
    )
    for row in possibilities:
        if all(board[i][j] == X for i, j in row):
            return X
        if all(board[i][j] == O for i, j in row):
            return O
    return None

# Function to check if the game is over
def terminal(board):
    return winner(board) is not None or all(status != EMPTY for row in board for status in row)

# Function to get the utility of the board
def utility(board):
    return 1 if winner(board) == X else -1 if winner(board) == O else 0

# Function to get the minimum value of the board
def min_value(board):
    if terminal(board):
        return utility(board), ()
    v = math.inf
    move = None
    for action in actions(board):
        aux, _ = max_value(result(board, action))
        if aux < v:
            v = aux
            move = action
            if v == -1:
