# Global lists to store fair and square numbers
fair = []
square = []

# Function to initialize the fair and square arrays up to a given limit
def initialize_array(limit):
    i = 1
    while i < limit:
        fair.append(i)
        value = i * i
        if isPalindrome(value):
            square.append(value)
        i = getNextPalindrome(str(i))

# Function to increment the value and handle carry
def increment(value, carry, newP):
    value += carry
    if value == 10:
        newP = newP + "0"
        return (1, newP)
    else:
        newP = newP + str(value)
        return (0, newP)

# Function to get the next palindrome number
def getNextPalindrome(prev):
    if len(prev) == 1:
        if prev == "9":
            return 11
        else:
            return int(prev) + 1

    search = re.compile(r'[^9]').search
    if not bool(search(prev)):
        middle = "0" * (len(prev) - 1)
        return int("1" + middle + "1")

    middle = len(prev) // 2
    newP = ""
    carry = 1
    for i in range(middle, len(prev)):
        carry, newP = increment(int(prev[i]), carry, newP)
    if len(prev) % 2 == 0:
        return int(newP[::-1] + newP)
    return int(newP[:0:-1] + newP)

# Function to check if a number is a palindrome
def isPalindrome(value):
    digits = str(value)
    return digits == digits[::-1]

# Function to find the number of palindromes within a given range
def numPalindromes(A, B):
