from abc import ABC, abstractmethod
from typing import Any, Tuple
import random

# all class and function definitions in the code file, if any
class AbstractDomain(ABC):
    """
    Base class to define an Abstract Domain.
    An object from an Abstract Domain is an element from a lattice, therefore the abstract
    domain must define a Lattice structure with its order relation, and top and bottom
    values.
    Additional operations to the Lattice are:
    - Join
    - Merge
    - Widening Operator (optional)
    - Narrowing Operator (optional)
    """

    @classmethod
    @abstractmethod
    def top(cls) -> Any:
        """Returns the Top element from the lattice"""
        raise NotImplementedError()

    @abstractmethod
    def is_top(self) -> bool:
        """Returns True if this object is the top of the lattice"""
        raise NotImplementedError()

    @abstractmethod
    def join(self, other: Any) -> Any:
        """Performs 'Least Upper Bound' operation between self and other"""
        raise NotImplementedError()

    def widen_op(self, other: Any) -> 'Tuple[Any, bool]':
        """Performs the Widen operation on self and other"""
        raise NotImplementedError()

    def narrow_op(self, other: Any) -> 'Tuple[Any, bool]':
        """Performs the Narrow operation on self and other"""
        raise NotImplementedError()

    def __bool__(self) -> bool:
        """This prevents to use any Abstract Domain as a boolean."""
        raise ValueError("Why am I being used as a bool!!")

class SimpleDomain(AbstractDomain):
    def __init__(self, value: int):
        self.value = value

    @classmethod
    def top(cls) -> Any:
        return cls(float('inf'))

    def is_top(self) -> bool:
        return self.value == float('inf')

    def join(self, other: Any) -> Any:
        return SimpleDomain(max(self.value, other.value))

    def widen_op(self, other: Any) -> 'Tuple[Any, bool]':
        if other.value > self.value:
            return SimpleDomain(float('inf')), True
        return self, False

    def narrow_op(self, other: Any) -> 'Tuple[Any, bool]':
        if self.value == float('inf'):
            return other, True
        return self, False

# main function
def main_solution(value1: int, value2: int) -> bool:
    """
    Determines if the join of two SimpleDomain objects results in the top element of the lattice.

    Args:
        value1 (int): The value of the first SimpleDomain object.
        value2 (int): The value of the second SimpleDomain object.

    Returns:
        bool: True if the join results in the top element, False otherwise.
    """
    domain1 = SimpleDomain(value1)
    domain2 = SimpleDomain(value2)
    result = domain1.join(domain2)
    return result.is_top()

