# import necessary packages
import random

# all class and function definitions in the code file, if any
class BTree:
    '''A Binary Tree.'''

    def __init__(self, node=None):
        '''Init a BTree rooted at node.'''
        self._root = node

    def is_bst(self):
        '''Return True iff this BTree is a binary search tree. Use < for node comparison.'''
        return _is_bst(self._root)

    def preorder(self):
        '''Return a list of values in this BTree, corresponding to a pre-order traversal.'''
        return _preorder(self._root)

    def inorder(self):
        '''Return a list of values in this BTree, corresponding to an in-order traversal.'''
        return _inorder(self._root)

    def postorder(self):
        '''Return a list of values in this BTree, corresponding to a post-order traversal.'''
        return _postorder(self._root)

    def size(self):
        '''Return the number of nodes in this BTree.'''
        return _size(self._root)

    def height(self):
        '''Return the height of this BTree: the number of nodes on the longest root-to-leaf path.'''
        return _height(self._root)

    def fringe(self):
        '''Return a list of leaves in this BTree, in left-to-right order.'''
        return _fringe(self._root)

class BTNode:
    '''A node in a BTree.'''

    def __init__(self, value, left=None, right=None):
        '''Init a BTNode with value value, left child left, and right child right.'''
        self.value = value
        self.left = left
        self.right = right

    def __lt__(self, other):
        '''Return whether the value in this BTNode is less than the value in BTNode other.'''
        return self.value < other.value

    def __eq__(self, other):
        '''Return whether the value in this BTNode is equal the value in BTNode other.'''
        return self.value == other.value

def _preorder(node):
    '''Return a list of values in a BTree rooted at node, corresponding to a pre-order traversal.'''
    if node is None:
        return []
    return [node.value] + _preorder(node.left) + _preorder(node.right)

def _inorder(node):
    '''Return a list of values in a BTree rooted at node, corresponding to a in-order traversal.'''
    if node is None:
        return []
    return _inorder(node.left) + [node.value] + _inorder(node.right)

def _postorder(node):
    '''Return a list of values in a BTree rooted at node, corresponding to a post-order traversal.'''
    if node is None:
        return []
    return _postorder(node.left) + _postorder(node.right) + [node.value]

def _is_bst(node):
    '''Return True iff the BTree rooted at node is a binary search tree. Use Python's < for node comparison.'''
    if node is None:
        return True
    if _is_bst(node.left) and _is_bst(node.right):
        return ((node.left is None or node > node.left) and
                (node.right is None or node < node.right))
    return False

def _size(node):
    '''Return the number of nodes in the BTree rooted at node.'''
    if node is None:
        return 0
    return 1 + _size(node.left) + _size(node.right)

def _fringe(node):
    '''Return a list of leaves in the BTree rooted at node, in left-to-right order.'''
    if node is None:
        return []
    if (node.left is None) and (node.right is None):
        return [node.value]
    return _fringe(node.left) + _fringe(node.right)

def _height(node):
    '''Return the height of the BTree rooted at node: the number of nodes on the longest root-to-leaf path.'''
    if node is None:
        return 0
    return 1 + max(_height(node.left), _height(node.right))

# main function
def main_solution(tree_structure):
    '''
    Given a tree structure in the form of nested dictionaries, this function constructs a Binary Tree and returns its properties.

    Input:
    - tree_structure (dict): A nested dictionary representing the structure of the binary tree.
      The dictionary should have keys 'value', 'left', and 'right'. 'value' is the value of the node,
      'left' and 'right' are either None or another dictionary representing the left and right children.

    Output:
    - dict: A dictionary containing the following keys:
      - 'is_bst' (bool): True if the tree is a Binary Search Tree, False otherwise.
      - 'preorder' (list): List of values in pre-order traversal.
      - 'inorder' (list): List of values in in-order traversal.
      - 'postorder' (list): List of values in post-order traversal.
      - 'size' (int): Number of nodes in the tree.
      - 'height' (int): Height of the tree.
      - 'fringe' (list): List of leaf nodes in left-to-right order.
    '''
    def build_tree(structure):
        if structure is None:
            return None
        return BTNode(structure['value'], build_tree(structure['left']), build_tree(structure['right']))

    tree = BTree(build_tree(tree_structure))

    return {
        'is_bst': tree.is_bst(),
        'preorder': tree.preorder(),
        'inorder': tree.inorder(),
        'postorder': tree.postorder(),
        'size': tree.size(),
        'height': tree.height(),
        'fringe': tree.fringe()
    }

