class Player:
    def __init__(self, name):
        self.name = name

class Historian(Player):
    def __init__(self, name, memory):
        Player.__init__(self, name)
        self.memory = memory
        self.history = []

    def choose_action(self):
        count = [0, 0, 0]
        winningAction = [2, 0, 1]

        if self.memory > len(self.history):
            return random.randint(0, 2)
        else:
            last = self.history[-self.memory:]
            for i in range(0, len(self.history) - self.memory):
                if last == self.history[i:i + self.memory]:
                    if self.history[(i + self.memory)] is None:
                        count[2] += 1
                    else:
                        count[self.history[(i + self.memory)]] += 1
            return winningAction[count.index(max(count))]

    def receive_result(self, game):
        self.history.append(game.a2 if game.p1 == self else game.a1)

# main function
