FUNC_DICT = {
    '*': lambda x, y: x * y,
    '+': lambda x, y: x + y,
    '-': lambda x, y: x - y,
    '/': lambda x, y: x / y,
    '<': lambda x, y: x < y,
    '>': lambda x, y: x > y,
    'eq': lambda x, y: x == y,
    'dif': lambda x, y: x != y,
    '>=': lambda x, y: x >= y,
    '<=': lambda x, y: x <= y,
    'sqrt': sqrt,
    'cos': cos,
    'sin': sin
