def swapRows(A, row1, row2):
    A[row1], A[row2] = A[row2], A[row1]

def Row_Transformation(A, x, row1, row2):
    for i in range(len(A[0])):
        A[row2][i] -= x * A[row1][i]

def RREFMatrix(A):
    if not A:
        return
    leading = 0
    Nrows = len(A)
    Ncols = len(A[0])
    for t in range(Nrows):
        if leading >= Ncols:
            return
        x = t
        while A[x][leading] == 0:
            x += 1
            if x == Nrows:
