        A[t] = [a / float(r) for a in A[t]]
        for x in range(Nrows):
            if x != t:
                r = A[x][leading]
                Row_Transformation(A, r, t, x)
        leading += 1

def MatrixRank(A):
    rank = 0
    for t in range(len(A)):
        for i in range(len(A[0])):
            if A[t][i] == 1 and i >= t:
                rank += 1
                break
    return rank

