class Syntax(object):
    def __repr__(self):
        return '<<{}>>'.format(self)

class Number(Syntax):
    def __init__(self, value):
        self.value = value

    @property
    def is_reducible(self):
        return False

    def __str__(self):
        return str(self.value)

