    # Convert JSON serializable inputs to original input variables
    program = tokenize(program)
    try:
        program = parse_program(program)
    except ValueError as e:
        return {"error": f"Syntax error at line {e.args[0]['line']}"}

    user_input = [int(val) for val in user_input]
    user_input.reverse()

