# import necessary packages
import copy
import math
import random

# Constants
X = "X"
O = "O"
EMPTY = None

# all class and function definitions in the code file, if any
def initial_state():
    """
    Returns starting state of the board.
    """
    return [[EMPTY, EMPTY, EMPTY],
            [EMPTY, EMPTY, EMPTY],
            [EMPTY, EMPTY, EMPTY]]

def player(board):
    """
    Returns player who has the next turn on a board.
    """
    count_x = sum(row.count(X) for row in board)
    count_o = sum(row.count(O) for row in board)
    return X if count_x == count_o else O

def actions(board):
    """
    Returns set of all possible actions (i, j) available on the board.
    """
    return {(i, j) for i in range(3) for j in range(3) if board[i][j] == EMPTY}

def result(board, action):
    """
    Returns the board that results from making move (i, j) on the board.
    """
    if action not in actions(board):
        raise Exception("This action is not valid")
    new_board = copy.deepcopy(board)
    new_board[action[0]][action[1]] = player(board)
    return new_board

def winner(board):
    """
    Returns the winner of the game, if there is one.
    """
    players = [X, O]
    for player_sign in players:
        if any(all(board[row][col] == player_sign for col in range(3)) for row in range(3)):
            return player_sign
        if any(all(board[row][col] == player_sign for row in range(3)) for col in range(3)):
            return player_sign
        if all(board[i][i] == player_sign for i in range(3)):
            return player_sign
        if all(board[i][2 - i] == player_sign for i in range(3)):
            return player_sign
    return None

def terminal(board):
    """
    Returns True if game is over, False otherwise.
    """
    return winner(board) in (X, O) or not actions(board)

def utility(board):
    """
    Returns 1 if X has won the game, -1 if O has won, 0 otherwise.
    """
    if winner(board) == X:
        return 1
    elif winner(board) == O:
        return -1
    else:
        return 0

def minimax(board):
    """
    Returns the optimal action for the current player on the board.
    """
    if terminal(board):
        return None
    if player(board) == X:
        best_value = -math.inf
        best_action = None
        for action in actions(board):
            action_value = min_value(result(board, action))
            if action_value > best_value:
                best_value = action_value
                best_action = action
                if best_value == 1:
                    break
    else:
        best_value = math.inf
        best_action = None
        for action in actions(board):
            action_value = max_value(result(board, action))
            if action_value < best_value:
                best_value = action_value
                best_action = action
                if best_value == -1:
                    break
    return best_action

def min_value(board):
    """
    Returns the lowest value
    """
    if terminal(board):
        return utility(board)
    v = math.inf
    for action in actions(board):
        v = min(v, max_value(result(board, action)))
    return v

def max_value(board):
    """
    Returns the highest value
    """
    if terminal(board):
        return utility(board)
    v = -math.inf
    for action in actions(board):
        v = max(v, min_value(result(board, action)))
    return v

# main function
def main_solution(board):
    """
    Returns the optimal action for the current player on the board.
    """
    # Convert the board to a JSON serializable format
    board_serializable = [[cell if cell is not None else "" for cell in row] for row in board]

    # Get the optimal action
    optimal_action = minimax(board)

    # Convert the optimal action to a JSON serializable format
    if optimal_action is None:
        return None
    else:
        return {"row": optimal_action[0], "col": optimal_action[1]}

