    global DICTIONARY
    global PREFIXES

    DICTIONARY = set()
    # Simulate loading from a file
    words = ["apple", "app", "apricot", "banana", "bat", "cat", "caterpillar", "dog", "dogged", "devious", "elephant", "egg", "fish", "frog", "goat", "grape", "hat", "horse", "iguana", "ink", "jelly", "kite", "lemon", "mango", "nut", "orange", "pear", "quail", "rabbit", "snake", "tiger", "umbrella", "violin", "whale", "xylophone", "yak", "zebra"]
    for word in words:
