import math

# main function
def main_solution(num):
    # Convert the input to an integer
    num = int(num)

    # Generate a list of prime numbers up to num
    ss_num = [2]
    for i in range(3, num):
        for j in range(2, int(math.sqrt(i)) + 1):
            if i % j == 0:
                break
        else:
            ss_num.append(i)

    # Find three prime numbers that sum up to num
    no = num // 3 + 2
    no2 = 0.7 * num + 2
    result = None

    try:
        for i in ss_num:
            if i >= no:
                continue
            for j in ss_num:
                if (i + j) >= no2:
                    continue
                k = num - i - j
                if k in ss_num:
                    result = (i, j, k)
                    raise StopIteration
    except StopIteration:
        pass

    # Return the result as a tuple
    return result

