                    raise ValueError('element is zero', k)
                l = A[j][k] / A[k][k]
                L[j][k] = l
                for m in range(k, n):
                    A[j][m] = A[j][m] - l * A[k][m]

        Y = [0 for i in range(n)]  # forward substitution
        for i in range(n):
