# import necessary packages
from collections import deque
from itertools import repeat, product

# all class and function definitions in the code file, if any
class Grid:
    def __init__(self, heights):
        self.heights = heights

    @classmethod
    def parse(cls, lines):
        heights = []
        for y, line in enumerate(lines):
            if (x := line.find("S")) >= 0:
                position = x, y
            if (x := line.find("E")) >= 0:
                target = x, y

            line = line.replace("S", "a").replace("E", "z")
            heights.append([ord(c) - ord("a") for c in line])

        return cls(heights), position, target

    def __str__(self):
        grid = [[chr(ord("a") + h) for h in row] for row in self.heights]
        return "\n".join(map("".join, grid))

    def neighbors(self, position):
        x, y = position
        if x > 0:
            yield x - 1, y
        if x < len(self.heights[0]) - 1:
            yield x + 1, y
        if y > 0:
            yield x, y - 1
        if y < len(self.heights) - 1:
            yield x, y + 1

    def __getitem__(self, idx):
        x, y = idx
        return self.heights[y][x]

    def __iter__(self):
        return product(range(len(self.heights[0])), range(len(self.heights)))


def search(grid, position, targets, reverse=False):
    queue = deque([(position, 0)])
    seen = set()

    while queue:
        position, length = queue.pop()
        if position in targets:
            return length
        if position in seen:
            continue
        seen.add(position)
        neighbors = grid.neighbors(position)
        if not reverse:
            neighbors = filter(lambda n: grid[n] <= grid[position] + 1, neighbors)
        else:
            neighbors = filter(lambda n: grid[n] >= grid[position] - 1, neighbors)

        queue.extendleft(zip(neighbors, repeat(length + 1)))


# main function
def main_solution(grid_lines):
    # Convert the input list of strings to a Grid object and get the start and end positions
    grid, start_position, end_position = Grid.parse(grid_lines)

    # Perform the search from the start position to the end position
    part1_result = search(grid, start_position, {end_position})

    # Perform the reverse search from the end position to any 'a' height position
    lows = set(filter(lambda pos: grid[pos] == 0, grid))
    part2_result = search(grid, end_position, lows, reverse=True)

    # Return the results as a dictionary
    return {"part1_result": part1_result, "part2_result": part2_result}

