            if dummyplayer == self.player:
                if score > alpha:
                    alpha = score
                if alpha >= beta:
                    return beta
            else:
                if score < beta:
                    beta = score
                if beta <= alpha:
                    return alpha
        if dummyplayer == self.player:
            return alpha
        else:
            return beta
    def makemove(self, state):
        a = -2
        moves = []
