# import necessary packages
import random

# all class and function definitions in the code file, if any
class Node(object):
    def __init__(self, name):
        self.name = name

    def getName(self):
        return self.name

    def __str__(self):
        return self.name

class Edge(object):
    def __init__(self, src, dest):
        self.source = src
        self.destination = dest

    def getSource(self):
        return self.source

    def getDestination(self):
        return self.destination

    def __str__(self):
        return self.source.getName() + " ---> " + self.destination.getName()

class Digraph(object):
    def __init__(self):
        self.edges = {}

    def addNode(self, node):
        if node in self.edges:
            raise ValueError("Duplicate node")
        else:
            self.edges[node] = []

    def addEdge(self, edge):
        src = edge.getSource()
        dest = edge.getDestination()
        if not (src in self.edges and dest in self.edges):
            raise ValueError("Node not in graph")
        self.edges[src].append(dest)

    def getChildren(self, node):
        return self.edges[node]

    def hasNode(self, node):
        return node in self.edges

    def getNode(self, name):
        for n in self.edges:
            if n.getName() == name:
                return n
        raise NameError(name)

    def __str__(self):
        result = ""
        for src in self.edges:
            for dest in self.edges[src]:
                result += src.getName() + " ---> " + dest.getName() + "\n"
        return result[:-1]

class Graph(Digraph):
    def addEdge(self, edge):
        Digraph.addEdge(self, edge)
        rev = Edge(edge.getDestination(), edge.getSource())
        Digraph.addEdge(self, rev)

def buildCityGraph(graphType):
    g = graphType()
    for name in ('Boston', 'Providence', 'New York', 'Chicago', 'Denver', 'Phoenix', 'Los Angeles'):
        g.addNode(Node(name))
    g.addEdge(Edge(g.getNode('Boston'), g.getNode('Providence')))
    g.addEdge(Edge(g.getNode('Boston'), g.getNode('New York')))
    g.addEdge(Edge(g.getNode('Providence'), g.getNode('Boston')))
    g.addEdge(Edge(g.getNode('Providence'), g.getNode('New York')))
    g.addEdge(Edge(g.getNode('New York'), g.getNode('Chicago')))
    g.addEdge(Edge(g.getNode('Chicago'), g.getNode('Denver')))
    g.addEdge(Edge(g.getNode('Denver'), g.getNode('Phoenix')))
    g.addEdge(Edge(g.getNode('Denver'), g.getNode('New York')))
    g.addEdge(Edge(g.getNode('Chicago'), g.getNode('Phoenix')))
    g.addEdge(Edge(g.getNode('Los Angeles'), g.getNode('Boston')))
    return g

def dfs(graph, start, end, path, shortest):
    path = path + [start]
    if start == end:
        return path
    for node in graph.getChildren(start):
        if node not in path:
            if shortest is None or len(path) < len(shortest):
                newPath = dfs(graph, node, end, path, shortest)
                if newPath is not None:
                    shortest = newPath
    return shortest

def shortestPath(graph, start, end):
    return dfs(graph, start, end, [], None)

def printPath(path):
    result = ''
    for i in range(len(path)):
        result += path[i].getName()
        if i != len(path) - 1:
            result += " ---> "
    return result

# main function
def main_solution(graphType, startCity, endCity):
    # Convert JSON serializable inputs to original input variables
    graphType = Digraph if graphType == "Digraph" else Graph
    startCity = Node(startCity)
    endCity = Node(endCity)

    # Build the graph
    g = buildCityGraph(graphType)

    # Find the shortest path
    path = shortestPath(g, g.getNode(startCity.getName()), g.getNode(endCity.getName()))

    # Convert the result to JSON serializable output
    if path is None:
        return "No path found"
    else:
        return printPath(path)

