# import necessary packages
from math import factorial

# all class and function definitions in the code file, if any
def binomial(n: int, r: int) -> int:
    """
    Binomial coefficient, nCr, aka the "choose" function
    n! / (r! * (n - r)!)
    """
    if 0 > r or n < r:
        return 0
    p = 1    
    for i in range(1, min(r, n - r) + 1):
        p *= n
        p //= i
        n -= 1
    return p

def permutations(S: list) -> list:
    """
    Generates all permutations of the input list S
    @input : a list of elements S
    @output : a list of all permutations of the list S
    """
    if len(S) == 0:
        return [[]]
    if len(S) == 1:
        return [S]
    all_perms = []
    for i in range(len(S)):
        m = S[i]
        rem_list = S[:i] + S[i+1:]
        for p in permutations(rem_list):
            all_perms.append([m] + p)
    return all_perms

def powerset(S: list) -> list:
    """
    Returns the powerset of the input list S
    @input : a list of elements S
    @output : the powerset of S
    """
    if len(S) == 0:
        return [[]]
    ps = powerset(S[1:])
    return ps + [[S[0]] + x for x in ps]

def subsets(S: list, k: int) -> list:
    """
    Generates all subsets T of the list S that have 
    cardinality k. 

    @input : a list of elements S
    @output : a list of all subsets of S with cardinality k
    """
    if k > len(S) or k < 0:
        raise Exception('must have 0<=k<=|S|, got k : ', k, 'and |S|', len(S))
    if k == 0:
        return [[]]
    if k == len(S):
        return [S]
    with_first = [[S[0]] + x for x in subsets(S[1:], k-1)]
    without_first = subsets(S[1:], k)
    return with_first + without_first

# main function
def main_solution(elements: list, operation: str) -> list:
    """
    Performs a specified combinatorial operation on a list of elements.

    @input elements: list of elements to perform the operation on.
    @input operation: string specifying the operation to perform. Can be "permutations", "powerset", or "subsets".
    @output: list of results from the specified operation.
    """
    if operation == "permutations":
        result = permutations(elements)
    elif operation == "powerset":
        result = powerset(elements)
    elif operation == "subsets":
        result = subsets(elements, 2)  # Default to subsets of size 2 for simplicity
    else:
        raise ValueError("Invalid operation specified. Choose from 'permutations', 'powerset', or 'subsets'.")

    return result

