# import necessary packages
import random

# all class and function definitions in the code file, if any
class Tree:
    def __init__(self, label, children=[]):
        self.label = label
        self.children = children

    def __str__(self):
        s = self.label
        for c in self.children:
            s += ' ( ' + str(c) + ' ) '
        return s

    def get_leaves(self):
        li = []
        for i in self.children:
            li.extend(i.get_leaves())
        if len(self.children) == 0:
            li.append(self.label)
        return li

    def get_productions(self):
        li = []
        if len(self.children) != 0:
            li1 = []
            for i in self.children:
                li1.append(i.label)
            li.append((self.label, li1))
        for i in self.children:
            li.extend(i.get_productions())
        return li

def read_grammar(lines):
    li = []
    for i in lines:
        l_x = i.split(':-')
        l_x[1] = l_x[1].split()
        li.append((l_x[0].strip(), l_x[1]))
    return li

def is_pos(rule, rules):
    pos = [i[0] for i in rules]
    for j in rule[1]:
        if j in pos:
            return False
    return True

def is_valid_production(production, rules):
    li = [i for i in rules if i[0] == production[0]]
    for j in li:
        if production[1] == j[1]:
            return True
        if is_pos(j, rules):
            if production[1][0] in j[1]:
                return True
    return False

def is_valid_tree(tree, rules, words):
    a = tree.get_leaves()
    if a != words:
        return False
    b = tree.get_productions()
    for i in b:
        if not is_valid_production(i, rules):
            return False
    return True

# main function
def main_solution(grammar_lines, sentence):
    """
    Validates if a given parse tree is a valid parse of a sentence according to a provided grammar.

    Args:
        grammar_lines (list of str): A list of strings representing the CFG rules.
        sentence (list of str): A list of strings representing the sentence to be parsed.

    Returns:
        bool: True if the parse tree is valid, False otherwise.
    """
    rules = read_grammar(grammar_lines)
    tree = Tree('S', [Tree('NP', [Tree('N', [Tree('dog')])]), Tree('VP', [Tree('V', [Tree('runs')])])])
    return is_valid_tree(tree, rules, sentence)

