# import necessary packages
import numpy as np

# all class and function definitions in the code file, if any
def checkeq(lst):
    if (lst[1:] == lst[:-1]):
        return 1
    else:
        return 0

def getlowest(lst):
    n = len(lst)
    flippedlist = lst[::-1]
    for i in range(n):
        if flippedlist[i] == "-":
            return n - i

def flip(lst):
    lowest = getlowest(lst) - 1
    for i in range(lowest + 1):
        if lst[i] == "-":
            lst[i] = "+"
        elif lst[i] == "+":
            lst[i] = "-"
    return lst

# main function
def main_solution(pancake_order):
    # Convert the input string to a list of characters
    orderlist = list(pancake_order)

    # Check if all pancakes are already happy
    if checkeq(orderlist) == 1:
        if orderlist[0] == "-":
            return 1
        else:
            return 0

    # Execute flips until all pancakes are happy
    movecount = 0
    while checkeq(orderlist) == 0:
        flip(orderlist)
        movecount += 1

    return movecount

