# import necessary packages
import random

# all class and function definitions in the code file, if any
class SquareMatrix:
    _min_value = -5
    _max_value = 5
    _max_size = 12

    def __init__(self, size):
        assert (1 <= size <= self._max_size)
        self.size = size
        self.matrix = [[0 for _ in range(size)] for _ in range(size)]

    def fill_from(self, list_of_lists):
        for i, row in enumerate(list_of_lists):
            if i >= self.size:
                break
            for j, element in enumerate(row):
                if j >= self.size:
                    break
                assert (self._min_value <= element <= self._max_value)
                self.matrix[i][j] = element

    def determinant(self, matrix=None, sign=1):
        if matrix is None:
            return self.determinant(matrix=self.matrix)

        size = len(matrix)
        if size == 1:
            return sign * matrix[0][0]

        if self.is_null_column(1, matrix):
            return 0

        edited_matrix = self.copy(matrix)

        if edited_matrix[0][0] == 0:
            for i in range(1, size):
                if edited_matrix[i][0] != 0:
                    self.swap_rows(1, i+1, edited_matrix)
                    sign *= -1
                    break

        first_element = edited_matrix[0][0]
        assert (first_element != 0)

        for i in range(1, size):
            coefficient = edited_matrix[i][0] / first_element
            for j in range(size):
                edited_matrix[i][j] -= coefficient * edited_matrix[0][j]

        sliced_matrix = self.get_slice(1, 1, edited_matrix)
        return edited_matrix[0][0] * self.determinant(sliced_matrix, sign)

    def swap_rows(self, r1, r2, matrix=None):
        if matrix is None:
            matrix = self.matrix
        r1 -= 1; r2 -= 1
        matrix[r1], matrix[r2] = matrix[r2], matrix[r1]

    def get_size(self, matrix=None):
        if matrix is None:
            matrix = self.matrix
        return len(matrix)

    def copy(self, matrix=None):
        if matrix is None:
            matrix = self.matrix
        return [row[:] for row in matrix]

    def get_slice(self, row=1, column=1, matrix=None):
        if matrix is None:
            matrix = self.matrix
        row -= 1; column -= 1
        return [matrix[i][column+1:] for i in range(row+1, len(matrix))]

    def is_null_column(self, column, matrix=None):
        if matrix is None:
            matrix = self.matrix
        column -= 1
        return all(row[column] == 0 for row in matrix)

# main function
def main_solution(matrix_size, matrix_elements):
    matrix = SquareMatrix(matrix_size)
    matrix.fill_from(matrix_elements)
    determinant = matrix.determinant()
    return determinant

