# import necessary packages
from collections import deque
import random

# all class and function definitions in the code file, if any
class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class Animal:
    def __init__(self, name, timestamp):
        self.name = name
        self.timestamp = timestamp

class Dog(Animal):
    def __init__(self, name, timestamp):
        super().__init__(name, timestamp)

class Cat(Animal):
    def __init__(self, name, timestamp):
        super().__init__(name, timestamp)

class AnimalSortedLinkedList:
    def __init__(self):
        self.first = None

    def add(self, data):
        node = Node(data)
        if self.first is None:
            self.first = node
            return
        if data.timestamp < self.first.data.timestamp:
            node.next = self.first
            self.first = node
            return
        current_node = self.first
        while current_node.next is not None and current_node.next.data.timestamp < data.timestamp:
            current_node = current_node.next
        node.next = current_node.next
        current_node.next = node

    def remove_first(self):
        if self.first is None:
            raise Exception("List empty")
        aux = self.first
        self.first = self.first.next
        return aux.data

class AnimalShelter:
