        self.dogs_list = AnimalSortedLinkedList()
        self.cats_list = AnimalSortedLinkedList()

    def enqueue(self, new_entry):
        if isinstance(new_entry, Dog):
            self.dogs_list.add(new_entry)
        else:
            self.cats_list.add(new_entry)

    def dequeue_dog(self):
        return self.dogs_list.remove_first()

    def dequeue_cat(self):
        return self.cats_list.remove_first()

    def dequeue_any(self):
        if self.dogs_list.first.data.timestamp < self.cats_list.first.data.timestamp:
            return self.dequeue_dog()
        else:
            return self.dequeue_cat()

# main function
def main_solution(animal_type, names, timestamps):
    shelter = AnimalShelter()
    animals = []
    for name, timestamp in zip(names, timestamps):
        if animal_type == "dog":
            animals.append(Dog(name, timestamp))
        else:
            animals.append(Cat(name, timestamp))

    for animal in animals:
        shelter.enqueue(animal)

    if animal_type == "dog":
        adopted_animal = shelter.dequeue_dog()
    else:
        adopted_animal = shelter.dequeue_cat()

    return {"name": adopted_animal.name, "timestamp": adopted_animal.timestamp}

