from functools import reduce
from operator import mul

# all class and function definitions in the code file, if any
def find_primes(up_to: int) -> list:
    primes = [2]
    for i in range(1, up_to):
        for prime in primes:
            if ((i + 1) % prime == 0): break
        else: primes.append(i + 1)
    return primes

def occurance_counter(up_to: int, prime: int) -> int:
    c = 0
    i = 1
    while prime**i <= up_to:
        c += up_to // prime**i
        i += 1
    return c

# main function
def main_solution(n: int) -> int:
    # all input arguments of the main_solution function should be json serializable (no self-defined objects, functions, np.array, set, tuple, etc.)
    if n == 0:
        return 1
    else:
        primes = find_primes(n)
        p_powers = [p**occurance_counter(n, p) for p in primes]
        return reduce(mul, p_powers)

