You are given a question that requires some input and output variables as follows:

Given a square matrix and a power, what is the resulting matrix after raising the original matrix to the specified power? The matrix is represented as a list of lists, where each sublist represents a row in the matrix. The power is an integer that indicates how many times the matrix should be multiplied by itself.

The input and output requirements are as follows:

Input:
  `matrix_order` (int): The order of the square matrix (number of rows/columns).
  `power` (int): The power to which the matrix should be raised.
  `matrix_values` (list of lists of int): A 2D list representing the matrix values. Each sublist represents a row in the matrix.

Output:
  `return` (list of lists of int): A 2D list representing the resulting matrix after raising the input matrix to the specified power. Each sublist represents a row in the resulting matrix.

Given the following input:

{'matrix_order': 3, 'power': 1, 'matrix_values': [[5, 3, 4], [9, 2, 4], [5, 1, 3]]}

Can you predict the output without writing any code? Please reason and put your final answer in the following json format: {"output": <your output>}, where <your output> should strictly match the the output requirement as specified.

Tip: Here is a reference code snippet for this question. You can refer to this code to guide your reasoning but not copy spans of code directly.

# import necessary packages
import random

# all class and function definitions in the code file, if any
class Node:
    def __init__(self, value):
        self.value = value
        self.next = None
        self.prev = None

class LinkedList:
    def __init__(self, head=None, tail=None):
        self.head = head
        self.tail = tail

    def valOf(self, n):
        if n < 0:
            return None
        if self.head is not None:
            elem = self.head
            for _ in range(n):
                elem = elem.next
            return elem.value
        return None

    def prepend(self, node):
        if not isinstance(node, Node):
            node = Node(node)
        if self.head is not None:
            self.head.prev = node
            node.next = self.head
            self.head = node
            node.prev = None
        else:
            self.head = self.tail = node
            node.prev = node.next = None
        return None

    def insert(self, node, where=None):
        if not isinstance(node, Node):
            node = Node(node)

        if self.head is None:
            self.head = self.tail = node
            node.prev = node.next = None
        elif where is None:
            node.prev = self.tail
            self.tail.next = node
            self.tail = node
            node.next = None
        else:
            node.next = where.next
            where.next.prev = node
            node.prev = where
            where.next = node
        return None

    def delete(self, node):
        if not isinstance(node, Node):
            node = Node(node)

        if self.head is None:
            return None
        elif self.head == node:
            self.head = node.next
            self.head.prev = None
            node.next = None
        elif self.tail == node:
            self.tail = node.prev
            node.prev = None
            self.tail.next = None
        else:
            node.next.prev = node.prev
            node.prev.next = node.next
            node.next = node.prev = None
        return None

    def __str__(self):
        s = ''
        if self.head is not None:
            point = self.head
        else:
            return ""

        while True:
            s += str(point.value) + " "
            if point.next is None:
                break
            point = point.next
        return s.strip()

class Matrix(LinkedList):
    def __init__(self, order, head=None, tail=None):
        LinkedList.__init__(self, head, tail)
        self.order = order

    def __str__(self):
        s = ''
        row = self.head
        while row is not None:
            s += LinkedList.__str__(row.value) + '\n'
            row = row.next
        return s

    def __mul__(self, t):
        if isinstance(t, Matrix):
            res = Matrix(self.order)
            rows = self.head

            while rows is not None:
                l = LinkedList()
                for j in range(self.order):
                    total = 0
                    for i in range(self.order):
                        total += rows.value.valOf(i) * t.valOf(i).valOf(j)
                    l.insert(total)
                res.insert(l)
                rows = rows.next
        return res

# main function
def main_solution(matrix_order, power, matrix_values):
    # Convert matrix_values to a Matrix object
    m = Matrix(matrix_order)
    for row in matrix_values:
        l = LinkedList()
        for value in row:
            l.insert(value)
        m.insert(l)

    # Calculate the kth power of the matrix
    res_total = None
    for _ in range(power):
        if res_total is None:
            res_total = m
        else:
            res_total *= m

    # Convert the result to a JSON serializable format
    result_matrix = []
    row = res_total.head
    while row is not None:
        row_values = []
        elem = row.value.head
        while elem is not None:
            row_values.append(elem.value)
            elem = elem.next
        result_matrix.append(row_values)
        row = row.next

    return result_matrix

