def base26(num):
    """Makes a base-26 number, using the alphabet as numerals.

    Arguments:
        num -- integer to turn into base 26
    """
    alphabet = list(map(chr, map(lambda x: 65 + x, range(0, 26))))
    if num == 0: return alphabet[0]

    s = ""
    while num > 0:
        s = alphabet[num % 26] + s
        num = int(num / 26)
    return s

