class Var(object):
    def __init__(self, name):
        self.name = name

    def run(self, context):
        return context[self.name]

class Add(object):
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def run(self, context):
        return self.x.run(context) + self.y.run(context)

class Sub(object):
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def run(self, context):
        return self.x.run(context) - self.y.run(context)

class Mul(object):
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def run(self, context):
        return self.x.run(context) * self.y.run(context)

class Neg(object):
    def __init__(self, x):
        self.x = x

    def run(self, context):
        return -self.x.run(context)

class TokenParser(object):
    def __init__(self, s):
        self.s = s
        self.curr = None

    def next(self):
        """
        returns (type, value)
        """
        if self.curr:
            res = self.curr
            self.curr = None
            return res
        s = self.s.lstrip()
        if not s:
            res = '', None
            n = 1
        elif s[0] in ['+', '-', '*', '(', ')']:
