# all class and function definitions in the code file, if any
class Stack:
    def __init__(self):
        self._stack = []

    def push(self, x):
        self._stack.append(x)

    def pop(self):
        return self._stack.pop()

    def clear(self):
        self._stack.clear()

_operators = ["+", "-", "*", "/", "//", "%", "**"]
_tri_func = {"sin": math.sin, "cos": math.cos, "tan": math.tan}
_math_func = {"log": math.log, "r": math.sqrt}

_necessary_num = 1
_floating_point = 5

def validate_element(xs):
    """<検査関数>有効な要素かどうか検査する関数
       @param xs 入力値の各要素リスト
       @return  各要素リスト"""
    if xs == []:
        return xs
    elif _operators.count(xs[0]) == 1:
        validate_element(xs[1:])
    elif xs[0] in _tri_func:
        validate_element(xs[1:])
    elif xs[0] in _math_func:
        validate_element(xs[1:])
    elif validate_num(xs[0]):
        validate_element(xs[1:])
    else:
        raise ValueError("無効な入力エラー")

def validate_num(s):
    """<検査関数>有効な数値かどうか検査する関数
       @param s 文字列
       @return  有効な数値の文字列"""
    if s[0] == "-":
        return validate_num(s[1:])
    elif s[0] == "+":
        return validate_num(s[1:])
    elif s.count(".") == 1:
        [a, b] = s.split(".")
        if not a.isdigit() or not b.isdigit():
