        return True
    elif not s.isdigit():
        raise ValueError("無効な数値エラー")
    return True

def calculation(num_expression_list):
    """後置記法（逆ポーランド記法）の計算関数
       @param num_expression_list 計算式のリスト
       @retval True       計算終了結果表示
               ErrorValue 計算不可能な式"""
    stack = Stack()
    infix = Stack()
    try:
        for token in num_expression_list:
            if token in _operators:
                tmp_num1 = stack.pop()
                tmp_num2 = stack.pop()
                infix_num1 = infix.pop()
                infix_num2 = infix.pop()
                infix.push("(" + infix_num2 + token + infix_num1 + ")")
