def gaussian_elimination(matrix_a, vector_b, n):
    for i in range(n):
        if matrix_a[i][i] == 0:
            swapped = False
            for j in range(i+1, n):
                if matrix_a[j][i] != 0:
                    for k in range(i, n):
                        matrix_a[i][k], matrix_a[j][k] = matrix_a[j][k], matrix_a[i][k]
                    vector_b[i], vector_b[j] = vector_b[j], vector_b[i]
                swapped = True
                break
            if not swapped:
                return None  # Indeterminate or contradictory system
        divisor = matrix_a[i][i]
        if divisor == 0:
            return None  # Indeterminate or contradictory system
        for j in range(i, n):
            matrix_a[i][j] /= divisor
        vector_b[i] /= divisor

        for j in range(i+1, n):
