            for k in range(i, n):
                matrix_a[j][k] -= factor * matrix_a[i][k]
            vector_b[j] -= factor * vector_b[i]

    for i in range(n-1, -1, -1):
        for j in range(i-1, -1, -1):
            factor = matrix_a[j][i]
            matrix_a[j][i] = 0
            vector_b[j] -= factor * vector_b[i]
    return vector_b

