# import necessary packages
import random

# all class and function definitions in the code file, if any
class GameBoard(object):
    def __init__(self, size):
        assert size > 2 and size < 9
        self.size = size
        self.moves = [' '] * size * size
        self.done = 0

    def check_valid_move(self, move):
        if move < 0 or move >= (self.size * self.size) or self.moves[move] != ' ':
            return None
        return move

    def turn(self, move, player):
        self.moves[move] = player
        if self.check_win():
            self.done = 1
        elif self.check_tie():
            self.done = -1

    def check_win(self):
        is_win = False
        horizontals = [self.moves[i * self.size:(i + 1) * self.size] for i in range(self.size)]
        verticals = [[self.moves[i + k * self.size] for k in range(self.size)] for i in range(self.size)]
        diagonals = [[self.moves[i * self.size + i] for i in range(self.size)], [self.moves[(i + 1) * self.size - (i + 1)] for i in range(self.size)]]
        for line in horizontals + verticals + diagonals:
            is_win = self.check_win_line(line)
            if is_win:
                break
        return is_win

    @staticmethod
    def check_win_line(line):
        if any([l == ' ' for l in line]):
            return False
        elif all([line[0] == line[i] for i in range(len(line))]):
            return True
        else:
            return False

    def check_tie(self):
        return all([m != ' ' for m in self.moves])

# main function
def main_solution(size, moves):
    """
    Simulates a tic-tac-toe game based on the given size of the board and a sequence of moves.

    Parameters:
    size (int): The size of the tic-tac-toe board (e.g., 3 for a 3x3 board).
    moves (list of tuples): A list of tuples where each tuple contains a move index (0-based) and the player symbol ('X' or 'O').

    Returns:
    dict: A dictionary with keys 'winner' (str) and 'final_board' (list of str).
    """
    game_board = GameBoard(size)
    players = ['X', 'O']

    for move_index, (move, player) in enumerate(moves):
        if game_board.check_valid_move(move) is not None:
            game_board.turn(move, player)
            if game_board.done != 0:
                break

    winner = 'Tie' if game_board.done == -1 else players[(move_index + 1) % 2] if game_board.done == 1 else None
    return {'winner': winner, 'final_board': game_board.moves}

