# import necessary packages
import random

# all class and function definitions in the code file, if any
def rmspp(number, attempts=100):
    if number < 2:
        return False
    if number == 2:
        return True
    if number % 2 == 0:
        return False
    s = number - 1
    r = 0
    while s % 2 == 0:
        r += 1
        s = s // 2
    while attempts:
        a = random.randint(1, number - 1)
        if mod_exp(a, s, number) != 1:
            for j in range(0, r):
                if mod_exp(a, (2 ** j) * s, number) == number - 1:
                    break
            else:
                return False
        attempts -= 1
    return True

def mod_exp(base, exponent, modulus):
    result = 1
    while exponent > 0:
        if (exponent & 1) == 1:
            result = (result * base) % modulus
        exponent >>= 1
        base = (base * base) % modulus
    return result

# main function
def main_solution(number):
    # Convert input to the required format
    number = int(number)

    # Call the function to check if the number is prime
    is_prime = rmspp(number)

    # Return the result as a JSON serializable output
    return {"is_prime": is_prime}

