    def build_tree(node_list):
        if not node_list:
            return None
        nodes = [None if val is None else TreeNode(val) for val in node_list]
        kids = nodes[::-1]
        root = kids.pop()
        for node in nodes:
            if node:
                if kids: node.left = kids.pop()
                if kids: node.right = kids.pop()
        return root

    pRoot = build_tree(tree_structure)
    solution = Solution()
    is_balanced = solution.IsBalanced_Solution(pRoot)
    return is_balanced

