        for col_idx in range(num_cols - 1):
            bridge = VirtualLink(name='{}<{}>{}'.format(col_idx, row_idx, col_idx + 1))
            NODES[row_idx][col_idx].interfaces.append(bridge)
            NODES[row_idx][col_idx + 1].interfaces.append(bridge)
