    a = tuple_a[1] 
    t1, t2 = a
    added = False
    for j in range(j_used+1, len(list_day), 1):
        available = True
        for h in range(t1, t2):
            available = available and list_day[j][h] == VAL_FREE
        if available:
            j_used = j
            for h in range(t1, t2):
                list_day[j_used][h] = VAL_ACTIVITY
            added = True
            break

