# import necessary packages
import numpy as np
from functools import wraps
from copy import copy
from abc import ABC, abstractmethod

# all class and function definitions in the code file, if any
class Vector:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __repr__(self):
        return f"({self.x}, {self.y})"

    def __hash__(self):
        return hash((self.x, self.y))

    def __add__(self, other):
        return Vector(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector(self.x - other.x, self.y - other.y)

    def __mul__(self, other):
        return Vector(self.x * other, self.y * other)

    def __truediv__(self, other):
        return Vector(float(self.x) / other, float(self.y) / other)

    def __neg__(self):
        return Vector(-self.x, -self.y)

    def __iter__(self):
        yield self.x
        yield self.y

    def sqr_magnitude(self):
        return self.x * self.x + self.y * self.y

    def magnitude(self):
        return np.sqrt(self.sqr_magnitude())

    def normal(self):
        return self / self.magnitude()

    def dot(self, other):
        return self.x * other.x + self.y * other.y


class ICollider(ABC):
    @abstractmethod
    def center(self):
        pass

    @abstractmethod
    def move(self, move_vector):
        pass


class RectCollider(ICollider):
    def __init__(self, size, position):
        self.width, self.height = size
        self._position = Vector(*position) - self._half_diagonal()

    def _half_diagonal(self):
        return Vector(self.width / 2, self.height / 2)

    def move(self, move_vector):
        self._position += move_vector

    def center(self):
        return self._position + self._half_diagonal()


class CircleCollider(ICollider):
    def __init__(self, radius, position):
        self.radius = radius
        self._position = Vector(*position)

    def move(self, move_vector):
        self._position += move_vector

    def center(self):
        return self._position


def clamp(n, low, high):
    return max(low, min(n, high))


def find_closest(r, c):
    closest_point = copy(c.center())
    closest_point.x = clamp(closest_point.x, r._position.x, r._position.x + r.width)
    closest_point.y = clamp(closest_point.y, r._position.y, r._position.y + r.height)
    return closest_point


def detect_collision_RectCircle(r, c):
    return (find_closest(r, c) - c.center()).sqr_magnitude() <= c.radius ** 2


# main function
def main_solution(rect_size, rect_position, circle_radius, circle_position):
    # Convert JSON serializable inputs to original input variables
    rect_collider = RectCollider(rect_size, rect_position)
    circle_collider = CircleCollider(circle_radius, circle_position)

    # Detect collision
    collision_detected = detect_collision_RectCircle(rect_collider, circle_collider)

    # Return the result as a JSON serializable output
    return {"collision_detected": collision_detected}

