# import necessary packages
import random

# all class and function definitions in the code file, if any
class TreeNode:
    def __init__(self, x):
        self.val = x
        self.left = None
        self.right = None

class BinaryTree(object):
    def build_tree(self, List):
        l = 0
        r = len(List) - 1
        if l > r:
            return None
        if l == r:
            return TreeNode(List[l])
        mid = (l + r) // 2
        root = TreeNode(List[mid])
        root.left = self.build_tree(List[:mid])
        root.right = self.build_tree(List[mid + 1:])
        return root

    def PrintFromTopToBottom(self, root):
        if not root:
            return []
        queue = []
        result = []
        queue.append(root)
        while len(queue) > 0:
            node = queue.pop(0)
            result.append(node.val)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        return result

class Solution:
    def HasSubtree(self, pRoot1, pRoot2):
        result = False
        if pRoot1 and pRoot2:
            if pRoot1.val == pRoot2.val:
                result = self.same(pRoot1, pRoot2)
            if not result:
                result = self.HasSubtree(pRoot1.left, pRoot2)
            if not result:
                result = self.HasSubtree(pRoot1.right, pRoot2)
        return result

    def same(self, pRoot1, pRoot2):
        if not pRoot2:
            return True
        if not pRoot1 or pRoot1.val != pRoot2.val:
            return False
        return self.same(pRoot1.left, pRoot2.left) and self.same(pRoot1.right, pRoot2.right)

