    # Convert JSON serializable inputs to original input variables
    bt = BinaryTree()
    pRoot1 = bt.build_tree(tree1_list)
    pRoot2 = bt.build_tree(tree2_list)

    # Invoke the function that requires non-JSON serializable inputs
    solution = Solution()
    result = solution.HasSubtree(pRoot1, pRoot2)

    # Convert the result to JSON serializable output
    return result

