def main_solution(limit):
    # Initialize global variables
    global prime_list, mot_prime_list, answer
    prime_list = []
    mot_prime_list = {}
    answer = 'MISSING'

    # Miller-Rabin primality test
    def Miller_Rabin(n):
        if n % 2 == 0:
            return False

        def MR_core(d, a, s=1):
            if s == 1:
                return MR_core(d >> 1, a, 2) == n
            elif s == 2:
                if d & 1:
                    m = MR_core(d >> 1, a, 3)
                    s = m * m % n * a % n
                    return n if s == n - 1 or s == 1 else s
                else:
                    m = MR_core(d >> 1, a, 2)
                    if m == n:
                        return n
                    else:
                        s = m * m % n
                        return n if s == n - 1 else s
            elif s == 3:
                if d == 0:
                    return 1
                else:
                    m = MR_core(d >> 1, a, 3)
                    if d & 1:
                        return m * m % n * a % n
                    else:
                        return m * m % n

        k = 3
        return all(MR_core(n - 1, randrange(2, n)) for i in range(k))

    # Initialize prime list up to the given limit
    def initPrimeList(number):
        global prime_list
        for n in range(2, number + 1):
            if Miller_Rabin(n):
                prime_list.append(n)

    # Check if two numbers concatenated in both ways are prime
    def checkConnectPrime(num1, num2):
        con_num1 = int(str(num1) + str(num2))
        con_num2 = int(str(num2) + str(num1))
        return Miller_Rabin(con_num1) and Miller_Rabin(con_num2)

    # Recursive function to find the chain of primes
    def findChain(prime_list, rest):
        global mot_prime_list, answer
        if len(rest) == 5:
            if answer == 'MISSING':
                answer = sum(rest)
            else:
                answer = min(sum(rest), answer)
            return True
        else:
            if len(prime_list) == 0:
                return False
            for p in prime_list:
                p_list = list(set(prime_list) & set(mot_prime_list[p]))
                findChain(p_list, rest + [p])
        return False

    # Initialize prime list
    initPrimeList(limit)

    # Find the chain of primes
    for num in prime_list:
        check_prime = [x for x in prime_list if x < num]
