    # Convert JSON serializable input to original input variables
    g = Graph('Project Graph')
    for dep in dependencies:
        names = dep.split(',')
        g.addEdge(names[0], names[1])

    # Perform the core solution
    stack = orderProjects(g.getNodes())

    # Convert the output to JSON serializable format
    if stack is None:
        return "Circular Dependency detected"
    else:
        build_order = [node.name for node in reversed(stack)]
        return build_order

