# import necessary packages
import random

# all class and function definitions in the code file, if any
class Node:
    def __init__(self, value, parent, left=None, right=None, closure=None):
        self.v = value
        self.count = 1
        self.p = parent
        self.l = left
        self.r = right
        self.cl = {} if closure is None else closure

class BSTDataModel:
    def __init__(self, debug):
        self.root = None
        self.cur = self.root
        self.gcl = {}
        self.debug = debug
        self.graph_num = 0

    def insert(self, value):
        if self.root is None:
            self.root = Node(value, None)
        else:
            self._insert_recursive(self.root, value)

    def _insert_recursive(self, node, value):
        if value < node.v:
            if node.l is None:
                node.l = Node(value, node)
            else:
                self._insert_recursive(node.l, value)
        elif value > node.v:
            if node.r is None:
                node.r = Node(value, node)
            else:
                self._insert_recursive(node.r, value)
        else:
            node.count += 1

    def verify_tree_val(self):
        if self.root is None:
            return True
        return self._verify_tree_val_recursive(self.root, None, True)

    def _verify_tree_val_recursive(self, node, parent, is_left):
        if node is None:
            return True
        if parent is not None:
            if is_left and node.v >= parent.v:
