def judge_seven_pairs(hands):
    for i in range(1,10):
        if not ((hands[i] == 2) or (hands[i] == 0)):
            return False
    return True

def judge_decomposable(hands):
    checking_hands = deepcopy(hands)
    for i in range(1,10):
        while checking_hands[i] >= 3:
            checking_hands[i] -= 3
        while checking_hands[i] > 0:
            if i+2 > 9:
