        self.setupInitialPosition()
        self.pieces = self.white_pieces + self.black_pieces

    def setupInitialPosition(self):
        self.white_pieces += [Pawn(self.position(col + '2'), self.white, 'pawn') for col in 'abcdefgh']
        self.white_pieces.append(Rook(self.position('a' + '1'), self.white, 'rook'))
