# import necessary packages
import numpy as np
import sys

# Constants
X = "X"
O = "O"
EMPTY = None

# Function to initialize the board
def initial_state():
    return np.array([[EMPTY, EMPTY, EMPTY],
                     [EMPTY, EMPTY, EMPTY],
                     [EMPTY, EMPTY, EMPTY]])

# Function to determine the next player
def player(board):
    x_times = np.count_nonzero(board == X)
    o_times = np.count_nonzero(board == O)
    return X if (x_times + o_times) % 2 == 0 else O

# Function to get all possible actions
def actions(board):
    return set((i, j) for i in range(3) for j in range(3) if board[i][j] == EMPTY)

# Function to get the result of an action
def result(board, action):
    new_board = board.copy()
    new_board[action[0]][action[1]] = player(board)
    return new_board

# Function to determine the winner
def winner(board):
    lines = [
        board[0], board[1], board[2],  # rows
        board[:, 0], board[:, 1], board[:, 2],  # columns
        [board[i][i] for i in range(3)],  # diagonal
        [board[i][2 - i] for i in range(3)]  # anti-diagonal
    ]
    for line in lines:
        if all(cell == X for cell in line):
            return X
        if all(cell == O for cell in line):
            return O
    return None

# Function to check if the game is over
def terminal(board):
    return winner(board) is not None or np.all(board != EMPTY)

# Function to get the utility of the board
def utility(board):
    win = winner(board)
    if win == X:
        return 1
    elif win == O:
        return -1
    return 0

# Function to get the max value
def max_value(board):
    if terminal(board):
        return utility(board)
    v = -sys.maxsize
    for action in actions(board):
        v = max(v, min_value(result(board, action)))
    return v

# Function to get the min value
def min_value(board):
    if terminal(board):
        return utility(board)
    v = sys.maxsize
    for action in actions(board):
        v = min(v, max_value(result(board, action)))
    return v

# Main function to solve the problem
def main_solution(board_state):
    board = np.array(board_state)
    if terminal(board):
        return {"winner": winner(board), "utility": utility(board)}
    else:
        return {"next_player": player(board), "possible_actions": list(actions(board))}

