# import necessary packages
import random
import abc

# all class and function definitions in the code file, if any
class AutoStorage:
    __counter = 0 

    def __init__(self):
        cls = self.__class__
        prefix = cls.__name__
        index = cls.__counter
        self.storage_name = f'_{prefix}#{index}' 
        cls.__counter += 1

    def __get__(self, instance, owner):
        if instance is None:
            return self
        else:
            return getattr(instance, self.storage_name)

    def __set__(self, instance, value):
        setattr(instance, self.storage_name, value)

class Validated(abc.ABC, AutoStorage):
    def __set__(self, instance, value):
        value = self.validate(instance, value)
        super().__set__(instance, value)

    @abc.abstractmethod
    def validate(self, instance, value):
        """return a validated value, or else raise a ValueError"""

class PositiveNumber(Validated):
    def validate(self, instance, value):
        if value <= 0:
            raise ValueError('value must be > 0')
        return value

class NonBlank(Validated):
    def validate(self, instance, value):
        if value is None:
            raise ValueError('value must not be None')
        value = value.strip()
        if len(value) == 0:
            raise ValueError('value must have length > 0')
        return value

class LineItem:
    description = NonBlank()
    weight = PositiveNumber()
    price = PositiveNumber()

    def __init__(self, description, weight, price):
        self.description = description
        self.weight = weight
        self.price = price

    def subtotal(self):
        return self.weight * self.price

# main function
def main_solution(description, weight, price):
    try:
        item = LineItem(description, weight, price)
        return {"description": item.description, "weight": item.weight, "price": item.price, "subtotal": item.subtotal()}
    except ValueError as e:
        return {"error": str(e)}

