# import necessary packages
import random

# all class and function definitions in the code file, if any
class robot(object):

    def __init__(self):
        self.__xy = [0, 0]
        self.__orientation = [0, 1, 0, 0]  # WEST, NORTH, EAST, SOUTH

    def move(self, cmd):
        if cmd == 'G':
            self.__apply()
        elif cmd == 'L':
            self.__change_direction(False)
        elif cmd == 'R':
            self.__change_direction(True)

    def __change_direction(self, direction):
        if direction:
            self.__orientation[0], self.__orientation[1:] = self.__orientation[-1], self.__orientation[:-1]
        else:
            self.__orientation[-1], self.__orientation[:-1] = self.__orientation[0], self.__orientation[1:]

    def __apply(self):
        index = self.__orientation.index(1)
        add_val = 1 if index in [1, 2] else -1
        self.__xy[index % 2] += add_val

    @property
    def state(self):
        return [self.__xy, self.__orientation]

# main function
def main_solution(commands):
    # commands is a list of strings, each string representing a sequence of commands
    result = []

    for cmds in commands:
        rob = robot()
        for cmd in cmds:
            rob.move(cmd)
        if rob.state[0] == [0, 0]:
            result.append("YES")
        else:
            result.append("NO")

    return result

