def gcd(a, b):
    if a < b:
        return gcd(b, a)
    while b > 0:
        a, b = b, a % b
    return a

def isprime(n):
    if n < 2:
        return False
    for m in range(2, int(n**0.5 + 1)):
        if n % m == 0:
            return False
    return True

def f(n, seed, target):
    ret = n**2 + seed
    return ret % target

def factoring(n, seed=3):
    if isprime(n):
        return n
    x, y, d = 2, 2, 1
    tmp = n
    while d == 1:
        x = f(x, seed, tmp)
        y = f(f(y, seed, tmp), seed, tmp)
        dif = x - y if x > y else y - x
        d = gcd(dif, tmp)
        seed += 1

    if d % 2 == 0:
        return 2
    if not isprime(d):
        return factoring(d, seed + 1)
    return factoring(d, 1)

def factors(target, seed=0):
