        self._column_pairs = {'a': 0, 'b': 1, 'c': 2, 'd': 3, 'e': 4, 'f': 5, 'g': 6, 'h': 7, 'i': 8}
        self._row_pairs = {'10': 0, '9': 1, '8': 2, '7': 3, '6': 4, '5': 5, '4': 6, '3': 7, '2': 8, '1': 9}

    def get_index_from_coord(self, coord):
        """Given a Xiangqi board coordinate string, returns a list containing the respective row and column indexes for that coordinate."""
        row_index = self._row_pairs[coord[1:]] if len(coord) == 3 else self._row_pairs[coord[1]]
        column_index = self._column_pairs[coord[0]]
        return [row_index, column_index]

