    max_ratio = 0
    n_value = 0
    for n in range(n_start, n_end, step):
        current_ratio = float(n) / phi(n)
        if current_ratio > max_ratio:
            max_ratio = current_ratio
            n_value = n
    return {"n_value": n_value, "max_ratio": max_ratio}

