def generate_parentheses(n):
    if n == 0:
        return set()
    if n == 1:
        return {'()'}
    else:
        solutions = set()
        for solution in generate_parentheses(n-1):
            for idx, char in enumerate(solution := '(' + solution):
                if char == '(':
                    solutions.add(solution[:idx+1]+')'+solution[idx+1:])
        return solutions

