# import necessary packages
import random

# all class and function definitions in the code file, if any
class FieldElement:
    def __init__(self, num, prime):
        if num < 0 or num >= prime:
            error = f'num={num} is not in field range 0 to {prime - 1}'
            raise ValueError(error)

        self.num = num
        self.prime = prime

    def __repr__(self):
        return f'FieldElement_{self.prime}({self.num})'

    def __eq__(self, other):
        if other is None:
            return False
        return self.prime == other.prime and self.num == other.num

    def __ne__(self, other):
        return not (self == other)

    def __add__(self, other):
        if self.prime != other.prime:
            raise TypeError('Cannot add two numbers in different Fields')
        num = (self.num + other.num) % self.prime
        return self.__class__(num, self.prime)

    def __sub__(self, other):
        if self.prime != other.prime:
            raise TypeError('Cannot subtract two numbers in different Fields')
        num = (self.num - other.num) % self.prime
        return self.__class__(num, self.prime)

    def __mul__(self, other):
        if self.prime != other.prime:
            raise TypeError('Cannot multiply two numbers in different Fields')
        num = (self.num * other.num) % self.prime
        return self.__class__(num, self.prime)

    def __rmul__(self, other):
        return self.__class__(other, self.prime) * self

    def __pow__(self, exponent):
        n = exponent % (self.prime - 1)
        num = pow(self.num, n, self.prime)
        return self.__class__(num, self.prime)

    def __truediv__(self, other):
        if self.prime != other.prime:
            raise TypeError('Cannot divide two numbers in different Fields')
        num = self.num * pow(other.num, self.prime - 2, self.prime) % self.prime
        return self.__class__(num, self.prime)

# main function
def main_solution(num1, prime1, num2, prime2, operation):
    # Convert JSON serializable inputs to original input variables
    field_element1 = FieldElement(num1, prime1)
    field_element2 = FieldElement(num2, prime2)

    # Perform the operation
    if operation == 'add':
        result = field_element1 + field_element2
    elif operation == 'sub':
        result = field_element1 - field_element2
    elif operation == 'mul':
        result = field_element1 * field_element2
    elif operation == 'pow':
        result = field_element1 ** num2
    elif operation == 'div':
        result = field_element1 / field_element2
    else:
        raise ValueError("Invalid operation")

