# import necessary packages
from math import inf
import random

# all class and function definitions in the code file, if any
def space_is_free(board, x, y):
    return board[x][y] == '-'

def board_is_full(board):
    for row in board:
        if '-' in row:
            return False
    return True

def who_win(board, player):
    win_conditions = [
        [(0, 0), (0, 1), (0, 2)],
        [(1, 0), (1, 1), (1, 2)],
        [(2, 0), (2, 1), (2, 2)],
        [(0, 0), (1, 0), (2, 0)],
        [(0, 1), (1, 1), (2, 1)],
        [(0, 2), (1, 2), (2, 2)],
        [(0, 0), (1, 1), (2, 2)],
        [(0, 2), (1, 1), (2, 0)]
    ]
    for condition in win_conditions:
        if all(board[x][y] == player for x, y in condition):
            return True
    return False

def draw(board):
    return board_is_full(board)

def make_a_move(board, x, y, move):
    if space_is_free(board, x, y):
        board[x][y] = move
        return board
    return board

def minimax(board, alpha, beta, turn_to_max):
    if who_win(board, 'X'):
        return 1
    elif who_win(board, 'O'):
        return -1
    elif draw(board):
        return 0

    if turn_to_max:
        best_eval = -inf
        for x in range(3):
            for y in range(3):
                if space_is_free(board, x, y):
                    board[x][y] = 'X'
                    eval = minimax(board, alpha, beta, False)
                    board[x][y] = '-'
                    best_eval = max(eval, best_eval)
                    alpha = max(alpha, eval)
                    if beta <= alpha:
                        break
        return best_eval
    else:
        best_eval = inf
        for x in range(3):
            for y in range(3):
                if space_is_free(board, x, y):
                    board[x][y] = 'O'
                    eval = minimax(board, alpha, beta, True)
                    board[x][y] = '-'
                    best_eval = min(eval, best_eval)
                    beta = min(beta, eval)
                    if beta <= alpha:
                        break
        return best_eval

def ai_move(board):
    best_eval = -inf
    best_move = (0, 0)
    for x in range(3):
        for y in range(3):
            if space_is_free(board, x, y):
                board[x][y] = 'X'
                eval = minimax(board, -inf, inf, False)
                board[x][y] = '-'
                if eval > best_eval:
                    best_eval = eval
                    best_move = (x, y)
    return best_move

# main function
def main_solution(board):
    # Convert the board to a list of lists if it's not already
    if isinstance(board, str):
        board = [list(row) for row in board.split(';')]

    # Check if the game is already over
    if who_win(board, 'X'):
        return "AI wins"
    elif who_win(board, 'O'):
        return "Player wins"
    elif draw(board):
        return "Draw"

    # AI makes a move
    x, y = ai_move(board)
    board = make_a_move(board, x, y, 'X')

    # Check the result after AI's move
    if who_win(board, 'X'):
        return "AI wins"
    elif draw(board):
        return "Draw"

    # Return the updated board as a string
    return ';'.join(''.join(row) for row in board)

