def isSafe(v, graph, dist):
    if (graph[v][0] <= dist - 50) or (graph[v][0] >= 50 - dist) or (graph[v][1] >= 50 - dist) or (graph[v][1] <= dist - 50):
        return True
    elif (graph[v][0] == 0) and (graph[v][1] == 0):
        if (graph[v][0]-15 <= dist - 50) or (graph[v][0]+15 >= 50 - dist) or (graph[v][1]+15 >= 50 - dist) or (graph[v][1]-15 <= dist - 50):
