            return False
    else:
        if (graph[v][0]-graph[w][0])**2 + (graph[v][1]-graph[w][1])**2 <= (dist)**2:
            return True
        else:
            return False

def DFS(v, graph, dist):
    graph[v][2] = 1
    answer = 'No'
    if isSafe(v, graph, dist):
        answer = 'Yes'
    else:
        for w in range(len(graph)):
            if (graph[w][2] == 0) and (Jump(v, w, graph, dist)):
                answer = DFS(w, graph, dist)
                if answer == 'Yes':
                    break
