class TowerOfHanoi:
    def __init__(self, disk, rod):
        self.disk = disk
        self.rod = rod
        self.rods = []
        self.moves = 0

    def numberOfRods(self):
        return self.rod

    def numberOfDisks(self):
        return self.disk

    def numberOfMoves(self):
