        square = 1
        while square <= len(array):
            bitSum = 0
            index = square
            while index <= len(array):
                bitIndex = index
                while bitIndex < (index + square) and bitIndex <= len(array):
                    if array[bitIndex - 1] != 2:
                        bitSum += array[bitIndex - 1]
                    bitIndex += 1
                index = (bitIndex - 1) + square + 1
            array[square - 1] = bitSum % 2   
            square *= 2
        return array

