# import necessary packages
from random import randint
import copy

# all class and function definitions in the code file, if any
def makeTable(n):
    return [[0] * n for i in range(n)]

def add_bombs(table, bombs):
    for i in range(bombs):
        is_bomb = False
        while not is_bomb:
            x = randint(0, len(table) - 1)
            y = randint(0, len(table) - 1)
            if table[x][y] != 9:
                table[x][y] = 9
                is_bomb = True
    return table

def change_table(table):
    for x in range(len(table)):
        for y in range(len(table[x])):
            if table[x][y] == 9:
                table = check_down_left(table, x, y)
                table = check_down_right(table, x, y)
                table = check_down(table, x, y)
                table = check_up_left(table, x, y)
                table = check_up_right(table, x, y)
                table = check_up(table, x, y)
                table = check_left(table, x, y)
                table = check_right(table, x, y)
    return table

def check_down_left(table, x, y):
    if x + 1 < len(table[x]) and y - 1 >= 0:
        if table[x + 1][y - 1] != 9:
            table[x + 1][y - 1] += 1
    return table

def check_down_right(table, x, y):
    if x + 1 < len(table[0]) and y + 1 < len(table):
        if table[x + 1][y + 1] != 9:
            table[x + 1][y + 1] += 1
    return table

def check_down(table, x, y):
    if x + 1 < len(table[0]):
        if table[x + 1][y] != 9:
            table[x + 1][y] += 1
    return table

def check_up_left(table, x, y):
    if x - 1 >= 0 and y - 1 >= 0:
        if table[x - 1][y - 1] != 9:
            table[x - 1][y - 1] += 1
    return table

def check_up_right(table, x, y):
    if x - 1 >= 0 and y + 1 < len(table):
        if table[x - 1][y + 1] != 9:
            table[x - 1][y + 1] += 1
    return table

def check_up(table, x, y):
    if x - 1 >= 0:
        if table[x - 1][y] != 9:
            table[x - 1][y] += 1
    return table

def check_left(table, x, y):
    if y - 1 >= 0:
        if table[x][y - 1] != 9:
            table[x][y - 1] += 1
    return table

def check_right(table, x, y):
    if y + 1 < len(table):
        if table[x][y + 1] != 9:
            table[x][y + 1] += 1
    return table

def dfs(x, y, visited, list, size):
    list.append((x, y))
    visited[x][y] = 1
    if(x < size - 1 and visited[x + 1][y] == 0):
        dfs(x + 1, y, visited, list, size)
    if(y < size - 1 and visited[x][y + 1] == 0):
        dfs(x, y + 1, visited, list, size)
    if (x > 0 and visited[x - 1][y] == 0):
        dfs(x - 1, y, visited, list, size)
    if (y > 0 and visited[x][y - 1] == 0):
        dfs(x, y - 1, visited, list, size)

# main function
def main_solution(size, bombs):
    # Generate the initial table with bombs
    table = makeTable(size)
    table = add_bombs(table, bombs)
    table = change_table(table)

    # Perform DFS to get the initial position list
    visited = [[0] * size for i in range(size)]
    position_list = []
    dfs(0, 0, visited, position_list, size)

    # Simulate the game to determine the result
    oldlist = copy.deepcopy(position_list)
    result = "You win"  # Default to win unless a bomb is hit
    for pos in oldlist:
        if table[pos[0]][pos[1]] == 9:
            result = "Game over"
            break

    # Return the result of the game
    return result

