def prime_seive(max_num):
    if max_num < 2:
        return []
    num_list = [2] + list(range(3, max_num + 1, 2))
    i = 1
    c = len(num_list)
    while i < c:
        j = i + 1
        while j < c:
            if num_list[j] % num_list[i] == 0:
                del num_list[j]
                c -= 1
            else:
                j += 1
        i += 1
    return num_list

