def integral(R, x1, x2):
    return 0.5 * (x2 * math.sqrt(R * R - x2 * x2) - x1 * math.sqrt(R * R - x1 * x1) +
                  R * R * (math.asin(x2 / R) - math.asin(x1 / R)))

def pos_area(R, x0, y0, d):
    R2 = R * R
    if x0 * x0 + y0 * y0 >= R2:
        return 0
    if (x0 + d) ** 2 + (y0 + d) ** 2 <= R2:
        return d * d
    if (x0 + d) ** 2 + y0 * y0 <= R2:
