            return integral(R, lb, x0 + d) - y0 * (x0 + d - lb) + d * (lb - x0)
    if x0 * x0 + (y0 + d) ** 2 >= R2:
        ub = math.sqrt(R2 - y0 * y0)
        return integral(R, x0, ub) - y0 * (ub - x0)
    else:
        lb = math.sqrt(R2 - (y0 + d) ** 2)
        ub = math.sqrt(R2 - y0 * y0)
        return integral(R, lb, ub) - y0 * (ub - lb) + d * (lb - x0)

def hole_area(R, g, r):
    tot = 0
    if g <= 0 or R <= 0:
        return 0
    stx = sty = r
    while True:
        x = stx
        y = sty
        ar = pos_area(R, x, y, g)
        if ar == 0:
