# import necessary packages
import numpy as np

# all class and function definitions in the code file, if any
class Board:
    def __init__(self, rows, col):
        self.board = np.zeros((rows, col))
        self.rows = rows
        self.col = col

    def drop_piece(self, row, selection, piece):
        self.board[row][selection] = piece

    def is_valid_location(self, selection):
        return self.board[self.rows-1][selection] == 0

    def get_next_open_row(self, selection):
        for r in range(self.rows):
            if self.board[r][selection] == 0:
                return r

    def wining_move(self, piece):
        #horizontal
        for c in range(self.col-3):
            for r in range(self.rows):
                if self.board[r][c] == piece and self.board[r][c+1] == piece and self.board[r][c+2] == piece and self.board[r][c+3] == piece:
                    return True
        #vertical
        for c in range(self.col):
            for r in range(self.rows-3):
                if self.board[r][c] == piece and self.board[r+1][c] == piece and self.board[r+2][c] == piece and self.board[r+3][c] == piece:
                    return True
        #ascending
        for c in range(self.col-3):
            for r in range(self.rows-3):
                if self.board[r][c] == piece and self.board[r+1][c+1] == piece and self.board[r+2][c+2] == piece and self.board[r+3][c+3] == piece:
                    return True
        #decending
        for c in range(self.col-3):
            for r in range(3, self.rows):
                if self.board[r][c] == piece and self.board[r-1][c+1] == piece and self.board[r-2][c+2] == piece and self.board[r-3][c+3] == piece:
                    return True
        return False

# main function
def main_solution(rows, cols, moves):
    # rows (int): Number of rows in the board.
    # cols (int): Number of columns in the board.
    # moves (list of tuples): List of moves where each tuple is (column, piece).

    board = Board(rows, cols)
    for move in moves:
        col, piece = move
        if board.is_valid_location(col):
            row = board.get_next_open_row(col)
            board.drop_piece(row, col, piece)
            if board.wining_move(piece):
                return f"Player {piece} wins!"
    return "No winner yet."

