        self._r = r
        self._c = c
        self._p = 0

    def place(self, s):
        assert self._board[s[0]][s[1]] == '*'
        self._board[s[0]][s[1]] = '.'
        self._p += 1

    def adj(self, s):
        x, y = s
        if x > 0:
            yield (x-1, y)
        if y > 0:
            yield (x, y-1)
        if x > 0 and y > 0:
            yield (x-1, y-1)
        if x+1 < self._r:
