# all class and function definitions in the code file, if any
class Hangman:
    """Play hangman"""

    def __init__(self, word):
        self.word = list(word)
        self.guessed = []
        self.mistakes = 0
        self.empty = list("_" * len(self.word))

    def guess_letter(self, letter):
        """Guess a letter."""
        letter = letter.lower()

        # check whether letter was already guessed
        if letter in self.guessed:
            return "Letter already guessed."

        # add letter to already guessed
        self.guessed.append(letter)

        # check if letter in word
        if letter in self.word:
            idxs = [num for num, let in enumerate(self.word) if let == letter]
            for i in idxs:
                self.empty[i] = letter
        else:
            self.mistakes += 1

        # check if game is finished
        if "_" not in self.empty:
            return "win", self.empty, self.mistakes
        elif self.mistakes >= 10:
            return "lose", self.empty, self.mistakes
        else:
            return "continue", self.empty, self.mistakes

