def isok(row, r):
    return row[r+1:] == '0'*(len(row)-r-1)

def bubble(rows, r, x):
    if r == len(rows) - 1:
        return x
    if isok(rows[r], r):
        return bubble(rows, r+1, x)
    for s in range(r+1, len(rows)):
        if isok(rows[s], r):
            break
    return bubble(rows[0:r] + rows[s:s+1] + rows[r:s] + rows[s+1:], r+1, x + (s-r))

