                return True
        else:
            if int(seq1[i]) > int(seq2[i]):
                return False
            elif int(seq1[i]) < int(seq2[i]):
                return True

    # Check for leading zeros in equal numeric tokens
    for i in range(len(seq1)):
        if 'a' <= seq1[i] <= 'z':
