from typing import List
from collections import defaultdict, deque

# all class and function definitions in the code file, if any
class Solution:
  def catMouseGame(self, graph: List[List[int]]) -> int:
    n = len(graph)
    nodes = {}
    for i in range(n):
      for j in range(1, n):
        for k in range(1, 3):
          nodes[(i, j, k)] = 0
          if i == 0:
            nodes[(i, j, k)] = 1
          elif i == j:
            nodes[(i, j, k)] = 2
    edges = defaultdict(set)
    for i in range(n):
      for j in range(1, n):
        for iprev in graph[i]:
          edges[(i, j, 2)].add((iprev, j, 1))
        for jprev in graph[j]:
          if jprev > 0:
            edges[(i, j, 1)].add((i, jprev, 2))
    degree = {}
    for i in range(n):
      for j in range(1, n):
        degree[(i, j, 1)] = len(graph[i])
        degree[(i, j, 2)] = len(graph[j]) - (0 in graph[j])
    queue = deque([])
    for i in range(n):
      queue.append((0, i, 1, 1))
      queue.append((0, i, 2, 1))
      if i > 0:
        queue.append((i, i, 1, 2))
        queue.append((i, i, 2, 2))
    while queue:
      i, j, k, s = queue.popleft()
      for iprev, jprev, kprev in edges[(i, j, k)]:
