def getProduct(num: int, list_p: list):
    if judge_p(num):
        list_p.append(num)
    else:
        i = 2
        while i <= int(math.sqrt(num)) + 1:
            if num % i == 0:
                if judge_p(i):
                    list_p.append(i)
                    r = int(num / i)
                    getProduct(r, list_p)
