# import necessary packages
from fractions import Fraction
from decimal import Decimal
import decimal
import copy
import random

# all class and function definitions in the code file, if any
class HasUnit:
    def preservecontext(f):
        def preserver(*args, **kwargs):
            oldcontext = decimal.getcontext()
            decimal.setcontext(decimal.ExtendedContext)
            result = f(*args, **kwargs)
            decimal.setcontext(oldcontext)
            return result
        return preserver

    def __init__(self, val, unit):
        if isinstance(val, (str, Decimal)):
            self._val = Fraction(val)
        else:
            self._val = val
        self._unit = unit

    @preservecontext
    def __str__(self):
        if isinstance(self._val, Fraction):
            return str(decimal_from_fraction(self._val))+" "+self._unit
        else:
            return str(self._val)+" "+self._unit

    def __repr__(self):
        return "{}({}, '{}')".format(type(self).__name__, self._val, self._unit)

    def val(self):
        if isinstance(self._val, Fraction):
            return decimal_from_fraction(self._val)
        else:
            return copy.deepcopy(self._val)

    def unit(self):
        return self._unit

    def _compare_to(self, other):
        if isinstance(other, HasUnit):
            assert self._unit == other._unit
            if not isinstance(other._val, (int, Fraction)):
                raise RuntimeError("other._val is a {} (should be one of int or Fraction)".format(type(other._val).__name__))
            to_compare = other._val
        elif isinstance(other, Decimal):
            to_compare = Fraction(other).limit_denominator()
        elif isinstance(other, (int, float, Fraction)):
            to_compare = other
        else:
            raise TypeError("incomparable types "+str(type(self))+", "+str(type(other)))

        if type(to_compare) is Decimal:
            raise RuntimeError("{} shouldn't be a Decimal, but it is".format(to_compare))
        return to_compare

    @preservecontext
    def __eq__(self, other):
        return self._val == self._compare_to(other)

    @preservecontext
    def __lt__(self, other):
        return self._val < self._compare_to(other)

    @preservecontext
    def __le__(self, other):
        to_compare = self._compare_to(other)
        return self < to_compare or self == to_compare

    @preservecontext
    def __gt__(self, other):
        return not self <= other

    @preservecontext
    def __ge__(self, other):
        return not self < other

    @preservecontext
    def __add__(self, other):
        to_math = self._compare_to(other)
        return type(self)(self._val + to_math, self._unit)

    @preservecontext
    def __sub__(self, other):
        to_math = self._compare_to(other)
        return type(self)(self._val - to_math, self._unit)

    @preservecontext
    def __mod__(self, other):
        to_math = self._compare_to(other)
        return type(self)(self._val % to_math, self._unit)

    @preservecontext
    def __format__(self, format_spec):
        return format(self._val, format_spec) + " " + self._unit

class ConvertibleUnit(HasUnit):
    def __init__(self, val, unit):
        HasUnit.__init__(self, val, unit)

    def to_bigger_unit(self):
        assert self._unit in self._bigger, "cannot bigify"
        return self.convert_to(self._bigger[self._unit])

    def to_smaller_unit(self):
        assert self._unit in self._smaller, "cannot smallify"
        return self.convert_to(self._smaller[self._unit])

    def to_bg(self):
        return self.to_bigger_unit()

    def to_sm(self):
        return self.to_smaller_unit()

    @HasUnit.preservecontext
    def convert_to(self, unit):
        unit_from = self._unit
        unit_to = unit

        if unit_to == self._unit:
            return type(self)(self._val, self._unit)

        conv_path = self._dijkstra(unit_from, unit_to)

        result = self._conv_calc(conv_path)

        return type(self)(result, unit)

    def _dijkstra(self, unit_from, unit_to):
        path = []
        visited = {}
        frontier = {unit_from: None}

        while unit_to not in frontier and len(frontier) > 0:
            newfrontier = {}
            for node, prev in frontier.items():
                newneighbors = {n: node for n in self._conv[node].keys() if n not in frontier and n not in visited}
                newfrontier.update(newneighbors)
                visited[node] = prev
            frontier.clear()
            frontier.update(newfrontier)
        if unit_to in frontier:
            path.append(unit_to)
            path.append(frontier[unit_to])
            nextnode = frontier[unit_to]
            while nextnode in visited:
                path.append(visited[nextnode])
                nextnode = visited[nextnode]
            finalpath = list(reversed(path[:-1]))
        else:
            raise ValueError("cannot convert to unit "+str(unit_to))

        return finalpath

    @HasUnit.preservecontext
    def _conv_calc(self, finalpath):
        result = self._val
        unit_from = finalpath[0]
        for unit_to in finalpath[1:]:
            convd = self._conv[unit_from]
            ratio = convd[unit_to]
            result = result * ratio.numerator / ratio.denominator
            unit_from = unit_to
        return result

