# import necessary packages
import itertools
import random

# all class and function definitions in the code file, if any
class Problem:
    def __init__(self, nflavors):
        self.N = nflavors
        self.customers = []

    def addCustomer(self, line):
        part = list(map(int, line.split()))
        num = part[0]
        constrains = []
        for i in range(num):
            constrains.append((part[1 + i * 2], part[2 + i * 2] != 0))
        self.customers.append(constrains)

    def evaluate(self, result):
        for c in self.customers:
            for rule in c:
                if result[rule[0] - 1] == int(rule[1]):
                    break
            else:
                return False
        return True

    def solve(self):
        mandatory = {}
        choices = {}
        result = [0] * self.N

        for c in self.customers:
            if len(c) == 1:
                rule = c[0]
                if rule[0] in mandatory:
                    if mandatory[rule[0]] != rule[1]:
                        return None
                else:
                    mandatory[rule[0]] = rule[1]
            else:
                for rule in c:
                    if rule[1]:
                        if rule[0] not in mandatory:
                            choices[rule[0]] = True

        for key in mandatory:
            result[key - 1] = int(mandatory[key])

        if self.evaluate(result) == True:
            return result

        NC = len(choices)
        for nmalted in range(1, NC + 1):
            for c in itertools.combinations(choices, nmalted):
                r = result[:]
                for ci in c:
                    r[ci - 1] = 1
                if self.evaluate(r) == True:
                    return r

        return None

