# import necessary packages
import re
import random
import string

# Constants
LETTERS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
NONLETTERS_PATTERN = re.compile('[^A-Z^a-z]')

# Function to find repeated sequences and their spacings
def repeat_sequence(string):
    string = NONLETTERS_PATTERN.sub('', string.upper())
    seq_and_spacings = {}

    for length in range(3, 6):
        for seqStart in range(len(string) - length):
            seq = string[seqStart:seqStart + length]
            for i in range(seqStart + length, len(string) - length):
                if string[i:i + length] == seq:
                    if seq not in seq_and_spacings:
                        seq_and_spacings[seq] = []
                    seq_and_spacings[seq].append(i - seqStart)
    return seq_and_spacings

# Function to find useful factors of a number
def useful_factors(number, key_length):
    if number < 2:
        return []
    factors = []
    for i in range(2, key_length + 1):
        if number % i == 0:
            factors.append(i)
            factors.append(int(number / i))
    if 1 in factors:
        factors.remove(1)
    return factors

# Function to find the most common factors
def most_common_factors(seqFactors, max_key_length):
    factor_counts = {}
    for seq in seqFactors:
        factor_list = list(seqFactors[seq])
        for factor in factor_list:
            if factor not in factor_counts:
                factor_counts[factor] = 0
            factor_counts[factor] += 1

    factor_by_count = []
    for factor in factor_counts:
        if factor <= max_key_length:
            factor_by_count.append((factor, factor_counts[factor]))
    factor_by_count.sort(key=lambda x: x[1], reverse=True)
    return factor_by_count

# Main function to perform Kasiski Examination
def main_solution(ciphertext, max_key_length):
    repeated_seq_spacing = repeat_sequence(ciphertext)
    seq_factors = {}

    for seq in repeated_seq_spacing:
        seq_factors[seq] = []
        for spacing in repeated_seq_spacing[seq]:
            seq_factors[seq].extend(useful_factors(spacing, max_key_length))

    factors_by_count = most_common_factors(seq_factors, max_key_length)

    likely_key_lengths = [element[0] for element in factors_by_count]
    return likely_key_lengths

