import random

# all class and function definitions in the code file, if any
def makeBoard(moves):
    board = 0
    for _ in range(moves):
        board = 10 * board + 8
    return board

def digitCount(n):
    number = abs(n)
    if n == 0:
        return 1
    counter = 0
    while number != 0:
        counter += 1
        number //= 10
    return counter

def kthDigit(n, k):
    number = abs(n)
    for _ in range(k):
        number //= 10
    return number % 10

def replaceKthDigit(n, k, d):
    number = n
    kth_Digit = kthDigit(n, k)
    number = number - kth_Digit * 10**k
    replace_number = d * (10**k)
    return number + replace_number

def getLeftmostDigit(n):
    digit_number = digitCount(n)
    return kthDigit(n, digit_number - 1)

def clearLeftmostDigit(n):
    digit_number = digitCount(n)
    return replaceKthDigit(n, digit_number - 1, 0)

