    if move != 1 and move != 2:
        return "move must be 1 or 2!"
    digit_number = digitCount(board)
    if position > digit_number or position < 1:
        return "offboard!"
    kth_Digit = kthDigit(board, digit_number - position)
    if kth_Digit != 8:
