def zero_one(h):
    """A factory to create the zero-one window function."""
    d = 1./h
    def phi(x, xi):
        v = np.abs(d * (x-xi))
        if v <= 0.5:
            return 1
        else:
            return 0
    return phi

def gauss(h):
    """A factory to create the Gauss window function."""
    a = 1./np.sqrt(2*np.pi)
    b = -.5 * (1./h)**2
    def phi(x, xi):
        return a * np.exp(b * (x-xi)**2)
    return phi

