class Solution2:
    def inorderTraversal(self, root):
        """
        :type root: TreeNode
        :rtype: List[int]
        """
        res = []
        if root:
            if root.left:
                res += self.inorderTraversal(root.left)
            res.append(root.val)
            if root.right:
                res.extend(self.inorderTraversal(root.right))
        return res

class Solution:
    def generateTrees(self, n):
        """
        :type n: int
        :rtype: List[TreeNode]
        """    
        if n == 0:
            return []
        if n == 1:
            return [TreeNode(1)]

        self.hash = {}       
        return self.helper(n, 1)

    def helper(self, n, numStart):
        """
        type n: int    剩余节点数目
        type numStart: int 
        type dad；TreeNode
        rtype:List[TreeNode] 
        """
        res = []
        if n == 0:
