             '7': 5, '8': 6, '9': 7, 'T': 8, 'J': 9, 
             'Q': 10, 'K': 11, 'A': 12}

def faces(hand):
    return [i[0] for i in hand]

def suits(hand):
    return [i[1] for i in hand]

def straight(hand, royal=False):
    cards = [cardRanks[i] for i in faces(hand)]
    cards.sort()
    last = cards[0]
    for card in cards[1:]:
        if card - last != 1:
            return False
        last = card
    return not royal or cards[0] == 8

def flush(hand):
    cards = suits(hand)
    return cards.count(cards[0]) == 5

def freqs(hand):
    faceList = faces(hand)
    return [faceList.count(i) for i in faceList]

def pairs(freqCount):
    return freqCount.count(2) // 2

def handRank(hand):
    isFlush = flush(hand)
    isStraight = straight(hand, True)
    if isFlush and isStraight:
        return 9
    isStraight = straight(hand)
    if isFlush and isStraight:
        return 8
    freqCounts = freqs(hand)
    if 4 in freqCounts:
        return 7
    if 2 in freqCounts and 3 in freqCounts:
        return 6
    if isFlush:
        return 5
    if isStraight:
        return 4
    if 3 in freqCounts:
        return 3
    pairCount = pairs(freqCounts)
    return pairCount

