# import necessary packages
import math
from copy import deepcopy
import numpy as np

# Constants
X = "X"
O = "O"
EMPTY = None

# Function to initialize the board
def initial_state():
    return [[EMPTY, EMPTY, EMPTY],
            [EMPTY, EMPTY, EMPTY],
            [EMPTY, EMPTY, EMPTY]]

# Function to determine the next player
def player(board):
    flat_board = [item for sublist in board for item in sublist]
    if flat_board.count(X) == flat_board.count(O):
        return X
    else:
        return O

# Function to get all possible actions
def actions(board):
    empty_spaces = set()
    for i, row in enumerate(board):
        for j, item in enumerate(row):
            if item == EMPTY:
                empty_spaces.add((i, j))
    return empty_spaces

# Function to get the result of an action
def result(board, action):
    board_after_action = deepcopy(board)
    try:
        i, j = action
    except:
        raise Exception("action input is not in the tuple format")
    if isinstance(i, int) and isinstance(j, int):
        board_after_action[i][j] = player(board)
    else:
        raise Exception("move indexes are not integers")
    return board_after_action

# Function to check if a player is the winner
def player_is_winner(board, player):
    horizontal_win = any(all(x == player for x in row) for row in board)
    vertical_win = any(all(x == player for x in row) for row in [list(i) for i in zip(*board)])
    diagonal_win = all(x == player for x in np.diag(board)) or all(x == player for x in np.flipud(board).diagonal(0)[::-1])
    return (horizontal_win or vertical_win or diagonal_win)

# Function to determine the winner
def winner(board):
    if player_is_winner(board, X):
        return X
    if player_is_winner(board, O):
        return O
    return None

# Function to check if the game is over
def terminal(board):
    flat_board = [item for sublist in board for item in sublist]
    game_has_a_winner = (not (winner(board) == None))
    board_completely_filled = (not (None in flat_board))
    return (game_has_a_winner or board_completely_filled)

# Function to get the utility of the board
def utility(board):
    if winner(board) == X:
        return 1
    if winner(board) == O:
        return -1
    return 0

# Function to get the maximum value of a state
def max_value(board, alpha, beta):
    if terminal(board):
        return utility(board)
    value = float('-inf')
    for action in actions(board):
        value = max(value, min_value(result(board, action), alpha, beta))
        alpha = max(alpha, value)
        if alpha >= beta:
            break
    return value

# Function to get the minimum value of a state
def min_value(board, alpha, beta):
    if terminal(board):
        return utility(board)
    value = float('inf')
    for action in actions(board):
        value = min(value, max_value(result(board, action), alpha, beta))
        beta = min(beta, value)
        if alpha >= beta:
            break
    return value

# Function to get the optimal action for the current player
def minimax(board):
    if terminal(board):
        return None
    actions_to_value = {}
    if player(board) == X:
        for action in actions(board):
            actions_to_value[action] = min_value(result(board, action), float('-inf'), float('inf'))
        return max(actions_to_value, key=actions_to_value.get)
    if player(board) == O:
        for action in actions(board):
            actions_to_value[action] = max_value(result(board, action), float('-inf'), float('inf'))
        return min(actions_to_value, key=actions_to_value.get)

# main function
def main_solution(board_state):
    # Convert the input board_state to a list of lists if it's not already
    if isinstance(board_state, str):
        board_state = eval(board_state)

    # Get the optimal action for the current player
    optimal_action = minimax(board_state)

    # Return the optimal action as a tuple
    return {"optimal_action": optimal_action}

