# import necessary packages
import math
import logging
from typing import List, Tuple

# all class and function definitions in the code file, if any
class Point(object):
    """Integer Cartesian coordinates. Immutable.
    x and y coordinates are public, read-only.
    """
    def __init__(self, x: float, y: float):
        self._x = x
        self._y = y

    @property
    def x(self):
        return self._x

    @property
    def y(self):
        return self._y

    def __repr__(self):
        return f"Point({self._x}, {self._y})"

class PolyLine(object):
    """A polyline is a sequence of points.
    All fields are private.
    """
    def __init__(self, points: List[Point]):
        self._points = points
        self._listeners = []

    def __iter__(self):
        return iter(self._points)

    def __len__(self):
        return len(self._points)

    def __getitem__(self, index):
        return self._points[index]

    def __eq__(self, other):
        return self._points == other._points

    def append(self, point: Point):
        self._points.append(point)

    def add_listener(self, listener):
        self._listeners.append(listener)

    def notify_all(self, event_name: str, options={}):
        for listener in self._listeners:
            listener.notify(event_name, options=options)

    def approximate(self, epsilon: float) -> List[Point]:
        """Approximate the polyline using the Ramer-Douglas-Peucker algorithm."""
        if len(self._points) < 2:
            return self._points

        def rdp(points, epsilon):
            dmax = 0.0
            index = 0
            for i in range(1, len(points) - 1):
                d = deviation(points[0], points[-1], points[i])
                if d > dmax:
                    index = i
                    dmax = d

            if dmax >= epsilon:
                results = rdp(points[:index + 1], epsilon)[:-1] + rdp(points[index:], epsilon)
            else:
                results = [points[0], points[-1]]

            return results

        return rdp(self._points, epsilon)

def deviation(p1: Point, p2: Point, p: Point) -> float:
    """Shortest distance from point p to a line through p1,p2"""
    intercept = normal_intercept(p1, p2, p)
    dx = intercept.x - p.x
    dy = intercept.y - p.y
    return math.sqrt(dx*dx + dy*dy)

def normal_intercept(p1: Point, p2: Point, p: Point) -> Point:
    """The point at which a line through p1 and p2 intersects a normal dropped from p."""
    if p2.x == p1.x:
        return Point(p1.x, p.y)
    elif p2.y == p1.y:
        return Point(p.x, p1.y)

    seg_slope = (p2.y - p1.y) / (p2.x - p1.x)
    normal_slope = -1.0 / seg_slope

    seg_b = p1.y - seg_slope * p1.x
    normal_b = p.y - normal_slope * p.x

    x_intersect = (seg_b - normal_b) / (normal_slope - seg_slope)
    y_intersect = seg_slope * x_intersect + seg_b

    return Point(x_intersect, y_intersect)

# main function
def main_solution(points: List[Tuple[float, float]], epsilon: float) -> List[Tuple[float, float]]:
    # Convert input points to Point objects
    polyline_points = [Point(x, y) for x, y in points]
    polyline = PolyLine(polyline_points)

    # Approximate the polyline
    approximated_points = polyline.approximate(epsilon)

    # Convert the result back to a list of tuples
    result = [(point.x, point.y) for point in approximated_points]

    return result

