# import necessary packages
import random

# all class and function definitions in the code file, if any
class Score:
    def __init__(self, player_name):
        self.__squaresize = 0
        self.__player_name = player_name
        self.__score = 0
        self.__multiplier = 1
        self.__turn = False
        self.__color = 0
        self.__owned = []
        self.__lines = []

    def get_name(self):
        return self.__player_name

    def get_score(self):
        return self.__score

    def changeSquaresize(self, squaresize):
        self.__squaresize = squaresize

    def add_points(self, amount):
        self.__score += amount * self.__multiplier
        return self.__score

    def subtract_points(self, amount):
        self.__multiplier = 1
        self.__score -= amount
        if self.__score < 0:
            self.__score = 0
        return self.__score

    def get_color(self):
        return self.__color

    def change_color(self, color):
        self.__color = color

    def get_turn(self):
        return self.__turn

    def end_turn(self):
        self.__turn = False

    def begin_turn(self):
        self.__turn = True

    def getOwned(self):
        return self.__owned

    def addOwned(self, qRect):
        self.__owned.append(qRect)

    def getLines(self):
        return self.__lines

    def addLines(self, qline):
        self.__lines.append(qline)

    def get_multiplier(self):
        return self.__multiplier

    def increment_multiplier(self, number):
        self.__multiplier += number
        return self.__multiplier

    def reset_multiplier(self):
        self.__multiplier = 1


class SquareGame:
    def __init__(self, player_count, game_size):
        self.playerOne = Score("Player One")
        self.playerTwo = Score("Player Two")
        self.playerThree = Score("Player Three")
        self.playerFour = Score("Player Four")
        self.setPlayerNumber(player_count)
        self.GameSize = game_size
        self.boardChange()
        self.playerOne.begin_turn()
        self.ChangeColor()

    def setPlayerNumber(self, x):
        if x == 2:
            self.playerList = [self.playerOne, self.playerTwo]
        elif x == 3:
            self.playerList = [self.playerOne, self.playerTwo, self.playerThree]
        elif x == 4:
            self.playerList = [self.playerOne, self.playerTwo, self.playerThree, self.playerFour]
        else:
            self.playerList = [self.playerOne]

    def boardChange(self):
        self.squareSize = 600 / self.GameSize
        self.board = [[[i * self.squareSize + 10, j * self.squareSize + 10, self.squareSize, self.squareSize], 0] for i in range(self.GameSize) for j in range(self.GameSize)]
        for player in self.playerList:
            player.changeSquaresize(self.squareSize)

    def ChangeColor(self):
        colorlist = ['0ea037', 'ff66cc', '3399ff', 'ff9900']
        colorlistQ = [colorlist[i] for i in range(len(self.playerList))]
        for i, player in enumerate(self.playerList):
            player.change_color(colorlistQ[i])

    def gainPoints(self, square, player):
        value = 0
        squaresformed = 0
        owned = list(combinations(player.getOwned(), 3))
        pointsets = [[(square[0], square[1]), (comb[0][0], comb[0][1]), (comb[1][0], comb[1][1]), (comb[2][0], comb[2][1])] for comb in owned]
        for pointset in pointsets:
            result = self.pointsAreSquare(pointset, player)
            if result[0]:
                squaresformed += 1
                value += result[1]
        if squaresformed > 1:
            player.increment_multiplier(squaresformed)
        else:
            player.reset_multiplier()
        player.add_points(value)

    def pointsAreSquare(self, pointset, player):
        size = 0
        a = pointset[0]
        b = pointset[1]
        c = pointset[2]
        d = pointset[3]
        ab = self.distance(a, b)
        ac = self.distance(a, c)
        ad = self.distance(a, d)
        bc = self.distance(b, c)
        bd = self.distance(b, d)
        cd = self.distance(c, d)
        if ab == ac:
            if ab >= ad:
                return False, 0
            elif ad == bc and ab == cd and ab == bd:
                size = int((ab / self.squareSize) ** 2)
                return True, size
            else:
                return False, 0
        elif ab == ad:
            if ab >= ac:
                return False, 0
            elif ac == bd and ab == cd and bc == ab:
                size = int((ab / self.squareSize) ** 2)
                return True, size
            else:
                return False, 0
        elif ad == ac:
            if ad >= ab:
                return False, 0
            elif ab == cd and ad == bc and ad == bd:
                size = int((ac / self.squareSize) ** 2)
                return True, size
            else:
                return False, 0
        else:
            return False, 0

    def distance(self, point1, point2):
        x1, y1 = point1
        x2, y2 = point2
        return ((x1 - x2) ** 2 + (y1 - y2) ** 2) ** (1 / 2)

# main function
def main_solution(player_count, game_size, player_moves):
    game = SquareGame(player_count, game_size)
    for move in player_moves:
        for player in game.playerList:
            if player.get_turn():
                for square in game.board:
                    if square[0] == move:
                        square[1] = player.get_color()
                        game.gainPoints(square[0], player)
                        player.addOwned(square[0])
                        player.end_turn()
                        break
                else:
                    game.playerList[0].begin_turn()
                break
    scores = {player.get_name(): player.get_score() for player in game.playerList}
    return scores

