@dataclass
class Option:
    S0: int
    K: int
    r: float = 0.05
    T: int = 1
    N: int = 2
    prob_u: Optional[float] = 0
    prob_d: Optional[float] = 0
    div: Optional[float] = 0
    sigma: float = 0
