    def dt(self) -> float:
        return self.T/float(self.N)

    @property
    def df(self) -> float:
        return math.exp(-(self.r - self.div) * self.dt)

    def _define_u_and_d(self):
        raise NotImplementedError("NotImplementedError: Needs to be implemented")


