        super().__post_init__()
        self._define_u_and_d()
        self.qu = (math.exp((self.r - self.div)*self.dt) - self.d)/(self.u - self.d)
        self.qd = 1 - self.qu        

    def _define_u_and_d(self) -> None:
        self.u = math.exp(self.sigma * math.sqrt(self.dt))
        self.d = 1/self.u

