# all class and function definitions in the code file, if any
def create_gameboard(rows, columns):
    return np.zeros((rows, columns))

def drop_pieces(gameboard, rows, columns, pieces):
    gameboard[rows][columns] = pieces

def available_slot(gameboard, rows, columns):
    return gameboard[rows-1][columns] == 0

def next_open_row(gameboard, rows, columns):
    for r in range(rows):
        if gameboard[r][columns] == 0:
            return r

def winning_move(gameboard, rows, columns, pieces):
    # Check horizontal locations for win
    for c in range(columns-3):
        for r in range(rows):
            if gameboard[r][c] == pieces and gameboard[r][c+1] == pieces and gameboard[r][c+2] == pieces and gameboard[r][c+3] == pieces:
                return True

    # Check vertical locations for win
    for c in range(columns):
        for r in range(rows-3):
            if gameboard[r][c] == pieces and gameboard[r+1][c] == pieces and gameboard[r+2][c] == pieces and gameboard[r+3][c] == pieces:
                return True

    # Check positively sloped diagonals
    for c in range(columns-3):
        for r in range(rows-3):
            if gameboard[r][c] == pieces and gameboard[r+1][c+1] == pieces and gameboard[r+2][c+2] == pieces and gameboard[r+3][c+3] == pieces:
                return True

    # Check negatively sloped diagonals
    for c in range(columns-3):
        for r in range(3, rows):
            if gameboard[r][c] == pieces and gameboard[r-1][c+1] == pieces and gameboard[r-2][c+2] == pieces and gameboard[r-3][c+3] == pieces:
                return True

    return False

# main function
def main_solution(moves):
    Row_Amount = 6
    Column_Amount = 7
    gameboard = create_gameboard(Row_Amount, Column_Amount)
    player_turn = 0
    game_over = False

    for move in moves:
        if game_over:
            break
        columns = move - 1
        if available_slot(gameboard, Row_Amount, columns):
            rows = next_open_row(gameboard, Row_Amount, columns)
            drop_pieces(gameboard, rows, columns, player_turn + 1)
            if winning_move(gameboard, Row_Amount, Column_Amount, player_turn + 1):
                game_over = True
        player_turn = (player_turn + 1) % 2

    return game_over

