        curr_fall = curr_state.fallback
        fallback_found = False
        while prev_fall is not curr_fall:
            if curr_fall.level <= curr_fall.move_to(fwd_letter).level:
                add_to_mapping(curr_fall.move_to(fwd_letter), fwd_letter)
                fallback_found = True
                break
            else:
