# import necessary packages
import random

# all class and function definitions in the code file, if any
class Board:
    def __init__(self, width=7, height=6):
        self.width = width
        self.height = height
        self.data = [[' '] * width for _ in range(height)]

    def addMove(self, col, ox):
        for row in range(self.height - 1, -1, -1):
            if self.data[row][col] == ' ':
                self.data[row][col] = ox
                return

    def allowsMove(self, col):
        return 0 <= col < self.width and self.data[0][col] == ' '

    def isFull(self):
        return all(not self.allowsMove(col) for col in range(self.width))

    def winsFor(self, ox):
        for row in range(self.height):
            for col in range(self.width):
                if (self.isOX(row, col, ox) and
                    self.isOX(row + 1, col, ox) and
                    self.isOX(row + 2, col, ox) and
                    self.isOX(row + 3, col, ox)):
                    return True
                if (self.isOX(row, col, ox) and
                    self.isOX(row, col + 1, ox) and
                    self.isOX(row, col + 2, ox) and
                    self.isOX(row, col + 3, ox)):
                    return True
                if (self.isOX(row, col, ox) and
                    self.isOX(row + 1, col + 1, ox) and
                    self.isOX(row + 2, col + 2, ox) and
                    self.isOX(row + 3, col + 3, ox)):
                    return True
                if (self.isOX(row, col, ox) and
                    self.isOX(row + 1, col - 1, ox) and
                    self.isOX(row + 2, col - 2, ox) and
                    self.isOX(row + 3, col - 3, ox)):
                    return True
        return False

    def isOX(self, row, col, ox):
        return 0 <= row < self.height and 0 <= col < self.width and self.data[row][col] == ox

class Player:
    def __init__(self, ox, tbt, ply):
        self.ox = ox
        self.tbt = tbt
        self.ply = ply

    def oppCh(self):
        return 'O' if self.ox == 'X' else 'X'

    def scoreBoard(self, b):
        if b.winsFor(self.ox):
            return 100.0
        elif b.winsFor(self.oppCh()):
            return 0.0
        else:
            return 50.0

    def tiebreakMove(self, scores):
        maxScore = max(scores)
        maxIndices = [i for i, score in enumerate(scores) if score == maxScore]
        if self.tbt == 'LEFT':
            return maxIndices[0]
        elif self.tbt == 'RIGHT':
            return maxIndices[-1]
        else:
            return random.choice(maxIndices)

