        for col in range(b.width):
            if not b.allowsMove(col):
                scores[col] = -1.0
            else:
                b.addMove(col, self.ox)
                if b.winsFor(self.ox):
                    scores[col] = 100.0
                elif b.winsFor(self.oppCh()):
                    scores[col] = 0.0
                elif self.ply == 0:
                    scores[col] = 50.0
                else:
                    op = Player(self.oppCh(), self.tbt, self.ply - 1)
                    opList = op.scoresFor(b)
                    scores[col] = 100 - max(opList)
                b.data[b.height - 1][col] = ' '
        return scores

    def nextMove(self, b):
        return self.tiebreakMove(self.scoresFor(b))

# main function
def main_solution(board_width, board_height, moves):
    """
    Simulates a game of Connect Four and determines if the game is over and who won.

    Input:
    - board_width (int): The width of the board.
    - board_height (int): The height of the board.
    - moves (list of int): A list of column indices representing the moves made in the game.

    Output:
    - return (dict): A dictionary with keys 'game_over' (bool) and 'winner' (str or None).
    """
    board = Board(board_width, board_height)
    player = Player('X', 'LEFT', 2)
    current_player = 'X'

    for move in moves:
        if board.allowsMove(move):
            board.addMove(move, current_player)
            if board.winsFor(current_player):
                return {'game_over': True, 'winner': current_player}
            current_player = 'O' if current_player == 'X' else 'X'

