                    if top_row_length > bot_row_length:
                        return DOWN

                else:
                    return DOWN

            else:
                return UP

        if len(rows[0]) > min_row_length and len(results) + 1 == len(rows):
            return DOWN

    return LEFT

def build_spiral(number):
    numbers = [str(x + 1) for x in range(number)]
