# import necessary packages
import random
from functools import update_wrapper

# all class and function definitions in the code file, if any
other = {1: 0, 0: 1}

def decorator(d):
    def _d(fn):
        return update_wrapper(d(fn), fn)
    update_wrapper(_d, d)
    return _d

@decorator
def memo(f):
    cache = {}
    def _f(*args):
        try:
            return cache[args]
        except KeyError:
            cache[args] = result = f(*args)
            return result
        except TypeError:
            return f(args)
    return _f

def dierolls():
    while True:
        d = random.randint(1, 6)
        yield d

def hold(state):
    p, me, you, pending = state
    return (other[p], you, me + pending, 0)

def roll(state, d):
    p, me, you, pending = state
    if d == 1:
        state = p, me, you, 1
        return hold(state)
    else:
        return (p, me, you, pending + d)

def Q_pig(state, action, Pwin):
    if action == 'hold':
        return 1 - Pwin(hold(state))
    elif action == 'roll':
        return (1 - Pwin(roll(state, 1)) 
                + sum(Pwin(roll(state, d)) for d in range(2, 7))) / 6
    raise ValueError

def pig_actions(state):
    _, _, _, pending = state
    return ['roll', 'hold'] if pending else ['roll']

goal = 40

@memo
def Pwin(state):
    (p, me, you, pending) = state
    if me + pending >= goal:
        return 1
    elif you >= goal:
        return 0
    else:
        return max(Q_pig(state, action, Pwin) for action in pig_actions(state))

def best_action(state, actions, Q, U):
    def EU(action): return Q(state, action, U)
    return max(actions(state), key=EU)

@memo
def win_diff(state):
    (p, me, you, pending) = state
    if me + pending >= goal or you >= goal:
        return (me + pending - you)
    else:
        return max(Q_pig(state, action, win_diff)
                   for action in pig_actions(state))

def max_diffs(state):
    return best_action(state, pig_actions, Q_pig, win_diff)

def max_wins(state):
    return best_action(state, pig_actions, Q_pig, Pwin)

# main function
def main_solution(player_strategy, initial_state):
    """
    Simulates a game of Pig between two players using the given strategy for the first player.
    The second player always uses the strategy that maximizes the difference in scores.

    Args:
    player_strategy (str): The strategy to be used by the first player, either 'max_wins' or 'max_diffs'.
    initial_state (tuple): The initial state of the game (p, me, you, pending), where:
        - p (int): The current player (0 or 1).
        - me (int): The score of the current player.
        - you (int): The score of the opponent.
        - pending (int): The pending score of the current player.

    Returns:
    str: The name of the winning strategy.
    """
    strategies = {'max_wins': max_wins, 'max_diffs': max_diffs}
    A = strategies[player_strategy]
    B = max_diffs
    dierolls_gen = dierolls()

    state = initial_state
    while True:
        (p, me, you, pending) = state
        if me >= goal:
            return A.__name__
        elif you >= goal:
            return B.__name__
        else:
            action = strategies[player_strategy](state) if p == 0 else B(state)
            if action == 'hold':
                state = hold(state)
            elif action == 'roll':
                state = roll(state, next(dierolls_gen))
            else:
                return B.__name__

