        for k in range(len(self.nodes)):
            for i in range(len(self.nodes)):
                for j in range(len(self.nodes)):
                    if distmatrix[i][j] > distmatrix[i][k] + distmatrix[k][j]:
                        distmatrix[i][j] = distmatrix[i][k] + distmatrix[k][j]
