    # Convert JSON serializable input to the required format
    foods = parse_food(food_lines)

    # Core solution logic
    allergenless_count = count_allergenless(foods)
    allergen_list = find_allergen_list(foods)

    # Convert output to JSON serializable format
    return {"allergenless_count": allergenless_count, "allergen_list": allergen_list}

