                if i < m-1 and board[i+1][j] == word[cur] and dic != 'up':
                    out = find_cur(i+1, j, cur, 'down')
                    if out == True:
                        return True
                if j < n-1 and board[i][j+1] == word[cur] and dic != 'left':
                    out = find_cur(i, j+1, cur, 'right')
                    if out == True:
                        return True
                return False

