# import necessary packages
import random

# main function
def main_solution(food_list):
    # Convert the input list of strings into the required format
    food = []
    for line in food_list:
        ingr = set(line.split(' (')[0].split(' '))
        aller = set(line.split('(contains ')[1].strip(')').replace(',','').split(' '))
        food.append([ingr, aller])

    # Determine potential allergens
    allergens = {}
    for ingr, aller in food:
        for a in aller:
            if a not in allergens:
                allergens[a] = ingr
            else:
                allergens[a] = allergens[a] & ingr  # Set intersection

    # Make single set of all potential allergens
    generalAllergens = set()
    for k, v in allergens.items():
        for i in v:
            generalAllergens.add(i)

    # Count the number of instances of ingredients that are not in our general allergen set
    count = 0
    for ingr, aller in food:
        for i in ingr:
            if i not in generalAllergens:
                count += 1

    return count

