class RDTSocket:
    def __init__(self):
        self.bound_port = -1
        self.is_connected = False
        self.remote_IP = ''
        self.remote_port = -1
        self.is_listening = False
        self.waiting_connections = []  # only used by listening socket
        self.acked = True  # whether the last sent packet has been acknowledged by the other side

    def bind(self, port):
        if self.bound_port != -1:
            raise Exception("AlreadyConnected")
        if port in self.proto.ports_in_use:
            raise Exception("AddressInUse")
        self.bound_port = port
        self.proto.ports_in_use.add(port)

    def connect(self, addr):
        if self.is_connected:
            raise Exception("AlreadyConnected")
        if self.is_listening:
            raise Exception("AlreadyListening")
        if self.bound_port == -1:
            port = 1
            while port in self.proto.ports_in_use:
                port += 1
            self.bind(port)
        self.is_connected = True
        self.remote_IP = addr[0]
        self.remote_port = addr[1]
        self.proto.connections[(self.bound_port, (self.remote_IP, self.remote_port))] = self
        self.send("SYN")

