        if not self.is_connected:
            raise Exception("NotConnected")
        local_port_string = self.port_string(self.bound_port)
        remote_port_string = self.port_string(self.remote_port)
        headers = (local_port_string + remote_port_string).encode('utf-8')
        segment = headers + data.encode('utf-8')
        checksum = self.checksum(segment)
        segment = checksum + segment
        self.acked = False
        counter = 0
        while not self.acked:
            if counter == 10:
                self.acked = True
                return  # no response is likely to come; time to give up
            counter += 1
            self.proto.input(segment, self.remote_IP)

