# import necessary packages
import re
from itertools import starmap

# all class and function definitions in the code file, if any
def dist(a, b):
    return sum(starmap(lambda c1, c2: abs(c1 - c2), zip(a, b)))

class Group():
    def __init__(self, initial):
        self.points = [initial]
        self.merged = False
    def insert(self, p):
        self.points.append(p)
    def merge(self, other):
        for p in self.points:
            for p2 in other.points:
                # If any point is in constellation with any point in the other group, the groups are mergeable
                if dist(p, p2) <= 3:
                    self.points.extend(other.points)
                    other.merged = True
                    return True
        return False

    def __contains__(self, p):
        for x in self.points:
            if dist(p, x) <= 3: return True
        return False
    def __eq__(self, other):
        return self.points == other.points and self.merged == other.merged

# main function
def main_solution(points):
    # Convert the list of strings to a list of tuples of integers
    points = [tuple(map(int, re.findall(r"[-\d]+", point))) for point in points]

    # Create groups from the points
    groups = [Group(point) for point in points]

    # Merge groups until no more merges are possible
    while True:
        didsth = False
        for g in groups:
            if g.merged: continue
            for g2 in groups:
                if g2.merged or g == g2: continue
                didsth = g.merge(g2) or didsth
        groups = list(filter(lambda g: not g.merged, groups))
        if not didsth: break

    # Return the number of remaining groups
    return len(groups)

