# import necessary packages
import random

# all class and function definitions in the code file, if any
class recursive:
    @staticmethod
    def Factorial(n):
        if n == 1:
            return 1
        else:
            return n * recursive.Factorial(n - 1)

    @staticmethod
    def Hanoi(n, a='A', b='B', c='C'):
        if n == 1:
            return f'move {n} from {a} to {c}'
        else:
            return (recursive.Hanoi(n - 1, a, c, b) +
                    f'move {n} from {a} to {c}' +
                    recursive.Hanoi(n - 1, b, a, c))

    @staticmethod
    def Fibonacci(n):
        if n == 1 or n == 2:
            return 1
        else:
            return recursive.Fibonacci(n - 1) + recursive.Fibonacci(n - 2)

# main function
def main_solution(function_choice, n):
    # function_choice: int (1 for Factorial, 2 for Hanoi, 3 for Fibonacci)
    # n: int (number of disks for Hanoi, number for Factorial or Fibonacci)

    if function_choice == 1:
        result = recursive.Factorial(n)
    elif function_choice == 2:
        result = recursive.Hanoi(n)
    elif function_choice == 3:
        result = recursive.Fibonacci(n)
    else:
        raise ValueError("Invalid function choice")

    return result

