# import necessary packages
import numpy as np
import random

# all class and function definitions in the code file, if any
class Find_words_in_grid:
    def __init__(self, grid, dictionary):
        self.__bEnable_diagonal_search = False
        self.__lexicon_words, self.__lexicon_stems = self.__get_dictionary(dictionary)
        self.__InputArray = np.array(grid)
        self.__Grid = self.__make_grid(self.__InputArray)
        self.__all_valid_neighbors = self.__valid_grid_neighbors()
        self.__valid_paths = []

    def __make_grid(self, input_array):
        return {(row, col): input_array[row,col].upper()
            for row in range(input_array.shape[0])
            for col in range(input_array.shape[1])
        }

    def __get_dictionary(self, dictionary):
        all_words, all_stems = set(), set()
        for word in dictionary:
            word = word.strip().upper()
            all_words.add(word)
            for i in range(1, len(word)):
                all_stems.add(word[:i])
        return all_words, all_stems

    def __find_Neighbors(self, position):
        row, col = position
        top_left = (row - 1, col - 1)
        top_center = (row - 1, col)
        top_right = (row - 1, col + 1)
        left = (row, col - 1)
        right = (row, col + 1)
        bottom_left = (row + 1, col - 1)
        bottom_center = (row + 1, col)
        bottom_right = (row + 1, col + 1)

        with_Diagonal_Stride = [top_left, top_center, top_right, left, right, bottom_left, bottom_center, bottom_right]
        without_Diagonal_Stride = [top_center, left, right, bottom_center]

        if self.__bEnable_diagonal_search:
            return with_Diagonal_Stride
        return without_Diagonal_Stride

    def __valid_grid_neighbors(self):
        valid_neighbors = {}
        for position in self.__Grid:
            position_neighbors = self.__find_Neighbors(position)
            valid_neighbors[position] = [p for p in position_neighbors if p in self.__Grid]
        return valid_neighbors

    def __path_to_word(self, path):
        return ''.join([self.__Grid[p] for p in path])

    def enable_Diagonal_Search(self, bVal):
        self.__bEnable_diagonal_search = bVal
        self.__all_valid_neighbors = self.__valid_grid_neighbors()    

    def __do_search(self, path):
        word = self.__path_to_word(path)
        if word in self.__lexicon_words:
            self.__valid_paths.append(path)
        if word not in self.__lexicon_stems:
            return 
        for next_pos in self.__all_valid_neighbors[path[-1]]:
            if next_pos not in path:
                self.__do_search(path + [next_pos])

    def find(self):
        for position in self.__Grid:
            self.__do_search([position])
        words = []
        for path in self.__valid_paths:
            if len(self.__path_to_word(path)) == self.__InputArray.shape[0] * self.__InputArray.shape[1]:
                words.append(self.__path_to_word(path))
        return set(words)

# main function
def main_solution(grid, dictionary, enable_diagonal_search):
    # Convert JSON serializable inputs to original input variables
    grid = np.array(grid)
    dictionary = dictionary.split(',')

    # Initialize the class and find the words
    oWordPuzzle = Find_words_in_grid(grid, dictionary)
    oWordPuzzle.enable_Diagonal_Search(enable_diagonal_search)
    words = oWordPuzzle.find()

    # Convert the output to JSON serializable format
    return list(words)

