class Solution:
    def VerifySquenceOfBST(self, sequence):
        if len(sequence) == 0:
            return False
        if len(sequence) == 1:
            return True
        root = sequence[-1]
        left = []
        right = []
        i = 0
        while i < len(sequence)-1:
            if sequence[i] < root:
                left.append(sequence[i])
            else:
                break
            i += 1
        while i < len(sequence)-1:
            if sequence[i] > root:
                right.append(sequence[i])
            else:
                return False
            i += 1
        if len(left) > 0:
            if not self.VerifySquenceOfBST(left):
                return False
        if len(right) > 0:
            if not self.VerifySquenceOfBST(right):
                return False
        return True

