class Vector:
    def __init__(self, args):
        self.dimension = len(args)
        self.coordinates = args

    def __eq__(self, other):
        if self.dimension != other.dimension:
            return False
        for x, y in zip(self.coordinates, other.coordinates):
            if x != y:
                return False
        return True

    def __add__(self, other):
        cargs = []
        for x, y in zip(self.coordinates, other.coordinates):
            cargs.append(x + y)
        return Vector(cargs)

    def __sub__(self, other):
        cargs = []
        for x, y in zip(self.coordinates, other.coordinates):
            cargs.append(x - y)
        return Vector(cargs)

    def __mul__(self, other):
        if isinstance(other, Vector):
            if self.dimension != other.dimension:
                raise ValueError("Non matching vector dimensions")
            result = 0
            for x, y in zip(self.coordinates, other.coordinates):
                result += x * y
            return result

        if isinstance(other, int):
            r = []
            for value in self.coordinates:
                r.append(value * other)
            return Vector(r)

        raise ValueError("Non matching vector dimensions")

    def __rmul__(self, number):
        r = []
        for value in self.coordinates:
            r.append(value * number)
        return Vector(r)

    def magnitude(self):
        result = 0
        for value in self.coordinates:
            result += value * value
        return math.sqrt(result)

    def direction(self):
        vectormagnitude = self.magnitude()
        directionVectorCoordinates = []
        for value in self.coordinates:
            directionVectorCoordinates.append(value / vectormagnitude)
        return Vector(directionVectorCoordinates)

    def __str__(self):
        return "Vector((" + ", ".join([str(x) for x in self.coordinates]) + "))"

    def __repr__(self):
        return str(self)

    def is_orthogonal_to(self, other):
        a = 0
        for x, y in zip(self.coordinates, other.coordinates):
            a += ((int)(x * y * 1000)) / 1000
        return a == 0

    def is_parallel_to(self, other):
        a = 0
        for x, y in zip(self.coordinates, other.coordinates):
            a += ((int)(x * y * 1000)) / 1000
        b = (int(self.magnitude() * other.magnitude() * 1000)) / 1000
        return abs(a) == abs(b)

