# import necessary packages
import random

# all class and function definitions in the code file, if any
class Node:
    def __init__(self, data):
        self.value = data  # An integer
        self.smaller = None
        self.larger = None

    def __str__(self):
        return str(self.value)

class BinTree:
    def __init__(self, A=None):
        if A is None:
            self.Tvalue = None
        else:
            self.Tvalue = Node(A[0])
            for value in A[1:]:
                self.insert(value)

    def insert(self, V):
        if self.Tvalue is None:
            self.Tvalue = Node(V)
        else:
            self._insert(V, self.Tvalue)

    def _insert(self, V, node):
        if V > node.value:
            if node.larger is None:
                node.larger = Node(V)
            else:
                self._insert(V, node.larger)
        elif V < node.value:
            if node.smaller is None:
                node.smaller = Node(V)
            else:
                self._insert(V, node.smaller)

    def has_depth(self, V):
        if self.Tvalue is None:
            return 1
        return self._has_depth(1, V, self.Tvalue)

    def _has_depth(self, root, V, node):
        if V == node.value:
            return root
        if V > node.value:
            if node.larger is None:
                return root
            else:
                return self._has_depth(root + 1, V, node.larger)
        elif V < node.value:
            if node.smaller is None:
                return root
            else:
                return self._has_depth(root + 1, V, node.smaller)

# main function
def main_solution(values, search_values):
    # values: list of integers to be inserted into the binary tree
    # search_values: list of integers to search for in the binary tree
    tree = BinTree(values)
    depths = [tree.has_depth(value) for value in search_values]
    return {"depths": depths}

