    return {
        "prime_factors": prime_factors,
        "prime_numbers_up_to_n": prime_numbers_up_to_n,
        "next_prime_number": next_prime_number
    }

def next_prime(n):
    # The function provides the next prime number
    prime = False
    while not prime:
