        if self.root is None:
            return []

        q = [(self.root, 1)]
        level = 0
        result = []
        while q:
            node, lv = q.pop(0)
            if lv != level:
                level = lv
                if result:
                    result[-1] = result[-1][:-2]  # Remove trailing ', '
                result.append(f"level {lv}: ")

            result.append(f"{node.key}, ")
            if node.left:
                q.append((node.left, lv + 1))
            if node.right:
                q.append((node.right, lv + 1))

        if result:
            result[-1] = result[-1][:-2]  # Remove trailing ', '
        return ''.join(result)

