        if self.root is None:
            return []

        q = [None, self.root]
        level = 0
        result = []
        result.append(f"level {level}: ")
        while q:
            if level % 2 == 1:
                node = q.pop(0)
            else:
                node = q.pop(-1)

            if node is None:
                if q:
                    level += 1
                    if level % 2 == 1:
                        q.append(None)
                    else:
                        q.insert(0, None)
                    result.append("\n")
                    result.append(f"level {level}: ")
            else:
                result.append(f"{node.key}, ")
                if level % 2 == 1:
                    if node.left:
                        q.append(node.left)
                    if node.right:
                        q.append(node.right)
                else:
                    if node.right:
                        q.insert(0, node.right)
                    if node.left:
                        q.insert(0, node.left)

        if result:
            result[-1] = result[-1][:-2]  # Remove trailing ', '
        return ''.join(result)

# main function
