class Node(object):
    """ 二叉树基础节点
    """

    def __init__(self, value, left=None, right=None):
        self.val = value
        self.left = left
        self.right = right

    def __repr__(self):
        return str(self.val)

def is_full1(head):
    """ 通过对比每层的节点数量，判断是不是满二叉树
    """
    if not head:
        return True
    level = 0
    node_num = 0
    queue = [[head, 0]]
    while queue:
        node, cur_lv = queue.pop(0)
        if cur_lv == level:
            node_num += 1
        else:
            if node_num != 1 << level:
                return False
            node_num = 1
            level = cur_lv
        if node.left:
            queue.append([node.left, cur_lv + 1])
        if node.right:
            queue.append([node.right, cur_lv + 1])
    return node_num == 1 << level

def isFull2(head):
    info = check_full(head)
    return info['is_full']

def check_full(head):
    if not head:
        return {'is_full': True, 'hight': 0}
    left_info = check_full(head.left)
    right_info = check_full(head.right)
    hight = max(left_info['hight'], right_info['hight']) + 1
    is_full = left_info['is_full'] and right_info['is_full'] and left_info['hight'] == right_info['hight']
    return {'is_full': is_full, "hight": hight}

