# import necessary packages
import math
import copy

# Constants
X = "X"
O = "O"
EMPTY = None

# Function to initialize the board
def initial_state():
    return [[EMPTY, EMPTY, EMPTY],
            [EMPTY, EMPTY, EMPTY],
            [EMPTY, EMPTY, EMPTY]]

# Function to determine the next player
def player(board):
    if sum([i.count(EMPTY) for i in board]) % 2 == 0:
        return O
    else:
        return X

# Function to get all possible actions
def actions(board):
    possibleActions = []
    for i in range(3):
        for j in range(3):
            if board[i][j] == EMPTY:
                possibleActions.append((i, j))
    return possibleActions

# Function to get the result of an action
def result(board, action):
    copyBoard = copy.deepcopy(board)
    i, j = action
    if copyBoard[i][j] == EMPTY:
        copyBoard[i][j] = player(board)
        return copyBoard
    else:
        raise ValueError("Invalid move")

# Function to determine the winner
def winner(board):
    b = board
    for i in range(3):
        if b[i][0] == b[i][1] == b[i][2]:
            if b[i][0] == X:
                return X
            elif b[i][0] == O:
                return O
        elif b[0][i] == b[1][i] == b[2][i]:
            if b[0][i] == X:
                return X
            elif b[0][i] == O:
                return O
    if b[0][0] == b[1][1] == b[2][2]:
        if b[0][0] == X:
            return X
        elif b[0][0] == O:
            return O
    elif b[0][2] == b[1][1] == b[2][0]:
        if b[0][2] == X:
            return X
        elif b[0][2] == O:
            return O
    return None

# Function to check if the game is over
def terminal(board):
    if winner(board) is not None or len(actions(board)) == 0:
        return True
    return False

# Function to get the utility of the board
def utility(board):
    xo = winner(board)
    if xo == X:
        return 1
    elif xo == O:
        return -1
    else:
        return 0

# Function to get the optimal action using minimax
def minimax(board):
    alpha = -math.inf
    beta = math.inf
    if player(board) == X:
        bestVal = -math.inf
        for action in actions(board):
            value = MIN_value(result(board, action), alpha, beta)
            if value > bestVal:
                move = action
                bestVal = value
    elif player(board) == O:
        bestVal = math.inf
        for action in actions(board):
            value = MAX_value(result(board, action), alpha, beta)
            if value < bestVal:
                move = action
                bestVal = value
    return move

# Minimax helper functions
def MIN_value(board, alpha, beta):
    if terminal(board):
        return utility(board)
    m = math.inf
    for action in actions(board):
        m = min(m, MAX_value(result(board, action), alpha, beta))
        beta = min(beta, m)
        if beta <= alpha:
            break
    return m

def MAX_value(board, alpha, beta):
    if terminal(board):
        return utility(board)
    m = -math.inf
    for action in actions(board):
        m = max(m, MIN_value(result(board, action), alpha, beta))
        alpha = max(alpha, m)
        if beta <= alpha:
            break
    return m

