        self.diff = difficulty

    def evaluate(self, board):
        result = self.gameover(board)
        if result == -1:  # Game not over
            score = 0
            # Go through rows
            for i in range(3):
                ours, theirs, neither = self.count_pieces(board, i, 'row')
                score += self.singleScore(ours, theirs, neither)
            # Go through columns
            for i in range(3):
                ours, theirs, neither = self.count_pieces(board, i, 'col')
                score += self.singleScore(ours, theirs, neither)
            # Diagonal UL to DR
            ours, theirs, neither = self.count_pieces(board, None, 'diag1')
            score += self.singleScore(ours, theirs, neither)
            # Diagonal UR to DL
            ours, theirs, neither = self.count_pieces(board, None, 'diag2')
            score += self.singleScore(ours, theirs, neither)
            return score
        elif result == 0:  # Tie
            return 0
        elif result == self.ID:
            return 500
        else:
            return -500

    def count_pieces(self, board, index, direction):
        ours, theirs, neither = 0, 0, 0
        if direction == 'row':
            for j in range(3):
                if board[index][j] == 0:
                    neither += 1
                elif board[index][j] == self.ID:
                    ours += 1
                else:
                    theirs += 1
        elif direction == 'col':
            for j in range(3):
                if board[j][index] == 0:
                    neither += 1
                elif board[j][index] == self.ID:
                    ours += 1
                else:
                    theirs += 1
        elif direction == 'diag1':
            for i in range(3):
                if board[i][i] == 0:
                    neither += 1
                elif board[i][i] == self.ID:
                    ours += 1
                else:
                    theirs += 1
        elif direction == 'diag2':
            for i in range(3):
                if board[i][2-i] == 0:
                    neither += 1
                elif board[i][2-i] == self.ID:
                    ours += 1
                else:
                    theirs += 1
        return ours, theirs, neither

    def singleScore(self, ours, theirs, neither):
        score = 0
        if ours == 1 and neither == 2:
            score += 1
        elif ours == 2 and neither == 1:
            score += 2
        elif theirs == 1 and neither == 2:
            score -= 1
        elif theirs == 2 and neither == 1:
