def empty_board(board):
    for i in range(3):
        for j in range(3):
            if board[i][j] != EMPTY:
                return False
    return True

# Function to determine the next player
def player(board):
    if empty_board(board):
        return X
    else:
        mov_x = sum(row.count(X) for row in board)
        mov_o = sum(row.count(O) for row in board)
        return X if mov_x == mov_o else O

# Function to get all possible actions
def actions(board):
    possible_actions = {(i, j) for i in range(3) for j in range(3) if board[i][j] == EMPTY}
    return possible_actions

# Function to get the result of an action
def result(board, action):
    if action not in actions(board):
        raise Exception('Invalid action')
    i, j = action
    new_board = copy.deepcopy(board)
    new_board[i][j] = player(board)
    return new_board

# Function to determine the winner
def winner(board):
    for i in range(3):
        if board[i][0] == board[i][1] == board[i][2] != EMPTY:
            return board[i][0]
    for j in range(3):
        if board[0][j] == board[1][j] == board[2][j] != EMPTY:
            return board[0][j]
    if board[0][0] == board[1][1] == board[2][2] != EMPTY:
        return board[0][0]
    if board[0][2] == board[1][1] == board[2][0] != EMPTY:
        return board[0][2]
    return None

# Function to check if the game is over
def terminal(board):
    return len(actions(board)) == 0 or winner(board) is not None

# Function to get the utility of the board
def utility(board):
    w = winner(board)
    if w == X:
        return -1
    elif w == O:
        return 1
    else:
        return 0

# Function to get the AI's move
def moveAI(board):
    bestScore = -math.inf
    available_moves = list(actions(board))
    for move in available_moves:
        new_board = result(board, move)
        score = minimax(new_board)
        if score > bestScore:
            bestScore = score
            bestMove = move
    return bestMove

# Minimax algorithm
def minimax(board):
    if terminal(board):
        return utility(board)

    if player(board) == O:  # Maximizer player
        bestScore = -math.inf
        for move in actions(board):
            new_board = result(board, move)
            score = minimax(new_board)
            bestScore = max(score, bestScore)
        return bestScore
    else:  # Minimizer player
        worstScore = math.inf
        for move in actions(board):
            new_board = result(board, move)
            score = minimax(new_board)
            worstScore = min(score, worstScore)
        return worstScore

