# import necessary packages
import random

# all class and function definitions in the code file, if any
class Link(object):
    def __init__(self, data, next=None):
        self.data = data
        self.next = next

class CircularList(object):
    def __init__(self):
        self.first = None

    def insert(self, data):
        new_link = Link(data)
        current = self.first

        if current == None:
            self.first = new_link
            self.first.next = new_link
            return

        while current.next != self.first:
            current = current.next

        current.next = new_link
        new_link.next = self.first

    def find(self, data):
        current = self.first

        if current == None:
            return False

        while current.data != data:
            current = current.next

        return current

    def delete(self, data):
        current = self.first
        previous = self.first

        if current == None:
            return

        if self.first.data == data:
            while previous.next != self.first:
                previous = previous.next
            previous.next = current.next
            self.first = previous.next
            return current
        else:
            while current.next != self.first:
                previous = current
                current = current.next
                if current.data == data:
                    previous.next = current.next
                    return current

    def delete_after(self, start, n):
        current = self.find(start)

        if current.data == current.next.data:
            self.delete(current.data)
            return

        for i in range(n-1):
            current = current.next

        self.delete(current.data)

        return current.next

# main function
def main_solution(number_of_soldiers, starting_soldier, elimination_step):
    soldiers = CircularList()

    for i in range(1, number_of_soldiers + 1):
        soldiers.insert(i)

    start = soldiers.delete_after(starting_soldier, elimination_step)
    while soldiers.first.next != soldiers.first:
        start = soldiers.delete_after(start.data, elimination_step)

    return soldiers.first.data

