mpmath.mp.prec = 300

# all class and function definitions in the code file, if any
def dynamic_programming(func):
    map = {}
    def decorator(*args, **kwargs):
        if (func, args) in map:
            return map[(func, args)]
        else:
            r = func(*args, **kwargs)
            map[(func, args)] = r
            return r
    return decorator

@dynamic_programming
def primes(n): 
    nroot = int(sqrt(n))
    sieve = list(range(n+1))
    sieve[1] = 0

    for i in range(2, nroot+1):
        if sieve[i] != 0:
            m = n // i - i
            sieve[i*i: n+1: i] = [0] * (m+1)

    sieve = [x for x in sieve if x != 0]
    return sieve

