# import necessary packages
import random

# all class and function definitions in the code file, if any
class edge:
    def __init__(self, position, orient: int):
        # orient 0 is horizontal
        # position n means it is after row n
        self.position = position
        self.orient = orient
        self.depth = 0

class face:
    def __init__(self, x, y):
        self.initial = (x, y)
        self.xy = [x, y]
        self.depth = 0
        self.orientation = 0

    def facing(self):
        if self.orientation == 0:
            return "up"
        else:
            return "down"

    def x(self):
        return self.xy[0]

    def y(self):
        return self.xy[1]

class paper:
    def __init__(self, height, width):
        self.height = height
        self.width = width
        self.edges, self.faces = self.generate(height, width)

    def generate(self, height, width):
        edges = []
        faces = []
        for x in range(height):
            if x < height - 1:
                edges.append(edge(x, 0))
            for y in range(width):
                faces.append(face(x, y))
                if x < height - 1 and y < width - 1:
                    edges.append(edge(y, 1))
        return edges, faces

    def fold(self, edge_index, direction):
        edge = self.edges[edge_index]
        for face in self.faces:
            if edge.orient == 0:  # Horizontal fold
                if face.xy[1] > edge.position:
                    face.xy[1] -= 2 * (face.xy[1] - edge.position) - 1
                    face.orientation = 1 - face.orientation
                    if direction == "up":
                        face.depth -= 1
                    else:
                        face.depth += 1
            else:  # Vertical fold
                if face.xy[0] > edge.position:
                    face.xy[0] -= 2 * (face.xy[0] - edge.position) - 1
                    face.orientation = 1 - face.orientation
                    if direction == "up":
