# import necessary packages
from typing import List, Union
from dataclasses import dataclass

# all class and function definitions in the code file, if any
@dataclass
class VendingMachine:
    product: str
    price: int
    product_number: int = 0
    funds: int = 0

    def vend(self):
        ans = []
        if self.product_number == 0:
            ans.append("Machine is empty. Please restock.")
            if self.funds > 0:
                ans.append(f"Here is your ${self.funds}.")
        if self.product_number > 0:
            if self.funds < self.price:
                ans.append(f"You must add ${self.price - self.funds} more funds.")
            if self.price == self.funds:
                ans.append(f"Here is your {self.product}.")
                self.funds = 0
                self.product_number -= 1
            if self.funds > self.price:
                ans.append(
                    f"Here is your {self.product} and ${self.funds - self.price} change."
                )
                self.funds = 0
                self.product_number -= 1
        return " ".join(ans)

    def add_funds(self, funds: int):
        ans = []
        if self.product_number == 0:
            ans.append("Machine is empty. Please restock.")
            ans.append(f"Here is your ${funds}.")
        else:
            self.funds += funds
            ans.append(f"Current balance: ${self.funds}")
        return " ".join(ans)

    def restock(self, amount: int):
        self.product_number += amount
        return f"Current {self.product} stock: {self.product_number}"

class Link:
    empty = ()

    def __init__(self, first, rest=empty):
        assert rest is Link.empty or isinstance(rest, Link)
        self.first = first
        self.rest = rest

    def __repr__(self):
        if self.rest is not Link.empty:
            rest_repr = ", " + repr(self.rest)
        else:
            rest_repr = ""
        return "Link(" + repr(self.first) + rest_repr + ")"

    def __str__(self):
        string = "<"
        while self.rest is not Link.empty:
            string += str(self.first) + " "
            self = self.rest
        return string + str(self.first) + ">"

class Tree:
    def __init__(self, label: int, branches: List["Tree"] = []):
        for b in branches:
            assert isinstance(b, Tree)
        self.label = label
        self.branches = list(branches)

    def is_leaf(self):
        return not self.branches

    def __repr__(self):
        if self.branches:
            branch_str = ", " + repr(self.branches)
        else:
            branch_str = ""
        return "Tree({0}{1})".format(self.label, branch_str)

    def __str__(self):
        def print_tree(t: Tree, indent: int = 0):
            tree_str = "  " * indent + str(t.label) + "\n"
            for b in t.branches:
                tree_str += print_tree(b, indent + 1)
            return tree_str

        return print_tree(self).rstrip()

