# import necessary packages
from collections import defaultdict

# all class and function definitions in the code file, if any
def is_prime(n):
    if n == 2:
        return True

    if n == 1 or n % 2 == 0:
        return False

    for i in range(3, int(n**0.5)+1, 2):
        if n % i == 0:
            return False

    return True

def are_perms(n1, n2, n3):
    str_n1 = str(n1)
    str_n2 = str(n2)
    str_n3 = str(n3)

    set_n1 = set(str_n1)
    set_n2 = set(str_n2)
    set_n3 = set(str_n3)

    if set_n1 != set_n2 or set_n1 != set_n3:
        return False

    for digit in str_n1:
        if not digit in str_n2 or not digit in str_n3:
            return False

    return True

# main function
