    # all input arguments of the main_solution function should be json serializable (no self-defined objects, functions, np.array, set, tuple, etc.)
    primes = defaultdict(int)
    for i in range(start_range, end_range, 2):
        if is_prime(i):
            primes[i]

    result = []
    for p1 in primes:
        for p2 in primes:
            if p2 >= p1:
                break

            p3 = p1 + (p1 - p2)
            if p3 in primes and are_perms(p1, p2, p3):
