        def search_recursive(node, target):
            if node is None:
                return None
            if node.data == target:
                return node
            left_result = search_recursive(node.left, target)
            if left_result:
                return left_result
            return search_recursive(node.right, target)
        return search_recursive(self.root, target)

    def InsertNode(self, pNode, data):
        if pNode is None:
            raise ValueError("Parent Node Not Found.")
        current = pNode
        for value in data:
            newNode = Node(value)
            newNode.level = pNode.level + 1
            if pNode.degree == 0:
                current.left = newNode
            else:
                current.right = newNode
            pNode.degree += 1
            current = newNode

    def countNode(self):
        def count_recursive(node):
            if node is None:
                return 0
            return 1 + count_recursive(node.left) + count_recursive(node.right)
        return count_recursive(self.root)

