# import necessary packages
import datetime
import threading
import time

# all class and function definitions in the code file, if any
class Package:
    """
    A package to deliver.
    """

    def __init__(self, name):
        self.name = name
        self.worker = None
        self.delivered = False

    def assign_worker(self, worker):
        self.worker = worker

    def mark_delivered(self):
        if self.delivered:
            raise Exception(f"Package {self.name} was already delivered")

        self.delivered = True


class Worker(threading.Thread):
    """
    Worker receives packages from employer and deliver them.
    """

    def __init__(self, name, employer):
        super().__init__()
        self.setName(name)
        self.employer = employer
        self.balance = 0
        self.packages_delivered = 0

    def run(self):
        while True:
            package = self.employer.get_package_to_deliver()
            if not package:
                break

            self.deliver_package(package)
            self.employer.report_package_delivered(package)
            self.packages_delivered += 1

    def deliver_package(self, package):
        package.assign_worker(self)


class Employer:
    """
    Employer hires workers and must deliver all packages.
    """

    def __init__(self, packages_to_deliver):
        self.packages = [Package(f"package_{n + 1}") for n in range(packages_to_deliver)]
        self.balance = len(self.packages)
        self.workers = []

    def hire(self, name):
        self.workers.append(Worker(name, self))

    the_lock = threading.Lock()

    def get_package_to_deliver(self):
        with self.the_lock:
            for package in self.packages:
                if not package.delivered:
                    return package

        return None

    def get_left_to_deliver(self):
        left = 0
        for package in self.packages:
            if not package.delivered:
                left += 1

        return left

    def report_package_delivered(self, package):
        self.balance -= 1
        package.worker.balance += 1
        try:
            package.mark_delivered()
        except Exception as e:
            pass

    def deliver_all_packages(self):
        start_time = datetime.datetime.now()

        for worker in self.workers:
            worker.start()

        while self.get_left_to_deliver() > 0:
            time.sleep(1)

        for worker in self.workers:
            worker.join()

        work_duration = int((datetime.datetime.now() - start_time).total_seconds())
        total_deliveries_reported = sum(worker.packages_delivered for worker in self.workers)

        return {
            "total_packages_planned": len(self.packages),
            "total_packages_delivered": total_deliveries_reported,
            "work_duration_seconds": work_duration
        }

# main function
def main_solution(packages_to_deliver, worker_names):
    employer = Employer(packages_to_deliver)
    for name in worker_names:
        employer.hire(name)
    result = employer.deliver_all_packages()
    return result

