        self.policy_grid = [['' for _ in range(self.maze_dim)] for _ in
                            range(self.maze_dim)]
        self.UNVISITED = 0
        self.VISITED = 1
        self.DOUBLE_VISITED = 2
        self.SHORTEST = 3

