        self.rotation = 0
        self.movement = 0
        self.sensors = sensors

        if self.mode == "explore":
            self.explore()
            self.rotate()
            self.move(self.movement)

        if self.mode == "search":
            self.find_shortest_path()
            self.switch_to_race()

