    def path_is(self, value, x=None, y=None):
        if x is None:
            x = self.x
        if y is None:
            y = self.y
        return self.path_map[x][y].value == value

    def follow_path(self, direction):
        if direction == "left":
            self.rotation = -90
            self.movement = 1
        elif direction == "forward":
            self.rotation = 0
            self.movement = 1
        elif direction == "right":
            self.rotation = 90
            self.movement = 1
        else:
            self.movement = 0
            self.movement = 0

    def continue_backtracking(self):
        self.movement = 1
        direction = self.path_map[self.x][self.y].previous
        self.rotation = self.direction_to_rotation[self.heading].get(direction, 0)

    def rotate(self):
