def partition(text, startTag, endTag):
    partitions = []
    i = 0
    level = 0
    for c in text:
        if c == startTag:
            if level == 0:
                start = i
            level += 1
        if c == endTag:
            level -= 1
            if level == 0:
                partitions.append(text[start:(i+1)])
        i += 1
