            if level == 2 and not node:
                node = text[nodeStart:i]
                childStart = i
        if c == endTag:
            level -= 1
            if level == 1:
                childEnd = i + 1
                children.append(textToTree(text[childStart:childEnd], startTag, endTag))
                childStart = i+1
            if level == 0 and not node:
