        self.first = first
        self.rest = rest
    def __getitem__(self, i):
        if i == 0:
            return self.first
        else:
            return self.rest[i-1]
    def __len__(self):
        return 1 + len(self.rest)
    def __repr__(self):
        if self.rest is Link.empty:
            return 'Link({})'.format(repr(self.first))
        return 'Link({0}, {1})'.format(repr(self.first), repr(self.rest))

class Tree:
    def __init__(self, label, branches=[]):
        self.label = label
        for branch in branches:
            assert isinstance(branch, Tree)
        self.branches = list(branches)
    def __repr__(self):
        if self.branches:
            return 'Tree({0}, {1})'.format(self.label, repr(self.branches))
        else:
            return 'Tree({0})'.format(repr(self.label))
    def is_leaf(self):
        return not self.branches
    def __str__(self):
        return '\n'.join(self.indented())
    def indented(self, k=0):
        indent = []
        for b in self.branches:
            for line in b.indented(k+1):
                indent.append(' ' + line)
        return [str(self.label)] + indent

class BTree(Tree):
    empty = Tree(None)
    def __init__(self, label, left=empty, right=empty):
        for b in (left, right):
            assert isinstance(b, BTree) or b is BTree.empty
        Tree.__init__(self, label, [left, right])
    @property
    def left(self):
        return self.branches[0]
    @property
    def right(self):
        return self.branches[1]
    def is_leaf(self):
        return [self.left, self.right] == [BTree.empty] * 2
    def __repr__(self):
        if self.is_leaf():
            return 'BTree({})'.format(self.label)
        elif self.right is BTree.empty:
            return 'BTree({0}, {1})'.format(self.label, repr(self.left))
        else:
            left, right = repr(self.left), repr(self.right)
            if self.left is BTree.empty:
                left = 'BTree.empty'
            return 'BTree({0}, {1}, {2})'.format(self.label, left, right)

def set_contains(s, v):
    if s is BTree.empty:
        return False
    elif s.label == v:
        return True
    elif s.label < v:
        return set_contains(s.right, v)
    elif s.label > v:
        return set_contains(s.left, v)

def adjoin_set(s, v):
    if s is BTree.empty:
        return BTree(v)
    elif s.label == v:
        return s
    elif s.label < v:
        return BTree(s.label, s.left, adjoin_set(s.right, v))
    elif s.label > v:
        return BTree(s.label, adjoin_set(s.left, v), s.right)

def balanced_bst(s):
    if not s:
        return BTree.empty
    mid = len(s) // 2
    left = balanced_bst(s[:mid])
    right = balanced_bst(s[mid+1:])
    return BTree(s[mid], left, right)

