# all class and function definitions in the code file, if any
class Stack:
    "A container with a last-in-first-out (LIFO) queuing policy."
    def __init__(self):
        self.list = []

    def push(self, item):
        "Push 'item' onto the stack"
        self.list.append(item)

    def pop(self):
        "Pop the most recently pushed item from the stack"
        return self.list.pop()

    def isEmpty(self):
        "Returns true if the stack is empty"
        return len(self.list) == 0

class Queue:
    "A container with a first-in-first-out (FIFO) queuing policy."
    def __init__(self):
        self.list = []

    def push(self, item):
        "Enqueue the 'item' into the queue"
        self.list.insert(0, item)

    def pop(self):
        """
          Dequeue the earliest enqueued item still in the queue. This
          operation removes the item from the queue.
        """
        return self.list.pop()

    def isEmpty(self):
        "Returns true if the queue is empty"
        return len(self.list) == 0

class Moves:
    ONE = (1, 2)
    TWO = (1, 3)
    THREE = (2, 1)
    FOUR = (2, 3)
    FIVE = (3, 1)
    SIX = (3, 2)

def getLegalMoves(container1, container2, container3):
    legalMoves = []
    if (container1[1] != 0) and (container2[1] != container2[0]):
        legalMoves.append(Moves.ONE)
    if (container1[1] != 0) and (container3[1] != container3[0]):
