import re
import sys

# Define an item from the shop
Item = namedtuple('Item', 'cost damage armor')

# Function to parse boss attributes from input
def parse_boss(boss_input):
    parser = re.compile(r'\d+', re.DOTALL)
    stats = parser.findall(boss_input.strip())
    return {
        'Hit Points': int(stats[0]),
        'Damage': int(stats[1]),
        'Armor': int(stats[2]),
    }

# Function to get list of weapons
def get_weapons():
    return (
        Item(cost=8, damage=4, armor=0),   # Dagger
        Item(cost=10, damage=5, armor=0),  # Shortsword
        Item(cost=25, damage=6, armor=0),  # Warhammer
        Item(cost=40, damage=7, armor=0),  # Longsword
        Item(cost=74, damage=8, armor=0),  # Greataxe
    )

# Function to get list of armors
def get_armors():
    return (
        Item(cost=0, damage=0, armor=0),    # Nothing
        Item(cost=13, damage=0, armor=1),   # Leather
        Item(cost=31, damage=0, armor=2),   # Chainmail
        Item(cost=53, damage=0, armor=3),   # Splintmail
        Item(cost=75, damage=0, armor=4),   # Bandedmail
        Item(cost=102, damage=0, armor=5),  # Platemail
    )

# Function to get list of rings
def get_rings():
    return (
        Item(cost=0, damage=0, armor=0),    # Damage +0 (Nothing, Ring 1)
        Item(cost=25, damage=1, armor=0),   # Damage +1
        Item(cost=50, damage=2, armor=0),   # Damage +2
        Item(cost=100, damage=3, armor=0),  # Damage +3
        Item(cost=0, damage=0, armor=0),    # Defense +0 (Nothing, Ring 2)
        Item(cost=20, damage=0, armor=1),   # Defense +1
        Item(cost=40, damage=0, armor=2),   # Defense +2
        Item(cost=80, damage=0, armor=3),   # Defense +3
    )

# Function to calculate net damage
def get_damage(attacker, defender):
    net_damage = attacker['Damage'] - defender['Armor']
    return net_damage if net_damage > 1 else 1

# Function to determine if player wins the battle
def player_wins_battle(player, boss):
    player_wins = False
    player_hp, player_hit = 100, get_damage(player, boss)
    boss_hp, boss_hit = boss['Hit Points'], get_damage(boss, player)
    while player_hp > 0:
        boss_hp -= player_hit
        if boss_hp < 1:
            player_wins = True
            break
        player_hp -= boss_hit
    return player_wins

# Function to calculate player's damage and armor
def get_player(weapon, armor, ring1, ring2):
    return {
        'Damage': weapon.damage + ring1.damage + ring2.damage,
        'Armor': armor.armor + ring1.armor + ring2.armor,
    }

# Function to get all possible player equipment combinations
def get_player_equipment():
    for weapon in get_weapons():
        for armor in get_armors():
            for ring1, ring2 in combinations(get_rings(), 2):
                yield (weapon, armor, ring1, ring2)

# Main function to solve the problem
def main_solution(boss_input):
    boss = parse_boss(boss_input)
    min_cost = sys.maxsize
    max_cost = -1
    for weapon, armor, ring1, ring2 in get_player_equipment():
        cost = weapon.cost + armor.cost + ring1.cost + ring2.cost
        player = get_player(weapon, armor, ring1, ring2)
        if cost < min_cost and player_wins_battle(player, boss):
            min_cost = cost
        if cost > max_cost and not player_wins_battle(player, boss):
            max_cost = cost
    return {'min_cost': min_cost, 'max_cost': max_cost}

