import random

# all class and function definitions in the code file, if any
class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class BinaryTree:
    def __init__(self):
        self.root = None

    def to_list(self, traversal_type):
        if traversal_type == 'inorder':
            return self._inorder_traversal(self.root, [])
        raise ValueError("Traversal type must be 'inorder'")

    def _inorder_traversal(self, node, lst):
        if node:
            self._inorder_traversal(node.left, lst)
            lst.append(node.value)
            self._inorder_traversal(node.right, lst)
        return lst

class Heap(BinaryTree):
    def __init__(self, xs=None):
        super().__init__()
        if xs:
            self.insert_list(xs)

    def __repr__(self):
        return type(self).__name__ + '(' + str(self.to_list('inorder')) + ')'

    def is_heap_satisfied(self):
        if self.root:
            return Heap._is_heap_satisfied(self.root)
        return True

    @staticmethod
    def _is_heap_satisfied(node):
        left = True
        right = True
        if node is None:
            return True
        if node.left:
            left = node.value <= node.left.value and Heap._is_heap_satisfied(node.left)
        if node.right:
            right = node.value <= node.right.value and Heap._is_heap_satisfied(node.right)
        return left and right

    def insert(self, value):
        if self.root is None:
            self.root = Node(value)
        else:
            self.root = Heap._insert(self.root, value)

    @staticmethod
    def _insert(node, value):
        if node is None:
            return
        if node.left and node.right:
            node.left = Heap._insert(node.left, value)
            if node.value > node.left.value:
                return Heap.upBubble(node, value)
        if node.left is None:
            node.left = Node(value)
            if node.value > node.left.value:
                return Heap.upBubble(node, value)
        elif node.right is None:
            node.right = Node(value)
            if node.value > node.right.value:
                return Heap.upBubble(node, value)
        return node

    @staticmethod
    def upBubble(node, value):
        if Heap._is_heap_satisfied(node) == True:
            return node
        if node.left and node.left.value > node.value:
            node.left = Heap.upBubble(node.left, value)
        if node.right and node.right.value > node.value:
            node.right = Heap.upBubble(node.right, value)
        if node.left:
            if node.left.value == value:
                t1 = node.value
                t2 = node.left.value
                node.value = t2
                node.left.value = t1
        if node.right:
            if node.right.value == value:
                t1 = node.value
                t2 = node.right.value
                node.value = t2
                node.right.value = t1
        return node

    def insert_list(self, xs):
        for item in xs:
            self.insert(item)

    def find_smallest(self):
        return self.root.value

    def remove_min(self):
        if self.root is None:
            return None
        elif self.root.left is None and self.root.right is None:
            self.root = None
        else:
            right = Heap.findright(self.root)
            self.root = Heap._remove(self.root)
            if right == self.root.value:
                return
            else:
                self.root.value = right
            if Heap._is_heap_satisfied(self.root) == False:
                return Heap.downBubble(self.root)

