# import necessary packages
import json

# all class and function definitions in the code file, if any
class Stack():
    def __init__(self):
        self.items = []

    def isEmpty(self):
        return self.items == []

    def peek(self):
        return self.items[-1]

    def push(self, item):
        self.items.append(item)

    def pop(self):
        return self.items.pop()

    def size(self):
        return len(self.items)

    def __str__(self):
        return str(self.items)

class InvalidTagException(Exception):
    def __init__(self, tag):
        self.tag = tag

class EmptyStackException(Exception):
    def __init__(self, tag):
        self.tag = tag

def getTag(file_content):
    tags = []
    i = 0
    while i < len(file_content):
        if file_content[i] == "<":
            tag = ""
            i += 1
            while i < len(file_content) and file_content[i] != ">" and not file_content[i].isspace():
                tag += file_content[i]
                i += 1
            tags.append(tag)
        i += 1
    return tags

# main function
def main_solution(html_content):
    # Convert the input string to a list of tags
    tags = getTag(html_content)

    # Initialize the stack and other variables
    tagStack = Stack()
    EXCEPTIONS = ["br", "meta", "hr"]
    VALIDTAGS = []

    # Process each tag
    for tag in tags:
        try:
            if tag[0] != "/":
                if tag in EXCEPTIONS:
                    continue
                tagStack.push(tag)
                if tag not in VALIDTAGS:
                    VALIDTAGS.append(tag)
            else:
                if not tagStack.isEmpty():
                    if tag[1:] == tagStack.peek():
                        tagStack.pop()
                    else:
                        raise InvalidTagException(tag)
                else:
                    raise EmptyStackException(tag)
        except InvalidTagException as it:
            return {"status": "error", "message": f"Error: tag is {it.tag} but top of stack is {tagStack.peek()}"}
        except EmptyStackException as es:
            return {"status": "error", "message": "Error: stack is empty but remaining closing tags"}

    # Check if the stack is empty
    if tagStack.isEmpty():
        return {"status": "success", "message": "Processing complete. No mismatches found"}
    else:
        return {"status": "error", "message": f"Processing complete. Unmatched tags remain on stack: {str(tagStack)}"}

