import hashlib
import json
from time import time
import random

# all class and function definitions in the code file, if any
class Blockchain(object):
    def __init__(self):
        self.chain = []
        self.current_transactions = [{}]
        self.new_block(previous_hash=1, proof=100)

    def new_block(self, proof, previous_hash=None):
        for transaction in self.current_transactions:
            block = {
                'index': len(self.chain) + 1,
                'timestamp': time(),
                'transactions': transaction,
                'proof': proof,
                'previous_hash': previous_hash or self.block_hash(self.chain[-1]),
            }
            self.chain.append(block)
        self.current_transactions = []

    def new_transaction(self, client, domain_name, zone_file_hash):
        self.current_transactions.append({
            'client': client,
            'domain_name': domain_name,
            'zone_file_hash': zone_file_hash
        })
        return self.last_block['index'] + 1

    def proof_of_work(self, previous_hash):
        proof = 0
        while not self.valid_proof(previous_hash, proof):
            proof += 1
        return proof

    def verify_blockchain(self, chain):
        last_block = chain[1]
        current_index = 2
        while current_index < len(chain):
            block = chain[current_index]
            if block['previous_hash'] != self.block_hash(last_block):
                return False
            if not self.valid_proof(last_block['previous_hash'], last_block['proof']):
                return False
            last_block = block
            current_index += 1
        return True

    def verify_block(self, block):
        if not self.valid_proof(block['previous_hash'], block['proof']):
            return False
        return True

    @staticmethod
    def valid_proof(previous_hash, proof):
        guess_hash = hashlib.sha256(f'{previous_hash} * {proof}'.encode()).hexdigest()
        return guess_hash[:4] == "0000"

    @staticmethod
    def block_hash(block):
        block_string = json.dumps(block, sort_keys=True).encode()
        return hashlib.sha256(block_string).hexdigest()

    @property
    def last_block(self):
        return self.chain[-1]

# main function
def main_solution(client, domain_name, zone_file_hash):
    blockchain = Blockchain()
    blockchain.new_transaction(client, domain_name, zone_file_hash)
    previous_hash = blockchain.last_block['previous_hash']
    proof = blockchain.proof_of_work(previous_hash)
    blockchain.new_block(proof, previous_hash)
    return blockchain.verify_blockchain(blockchain.chain)

