class fuel_management_circuit:
    def __init__(self):
        self.wires = []
        self.intersections = []

    def add_wire(self, wire):
        self.wires.append(wire)

    def find_direction_between_positions(self, start_position, end_position):
        return tuple(map(operator.sub, end_position, start_position))

    def is_move_horizontal(self, direction):
        return direction[0] != 0 and direction[1] == 0

    def is_move_vertical(self, direction):
        return direction[0] == 0 and direction[1] != 0

    def are_moves_perpendicular(self, direction_wire1, direction_wire2):
        return (self.is_move_horizontal(direction_wire1) and self.is_move_vertical(direction_wire2)) or \
               (self.is_move_horizontal(direction_wire2) and self.is_move_vertical(direction_wire1))

    def find_intersection_if_perpendicular_directions(self, start_position_vertical_wirepiece, start_position_horizontal_wirepiece):
        return (start_position_vertical_wirepiece[0], start_position_horizontal_wirepiece[1])

    def is_valid_perpendicular_intersection(self, intersection, start_position_vertical_wirepiece, end_position_vertical_wirepiece, start_position_horizontal_wirepiece, end_position_horizontal_wirepiece):
        is_on_horizontal_wirepiece = self.is_coordinate_on_wirepiece(intersection, start_position_horizontal_wirepiece, end_position_horizontal_wirepiece)
        is_on_vertical_wirepiece = self.is_coordinate_on_wirepiece(intersection, start_position_vertical_wirepiece, end_position_vertical_wirepiece)
        return is_on_horizontal_wirepiece and is_on_vertical_wirepiece

    def is_coordinate_on_wirepiece(self, coordinate, start_position_wirepiece, end_position_wirepiece):
        direction_wirepiece = self.find_direction_between_positions(start_position_wirepiece, end_position_wirepiece)
        if self.is_move_horizontal(direction_wirepiece):
            return self.is_coordinate_on_horizontal_wirepiece(coordinate, start_position_wirepiece, end_position_wirepiece)
        elif self.is_move_vertical(direction_wirepiece):
            return self.is_coordinate_on_vertical_wirepiece(coordinate, start_position_wirepiece, end_position_wirepiece)
        return False

    def is_coordinate_on_horizontal_wirepiece(self, coordinate, start_position_wire, end_position_wire):
        min_x = min(start_position_wire[0], end_position_wire[0])
        max_x = max(start_position_wire[0], end_position_wire[0])
        return min_x <= coordinate[0] <= max_x and coordinate[1] == start_position_wire[1] and coordinate[1] == end_position_wire[1]

    def is_coordinate_on_vertical_wirepiece(self, coordinate, start_position_wire, end_position_wire):
        min_y = min(start_position_wire[1], end_position_wire[1])
        max_y = max(start_position_wire[1], end_position_wire[1])
        return min_y <= coordinate[1] <= max_y and coordinate[0] == start_position_wire[0] and coordinate[0] == end_position_wire[0]

    def calc_manhattan_distance(self, point1, point2):
        return abs(point1[0] - point2[0]) + abs(point1[1] - point2[1])

# main function
def main_solution(wire1, wire2):
    circuit = fuel_management_circuit()

    # Convert input to the required format
    positions_wire1 = [(0, 0)] + wire1
    positions_wire2 = [(0, 0)] + wire2

    circuit.add_wire(positions_wire1)
    circuit.add_wire(positions_wire2)

    intersections = []

    for i in range(len(positions_wire1) - 1):
        for j in range(len(positions_wire2) - 1):
            start1, end1 = positions_wire1[i], positions_wire1[i + 1]
            start2, end2 = positions_wire2[j], positions_wire2[j + 1]

            direction1 = circuit.find_direction_between_positions(start1, end1)
            direction2 = circuit.find_direction_between_positions(start2, end2)

            if circuit.are_moves_perpendicular(direction1, direction2):
                if circuit.is_move_vertical(direction1):
                    intersection = circuit.find_intersection_if_perpendicular_directions(start1, start2)
                    if circuit.is_valid_perpendicular_intersection(intersection, start1, end1, start2, end2):
                        intersections.append(intersection)
                else:
                    intersection = circuit.find_intersection_if_perpendicular_directions(start2, start1)
                    if circuit.is_valid_perpendicular_intersection(intersection, start2, end2, start1, end1):
                        intersections.append(intersection)

    # Calculate Manhattan distances for all intersections
    distances = [circuit.calc_manhattan_distance((0, 0), intersection) for intersection in intersections]

    # Return the minimum distance
    return min(distances) if distances else 0

