# main function
def main_solution(class_diagram):
    """
    Determines whether a given class diagram contains a diamond inheritance.

    Args:
        class_diagram (list of list of int): A list where each element is a list representing a class and its inheritance.
            The first element of each inner list is the number of classes it inherits from, followed by the class numbers it inherits from.

    Returns:
        str: 'Yes' if the class diagram contains a diamond inheritance, otherwise 'No'.
    """
    G = {}
    for i in range(len(class_diagram)):
        G[i + 1] = class_diagram[i][1:]

    def next_node(u):
        if u in G:
            for v in G[u]:
                yield v

    def DFS(S, next_node):
        L = [(S, 0)]
        seen = {S: S}
        while L:
            u, d = L.pop()
            for v in next_node(u):
                if v not in seen:
                    seen[v] = u
                    L.append((v, d + 1))
                else:
                    return True
        return False

    for u in G:
        if DFS(u, next_node):
            return 'Yes'
    return 'No'

