            count = 0
            value = ''
            for box in unit:
                if possibility in values[box]:
                    count += 1
                    if count == 1:
                        value = box
            if count == 1:
                values = assign_value(values, value, possibility)
    return values

def reduce_puzzle(values):
    """Iterate eliminate() and only_choice()."""
    stalled = False
    while not stalled:
