# import necessary packages
from typing import List, Optional

# Definition for a binary tree node.
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

# all class and function definitions in the code file, if any
class Solution:
    def find(self, root1: Optional[TreeNode], root2: Optional[TreeNode]) -> bool:
        if not root1 and not root2:
            return True
        if (not root1 and root2) or (not root2 and root1) or (root1.val != root2.val):
            return False
        return self.find(root1.left, root2.right) and self.find(root1.right, root2.left)

    def isSymmetric(self, root: Optional[TreeNode]) -> bool:
        if not root:
            return True
        return self.find(root.left, root.right)

# main function
def main_solution(tree_structure: List[Optional[int]]) -> bool:
    # Convert the list representation of the tree to a TreeNode structure
    def list_to_tree(tree_list: List[Optional[int]]) -> Optional[TreeNode]:
        if not tree_list:
            return None
        nodes = [TreeNode(val) if val is not None else None for val in tree_list]
        n = len(nodes)
        for i in range(n):
            if nodes[i] is not None:
                left_child = 2 * i + 1
                right_child = 2 * i + 2
                if left_child < n:
                    nodes[i].left = nodes[left_child]
                if right_child < n:
                    nodes[i].right = nodes[right_child]
        return nodes[0]

    root = list_to_tree(tree_structure)
    solution = Solution()
    return solution.isSymmetric(root)

