    board = Board(board_length)
    if initial_shape == 'T':
        movement = start_t_move(board_length)
    elif initial_shape == '1':
        movement = start_1_move(board_length)
    elif initial_shape == 'L':
        movement = start_L_move(board_length)
    else:
        raise Exception("Invalid initial shape")

    # Perform moves
    for move in moves:
        movement = make_the_board_move(movement, move)
        if not board.validate_movement(movement):
            return "Game Over"
        if board.check_for_collision(movement):
            return "Game Over"
        board.make_move(movement)

    # Convert output to JSON serializable
    return "Continue"

