# all class and function definitions in the code file, if any
class ChessBoard:
    size = 8

    def __init__(self, pieces):
        self.board = [[{} for _ in range(8)] for _ in range(8)]
        self.count_black_pieces = 0
        self.count_white_pieces = 0
        count = 0
        for piece in pieces:
            self._addChessPiece(count, piece['colour'], piece['type'])
            count += 1
            if piece['colour'] == 'BLACK':
                self.count_black_pieces += 1
            else:  # piece['colour'] == 'WHITE'
                self.count_white_pieces += 1
        for row in self.board:
            for piece in row:
                if piece != {}:
                    self._setPieceHeuristic(piece)

    def _addChessPiece(self, id, colour, type):
        row = id // self.size
        col = id % self.size
        piece = {
            'id': id,
            'type': type,
            'colour': colour,
            'heuristic_same': 0,
            'heuristic_diff': 0,
            'location': (row, col)
