        while (col < self.size) and (board[row][col] == {}):
            col += 1
        if (col < self.size) and (board[row][col]['colour'] == colour):
            count += 1
        return count

    def _countDiagonalAttack(self, board, position, colour):
        count = 0
        row = position[0]
        col = position[1]
        # check NORTH-EAST
        row -= 1
        col += 1
        while (row >= 0) and (col < self.size) and (board[row][col] == {}):
            row -= 1
