        if (row >= 0) and (col < self.size) and (board[row][col]['colour'] == colour):
            count += 1
        row = position[0]
        col = position[1]
        # check NORTH-WEST
        row -= 1
        col -= 1
        while (row >= 0) and (col >= 0) and (board[row][col] == {}):
            row -= 1
            col -= 1
        if (row >= 0) and (col >= 0) and (board[row][col]['colour'] == colour):
