# import necessary packages
import random

# all class and function definitions in the code file, if any
class DrugNode(object):
    def __init__(self, UId, availCount):
        self.UId = UId
        self.avCount = availCount
        self.chkoutCtr = 1
        self.left = None
        self.right = None
        self.height = 1

class AVL_Tree(object):
    def _readDrugList(self, root, UId, availCount):
        if not root:
            return DrugNode(UId, availCount)
        elif UId == root.UId:
            self._updateDrugList(root, UId, availCount)
            return root
        elif UId < root.UId:
            root.left = self._readDrugList(root.left, UId, availCount)
        else:
            root.right = self._readDrugList(root.right, UId, availCount)

        root.height = 1 + max(self.getHeight(root.left), self.getHeight(root.right))
        balance = self.getBalance(root)

        if balance > 1 and UId < root.left.UId:
            return self.rightRotate(root)
        if balance < -1 and UId > root.right.UId:
            return self.leftRotate(root)
        if balance > 1 and UId > root.left.UId:
            root.left = self.leftRotate(root.left)
            return self.rightRotate(root)
        if balance < -1 and UId < root.right.UId:
            root.right = self.rightRotate(root.right)
            return self.leftRotate(root)

        return root

    def leftRotate(self, z):
        y = z.right
        T2 = y.left
        y.left = z
        z.right = T2
        z.height = 1 + max(self.getHeight(z.left), self.getHeight(z.right))
        y.height = 1 + max(self.getHeight(y.left), self.getHeight(y.right))
        return y

    def rightRotate(self, z):
        y = z.left
        T3 = y.right
        y.right = z
        z.left = T3
        z.height = 1 + max(self.getHeight(z.left), self.getHeight(z.right))
        y.height = 1 + max(self.getHeight(y.left), self.getHeight(y.right))
        return y

    def getHeight(self, root):
        if not root:
            return 0
        return root.height

    def getBalance(self, root):
        if not root:
            return 0
        return self.getHeight(root.left) - self.getHeight(root.right)

    def _updateDrugList(self, DrugNode, UId, availCount):
        if not DrugNode:
            return 0
        elif UId == DrugNode.UId:
            DrugNode.chkoutCtr += 1
            if DrugNode.chkoutCtr % 2 != 0:
                DrugNode.avCount += availCount
            else:
                if DrugNode.avCount >= availCount:
                    DrugNode.avCount -= availCount
                else:
                    print("Sorry - Not Enough Quantities available to Sell -- From the command updateDrugList: {0}, {1}".format(UId, availCount))
            return 1
        elif UId < DrugNode.UId:
            return self._updateDrugList(DrugNode.left, UId, availCount)
        else:
            return self._updateDrugList(DrugNode.right, UId, availCount)

    def _checkDrugStatus(self, DrugNode, UId):
        if not DrugNode:
            return False
        if DrugNode.UId == UId:
            return {
                "UId": DrugNode.UId,
                "chkoutCtr": DrugNode.chkoutCtr,
                "avCount": DrugNode.avCount
            }
        elif UId < DrugNode.UId:
            return self._checkDrugStatus(DrugNode.left, UId)
        else:
            return self._checkDrugStatus(DrugNode.right, UId)

# main function
def main_solution(drug_entries, check_status_UId):
    """
    Main function to manage drug inventory and check drug status.

    Args:
        drug_entries (list of tuples): List of tuples where each tuple contains a drug's UId and availCount.
        check_status_UId (int): The UId of the drug to check the status for.

    Returns:
        dict: A dictionary containing the status of the drug with the given UId.
    """
    myTree = AVL_Tree()
    root = None

    for UId, availCount in drug_entries:
        root = myTree._readDrugList(root, UId, availCount)

    status = myTree._checkDrugStatus(root, check_status_UId)
    if not status:
        return {"status": "Drug id {0} does not exist.".format(check_status_UId)}
    return status

