class TreeNode:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def TreeDepth(root):
    if root is None:
        return 0
    left = TreeDepth(root.left)
    right = TreeDepth(root.right)
    return max(left + 1, right + 1)

def bst_init(List):
    if len(List) == 0:
        return None
    root = TreeNode(List[0])
    for i in range(1, len(List)):
        bst_append(root, List[i])
    return root

