    while root is not None and root.val != val:
        if val < root.val and root.left is not None:
            root = root.left
        elif val > root.val and root.right is not None:
            root = root.right
        else:
            break
    if root is None or root.val == val:
        return False
    new_node = TreeNode(val)
    if val < root.val:
        root.left = new_node
    elif val > root.val:
        root.right = new_node
    return True

