# import necessary packages
from abc import ABC, abstractmethod

# all class and function definitions in the code file, if any
class Graph(ABC):

    def __init__(self, unproc_nodes=[], dict_graph={}):
        if unproc_nodes and dict_graph:
            raise ValueError("Cannot have both a list of nodes and a graph of nodes as arguments for the Graph Constructor")

        if dict_graph:
            self._graph = dict_graph
            self._num_nodes = len(self._graph)
        else:
            self._graph = self.build_graph(unproc_nodes)

    @property
    def graph(self):
        return self._graph

    @property
    def size(self):
        return self._num_nodes

    @abstractmethod
    def build_graph(self, nodes_list=[]):
        pass

    @abstractmethod
    def add_node(self, node, arc):
        pass

    @abstractmethod
    def del_node(self, node):
        pass

class UndirGraph(Graph):

    def __init__(self, unproc_nodes=[], graph_dict={}):
        super().__init__(unproc_nodes)

    def build_graph(self, node_list):
        graph = {}
        self._num_nodes = 0

        for vertex in node_list:
            self._num_nodes += 1
            graph[vertex] = []

        return graph

    def add_node(self, node, arc=[]):
        if node in self._graph:
            self._graph[node].extend(arc)
        else:
            self._graph[node] = arc
            self._num_nodes += 1

    def del_node(self, node):
        if node in self._graph:
            del self._graph[node]
            self._num_nodes -= 1

