from datetime import datetime, timedelta
from dateutil import tz

# main function
def main_solution(datetime_str, tz_list, operation):
    """
    Converts a given naive datetime string to multiple time zones and performs a specified operation on the datetime.

    Parameters:
    datetime_str (str): A naive datetime string in the format 'YYYY-MM-DD HH:MM:SS'.
    tz_list (list of str): A list of timezone strings (e.g., ['America/New_York', 'Europe/London']).
    operation (str): The operation to perform on the datetime. Options are 'wall_add', 'wall_sub', 'absolute_add', 'absolute_sub'.

    Returns:
    dict: A dictionary where keys are timezone strings and values are the resulting datetime strings after the specified operation.
    """
    # Convert the input datetime string to a datetime object
    dt = datetime.strptime(datetime_str, '%Y-%m-%d %H:%M:%S')

    # Initialize the result dictionary
    result = {}

    # Perform the specified operation for each timezone
    for tzstr in tz_list:
        # Localize the datetime to the specified timezone
        localized_dt = dt.replace(tzinfo=tz.gettz(tzstr))

        # Perform the operation
        if operation == 'wall_add':
            new_dt = wall_add(localized_dt, timedelta(hours=1))
        elif operation == 'wall_sub':
            new_dt = wall_sub(localized_dt, timedelta(hours=1))
        elif operation == 'absolute_add':
            new_dt = absolute_add(localized_dt, timedelta(hours=1))
        elif operation == 'absolute_sub':
            new_dt = absolute_sub(localized_dt, timedelta(hours=1))
        else:
            raise ValueError("Invalid operation specified")

        # Convert the resulting datetime to a string and store in the result dictionary
        result[tzstr] = new_dt.strftime('%Y-%m-%d %H:%M:%S')

    return result

# Helper functions from the original code file
def wall_add(dt: datetime, offset: timedelta) -> datetime:
    """Addition with "wall-time" semantics"""
    return dt + offset

def wall_sub(dt: datetime, other: datetime) -> timedelta:
    """Subtraction with "wall time" semantics"""
    if isinstance(other, timedelta):
        return wall_add(dt, -1 * other)
    return dt.replace(tzinfo=None) - other.replace(tzinfo=None)

def absolute_add(dt: datetime, offset: timedelta) -> datetime:
    """Addition with "absolute time" semantics"""
    return (dt.astimezone(tz.UTC) + offset).astimezone(dt.tzinfo)

def absolute_sub(dt: datetime, other: datetime) -> timedelta:
    if isinstance(other, timedelta):
        return absolute_add(dt, -1 * other)
