def is_graph(g):
    if type(g) is not list:
        return False
    n = len(g)
    for adjl in g:
        if type(adjl) is not list:
            return False
        for v in adjl:
            if type(v) is not int:
                return False
            if v < 0 or v >= n:
                return False
        if adjl != sorted(list(set(adjl))):
            return False
    for v1 in range(n):
        if v1 in g[v1]:
            return False
        for v2 in range(v1):
            e12 = v2 in g[v1]
            e21 = v1 in g[v2]
            if e12 != e21:
                return False
    return True

def graphs(n):
    assert n >= 0
    if n <= 2:
        if n == 0:
            yield []
            return
        if n == 1:
            yield [[]]
            return
        if n == 2:
            yield [[], []]
            yield [[1], [0]]
            return
    alledges = ((j, i) for i in range(n) for j in range(i))
    for edges in powerset(itertools.islice(alledges, 2, None)):
        g = [[] for v in range(n)]
        for e in edges:
            g[e[0]].append(e[1])
            g[e[1]].append(e[0])
        yield g
        g2 = g[:]
        g2[0] = [1] + g2[0]
        g2[1] = [0] + g2[1]
        yield g2
        g3 = g[:]
        g3[0] = [2] + g3[0]
        g3[2] = [0] + g3[2]
        yield g3
        g4 = g3[:]
        g4[0] = [1] + g4[0]
        g4[1] = [0] + g4[1]
        yield g4

def clique_number(g):
    def clique_number_with(g, n, s, v):
        for x in range(v, n):
            for z in s:
                if z not in g[x]:
                    break
            else:
                if x + 1 == n:
                    return len(s) + 1
                c1 = clique_number_with(g, n, s, x + 1)
                s.append(x)
                c2 = clique_number_with(g, n, s, x + 1)
                s.pop()
                return max(c1, c2)
        return len(s)

    n = len(g)
    if n < 2:
        return n
    return clique_number_with(g, n, [], 0)

# main function
def main_solution(graph_order):
    # Generate all graphs of the given order
    all_graphs = list(graphs(graph_order))

    # Filter out invalid graphs
    valid_graphs = [g for g in all_graphs if is_graph(g)]

    # Calculate the clique number for each valid graph
    clique_numbers = [clique_number(g) for g in valid_graphs]

    # Return the maximum clique number found
    return max(clique_numbers)

