# import necessary packages
import random

# all class and function definitions in the code file, if any
def cross(A, B):
    "Cross product of elements in A and elements in B."
    return [a+b for a in A for b in B]

def parse_grid(grid):
    """Convert grid to a dict of possible values, {square: digits}, or
    return False if a contradiction is detected."""
    values = dict((s, digits) for s in squares)
    for s,d in grid_values(grid).items():
        if d in digits and not assign(values, s, d):
            return False
    return values

def grid_values(grid):
    return dict(zip(squares, grid))

def assign(values, s, d):
    other_values = values[s].replace(d, '')
    if all(eliminate(values, s, d2) for d2 in other_values):
        return values
    else:
        return False

def eliminate(values, s, d):
    if d not in values[s]:
        return values
    values[s] = values[s].replace(d,'')
    if len(values[s]) == 0:
        return False
    elif len(values[s]) == 1:
        d2 = values[s]
        if not all(eliminate(values, s2, d2) for s2 in peers[s]):
            return False
    elif len(values[s]) == 2:
        t = values[s]
        for s2 in peers[s]:
            if t == values[s2]:
                uns = [x for x in unitlist if t in x and s2 in x]
                for u in uns:
                    if not all(eliminate(values, s3, t[:1]) for s3 in u):
                        return False
                    if not all(eliminate(values, s3, t[1:]) for s3 in u):
                        return False
    for u in units[s]:
        dplaces = [s for s in u if d in values[s]]
        if len(dplaces) == 0:
            return False
        elif len(dplaces) == 1:
            if not assign(values, dplaces[0], d):
                return False
    return values

def search(values):
    if values is False:
        return False
    if all(len(values[s]) == 1 for s in squares): 
        return values
    n,s = min((len([x for x in peers[s] if len(values[x]) > 1]), s) for s in squares if len(values[s]) > 1)
    return some(search(assign(values.copy(), s, d)) for d in values[s])

def some(seq):
    for e in seq:
        if e: return e
    return False

def init_vars(N):
    global digits, rows, cols, rblocks, cblocks, squares, unitlist, units, peers
    N2 = N**2
    digits   = ''.join([chr(c) for c in range(98, 98 + N2)])
    rows     = ''.join([chr(c) for c in range(65, 65 + N2)])
    cols     = digits
    rblocks  = [rows[i * N : i * N + N] for i in range(0, N)]
    cblocks  = [cols[i * N : i * N + N] for i in range(0, N)]
    squares  = cross(rows, cols)
    unitlist = ([cross(rows, c) for c in cols] +
                [cross(r, cols) for r in rows] +
                [cross(rs, cs) for rs in rblocks for cs in cblocks])
    units    = dict((s, [u for u in unitlist if s in u]) 
                    for s in squares)
    peers    = dict((s, set(sum(units[s],[]))-set([s]))
                    for s in squares)

