    init_vars(N)

    # Convert puzzle to a list of characters
    puzzle = [chr(int(x) + 97) for x in puzzle]

    # Solve the puzzle
    solution = search(parse_grid(puzzle))

    # Convert solution to a list of integers
    if solution:
        solution = [ord(solution[s]) - 97 for s in squares]
    else:
        solution = []

    return solution

