    m = []
    for i in range(len(matrix[0])):
        l1 = []
        for arr in matrix:
            l1.append(arr[i])
        m.append(l1)
    return m

def determinant(matrix):
    """calculates the determinant of a matrix"""
    if len(matrix) == 1:
        return matrix[0][0]
    if len(matrix) == 2:
