class TicTacToe:
    PLAYER_ONE = 0
    PLAYER_TWO = 1
    NO_WINNER = -1

    def __init__(self):
        self.currentBoard = [' ']*9
        self.playerOneMoves = []
        self.playerTwoMoves = []
        self.allMoves = []
        self.currentPlayer = TicTacToe.PLAYER_ONE

    def get_num_moves(self):
        return len(self.allMoves)

    def get_available_moves(self):
        return [index for index, value in enumerate(self.currentBoard) if value == ' ']

    def add_move(self, moveIndex: int):
        if self.currentPlayer == TicTacToe.PLAYER_ONE:
            self.playerOneMoves.append(moveIndex)
            symbol = 'x'
        else:
            self.playerTwoMoves.append(moveIndex)
            symbol = 'o'
        self.allMoves.append(moveIndex)
        self.currentBoard[moveIndex] = symbol
        self.currentPlayer = (self.currentPlayer + 1) % 2

    def check_win(self):
        winningCombos = [[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]]
        winner = TicTacToe.NO_WINNER
        over = (len(self.allMoves) == 9)
        for combo in winningCombos:
            if set(combo).issubset(self.playerOneMoves):
                winner, over = TicTacToe.PLAYER_ONE, True
            elif set(combo).issubset(self.playerTwoMoves):
                winner, over = TicTacToe.PLAYER_TWO, True
        return winner, over

    def minimax(self, maximize: bool):
        bestScore = None
        bestMove = None
        winner, isOver = self.check_win()
        if isOver:
            numMoves = self.get_num_moves()
            bestMove = self.allMoves[-1]
            if winner == TicTacToe.PLAYER_ONE:
                bestScore = numMoves - 10
            elif winner == TicTacToe.PLAYER_TWO:
                bestScore = 10 - numMoves
            else:
                bestScore = 0
        else:
            moves = []
            scores = []
            for possibleMove in self.get_available_moves():
                possibleGame = copy.deepcopy(self)
                possibleGame.add_move(possibleMove)
                nextMove, nextScore = possibleGame.minimax(not maximize)
                scores.append(nextScore)
                if maximize:
                    moves.append(possibleMove)
                else:
                    moves.append(nextMove)
            if maximize:
                bestScore = max(scores)
            else:
                bestScore = min(scores)
            bestMove = moves[scores.index(bestScore)]
        return bestMove, bestScore

# main function
def main_solution(moves: list):
    game = TicTacToe()
    for move in moves:
        game.add_move(move)
    winner, isOver = game.check_win()
    if isOver:
        return {"winner": winner, "isOver": isOver}
    else:
        cpuMove, score = game.minimax(True)
        game.add_move(cpuMove)
