    def knightSearch(self, yStart, xStart, colour, yEnd=None, xEnd=None):
        targets = self.peices[[0 if colour == 'white' else 1][0]]
        increment = [(-2, 1), (-1, 2), (-2, -1), (-1, -2), (2, 1), (2, -1), (1, -2), (1, 2)]
        for i in increment:
