    net_network_address, net_first_host_address, net_last_host_address, net_broadcast_address = convert_addresses_to_dotted(net_network_address_binary, net_first_host_binary, net_last_host_binary, net_broadcast_address_binary)

    # Return the results as a dictionary
    return {
        "network_address": net_network_address,
        "first_host_address": net_first_host_address,
        "last_host_address": net_last_host_address,
        "broadcast_address": net_broadcast_address
    }

# Helper functions from the original code
def convert_mask_to_binary(subnet_mask):
    masks = [255, 254, 252, 248, 240, 224, 192, 128, 0]
    b = subnet_mask.split('.')
    if len(b) != 4:
        raise ValueError("Invalid subnet mask")
    for octet in b:
        if int(octet) not in masks:
            raise ValueError("Invalid subnet mask")

    mask_octets_padded = []
    mask_octets_decimal = subnet_mask.split(".")
    for octet_index in range(0, len(mask_octets_decimal)):
        binary_octet = bin(int(mask_octets_decimal[octet_index])).split("b")[1]
        if len(binary_octet) < 8:
            binary_octet_padded = binary_octet.zfill(8)
            mask_octets_padded.append(binary_octet_padded)
        else:
            mask_octets_padded.append(binary_octet)

    binary_mask = "".join(mask_octets_padded)
    no_of_zeros = binary_mask.count("0")
    no_of_ones = 32 - no_of_zeros
    no_of_hosts = abs(2 ** no_of_zeros - 2)
    return (binary_mask, no_of_ones, no_of_zeros, no_of_hosts)

def convert_ipv4_to_binary(ipv4_address):
    ip_octets_padded = []
    ip_octets_decimal = ipv4_address.split(".")
    for octet_index in range(0, len(ip_octets_decimal)):
        binary_octet = bin(int(ip_octets_decimal[octet_index])).split("b")[1]
        if len(binary_octet) < 8:
            binary_octet_padded = binary_octet.zfill(8)
            ip_octets_padded.append(binary_octet_padded)
        else:
            ip_octets_padded.append(binary_octet)
    binary_ip = "".join(ip_octets_padded)
    return binary_ip

def generate_address_binary(binary_ip, no_of_ones, no_of_zeros, no_of_hosts):
    network_address_binary = binary_ip[:(no_of_ones)] + "0" * no_of_zeros
    first_host_binary = binary_ip[:(no_of_ones)] + "0" * (no_of_zeros - 1) + "1"
    last_host_binary = binary_ip[:(no_of_ones)] + "1" * (no_of_zeros - 1) + "0"
    broadcast_address_binary = binary_ip[:(no_of_ones)] + "1" * no_of_zeros
    return (network_address_binary, first_host_binary, last_host_binary, broadcast_address_binary)

def convert_addresses_to_dotted(network_address_binary, first_host_binary, last_host_binary, broadcast_address_binary):
    def binary_to_dotted(binary_address):
        ip_octets = []
        for octet in range(0, len(binary_address), 8):
            ip_octet = binary_address[octet:octet+8]
            ip_octets.append(str(int(ip_octet, 2)))
        return ".".join(ip_octets)

    network_address = binary_to_dotted(network_address_binary)
    first_host_address = binary_to_dotted(first_host_binary)
    last_host_address = binary_to_dotted(last_host_binary)
    broadcast_address = binary_to_dotted(broadcast_address_binary)
    return (network_address, first_host_address, last_host_address, broadcast_address)

