# Helper functions from the original code
def convert_mask_to_binary(subnet_mask):
    masks = [255, 254, 252, 248, 240, 224, 192, 128, 0]
    b = subnet_mask.split('.')
    if len(b) != 4:
        raise ValueError("Invalid subnet mask")
    for octet in b:
