# all class and function definitions in the code file, if any
class MapSite():
    def Enter(self):
        raise NotImplementedError("This is an abstract class")

class Direction(Enum):
    North = 0
    South = 1
    East  = 2
    West  = 3

class Room(MapSite):
    def __init__(self, roomNo):
        self._roomNumber = int(roomNo)
        self._sides = [MapSite] * 4

    def Enter(self):
        pass

    def SetSide(self, Direction, Mapsite):
        self._sides[Direction] = Mapsite

    def GetSide(self, Direction):
        return self._sides[Direction]

class Wall(MapSite):
    def Enter(self):
        pass

class Door(MapSite):
    def __init__(self, room1 = None, room2 = None):
        self._room1 = room1
        self._room2 = room2
        self._isOpen = False

    def GetToOtherSideFrom(self, Room):
        if not self._isOpen:
            self.Open()

        if Room._roomNumber == self._room1._roomNumber:
            other_room = self._room2
        else:
            other_room = self._room1
        self._isOpen = False
        return other_room

    def Enter(self):
        pass

    def Open(self):
        self._isOpen = True

class Maze():
    def __init__(self):
        self._rooms = {}

    def AddRoom(self, room):
        self._rooms[room._roomNumber] = room

    def RoomNo(self, room_number):
        return self._rooms[room_number]

class MazeFactory():
    @classmethod
    def MakeMaze(cls):
        return Maze()
    @classmethod
    def MakeWall(cls):
        return Wall()
    @classmethod
    def MakeRoom(cls, room_number):
        return Room(room_number)
    @classmethod
    def MakeDoor(cls, r1, r2):
        return Door(r1, r2)

class EnchantedRoom(Room):
    def __init__(self, room_number):
        self._roomNumber = room_number
        self._sides = [MapSite] * 4

    def Enter(self):
        pass

class DoorNeedingASpell(Door):
    def __init__(self, room1 = None, room2 = None):
        self._room1 = room1
        self._room2 = room2
        self._isOpen = False

    def Open(self):
        self._isOpen = True

class EnchantedMazeFactory(MazeFactory):
    @classmethod
    def MakeRoom(cls, room_number):
        return EnchantedRoom(room_number)
    @classmethod
    def MakeDoor(cls, r1, r2):
        return DoorNeedingASpell(r1, r2)

class BombRoom(Room):
    def __init__(self, room_number):
        self._roomNumber = room_number
        self._sides = [MapSite] * 4
        self._bombDisabled = False

    def Enter(self):
        pass

    def DisableBomb(self):
        pass

class BombProofDoor(Door):
    def __init__(self, room1 = None, room2 = None):
        self._room1 = room1
        self._room2 = room2
        self._isOpen = False

    def GetToOtherSideFrom(self, room):
        if not self._isOpen:
            self.Open()
        if room._roomNumber == self._room1._roomNumber:
            other_room = self._room2
        else:
            other_room = self._room1
        return other_room

    def Open(self):
        self._isOpen = True

class BombProofWall(Wall):
    def Enter(self):
        pass

class BombedMazeFactory(MazeFactory):
    @classmethod
    def MakeRoom(cls, n):
        return BombRoom(n)

    @classmethod
    def MakeDoor(cls, r1, r2):
        return BombProofDoor(r1, r2)

    @classmethod
    def MakeWall(cls):
        return BombProofWall()

class MazeGame():
    def CreateMaze(self, factory = MazeFactory):
        maze = factory.MakeMaze()
        room1 = factory.MakeRoom(1)
        room2 = factory.MakeRoom(2)
        door12 = factory.MakeDoor(room1, room2)
        room1.SetSide(Direction.North.value, factory.MakeWall())
        room1.SetSide(Direction.East.value, factory.MakeWall())
        room1.SetSide(Direction.South.value, factory.MakeWall())
        room1.SetSide(Direction.West.value, door12)
        room2.SetSide(Direction.North.value, factory.MakeWall())
        room2.SetSide(Direction.West.value, factory.MakeWall())
        room2.SetSide(Direction.South.value, factory.MakeWall())
        room2.SetSide(Direction.East.value, door12)
        maze.AddRoom(room1)
        maze.AddRoom(room2)
        return maze

# main function
def main_solution(factory_type):
    # Convert factory_type to the appropriate factory class
    factory_map = {
        "MazeFactory": MazeFactory,
        "EnchantedMazeFactory": EnchantedMazeFactory,
        "BombedMazeFactory": BombedMazeFactory
    }
    factory = factory_map[factory_type]

    # Create the maze
    maze = MazeGame().CreateMaze(factory)

    # Find the rooms in the maze
    maze_rooms = []
    for room_number in range(1, 3):
        room = maze.RoomNo(room_number)
        maze_rooms.append(room._roomNumber)

    # Return the room numbers as a list
    return maze_rooms

