def is_orthogonal(mx):
    transp = [row[:] for row in mx]  # Create a deep copy of the matrix
    for i in range(len(mx)):
        for j in range(len(mx[0])):
            transp[j][i] = mx[i][j]  # Transpose the matrix

    M_rows = len(mx)
    M_cols = len(mx[0])
    T_rows = len(transp)
    T_cols = len(transp[0])

    if M_cols != T_rows:
        return False

    result = [[0 for _ in range(T_cols)] for _ in range(M_rows)]

    for i in range(M_rows):
        for j in range(T_cols):
            for k in range(M_cols):
                result[i][j] += mx[i][k] * transp[k][j]

    identity_matrix = [[1 if i == j else 0 for j in range(M_rows)] for i in range(M_rows)]

    return result == identity_matrix

