import itertools
import math

# all class and function definitions in the code file, if any
def get_y_for_circle(x, center_x, center_y, radius):
    if abs(x - center_x) > radius:
        raise ValueError()
    y = math.sqrt(radius ** 2 - (center_x - x) ** 2)
    return (math.ceil(center_y - y), math.floor(center_y + y))

def points_covered_by_sensor(center_x, center_y, radius):
    r = set()
    for x in range(center_x - radius, center_x + radius + 1):
        try:
            y_min, y_max = get_y_for_circle(x, center_x, center_y, radius)
            for y in range(y_min, y_max + 1):
                r.add((x, y))
        except ValueError:
            continue
    return r

# main function
def main_solution(room_size, sensors):
    # Convert JSON serializable inputs to original input variables
    room = room_size
    sensors = sensors

    # Core logic to determine if the room is completely covered by sensors
    covered_by_sensor = set()
    for sensor in sensors:
        sensor_x, sensor_y, sensor_r = sensor
        covered_by_sensor.update(points_covered_by_sensor(sensor_x, sensor_y, sensor_r))

