def carry(func):
    """ Decorator converts call of function with defined number of
    positional arguments to call of function with one argument. """

    def wrapper(*args):
        if len(args) == func.__code__.co_argcount:
            return func(*args)
        return lambda x: wrapper(*(args+(x,)))

    return wrapper

