def check(string):
    result = re.search(r'(.)(.)\2\1', string)
    if result is None:
        return False
    if result.group(1) == result.group(2):
        return False
    return True

def find_groups(string):
    cleaned = clean(string)
    a = []
    for i in range(0, len(cleaned) - 2):
        result = re.findall(r'((.)(.)\2)', cleaned)
        for r in result:
