# Function to check if a number is prime
def isPrime(num): 
    prime_flag = 0

    if(num > 1):
        for i in range(2, int(math.sqrt(num)) + 1):
            if (num % i == 0):
                prime_flag = 1
                break
        if (prime_flag == 0):
            return True
        else:
            return False
    else:
        return False

# Function to check if a number is not prime
def notPrime(num):
    if num == 1:
        return True

    if not isPrime(num):
        return True
    else:
        return False

# Function to perform bottom-up approach to find the longest non-prime number
def bottomUp(num, prev_num, d):
    for i in range(len(num)):
        check_num = prev_num + num[i]
        if notPrime(int(check_num)):
            d.update({len(check_num):int(check_num)})
            return 

    for i in range(len(num)):
        prev_num += num[i]
        new_num = num[:i] + num[i+1:]
        bottomUp(new_num, prev_num, d)

        if d:
            return

# Main solution function
def main_solution(k, n):
    n_str = str(n)
    d = {}
    bottomUp(n_str, '', d)
    key = list(d.keys())[0]
    return key, d[key]

