        self.i = 1
        return self

    def get_prime_numbers(self):
        self.i += 1
        for prime in self.prime_numbers:
            if self.i % prime == 0:
                return False
        return True

    def __next__(self):
        while self.i < self.n:
            if self.get_prime_numbers():
                self.prime_numbers.append(self.i)
                return self.i
        else:
            raise StopIteration()

def get_prime_numbers(i):
    if i == 1:
        return False
    for x in range(2, i):
        if i % x == 0:
            return False
    return True

def sum_digits(i):
    middle = len(str(i)) // 2
    if middle == 0 or str(i)[:middle] == str(i)[-middle:]:
        return True
    if len(str(i)) > 3:
        for _ in range(i):
            num = list(str(i))
            if int(num[0]) + int(num[1]) == int(num[2]) + int(num[3]):
                return True
    else:
        return False

def prime_numbers_generator(i=1, n=10000, func_filter1=get_prime_numbers, func_filter2=sum_digits):
    while i < n:
        if func_filter1(i) and func_filter2(i):
            yield i
        i += 1

