    # all input arguments of the main_solution function should be json serializable (no self-defined objects, functions, np.array, set, tuple, etc.)
    primeList = genPrimesList(limit)
    consecList = []
    consecPrimeCount = 0
    for num in range(10, 200000):
        distinctDiv = 0
        divisors = []
        if num not in primeList:
            tempNum = num
            numLimit = num // 2 + 1
            for prime in primeList:
                if prime > numLimit:
                    break
                while tempNum % prime == 0:
                    tempNum //= prime
                    if prime not in divisors:
                        divisors.append(prime)
                        distinctDiv += 1
