# Function to calculate the weight of a word at a given balance point
def calculate_weight(word, balance_point):
    left_weight = 0
    right_weight = 0
    for i, char in enumerate(word):
        if i < balance_point:
            left_weight += (balance_point - i) * (string.ascii_uppercase.index(char) + 1)
        elif i > balance_point:
            right_weight += (i - balance_point) * (string.ascii_uppercase.index(char) + 1)
    return left_weight, right_weight

