# import necessary packages
import random

# all class and function definitions in the code file, if any
class Node:
    def __init__(self, one, two, three, four, five, six):
        self.node_one = one
        self.node_two = two
        self.node_three = three
        self.node_four = four
        self.node_five = five
        self.node_six = six
        self.active = False
        self.elevation = 1

    def node_bridge(self, node):
        return {
            self.node_one: 1,
            self.node_two: 2,
            self.node_three: 3,
            self.node_four: 4,
            self.node_five: 5,
            self.node_six: 6
        }.get(node)

    def all_used_nodes(self):
        nodes = set()
        for attr in ['node_one', 'node_two', 'node_three', 'node_four', 'node_five', 'node_six']:
            if getattr(self, attr) is not None:
                nodes.add(getattr(self, attr))
        return nodes

    def find_immediate_connectors(self, node):
        connectors = set()
        for attr in ['node_one', 'node_two', 'node_three', 'node_four', 'node_five', 'node_six']:
            if getattr(self, attr) is not None and getattr(self, attr).node_bridge(node) is not None:
                connectors.add(getattr(self, attr).node_bridge(node))
        return connectors

    def insert_node(self, node):
        if self.node_connector(node) is None:
            return None

        my_connection = self.node_bridge(node)
        node_connection = node.node_bridge(self)

        new_node = Node(node, None, None, None, None, self)

        setattr(self, f'node_{my_connection}', new_node)
        setattr(node, f'node_{node_connection}', new_node)

        return new_node

    def node_connector(self, node):
        for attr in ['node_one', 'node_two', 'node_three', 'node_four', 'node_five', 'node_six']:
            if getattr(self, attr) is not None and getattr(self, attr).node_bridge(node) is not None:
                return getattr(self, attr)
        return None

