# import necessary packages
import random

# all class and function definitions in the code file, if any
# they will be used in the main_solution function, you may need to modify them to meet the requirements of the main_solution function (optional)
class Tree:
    """A Tree consists of a label and a sequence 
    of 0 or more Trees, called its children."""

    def __init__(self, label, *children):
        """A Tree with given label and children. 
        For convenience, if children[k] is not a Tree,
        it is converted into a leaf whose operator is
        children[k]."""
        self.__label = label
        self.__children = \
          [ c if type(c) is Tree else Tree(c) 
              for c in children]

    @property
    def is_leaf(self):
        return self.arity == 0

    @property
    def label(self):
        return self.__label

    @property
    def arity(self):
        """The number of my children."""
        return len(self.__children)

    def __iter__(self):
        """An iterator over my children."""
        return iter(self.__children)

    def __getitem__(self, k):
        """My kth child."""
        return self.__children[k]

def leaf_count(T):
    """Number of leaf nodes in the Tree T."""
    if T.is_leaf:
        return 1
    else:
        return sum(leaf_count(child) for child in T)

# main function
def main_solution(tree_structure):
    """
    Counts the number of leaf nodes in a given tree structure.

    Args:
    tree_structure (list): A list representing the tree structure. Each element is either a Tree object or a label (if it's a leaf).

    Returns:
    int: The number of leaf nodes in the tree.
    """
    # Convert the input list to a Tree object
    def list_to_tree(lst):
        if isinstance(lst, list):
            return Tree(lst[0], *[list_to_tree(child) for child in lst[1:]])
        else:
            return Tree(lst)

    tree = list_to_tree(tree_structure)
    return leaf_count(tree)

