class Solution:
    cache = {1: False}

    def divisorGame(self, N: int) -> bool:
        candidates = (N - i for i in range(1, int(math.sqrt(N))+1) if N % i == 0 and i < N)
        for n in candidates:
            if self.cache.get(n) is None:
                result = self.divisorGame(n)
                self.cache[n] = result
            if self.cache[n] is False:
                return True
        return False

